// ── Gate-tuning live readouts ───────────────────────────────────────────────
// Several thresholds gate on a live/windowed quantity the user can't otherwise see (RPM edge
// margin, current-drift spread, spectral tone peak, current slew, voltage slope). The firmware
// streams a 10s rolling extreme of each on CSV2 (ROLL_EMPTY = no sample in the window); the iExcess
// peak-over-command rides CSV1 at 10Hz so its 10s peak is computed here. Each readout shows the number to
// set the threshold relative to. Spans live next to each threshold input in index.html.
const ROLL_EMPTY_SENTINEL = -1999999999;   // firmware sends -2000000000 when a 10s window had no sample
const GATE_READOUTS_CSV2 = [
    { spans: ['faRpmEdgeMargin_live'],                                                       f: 'faRpmEdge10sMin',  s: 10,    lbl: '10s worst margin', u: 'RPM', d: 1 },
    { spans: ['faAmpsDriftFloorA_live', 'faAmpsDriftPct_live'],                              f: 'faAmpsDrift10sMax', s: 100,  lbl: '10s peak drift',   u: 'A',   d: 2 },
    { spans: ['faPeakMinA_live'],                                                            f: 'faTonePk10sMax',   s: 100,   lbl: '10s peak tone',    u: 'A',   d: 2 },
    { spans: ['LoadDumpDtThresh1_live', 'LoadDumpDtThresh_live', 'LoadDumpDtThresh3_live'],  f: 'ldSlew10sMax',     s: 10,    lbl: '10s peak slew',    u: 'A/s', d: 1 },
    { spans: ['SlopeBleedThresh_live'],                                                      f: 'cvSlope10sMax',    s: 10000, lbl: '10s peak rise',    u: 'V/s', d: 3 },
    // Ripple-capture admission gates — firmware streams (window quantity − its limit); <=0 = passing.
    // The self-scaling limits are invisible per-window values, so each label spells its limit rule out.
    { spans: ['ripCmdGate_live'],                                                            f: 'ripCmdExc10sMax',  s: 100,   lbl: 'command travel beyond limit (larger of Floor / Slope % × mean), 10s worst, ≤0 passes',   u: 'A', d: 2 },
    { spans: ['ripAltGate_live'],                                                            f: 'ripAltExc10sMax',  s: 100,   lbl: 'alt mean-shift beyond limit (larger of Floor / ¼ window swing), 10s worst, ≤0 passes',  u: 'A', d: 2 },
    { spans: ['ripBattGate_live'],                                                           f: 'ripBattExc10sMax', s: 100,   lbl: 'batt mean-shift beyond limit (larger of Floor / ¼ window swing), 10s worst, ≤0 passes', u: 'A', d: 2 },
    { spans: ['ripRpmGate_live'],                                                            f: 'ripRpmShift10sMax', s: 10,   lbl: 'RPM mean-shift beyond limit (larger of 10 RPM / ¼ window swing), 10s worst, ≤0 passes', u: 'RPM', d: 1 },
];
// Pass/fail styling for the anomaly steady-state gate readouts: green+bold when the last-10s extreme
// currently satisfies the gate, red+bold when it doesn't, neutral (muted gray) when the window had no
// sample. Colors match the local convention (#5cb85c pass, #ef4444 fail used elsewhere in this file).
const GATE_PASS_COLOR = '#5cb85c';
const GATE_FAIL_COLOR = '#ef4444';
function gateColor(id, pass) {
    const el = document.getElementById(id);
    if (!el) return;
    if (pass === null) { el.style.color = ''; el.style.fontWeight = 'normal'; el.style.opacity = '0.7'; return; }
    el.style.color = pass ? GATE_PASS_COLOR : GATE_FAIL_COLOR;
    el.style.fontWeight = '700';
    el.style.opacity = '1';
}
function gateEchoNum(id) { const el = document.getElementById(id); return el ? parseFloat(el.textContent) : NaN; }
function gateReadoutOnCsv2(data) {
    for (const r of GATE_READOUTS_CSV2) {
        const raw = Number(data[r.f]);
        const txt = (!isFinite(raw) || raw <= ROLL_EMPTY_SENTINEL)
            ? r.lbl + ': —'
            : `${r.lbl}: ${(raw / r.s).toFixed(r.d)} ${r.u}`;
        for (const id of r.spans) { const el = document.getElementById(id); if (el) el.textContent = txt; }
    }
    // Mirror the firmware gate (2_functions.ino faWindowFinalize) so the user sees pass/fail at a glance.
    // RPM: worst edge margin (signed; negative = straddled a band boundary) passes when >= the set margin.
    const rpmRaw = Number(data.faRpmEdge10sMin);
    if (!isFinite(rpmRaw) || rpmRaw <= ROLL_EMPTY_SENTINEL) gateColor('faRpmEdgeMargin_live', null);
    else { const set = gateEchoNum('faRpmEdgeMargin_echo'); gateColor('faRpmEdgeMargin_live', isFinite(set) ? (rpmRaw / 10) >= set : null); }
    // Drift: the firmware streams the EMA spread minus its own effective limit (max of floor / pct-of-mean),
    // computed from the exact filtered window mean — no client recompute. <=0 means the drift gate passed.
    // Both rows reflect the one gate. (faAmpsDriftExc10sMax is the 10s peak, i.e. the worst window.)
    const drExc = Number(data.faAmpsDriftExc10sMax);
    const drPass = (!isFinite(drExc) || drExc <= ROLL_EMPTY_SENTINEL) ? null : (drExc / 100) <= 0;
    gateColor('faAmpsDriftFloorA_live', drPass);
    gateColor('faAmpsDriftPct_live', drPass);
    // Ripple-capture gates: same excess convention (<=0 = that gate passed every window in the last 10s).
    // RPM row included — the firmware streams shift − limit directly.
    for (const [f, id, s] of [['ripCmdExc10sMax', 'ripCmdGate_live', 100], ['ripAltExc10sMax', 'ripAltGate_live', 100], ['ripBattExc10sMax', 'ripBattGate_live', 100], ['ripRpmShift10sMax', 'ripRpmGate_live', 10]]) {
        const v = Number(data[f]);
        gateColor(id, (!isFinite(v) || v <= ROLL_EMPTY_SENTINEL) ? null : (v / s) <= 0);
    }
    // (ripAltAdmitCount/ripBattAdmitCount still ride CSV2 but have no UI row.)
}
// iExcessLive: G3 (alternator) detector strip. Firmware ships one peak/threshold pair;
// threshMin ≤ 0 = disarmed.
const _ieSparkG3 = { peak: new Array(200).fill(0), minE: new Array(200).fill(0), fired: new Array(200).fill(0), N: 200, armed: false,
    canvasId: 'iExcessSparkG3', autoId: 'iExcessSparkAutoG3', peakId: 'mExcessEmaLiveG3', eId: 'iExcessELiveG3', floorId: 'IExcessFloorA_echo', ceilId: 'IExcessCeilA_echo' };
function iExcessLiveOnCsv1(data) {
    if (!document.getElementById('iExcessSparkG3')) return;  // strip not present on this page
    const peak = Number(data.mExcessEmaPeak) / 10;
    const minE = Number(data.iExcessThreshMin) / 10;
    const fired = (Number(data.protEventMask) & 2) ? 1 : 0;
    const S = _ieSparkG3;
    const own = (minE > 0);
    S.armed = own;
    S.peak.push(own && isFinite(peak) ? peak : 0); S.peak.shift();
    S.minE.push(own && isFinite(minE) ? minE : 0); S.minE.shift();
    S.fired.push(own ? fired : 0); S.fired.shift();
    const pe = document.getElementById(S.peakId); if (pe) pe.textContent = (own && isFinite(peak)) ? peak.toFixed(2) : '—';
    const ee = document.getElementById(S.eId); if (ee) ee.textContent = (own && minE > 0) ? minE.toFixed(1) : '—';
    const canvas = document.getElementById(S.canvasId); if (canvas) drawIExcessSpark(canvas, S);
}
function drawIExcessSpark(c, S) {
    const N = S.N;
    if (!S._init) { S._init = true; const cb = document.getElementById(S.autoId); if (cb) cb.checked = localStorage.getItem(S.autoId) === '1'; }
    const autoEl = document.getElementById(S.autoId), auto = !!(autoEl && autoEl.checked);
    const floorEl = document.getElementById(S.floorId), ceilEl = document.getElementById(S.ceilId);
    const floor = (floorEl && parseFloat(floorEl.textContent)) || 4;
    const ceil = (ceilEl && parseFloat(ceilEl.textContent)) || 25;
    const dpr = window.devicePixelRatio || 1, w = c.clientWidth || 220, h = c.clientHeight || 30;
    if (c.width !== w * dpr || c.height !== h * dpr) { c.width = w * dpr; c.height = h * dpr; }
    const g = c.getContext('2d'); g.setTransform(dpr, 0, 0, dpr, 0, 0); g.clearRect(0, 0, w, h);
    const pad = 2;
    let dmax = 0; for (let i = 0; i < N; i++) dmax = Math.max(dmax, S.peak[i], S.minE[i]);
    // Fixed: 0→ceiling so both clamps are framed. Auto: anchor the top to the data (which includes E),
    // so it can't zoom tighter than "E with headroom" — avoids the excessive-zoom-on-a-flat-signal trap.
    const ymax = auto ? Math.max(dmax, 1) * 1.15 : Math.max(ceil, dmax) * 1.05;
    const X = i => pad + i * (w - 2 * pad) / (N - 1), Y = v => h - pad - (Math.min(v, ymax) / ymax) * (h - 2 * pad);
    // floor always; ceiling whenever it's within the visible range
    g.strokeStyle = '#bbb'; g.lineWidth = 1; g.setLineDash([2, 3]);
    g.beginPath(); g.moveTo(0, Y(floor)); g.lineTo(w, Y(floor)); g.stroke();
    if (ceil <= ymax) {
        g.strokeStyle = '#9b59b6'; g.setLineDash([5, 3]);
        g.beginPath(); g.moveTo(0, Y(ceil)); g.lineTo(w, Y(ceil)); g.stroke();
    }
    g.setLineDash([]);
    if (!S.armed) g.globalAlpha = 0.35;  // disarmed strip: history stays visible but clearly not live
    // vertical fire markers — full-height red line at every frame that truly fired (drawn first,
    // behind the traces). From the real fire flag (protEventMask), not the plotted crossing.
    g.strokeStyle = 'rgba(192,57,43,0.85)'; g.lineWidth = 1.5;
    for (let i = 0; i < N; i++) {
        if (S.fired[i]) { const x = X(i); g.beginPath(); g.moveTo(x, 0); g.lineTo(x, h); g.stroke(); }
    }
    // min-E line (amber)
    g.beginPath(); for (let i = 0; i < N; i++) { const x = X(i), y = Y(S.minE[i]); i ? g.lineTo(x, y) : g.moveTo(x, y); }
    g.strokeStyle = '#d68910'; g.lineWidth = 1.4; g.stroke();
    // peak-excess line (teal throughout — the fire is shown by the vertical marker)
    g.beginPath(); for (let i = 0; i < N; i++) { const x = X(i), y = Y(S.peak[i]); i ? g.lineTo(x, y) : g.moveTo(x, y); }
    g.strokeStyle = '#00a19a'; g.lineWidth = 1.7; g.stroke();
    g.fillStyle = '#00a19a';
    g.beginPath(); g.arc(X(N - 1), Y(S.peak[N - 1]), 2.4, 0, 7); g.fill();
    g.globalAlpha = 1;
    if (!S.armed) { g.fillStyle = '#888'; g.font = '10px sans-serif'; g.fillText('disarmed', 6, 12); }
}

// Commissioning RPM sparkline: permanent strip in the commissioning modal so the user can
// hold engine speed steady without leaving the dialog. Fixed-count ring (150 samples ≈ 15 s at
// the ~10 Hz CSV1 cadence, same fixed-ring convention as the iExcess strip). No-ops when the
// modal is closed (canvas has zero width).
const _cxRpmSpark = { rpm: new Array(150).fill(NaN), N: 150 };
function cxRpmSparkOnCsv1(data) {
    const canvas = document.getElementById('cxRpmSpark');
    if (!canvas) return;
    const rpm = Number(data.RPM);
    if (cx) {                                  // green/red in-range check for the resonance current-check
        cx.liveRpm = isFinite(rpm) ? rpm : NaN;
        if (cx.rtestState === 'leveling') cxRtTick();
    }
    const S = _cxRpmSpark;
    S.rpm.push(isFinite(rpm) ? rpm : NaN); S.rpm.shift();
    const ve = document.getElementById('cx-rpm-spark-val');
    if (ve) ve.textContent = isFinite(rpm) ? Math.round(rpm) + ' RPM' : '—';
    // Draw only when the strip is laid out (modal open, not hidden by the sweep game) — but the
    // ring above must keep feeding regardless: the game reads the same ring for its trace.
    if (canvas.clientWidth) drawCxRpmSpark(canvas);
}
function drawCxRpmSpark(c) {
    const S = _cxRpmSpark, N = S.N;
    const dpr = window.devicePixelRatio || 1, w = c.clientWidth || 220, h = c.clientHeight || 48;
    if (c.width !== w * dpr || c.height !== h * dpr) { c.width = w * dpr; c.height = h * dpr; }
    const g = c.getContext('2d'); g.setTransform(dpr, 0, 0, dpr, 0, 0); g.clearRect(0, 0, w, h);
    const pad = 3;
    let dmin = Infinity, dmax = -Infinity;
    for (let i = 0; i < N; i++) { const v = S.rpm[i]; if (isFinite(v)) { if (v < dmin) dmin = v; if (v > dmax) dmax = v; } }
    if (!isFinite(dmin)) return;  // nothing yet
    // Auto Y with a ±5% floor of headroom so a dead-steady RPM doesn't render as full-scale jitter.
    const span = Math.max(dmax - dmin, dmax * 0.05, 20);
    const lo = dmin - span * 0.15, hi = dmax + span * 0.15;
    const X = i => pad + i * (w - 2 * pad) / (N - 1), Y = v => h - pad - ((v - lo) / (hi - lo)) * (h - 2 * pad);
    g.beginPath();
    let started = false;
    for (let i = 0; i < N; i++) {
        const v = S.rpm[i]; if (!isFinite(v)) { started = false; continue; }
        const x = X(i), y = Y(v); started ? g.lineTo(x, y) : g.moveTo(x, y); started = true;
    }
    g.strokeStyle = '#2ec4b6'; g.lineWidth = 1.7; g.stroke();
    const last = S.rpm[N - 1];
    if (isFinite(last)) { g.fillStyle = '#2ec4b6'; g.beginPath(); g.arc(X(N - 1), Y(last), 2.6, 0, 7); g.fill(); }
}

