// Temp-comp zero correction: live learned-equation readout under the Alternator Zero Correction toggle.
function fetchZeroFitState(){
    return fetch(buildURL('/zerofitstate')).then(r=>r.json()).then(j=>{
        if (!j) return;
        const st = document.getElementById('zerofit-status');
        if (!st) return;
        if (Number(j.valid) !== 1) {
            st.textContent = 'Fit: learning (' + (Number(j.histCount)||0) + ' days) — no correction yet';
            return;
        }
        // b is A/°F; show the correction it's applying now and the slope, keyed to the chosen sensor.
        const corr = Number(j.corrNow) || 0, slope = Number(j.b) || 0, r2 = Number(j.r2) || 0;
        const applied = Number(j.applied) === 1;
        st.textContent = 'Fit: ' + (j.sensor === 'alt' ? 'alt-temp' : 'board-temp')
            + ', ' + slope.toFixed(4) + ' A/°F, R²' + r2.toFixed(2)
            + ' → ' + (applied ? '' : 'would apply ') + corr.toFixed(2) + ' A'
            + (applied ? ' applied' : ' (Off)');
    }).catch(()=>{});
}

// Confidence-state labels + colors (firmware FrontStore::classify; OUTPUT-BLIND \u2014 position +
// record-book geometry only). 0/1 show the live %; 2/3 deliberately show no number.
const ALT_STATE_LABEL = ['MEASURED','ESTIMATED','Learning this operating region','No reference here yet'];
const ALT_STATE_COLOR = ['#2e9e4f','#3a7bd5','#888','#888'];   // measured green / estimated blue (spec §3); 2/3 grey (no number)
const ALT_RING_COLOR  = '#f0ad4e';                             // orange ring outlining a FULL steady-run dot (overlay, spec §3)

function updateAltHealth() {
  const pctEl = document.getElementById('alt-health-pct');
  const statEl = document.getElementById('alt-health-status');
  const covEl = document.getElementById('alt-coverage');
  // Headline = LIVE output % vs best-ever (NO clamp \u2014 can read > 100 vs a stale front) + the
  // confidence state. No verdict strings \u2014 trends are read from the plots, not editorialized here.
  const st = altLive.state|0;
  const graded = altLive.valid && (st===0 || st===1) && altLive.pct>0;
  if (pctEl) {
    pctEl.textContent = graded ? Math.round(altLive.pct)+'%' : '\u2014';
    pctEl.style.color = graded ? ALT_STATE_COLOR[st] : '';
  }
  if (statEl) {
    const usingUploaded = altLive.source >= 1;
    let txt = altLive.status===3 ? 'Disabled (Ignore Temperature)'
            : !altLive.valid ? 'Not running'
            : (ALT_STATE_LABEL[st] || '');
    if (altLive.status!==3 && usingUploaded) txt += ' \u00b7 Uploaded reference';
    if (altLive.status!==3 && altLive.paused>=1) txt += ' \u00b7 learning paused';
    statEl.textContent = txt;
    statEl.style.color = graded ? ALT_STATE_COLOR[st] : '#888';
  }
  // High-field-low-output alert (independent safety net \u2014 fires regardless of the record book)
  const hfEl = document.getElementById('alt-hifield-alert');
  if (hfEl) hfEl.style.display = altLive.hiFieldAlert>=1 ? '' : 'none';
  // Session statistics over the graded, session-steady samples (mean + 10th-percentile weak tail) \u2014
  // the same points the This Session plot dots; a real ~5% decline shows here before the trend buckets can.
  const sessEl = document.getElementById('alt-session-stats');
  if (sessEl) sessEl.textContent = (altLive.sessionN>=10)
    ? ('this session: mean '+Math.round(altLive.sessionMean)+'% \u00b7 10th percentile '+Math.round(altLive.sessionP10)+'% \u00b7 '+Math.round(altLive.sessionN)+' graded samples')
    : '';
  // Best-surface size + engine-hours of data gathered (no live "now %": the plot's dot already shows it).
  if (covEl) {
    covEl.textContent = (altLive.ptCount>0)
      ? (Math.round(altLive.ptCount)+' best surface points \u00b7 '+Math.round(altLive.engHours)+' engine-hr')
      : 'no best surface points yet';
  }
  // Default reference (own history) is not labelled — it's the uninteresting common case. Only the
  // genuinely distinct states are surfaced: an actively uploaded reference, and learning paused.
  const modeLbl = document.getElementById('alt-mode-label');
  if (modeLbl) modeLbl.textContent = [altLive.source>=1 ? 'Uploaded reference' : '',
                                      altLive.paused>=1 ? 'learning paused' : '']
                                     .filter(Boolean).join(' · ');
  setSeg(['alt-src-hist','alt-src-file'], altLive.source>=1?1:0);
  setSeg(['alt-learn-on','alt-learn-off'], altLive.paused>=1?1:0);
  setSeg(['alt-sim-off','alt-sim-on'], altLive.sim>=1?1:0);   // simulator segmented toggle in Setup (mirrors Vessel Performance)
}

