function updateLifeIndicators(data) {
    const indicatorColors = ['#00a19a', '#ff9800', '#f44336']; // Green, Yellow, Red
    const colorNames = ['Good', 'Caution', 'Critical'];

    const indicators = [
        { id: 'insulation-indicator', percent: data.InsulationLifePercent },
        { id: 'grease-indicator', percent: data.GreaseLifePercent },
        { id: 'brush-indicator', percent: data.BrushLifePercent },
        { id: 'predicted-indicator', hours: data.PredictedLifeHours }
    ];

    indicators.forEach(indicator => {
        const element = document.getElementById(indicator.id);
        if (!element) return;

        let colorIndex = 0; // Default green

        if (indicator.percent !== undefined) {
            // For percentage indicators
            if (indicator.percent < 20) colorIndex = 2;      // Red below 20%
            else if (indicator.percent < 50) colorIndex = 1; // Yellow below 50%
        } else if (indicator.hours !== undefined) {
            // For predicted hours indicator
            if (indicator.hours < 1000) colorIndex = 2;      // Red below 1000 hours
            else if (indicator.hours < 5000) colorIndex = 1; // Yellow below 5000 hours
        }

        element.style.color = indicatorColors[colorIndex];
        element.textContent = colorNames[colorIndex];
    });
}


// Open-loop field modes (manual / limp-home) command duty directly, bypassing the current-limiting
// loop. On a 24/48V bank each duty-percent drives ~2×/4× the field current of 12V, so a duty that's
// safe at 12V can over-current the field. Warn (don't cap) each time the user enters one of these
// modes on a higher-voltage system. window._nominalStored is the system voltage from the Vessel Info fetch/save.
function warnHighVoltageOpenLoop(modeName) {
    const nsv = parseInt(window._nominalStored, 10) || 12;
    if (nsv <= 12) return;
    const mult = nsv / 12;
    xAlert(modeName + ' on a ' + nsv + 'V system\n\n'
        + modeName + ' commands field duty directly, bypassing the current-limiting loop. At ' + nsv
        + 'V each duty-percent drives about ' + mult + '× the field current of a 12V system, so a '
        + 'duty that is safe at 12V can over-current the field here.\n\n'
        + 'Keep the commanded duty low and raise it gradually while watching field/output current.');
}

function handleManualFieldToggle(checkboxId) {
    const cb = document.getElementById(checkboxId);
    if (!cb) return false;

    // ESP32 convention is inverted: 0 = PID, 1 = Manual
    // So when checkbox is checked (PID), we send 0; unchecked (Manual), we send 1
    const invertedVal = cb.checked ? '0' : '1';
    if (invertedVal === '1') warnHighVoltageOpenLoop('Manual field mode');  // entering open-loop manual

    const result = handleUserToggle(checkboxId, 'ManualFieldToggle', 'ManualFieldToggle');

    const pending = pendingToggles.get('ManualFieldToggle');
    if (pending) {
        pending.desiredValue = cb.checked ? 1 : 0;  // checked=PID=invertedManual=1
    }

    const hiddenInput = document.getElementById('ManualFieldToggle');
    if (hiddenInput) hiddenInput.value = invertedVal;

    return result;
}

// ===== Segmented A/B controls =====
// Render peer-choice settings (mode A vs mode B) as a segmented control instead of
// an on/off slider, reusing the existing hidden checkbox plumbing untouched. The
// visible buttons drive the hidden checkbox; firmware sync, pendingToggles, the
// onchange handler and form submit all still flow through that checkbox.
// data-seg-for names the hidden checkbox; each button's data-checked is the
// checked-state ("0"/"1") that button represents.
function syncSegmented(checkboxId) {
    const cb = document.getElementById(checkboxId);
    if (!cb) return;
    const wrap = document.querySelector('.ab-seg[data-seg-for="' + checkboxId + '"]');
    if (!wrap) return;
    wrap.querySelectorAll('.cap-mode-btn').forEach(b => {
        b.classList.toggle('cap-mode-active', (b.dataset.checked === '1') === cb.checked);
    });
}

function abSegClick(btn) {
    const wrap = btn.closest('.ab-seg');
    if (!wrap) return;
    const cbId = wrap.dataset.segFor;
    const cb = document.getElementById(cbId);
    if (!cb) return;
    const want = (btn.dataset.checked === '1');
    if (cb.checked !== want) {
        cb.checked = want;
        cb.dispatchEvent(new Event('change')); // runs the checkbox's existing onchange (handler + form submit)
    }
    syncSegmented(cbId);
}

// Segmented control over a hidden value input (no checkbox) for multi-value peer
// settings like BatteryCurrentSource. data-seg-name names the hidden input
// (id="<name>_val", name="<name>"); each button's data-val is the value to send.
function syncSegmentedSelect(name, val) {
    const wrap = document.querySelector('.ab-seg-select[data-seg-name="' + name + '"]');
    if (!wrap) return;
    wrap.querySelectorAll('.cap-mode-btn').forEach(b => {
        b.classList.toggle('cap-mode-active', b.dataset.val === String(val));
    });
}

function abSegSelectClick(btn) {
    const wrap = btn.closest('.ab-seg-select');
    if (!wrap) return;
    const name = wrap.dataset.segName;
    const hidden = document.getElementById(name + '_val');
    if (hidden) hidden.value = btn.dataset.val;
    syncSegmentedSelect(name, btn.dataset.val);
    const form = btn.closest('form');
    if (form) { updatePasswordFields(); form.submit(); }
}

// ==================== PID TUNING PLOT (SEPARATE SYSTEM) ====================

//Background text display stuff
function getEchoText(id, fallback = '?') {
    const el = document.getElementById(id);
    if (!el) return fallback;
    const t = (el.textContent || '').trim();
    return t.length ? t : fallback;
}

// ── "s" signal-info badges (Protections + Setup▸Diag) ────────────────────────────────────
// Each badge states: the signal a setting acts on / is compared to, the physical source
// (INA228 / ADS1115 / on-chip ADC / PWM command / temp sensor), the filter and its time
// constant, and where the value gets set. Content is built from the SAME echo spans the
// settings UI already maintains, so it is regenerated on open and re-rendered on every
// CSV3 / AltSettings frame while a box is open — live values stay hot without new telemetry.
let _sinfoOpenN = 0;

function sinfoToggle(el) {
    if (!el.classList.contains('active')) sinfoRender(el);
    el.classList.toggle('active');
    _sinfoOpenN = Math.max(0, _sinfoOpenN + (el.classList.contains('active') ? 1 : -1));
}

function sinfoRender(el) {
    const fn = SINFO[el.dataset.sinfo];
    let box = el.querySelector('.tooltip-box');
    if (!box) { box = document.createElement('span'); box.className = 'tooltip-box'; el.appendChild(box); }
    box.innerHTML = fn ? fn().map(r => '<div class="s-row"><span class="s-k">' + r[0] + ':</span> ' + r[1] + '</div>').join('') : 'No signal info registered.';
}

function sinfoRefreshOpen() {
    if (!_sinfoOpenN) return;
    document.querySelectorAll('.sinfo.active').forEach(sinfoRender);
}

// live-value helpers: echo text with a unit, and echo parsed as a number
function svv(id, unit) { return '<b>' + getEchoText(id) + (unit ? '&nbsp;' + unit : '') + '</b>'; }
function svTargetV() {
    // voltageTarget rides CSV1 into cvPlotCache (÷100 = volts); blank until the stream is up
    const t = (typeof cvPlotCache === 'object' && cvPlotCache && cvPlotCache.voltageTarget != null)
        ? ' (now <b>' + (cvPlotCache.voltageTarget / 100).toFixed(2) + '&nbsp;V</b>)' : '';
    return 'the active charge target' + t + ' — set on Setup ▸ Battery ▸ Charge Settings, moves with charge stage';
}
function svTempSensor() {
    const s = getEchoText('TempSource_echo');
    if (s === 'Digital') return 'digital one-wire probe (DS18B20) per Temp Source on Setup ▸ Alternator';
    if (s === 'Thermistor') return 'thermistor per Temp Source on Setup ▸ Alternator';
    return 'digital probe or thermistor, per Temp Source on Setup ▸ Alternator';
}

// shared source descriptions
const S_ADS_ALT = 'alternator output current — Hall-effect clamp, read by the external 16-bit ADC (ADS1115 ch&nbsp;1, shared round-robin), fresh within ~30&nbsp;ms';
const S_INA_I = 'battery current — INA228 shunt monitor, new sample every ~5&nbsp;ms while charging';
const S_INA_V = 'battery voltage — INA228 bus-voltage register, new sample every ~5&nbsp;ms';
const S_FAST = 'the same alternator Hall clamp, tapped to the ESP32’s own on-chip ADC (GPIO3) at 20,000 samples/s — separate from the ADS1115 slow path';
const S_RPM_ADS = 'engine speed — tach conditioner voltage on ADS1115 ch&nbsp;2 × RPM scaling factor';
const S_DUTY = 'field drive strength (duty cycle) — the regulator’s own PWM command, no sensor involved';

function sIETau() { return 'smoothed with a moving-average low-pass (EMA), time constant ' + svv('IExcessTau_echo', 'ms') + ' — adjustable: the "Averaging Time Constant" field in this Detection section'; }
function sAltEma() { return 'smoothed with a moving-average low-pass (EMA), time constant ' + svv('altEmaSec_echo', 's') + ' — adjustable: the "Signal smoothing filter" field in this Steady-State Detection group'; }

const SINFO = {
    // ── Protections: Detection ──
    MaxTableValue: () => [
        ['Signal', S_ADS_ALT],
        ['Compared to', 'derived trip point = this limit + 10&nbsp;A = ' + svv('HardOCTripAmps_echo', 'A') + ', after the debounce below'],
        ['Filter', 'none — raw; this is the last line of defense'],
        ['Set', 'same setting as the Alternator Current Limit on the Tuning tab — editing either updates the trip point'],
    ],
    HardOCDebounceMs: () => [
        ['Signal', S_ADS_ALT],
        ['Role', 'excess above ' + svv('HardOCTripAmps_echo', 'A') + ' must persist this long continuously before the field cut'],
        ['Filter', 'none — raw'],    ],
    ovG1: () => [
        ['Signal', 'predicted voltage = measured + ' + svv('TdPred_echo', 's') + ' × rate-of-rise (rising only), vs ' + svv('OvPredMarginV_echo', 'V') + ' above target'],
        ['Source', S_INA_V + ', unfiltered'],
        ['Filter', 'only the rate-of-rise is smoothed — moving-average low-pass (EMA), time constant ' + svv('DvdtTC_echo', 'ms') + ' — adjustable: the "dvdt EMA TC" field in this group'],
        ['Compared to', svTargetV()],
    ],
    DvdtTC: () => [
        ['Signal', 'the voltage rate-of-rise feeding Group 1’s prediction'],
        ['Source', 'successive INA228 bus-voltage samples ~5&nbsp;ms apart'],
        ['Filter', 'this field IS the filter — moving-average low-pass (EMA) time constant'],    ],
    ovG2: () => [
        ['Signal', 'measured battery voltage vs ' + svv('OvMeasMarginV_echo', 'V') + ' above target'],
        ['Source', S_INA_V + ', unfiltered — fastest possible reaction'],
        ['Compared to', svTargetV()],
    ],
    iexG3: () => [
        ['Signal', 'smoothed excess of alternator current over the live current command'],
        ['Source', S_ADS_ALT],
        ['Filter', sIETau()],
        ['Armed', 'whenever charging with test protections on — strict near-target regime inside the Strict Band, looser bulk regime below it'],
    ],
    IExcessArmMarginV: () => [
        ['Signal', 'battery voltage vs (target − this band)'],
        ['Source', S_INA_V + ', unfiltered'],
        ['Role', 'picks which detector regime is armed: inside the band = strict near-target detector, below it = looser bulk detector'],
        ['Compared to', svTargetV()],
    ],
    IExcessFrac: () => [
        ['Signal', 'smoothed current excess vs ' + svv('IExcessFrac_echo', '%') + ' of the live current command, clamped to the Floor / Ceiling'],
        ['Source', S_ADS_ALT + ' — near-target regime, picked by the Strict Band'],
        ['Filter', sIETau()],    ],
    IExcessFracBulk: () => [
        ['Signal', 'smoothed alternator-current excess vs ' + svv('IExcessFracBulk_echo', '%') + ' of the live ceiling'],
        ['Ceiling', 'RPM-table cap (auto-learned table, Setup ▸ Alternator) minus any thermal / warm-up derate, never above the Command Limit'],
        ['Source', S_ADS_ALT],
        ['Filter', sIETau()],
    ],
    IExcessFloorA: () => [
        ['Role', 'lower bound (amps) on the alternator detector’s threshold'],
        ['Signal context', S_ADS_ALT],
        ['Set', 'operator-owned — never auto-written by commissioning; size it with the ripple plot below (measured in Commissioning ▸ Step 5)'],
    ],
    IExcessCeilA: () => [
        ['Role', 'upper bound (amps) on the alternator detector’s threshold'],
        ['Signal context', S_ADS_ALT],    ],
    BattCurrentLimitA: () => [
        ['Role', 'ceiling, not a trip: the alternator command is capped at this limit + the measured house-load draw, so the battery never receives more than this'],
        ['Load offset', 'EMA of (alternator current − battery current), ~0.25 s — clamped ≥ 0 so estimate noise can only lower the ceiling'],
        ['Source', S_INA_I + ' — requires the INA228 shunt as Battery Current Source; 0 = disabled'],
    ],
    ripPlotAlt: () => [
        ['Threshold lines', 'recomputed live from the threshold / floor / ceiling fields above'],
        ['Ripple line', 'alternator ripple measured during Commissioning ▸ Step 5 (current check), filtered with the same EMA the detectors use (τ = ' + svv('IExcessTau_echo', 'ms') + ' — the "Averaging Time Constant" field above) so it is detector-eye ripple; fixed until Step 5 is re-run'],
        ['Source', S_ADS_ALT],
    ],
    IExcessTau: () => [
        ['Role', 'this field IS the filter — moving-average low-pass (EMA) time constant on the detector’s excess signal (both regimes)'],
        ['Also used by', 'the measured-ripple capture (Setup ▸ Diag ▸ Ripple Capture) and the commissioning ripple fit, so the ripple plots stay comparable to what the detectors see. Changing it changes those measurements too.'],    ],
    IExcessRelFrac: () => [
        ['Signal', 'the same smoothed excess (EMA, τ = ' + svv('IExcessTau_echo', 'ms') + ' — the "Averaging Time Constant" field above) vs ' + svv('IExcessRelFrac_echo', '%') + ' of the threshold, for re-arm'],    ],
    loadDump: () => [
        ['Signal', 'rate-of-change of battery current, computed on every new sample'],
        ['Source', S_INA_I],
        ['Filter', 'none — raw per-sample derivative (a filtered edge would be missed)'],
        ['Armed', 'whenever charging with fast battery reads — even when test protections are disabled'],    ],
    // ── Protections: Response ──
    KHard: () => [
        ['Acts on', 'the current cap — trimmed by ' + svv('KHard_echo', 'A') + ' per volt of overshoot, recomputed from the live overshoot every control tick'],
        ['Overshoot signal', 'Group 1 predicted / Group 2 measured battery voltage (INA228 bus register)'],    ],
    IExcessKBleed: () => [
        ['Acts on', 'the voltage-loop integrator, once at the instant the Group 3 detector fires; the amount scales with the smoothed excess (EMA, τ = ' + svv('IExcessTau_echo', 'ms') + ' — the "Averaging Time Constant" field in Detection)'],    ],
    AwBleedRate: () => [
        ['Acts on', 'the voltage-loop integrator while any protection is clamping'],
        ['Effective rate', (function () { const r = parseFloat(getEchoText('AwBleedRate_echo')), m = parseFloat(getEchoText('MaxTableValue_echo')); return svv('AwBleedRate_echo') + ' × Command Limit ' + svv('MaxTableValue_echo', 'A') + (isFinite(r) && isFinite(m) ? ' = <b>' + (r * m).toFixed(0) + '&nbsp;A/s</b>' : ''); })()],    ],
    // ── Protections: Recovery ──
    fastRise: () => [
        ['Acts on', 'the current-setpoint slew after a protection releases'],
        ['Effective rate', (function () { const x = parseFloat(getEchoText('FastSetpointRiseRate_echo')), b = parseFloat(getEchoText('SetpointRiseRate_echo')); return svv('FastSetpointRiseRate_echo', '×') + ' the normal Setpoint Rise Rate ' + svv('SetpointRiseRate_echo', 'A/s') + ' (set on Tuning ▸ Current)' + (isFinite(x) && isFinite(b) ? ' = <b>' + (x * b).toFixed(0) + '&nbsp;A/s</b>' : ''); })()],
        ['Gate', 'battery voltage (INA228, unfiltered) below target − ' + svv('FastSetpointRiseHeadroomV_echo', 'V') + ', capped at ' + svv('FastSetpointRiseWindowMs_echo', 'ms')],
        ['Compared to', svTargetV()],
    ],
    // ── Setup ▸ Diag: C1+C2 fast channel ──
    faDrift: () => [
        ['Signal', 'the fast channel’s own current, smoothed by a 300&nbsp;ms moving-average low-pass (EMA — hardcoded in firmware, not adjustable), judged across each 0.5&nbsp;s capture window (also hardcoded)'],
        ['Source', S_FAST + ' (16-sample average → 1,250/s stream)'],
        ['Gates', 'both the anomaly detector’s arming (C1) and the map folds (C2): window rejected when drift exceeds the larger of the floor or the slope % of the window’s mean current'],    ],
    faAtten: () => [
        ['Signal', S_ADS_ALT + ' (the authoritative slow reading — not the fast channel itself), with a 5&nbsp;s dwell (hardcoded in firmware)'],
        ['Acts on', 'the on-chip ADC’s input range on GPIO3: sensitive (6&nbsp;dB) below the switch-down value, high-range (12&nbsp;dB) above the switch-up value; the switch lands on a window boundary'],    ],
    // ── Setup ▸ Diag: C2 map-only gates ──
    faRpmEdgeMargin: () => [
        ['Signal', S_RPM_ADS + ', smoothed by a 1&nbsp;s moving-average low-pass (EMA — hardcoded in firmware, not adjustable)'],
        ['Gate', 'the whole 0.5&nbsp;s window must stay inside one 50-RPM bin with at least this margin to both edges — map folds only, never detector arming'],
        ['Auto-relaxed', 'during the commissioning map bootstrap this gate is loosened automatically'],
    ],
    faPeakMinA: () => [
        ['Signal', 'each detected tone’s amplitude from the spectrum (FFT) of a 0.5&nbsp;s window (hardcoded) of the 1,250/s stream'],
        ['Source', S_FAST],
    ],
    // ── Setup ▸ Diag: C3 steadiness bands ──
    altBandRpm: () => [
        ['Signal', S_RPM_ADS],
        ['Filter', sAltEma()],
        ['Gate', 'hold within the band for the steady time — all five axes (RPM, duty, voltage, amps, temperature) must be steady at once before a point records'],    ],
    altBandDuty: () => [
        ['Signal', S_DUTY],
        ['Filter', sAltEma()],
        ['Gate', 'hold within the band for the steady time — one of the five axes that must all be steady at once'],    ],
    altBandVbus: () => [
        ['Signal', S_INA_V],
        ['Filter', sAltEma()],
        ['Gate', 'hold within the band for the steady time — one of the five axes that must all be steady at once'],    ],
    altBandTemp: () => [
        ['Signal', 'alternator temperature — ' + svTempSensor()],
        ['Filter', 'none — judged raw, deliberately unsmoothed (thermal mass is its own filter)'],
        ['Gate', 'full steady runs need the whole dwell; the This-Session tier automatically uses half of it (' + (function () { const v = parseFloat(getEchoText('altThermSec_echo')); return isFinite(v) ? '<b>' + (v / 2).toFixed(0) + '&nbsp;s</b>' : 'half the dwell'; })() + ')'],    ],
    altBandAmps: () => [
        ['Signal', S_ADS_ALT],
        ['Filter', sAltEma()],
        ['Gate', 'band = the larger of the % of reading or the floor, held for the steady time — one of the five axes that must all be steady at once'],    ],
    altEmaSec: () => [
        ['Role', 'this field IS the filter — an interval-aware moving-average low-pass (EMA) on RPM, field duty, voltage, and amps before their steadiness bands are judged; temperature is deliberately excluded'],    ],
    altMinRun: () => [
        ['Signal', 'the combined steadiness verdict of all five axes (RPM, field duty, voltage, amps, temperature) — a steady run shorter than this never emits a point'],    ],
    altAdmit: () => [
        ['Signals', 'smoothed alternator amps (ADS1115 Hall clamp) and smoothed field duty (PWM command)'],
        ['Filter', sAltEma()],    ],
    altFit: () => [
        ['Acts on', 'the best-ever reference surface and its locally-weighted fit (LWLR)'],
        ['Fit inputs', 'smoothed RPM, excitation (derived from field duty / voltage / temperature), vs the recorded points'],
        ['Prune k', 'stored on the device but applied cloud-side by the prune job'],
    ],
    altHiField: () => [
        ['Signals', 'smoothed field duty (PWM command) at or above ' + svv('altHiFieldPct_echo', '%') + ' AND smoothed alternator amps (ADS1115) at or below ' + svv('altLowOutAmps_echo', 'A') + ' for ' + svv('altHiFieldSec_echo', 's')],
        ['Filter', sAltEma()],
        ['Role', 'advisory readout only — no audible alarm, no field action'],    ],
    // ── Setup ▸ Diag: C4 measured-ripple capture ──
    ripWinMs: () => [
        ['Signals', 'battery current (INA228 shunt, ~5&nbsp;ms samples while charging) + alternator current (ADS1115 Hall clamp, fresh within ~30&nbsp;ms) + engine speed (ADS1115 ch&nbsp;2)'],
        ['Filter', 'the same EMA the over-current detectors use — τ = ' + svv('IExcessTau_echo', 'ms') + ', set as "Averaging Time Constant" on Setup ▸ Alternator ▸ Protections'],
        ['Recorded value', 'the smaller of the two half-window peak-to-peaks'],
        ['Consumed by', 'Commissioning ▸ Step 5 current check and the RPM-table game'],
    ],
    ripDriftFloorA: () => [
        ['Signals', 'the two half-window averages of each sensor (alternator ADS1115, battery INA228, plus RPM with its own fixed floor), and the travel of the current command'],
        ['Command', 'the slewed current setpoint — internal, no sensor'],    ],
    ripDriftPct: () => [
        ['Signal', 'travel of the current command only — the slewed internal setpoint, no sensor; the sensor gates self-scale instead (see the floor)'],    ],
};

function drawPidWatermark(u) {
    const kp = getEchoText('PidKp_echo');
    const ki = getEchoText('PidKi_echo');
    const kd = getEchoText('PidKd_echo');
    const kb = getEchoText('PIDTrackingGain_echo');
    const riseRate = getEchoText('SetpointRiseRate_echo');
    const fallRate = getEchoText('SetpointFallRate_echo');
    const dutyRate = getEchoText('DutyRampRate_echo');
    const sampleTime = getEchoText('PidSampleDivisor_echo');
    const vLoopInt = getEchoText('VoltageLoopInterval_echo');
    const vKp = getEchoText('VoltageKp_echo');
    const wavePer = getEchoText('wavePeriod_echo');
    const waveAmp = getEchoText('waveAmplitude_echo');
    const rpm = typeof window._lastKnownRPM !== 'undefined' ? window._lastKnownRPM : '?';

    const col1 = [
        `Kp: ${kp}`,
        `Ki: ${ki}`,
        `Kd: ${kd}`,
        `kb: ${kb}`,
    ];

    const col2 = [
        `Rise: ${riseRate} A/s`,
        `Fall: ${fallRate} A/s`,
        `Duty: ${dutyRate} %/s`,
        `RPM: ${rpm}`,
    ];

    const col3 = [
        `PID: ${sampleTime} ms`,
        `VLoop: ${vLoopInt} ms`,
        `VKp: ${vKp} A/V`,
        `Wave: ${wavePer}s @ ${waveAmp}A`,
    ];

    const ctx = u.ctx;
    const x0 = u.bbox.left;
    const y0 = u.bbox.top;
    ctx.save();
    ctx.globalAlpha = 0.28;
    ctx.fillStyle = '#666';
    ctx.font = 'bold 18px monospace';
    ctx.textBaseline = 'top';
    ctx.shadowColor = 'rgba(255,255,255,0.6)';
    ctx.shadowBlur = 2;

    const lineH = 24;
    const colSpacing = 220;

    let x = x0 + 14;
    let y = y0 + 14;
    for (let i = 0; i < col1.length; i++) {
        ctx.fillText(col1[i], x, y);
        y += lineH;
    }

    x += colSpacing;
    y = y0 + 14;
    for (let i = 0; i < col2.length; i++) {
        ctx.fillText(col2[i], x, y);
        y += lineH;
    }

    x += colSpacing;
    y = y0 + 14;
    for (let i = 0; i < col3.length; i++) {
        ctx.fillText(col3[i], x, y);
        y += lineH;
    }

    ctx.restore();
}
let pidTuningPlot = null;
let pidTuningData = null;
let pidTuningResizeObserver = null;
let pidTuningIndex = 0;


// Series visibility state (persistent across redraws)
let pidTuningSeriesVisible = {
    setpointLimited: true,
    pidInput: true,
    uTargetAmps: true,
    dutyCycle: true,
    pidOutput: true,
    rpm: true
};

function initPidTuningDataStructures() {
    const intervalMs = window._lastKnownInterval || 200;
    // Buffer ALWAYS holds the full 5 min (LIVE_BUFFER_SEC), independent of the selected X window (xTime) —
    // so switching to 5M always has history and a window change never reallocates or loses data. The
    // x-scale range fn (in initPidTuningPlot) draws only the selected window. Mirrors the main live plots.
    const maxPoints = Math.ceil(LIVE_BUFFER_SEC * 1000 / intervalMs);

    if (maxPoints <= 0 || maxPoints > 10000 || isNaN(maxPoints)) {
        diagError(`Invalid maxPoints: ${maxPoints} (interval=${intervalMs}, buffer=${LIVE_BUFFER_SEC}s)`);
        return;
    }

    const intervalSec = intervalMs / 1000;

    const xAxisData = [];
    for (let i = 0; i < maxPoints; i++) {
        xAxisData[i] = -(maxPoints - 1 - i) * intervalSec;
    }

    pidTuningData = [
        [...xAxisData],                      // [0] X-axis (seconds ago)
        new Array(maxPoints).fill(0),        // [1] setpointLimited
        new Array(maxPoints).fill(0),        // [2] pidInput (PID EMA input = g_pidI_filtered, not truly raw)
        new Array(maxPoints).fill(0),        // [3] uTargetAmps
        new Array(maxPoints).fill(0),        // [4] dutyCycle
        new Array(maxPoints).fill(0),        // [5] pidOutput
        new Array(maxPoints).fill(0)         // [6] RPM / 100
    ];

    pidTuningIndex = 0;
    plotInterp.pid.arrivalTime = 0;
}
// Manual override for the PID plot's right-hand duty axis (browser-side only;
// the left amps axis persists on the regulator as yyMin/yyMax).
let pidDutyRange = null;
try { pidDutyRange = JSON.parse(localStorage.getItem('pidDutyRange')) || null; } catch (e) { }
// Auto checkbox state for the PID plot's left amps axis. When on, the amps axis
// auto-fits the data instead of using the firmware yyMin/yyMax. pidAmpsLock pins
// the auto range at a frozen value (lock button) while auto stays on.
let pidAmpsAuto = localStorage.getItem('pidAmpsAuto') === 'true';
let pidAmpsLock = null;   // [min,max] frozen by the lock button, or null

function initPidTuningPlot() {
    const plotEl = document.getElementById('pid-tuning-plot');
    if (!plotEl) {
        diagError("PID tuning plot element not found");
        return;
    }

    const opts = {
        width: Math.min(plotEl.clientWidth || 600, 800),  // || 600: never born 0-wide if built hidden
        height: 400,
        series: [
            {},
            {
                label: "Setpoint (slewed)",
                stroke: pidTuningSeriesVisible.setpointLimited ? "#FF6B6B" : "transparent",
                width: 2,
                scale: "amps"
            },
            {
                label: "Measured Current (PID input)",
                stroke: pidTuningSeriesVisible.pidInput ? "#4CAF50" : "transparent",
                width: 1,
                scale: "amps",
                dash: [4, 2]
            },
            {
                label: "Setpoint (raw)",
                stroke: pidTuningSeriesVisible.uTargetAmps ? "#FFA726" : "transparent",
                width: 1,
                scale: "amps",
                dash: [2, 2]
            },
            {
                label: "Duty Applied",
                stroke: pidTuningSeriesVisible.dutyCycle ? "#2196F3" : "transparent",
                width: 2,
                scale: "duty"
            },
            {
                label: "PID Output",
                stroke: pidTuningSeriesVisible.pidOutput ? "#9C27B0" : "transparent",
                width: 2,
                scale: "duty",
                dash: [6, 4]
            },
            {
                label: "RPM / 100",
                stroke: pidTuningSeriesVisible.rpm ? "#00BCD4" : "transparent",
                width: 1,
                scale: "amps"
            }
        ],
        scales: {
            x: {
                time: false,
                auto: false,
                // fn (not static array) so setData(...) re-runs it after rebuildPidTuningWindow
                // resizes the buffer — re-windows in place with no destroy/recreate.
                // Fixed [-width, 0] with the right edge pinned at 0, NOT data-driven [x[0], x[last]]:
                // applyInterp() slides x[last] left then snaps it back each packet, which a data-driven
                // range renders as an x-axis tick shiver. Width derived from the buffer tracks the window.
                range: () => { const w = (xTime && xTime > 0) ? xTime : 60; return [-w, 0]; }   // selected window, NOT buffer span — 5-min buffer holds history, this draws the visible slice
            },
            amps: {
                // Default auto (NOT auto:false): uPlot only refreshes the data min/max it
                // passes here when the scale is auto, which the auto-fit branch needs.
                // Manual (auto off) returns the firmware yyMin/yyMax; lock pins the frozen range.
                range: (u, mn, mx) => pidAmpsLock ? pidAmpsLock
                    : (pidAmpsAuto ? stableAutoRange(mn, mx, 0.1) : [yyMin, yyMax])
            },
            duty: {
                auto: false,
                range: () => pidDutyRange || [-25, 105]   // fn, not array: same reason
            }
        },
        axes: [
            {
                label: "Seconds Ago",
                grid: { show: true }
            },
            {
                scale: "amps",
                label: "Current (A) / RPM (/100)",
                grid: { show: true },
                side: 3,
                // corners always labeled (manual yyMin/yyMax or the auto-fit endpoints)
                splits: edgeLabeledSplits(() => true)
            },
            {
                scale: "duty",
                label: "Duty Cycle (%)",
                grid: { show: true },
                side: 1,
                // default [-25,105] is style padding, not a user range — nice ticks for it
                splits: edgeLabeledSplits(() => pidDutyRange != null)
            }
        ],
        legend: {
            show: false
        },
        plugins: [{
            hooks: {
                init: [
                    (u) => {
                        createPidTuningLegend(u);

                        const resizePlot = debounce(() => {
                            const plotEl = document.getElementById("pid-tuning-plot");
                            if (plotEl && pidTuningPlot) {
                                pidTuningPlot.setSize({ width: plotEl.clientWidth, height: 400 });
                            }
                        }, 150);

                        if (pidTuningResizeObserver) {
                            pidTuningResizeObserver.disconnect();
                        }
                        pidTuningResizeObserver = new ResizeObserver(resizePlot);
                        pidTuningResizeObserver.observe(plotEl);
                    }
                ],
                drawClear: [
                    (u) => {
                        if (!u.root || u.root.offsetParent === null) return;
                        drawPidWatermark(u);
                    }
                ]
            }
        }]
    };

    pidTuningPlot = new uPlot(opts, pidTuningData, plotEl);
    if (document.body.classList.contains('dark-mode')) updateUplotTheme(pidTuningPlot);

    // Corner auto checkbox + lock — same convention as the Plots tab. The checkbox
    // drives the left Current axis: checked = auto-fit, unchecked = the firmware
    // yyMin/yyMax. Checking also returns the right Duty axis to its default range.
    // Lock freezes the current auto range while data streams. The checkbox is the
    // only way back to auto-fit — no hidden clear-the-box gesture.
    plotEl.style.position = 'relative';
    const exPidAs = plotEl.querySelector('.autoscale-ctrl'); if (exPidAs) exPidAs.remove();
    pidAmpsLock = null;
    const pidAsDiv = document.createElement('div');
    pidAsDiv.className = 'autoscale-ctrl';
    pidAsDiv.style.cssText = 'position:absolute;top:6px;right:8px;z-index:10;display:flex;flex-direction:column;align-items:flex-end;gap:2px;font-size:11px;';
    pidAsDiv.innerHTML = '<div style="display:flex;align-items:center;gap:3px;opacity:0.6;"><input type="checkbox" id="autoscale-pid-cb" style="cursor:pointer;width:12px;height:12px;margin:0;"><label for="autoscale-pid-cb" style="cursor:pointer;user-select:none;">auto</label></div><button id="lock-pid-btn" style="display:none;font-size:10px;padding:0 5px;cursor:pointer;border:1px solid #999;border-radius:2px;background:transparent;opacity:0.6;line-height:16px;">lock</button>';
    plotEl.appendChild(pidAsDiv);
    const pidAsCb = document.getElementById('autoscale-pid-cb');
    const pidLockBtn = document.getElementById('lock-pid-btn');
    const pidResetLock = () => { pidAmpsLock = null; pidLockBtn.textContent = 'lock'; pidLockBtn.style.opacity = '0.6'; };
    pidAsCb.checked = pidAmpsAuto;
    pidLockBtn.style.display = pidAmpsAuto ? '' : 'none';   // lock only relevant while auto is on
    pidAsCb.addEventListener('change', e => {
        pidAmpsAuto = e.target.checked;
        localStorage.setItem('pidAmpsAuto', pidAmpsAuto);
        pidResetLock();
        if (pidAmpsAuto) {
            pidDutyRange = null; localStorage.removeItem('pidDutyRange');   // duty back to default
            pidLockBtn.style.display = '';
        } else if (pidTuningPlot) {
            // leaving auto: amps falls back to firmware yyMin/yyMax; pin duty to what's shown
            pidDutyRange = [pidTuningPlot.scales.duty.min, pidTuningPlot.scales.duty.max];
            localStorage.setItem('pidDutyRange', JSON.stringify(pidDutyRange));
            pidLockBtn.style.display = 'none';
        }
        if (pidTuningPlot) pidTuningPlot.setData(pidTuningData);
    });
    pidLockBtn.addEventListener('click', () => {
        if (!pidAmpsAuto) return;            // lock only applies while auto is on
        if (pidAmpsLock) { pidResetLock(); }
        else if (pidTuningPlot) {            // freeze the current auto range
            pidAmpsLock = [pidTuningPlot.scales.amps.min, pidTuningPlot.scales.amps.max];
            pidLockBtn.textContent = 'unlock'; pidLockBtn.style.opacity = '1';
        }
        if (pidTuningPlot) pidTuningPlot.setData(pidTuningData);
    });

    // Click-to-edit Y limits: amps axis saves to the regulator (yyMin/yyMax,
    // same as the form fields below) and unchecks auto; duty axis is a local override.
    attachYAxisEdit(pidTuningPlot, [
        {
            scale: 'amps', decimals: 0,
            apply: (mn, mx) => {
                yyMin = Math.round(mn); yyMax = Math.round(mx);
                pidAmpsAuto = false; localStorage.setItem('pidAmpsAuto', 'false');
                pidAsCb.checked = false; pidResetLock(); pidLockBtn.style.display = 'none';
                pidTuningPlot.setScale('amps', { min: yyMin, max: yyMax });
                sendYAxisSetting({ yyMin: yyMin, yyMax: yyMax });
            }
        },
        {
            scale: 'duty', decimals: 0,
            apply: (mn, mx) => {
                pidDutyRange = [mn, mx];
                localStorage.setItem('pidDutyRange', JSON.stringify(pidDutyRange));
                pidTuningPlot.setScale('duty', { min: mn, max: mx });
            }
        }
    ]);
}

// Resize the PID rolling window WITHOUT recreating the plot: rebuild the x axis at
// the new length, right-align the newest overlapping samples (shrink keeps the newest
// tail; grow pads the past with zeros), and let setData re-run the range fns. The plot
// DOM, autoscale/lock controls, legend, and Y-edit boxes all survive untouched.
// (Mirrors rebuildCVTuningWindow — destroy/recreate flashed and jumped the plot.)
function rebuildPidTuningWindow() {
    const old = pidTuningData;
    initPidTuningDataStructures();
    if (old && pidTuningData) {
        const oldN = old[1].length, newN = pidTuningData[1].length;
        const n = Math.min(oldN, newN);
        for (let s = 1; s <= 6; s++)
            for (let i = 0; i < n; i++)
                pidTuningData[s][newN - 1 - i] = old[s][oldN - 1 - i];
    }
    if (pidTuningPlot) pidTuningPlot.setData(pidTuningData);
}

// X-window buttons under the PID plot. Re-windows in place and persists xTime to the
// regulator (firmware-backed setting, unlike the CV plot's JS-only cvXTime).
function setPIDXTime(val) {
    const v = parseFloat(val);
    if (!isFinite(v) || v <= 0) return;
    xTime = v;
    cachedXTime = v;        // pre-match the CSV3 echo so it doesn't double-rebuild
    // Re-window in place: buffer already holds 5 min, just re-run the x-range fn — no realloc, no history loss.
    if (pidTuningPlot && pidTuningData) pidTuningPlot.setData(pidTuningData, true);
    updatePIDXButtons();
    sendYAxisSetting({ xTime: v });   // persist on the regulator (NVS) + echo to other clients
}

// Light the button matching the active xTime window.
function updatePIDXButtons() {
    const eff = (xTime && xTime > 0) ? xTime : 60;
    document.querySelectorAll('#pidXTimeButtons button').forEach(b => {
        b.classList.toggle('on', Number(b.value) === Number(eff));   // segmented-control active pill
    });
}

// Custom legend with checkboxes for PID tuning plot
function createPidTuningLegend(u) {
    const plotContainer = document.getElementById('pid-tuning-plot');
    if (!plotContainer) return;

    const existingLegend = plotContainer.querySelector('.custom-legend');
    if (existingLegend) {
        existingLegend.remove();
    }

    const legendDiv = document.createElement('div');
    legendDiv.className = 'custom-legend';
    legendDiv.style.cssText = `
        display: flex;
        justify-content: center;
        gap: 15px;
        margin-top: 10px;
        flex-wrap: wrap;
    `;

    const legendItems = [
        { key: 'setpointLimited', label: 'Setpoint (slewed)', color: '#FF6B6B', seriesIdx: 1 },
        { key: 'pidInput', label: 'Measured Current (PID input)', color: '#4CAF50', seriesIdx: 2 },
        { key: 'uTargetAmps', label: 'Setpoint (raw)', color: '#FFA726', seriesIdx: 3 },
        { key: 'dutyCycle', label: 'Duty Applied', color: '#2196F3', seriesIdx: 4 },
        { key: 'pidOutput', label: 'PID Output', color: '#9C27B0', seriesIdx: 5 },
        { key: 'rpm', label: 'RPM / 100', color: '#00BCD4', seriesIdx: 6 },
    ];

    legendItems.forEach(item => {
        const legendItem = document.createElement('label');
        legendItem.style.cssText = `
            display: flex;
            align-items: center;
            gap: 6px;
            font-size: 12px;
            cursor: pointer;
            user-select: none;
        `;

        const checkbox = document.createElement('input');
        checkbox.type = 'checkbox';
        checkbox.checked = pidTuningSeriesVisible[item.key];
        checkbox.style.cssText = `
            cursor: pointer;
            margin: 0;
        `;

        checkbox.addEventListener('change', () => {
            pidTuningSeriesVisible[item.key] = checkbox.checked;
            togglePidTuningSeries(item.seriesIdx, item.color, checkbox.checked);
        });

        const colorBox = document.createElement('div');
        colorBox.style.cssText = legendSwatchCss(item.color, seriesDashOf(u, item.seriesIdx));
        colorBox.style.opacity = pidTuningSeriesVisible[item.key] ? 1 : 0.3;

        const span = document.createElement('span');
        span.textContent = item.label;
        span.style.cssText = `
            color: var(--text-dark);
            opacity: ${pidTuningSeriesVisible[item.key] ? 1 : 0.5};
        `;

        legendItem.appendChild(checkbox);
        legendItem.appendChild(colorBox);
        legendItem.appendChild(span);
        legendDiv.appendChild(legendItem);
    });

    plotContainer.appendChild(legendDiv);
}

function togglePidTuningSeries(seriesIdx, color, visible) {
    if (!pidTuningPlot) {
        return;
    }
    // Use show property instead of stroke
    pidTuningPlot.setSeries(seriesIdx, {
        show: visible
    });
    const legendItems = document.querySelectorAll('.custom-legend label');
    const itemIndex = seriesIdx - 1;

    if (legendItems[itemIndex]) {
        const colorBox = legendItems[itemIndex].querySelector('div');
        const label = legendItems[itemIndex].querySelector('span');
        if (colorBox) colorBox.style.opacity = visible ? 1 : 0.3;
        if (label) label.style.opacity = visible ? 1 : 0.5;
    }
}

// Plot update batching for PID tuning
let pidTuningUpdateScheduled = false;

function queuePidTuningPlotUpdate() {
    if (pidTuningUpdateScheduled) return;

    pidTuningUpdateScheduled = true;
    requestAnimationFrame(() => {
        if (pidTuningPlot && pidTuningData) {
            pidTuningPlot.setData(pidTuningData);
        }
        pidTuningUpdateScheduled = false;
    });
}

function updatePidTuningConfiguration(data) {
    let axisChanged = false;
    let timeChanged = false;

    if (data.yyMin !== undefined && data.yyMin !== yyMin) {
        yyMin = data.yyMin;
        axisChanged = true;
    }
    if (data.yyMax !== undefined && data.yyMax !== yyMax) {
        yyMax = data.yyMax;
        axisChanged = true;
    }

    if (data.xTime !== undefined && !isNaN(data.xTime) && data.xTime > 0 && data.xTime !== xTime) {
        xTime = data.xTime;
        timeChanged = true;
    }

    if (timeChanged) {
        // Re-window in place — no destroy/recreate (avoids the plot flash/jump on echo)
        rebuildPidTuningWindow();
        updatePIDXButtons();
    } else if (axisChanged && pidTuningPlot) {
        // Re-range in place — recreate caused a page jump on every Y edit echo
        pidTuningPlot.setScale('amps', { min: yyMin, max: yyMax });
    }
}

// Sync dual-control parameters between tabs
function syncDualControlParameters(batteryAh, solarWatts) {
    const vesselForm = document.getElementById('vessel-info-form');
    if (vesselForm) {
        if (batteryAh !== undefined) vesselForm.BATTERY_CAPACITY_AH.value = batteryAh;
        if (solarWatts !== undefined) vesselForm.SOLAR_WATTS.value = solarWatts;
    }

    if (window.vesselInfo) {
        if (batteryAh !== undefined) window.vesselInfo.battery_capacity_ah = batteryAh;
        if (solarWatts !== undefined) window.vesselInfo.solar_watts = solarWatts;
    }
}


function interceptDualControlSubmissions() {
    document.querySelectorAll('form[action="/get"]').forEach(form => {
        const batteryInput = form.querySelector('input[name="BatteryCapacity_Ah"]');
        const solarInput = form.querySelector('input[name="SolarWatts"]');

        if (batteryInput || solarInput) {
            form.addEventListener('submit', function (e) {
                // Let form submit normally (to ESP32)
                // But ALSO update our cache and other tab
                setTimeout(() => {
                    if (batteryInput) {
                        const value = parseInt(batteryInput.value);
                        syncDualControlParameters(value, undefined);
                    }
                    if (solarInput) {
                        const value = parseInt(solarInput.value);
                        syncDualControlParameters(undefined, value);
                    }
                }, 100); // Small delay to let form submit
            });
        }
    });
}

function populateYearDropdown() {
    const yearSelect = document.querySelector('[name="BOAT_YEAR"]');
    if (yearSelect) {
        // Range: 1900 floor (no real recreational boats older), current year + 5
        // ceiling so the dropdown is still valid for the next 5 calendar years
        // without a code change. Descending order puts the most-likely selections
        // near the top. Default selection is the current calendar year.
        const currentYear = new Date().getFullYear();
        for (let year = currentYear + 5; year >= 1900; year--) {
            const option = document.createElement('option');
            option.value = year;
            option.textContent = year;
            if (year === currentYear) {
                option.selected = true;
            }
            yearSelect.appendChild(option);
        }
    }
}

