let tuningBodePollTimer = null;

// Register a pending toggle + set a hidden input without a checkbox (button-driven toggles). Mirrors
// what handleUserToggle does, but the unified Begin/Stop Test button has no checkbox to read from.
function setPendingToggleValue(hiddenInputId, dataKey, value) {
    const hiddenInput = document.getElementById(hiddenInputId);
    if (hiddenInput) hiddenInput.value = String(value);
    pendingToggles.set(dataKey, { desiredValue: parseInt(value), baseRev: lastSeenRev });
}

// Swap the unified Begin Test button between its idle and running states. Used for ALL three waveform
// types — Square / Sine manual run until Stop Test; Sine sweep also flips back when it self-completes.
function _setTestBtnRunning(running) {
    const btn = document.getElementById('tuningBeginTestBtn');
    if (!btn) return;
    if (running) {
        btn.textContent = '■ Stop Test';
        btn.classList.remove('btn-primary');
        btn.classList.add('btn-danger');
        btn.onclick = tuningStopTest;
    } else {
        btn.textContent = '▶ Begin Test';
        btn.classList.remove('btn-danger');
        btn.classList.add('btn-primary');
        btn.onclick = tuningToggleTest;
    }
}

// Single entry point for the Current Target Generator.
// The Waveform Type selector decides what runs: 0 square / 1 sine manual
// arm the generator and run continuously until Stop; 2 sine sweep arms then fires the closed-loop
// frequency sweep. Pressing again while running (Stop Test) disarms.
function tuningToggleTest() {
    if (!currentAdminPassword) { xAlert("Please unlock settings first."); return; }
    // Already running → this press is a Stop.
    if (parseInt(getField("TuningMode") ?? 0) === 1) { tuningStopTest(); return; }

    // Another loop's test must not be running.
    const conflict = getActiveTestKey();
    if (conflict && conflict !== 'curr') {
        xAlert((TEST_PANEL_META[conflict]?.title ?? conflict) + ' is already running.\n\nTurn it off before starting another test.');
        return;
    }

    const pw = encodeURIComponent(currentAdminPassword);
    const waveform = parseInt(getField("tuningWaveform_sel") ?? 0);  // 0 square / 1 sine manual / 2 sine sweep
    const statusEl = document.getElementById('tuning-sweep-status');

    // Optimistically reflect the armed state, register the pending toggle so the stream echo doesn't
    // bounce it back, then send the arm command (TuningMode=1 is all square/sine-manual need to run).
    setPendingToggleValue('TuningMode', 'TuningMode', 1);
    _setTestBtnRunning(true);

    if (waveform === 2) {
        if (statusEl) statusEl.textContent = 'Arming…';
        fetch(buildURL("/get?TuningMode=1&password=" + pw))
            .then(() => _startTuningSweepNow(pw))
            .catch(err => { if (statusEl) statusEl.textContent = 'Arm failed: ' + err; _setTestBtnRunning(false); });
    } else {
        if (statusEl) statusEl.textContent = 'Running…';
        fetch(buildURL("/get?TuningMode=1&password=" + pw))
            .catch(err => { if (statusEl) statusEl.textContent = 'Start failed: ' + err; _setTestBtnRunning(false); });
    }
}

// Fire the sweep and poll /tuningbode until it completes. Assumes the generator is already armed.
function _startTuningSweepNow(pw) {
    const statusEl = document.getElementById('tuning-sweep-status');
    fetch(buildURL("/get?startTuningSweep=1&password=" + pw))
        .then(r => {
            if (!r.ok) { if (statusEl) statusEl.textContent = 'Start failed (HTTP ' + r.status + ')'; return; }
            if (statusEl) statusEl.textContent = 'Sweep running…';
            _setTestBtnRunning(true);
            const bsec = document.getElementById('tuning-bode-section'); if (bsec) bsec.style.display = 'none';
            if (tuningBodePollTimer) clearInterval(tuningBodePollTimer);
            let waited = 0;
            tuningBodePollTimer = setInterval(() => {
                waited += 1500;
                fetch(buildURL('/tuningbode'))
                    .then(r => r.ok ? r.json() : null)
                    .then(data => {
                        if (!data) return;
                        if (statusEl) statusEl.textContent = data.active
                            ? ('Sweep running… ' + (data.pts ? data.pts.length : 0) + '/10')
                            : (data.done ? 'Sweep complete.' : 'Idle');
                        if (data.done && !data.active) {
                            clearInterval(tuningBodePollTimer); tuningBodePollTimer = null;
                            // Sweep finished — disarm the generator so the button returns to "Begin Test".
                            // A completed sweep is a finished test (unlike square/sine-manual, which stay
                            // armed until the user presses Stop).
                            setPendingToggleValue('TuningMode', 'TuningMode', 0);
                            fetch(buildURL("/get?TuningMode=0&password=" + pw)).catch(() => {});
                            _setTestBtnRunning(false);
                            renderTuningBode(data);
                        }
                    })
                    .catch(() => {});
                if (waited > 180000) {
                    clearInterval(tuningBodePollTimer); tuningBodePollTimer = null;
                    setPendingToggleValue('TuningMode', 'TuningMode', 0);
                    fetch(buildURL("/get?TuningMode=0&password=" + pw)).catch(() => {});
                    _setTestBtnRunning(false);
                    if (statusEl) statusEl.textContent = 'Timed out.';
                }
            }, 1500);
        })
        .catch(err => { if (statusEl) statusEl.textContent = 'Start failed: ' + err; });
}

// Stop the current test by disarming the generator — works for square, sine-manual, and a running sweep.
function tuningStopTest() {
    const pw = encodeURIComponent(currentAdminPassword || '');
    setPendingToggleValue('TuningMode', 'TuningMode', 0);
    fetch(buildURL("/get?TuningMode=0&password=" + pw)).catch(() => {});
    if (tuningBodePollTimer) { clearInterval(tuningBodePollTimer); tuningBodePollTimer = null; }
    const statusEl = document.getElementById('tuning-sweep-status');
    if (statusEl) statusEl.textContent = 'Stopped.';
    _setTestBtnRunning(false);
}

// Reflect firmware TuningMode state onto the unified Begin/Stop button + hidden input, honoring any
// in-flight optimistic toggle so the stream echo doesn't bounce it (same pattern as updateCheckbox).
// Catches reboot-with-generator-on and disarms triggered by another client.
function updateTuningModeUI(value) {
    if (value === undefined) return;
    const pending = pendingToggles.get("TuningMode");
    if (pending) {
        if (pending.deadlineMs === undefined) pending.deadlineMs = Date.now() + 2500;
        if (value !== pending.desiredValue) {
            if (Date.now() <= pending.deadlineMs) return;   // keep optimistic UI
            pendingToggles.delete("TuningMode");            // timed out → accept firmware state
        } else {
            pendingToggles.delete("TuningMode");            // confirmed
        }
    }
    const hidden = document.getElementById("TuningMode");
    if (hidden) hidden.value = String(value);
    toggleStates["TuningMode"] = value;
    const btn = document.getElementById('tuningBeginTestBtn');
    if (!btn) return;
    const btnRunning = btn.classList.contains('btn-danger');
    if (value === 1 && !btnRunning) _setTestBtnRunning(true);
    if (value !== 1 && btnRunning) {
        _setTestBtnRunning(false);
        if (tuningBodePollTimer) { clearInterval(tuningBodePollTimer); tuningBodePollTimer = null; }
        const statusEl = document.getElementById('tuning-sweep-status');
        if (statusEl && statusEl.textContent === 'Running…') statusEl.textContent = '';
    }
}

function renderTuningBode(data) {
    const sec  = document.getElementById('tuning-bode-section');
    const body = document.getElementById('tuning-bode-body');
    const sum  = document.getElementById('tuning-bode-summary');
    if (sec) sec.style.display = '';
    if (document.getElementById('tuningSweepLogSection')?.open) fetchTuningSweepLog();
    if (!data || !data.pts || !data.pts.length) {
        if (body) body.innerHTML = '<tr><td colspan="3" style="padding:6px 4px; color:#f0a500;">No Bode data.</td></tr>';
        return;
    }
    const pts = data.pts;
    const g0 = Math.max(1e-9, pts[0].g);   // low-frequency reference gain (≈1 for good tracking)
    if (body) body.innerHTML = pts.map(p => {
        const rel   = p.g / g0;
        const relDb = 20 * Math.log10(Math.max(1e-6, rel));
        const col   = rel < 0.708 ? '#f0a500' : '#4caf50';
        return '<tr style="border-bottom:1px solid #333;">' +
            '<td style="padding:6px 4px;">' + p.f.toFixed(2) + '</td>' +
            '<td style="padding:6px 4px; color:' + col + ';">' + rel.toFixed(2) + ' (' + relDb.toFixed(1) + ' dB)</td>' +
            '<td style="padding:6px 4px;">' + p.ph.toFixed(0) + '</td></tr>';
    }).join('');
    // Log-frequency interpolation of the −3 dB crossing (points are log-spaced) — matches the
    // open-loop FOPDT fit and the firmware-logged value so all three readouts agree.
    let f3 = null;
    for (let i = 1; i < pts.length; i++) {
        const relPrev = pts[i - 1].g / g0, relCur = pts[i].g / g0;
        if (relPrev >= 0.708 && relCur < 0.708) {
            const lf0 = Math.log(pts[i - 1].f), lf1 = Math.log(pts[i].f);
            const t = (0.708 - relPrev) / (relCur - relPrev);
            f3 = Math.exp(lf0 + t * (lf1 - lf0));
            break;
        }
    }
    if (sum) sum.innerHTML = f3
        ? 'Closed-loop −3 dB bandwidth: <strong>~' + f3.toFixed(1) + ' Hz</strong> — the fastest setpoint motion your tuned PID can follow. Compare with the Plant Delay sine Bode: the gap is how much the feedback extended the raw plant.'
        : 'Tracking held to the top of the sweep — raise Sweep End to find the closed-loop bandwidth.';
}

function openSystemIDModal() {
    if (!currentAdminPassword) {
        xAlert("Please unlock settings first.");
        return;
    }
    // Reset panel position to default top-right on each open
    const panel = document.getElementById('sysid-modal-panel');
    if (panel) { panel.style.left = ''; panel.style.top = '80px'; panel.style.right = '20px'; }
    const overlay = document.getElementById('sysid-modal-overlay');
    overlay.classList.remove('sysid-min', 'sysid-running');   // always open expanded
    sysidShowScreen('preflight');
    overlay.style.display = 'block';
    sysidInitDrag();
    sysidUpdatePreflight();
    sysidPreflightInterval = setInterval(sysidUpdatePreflight, 1000);
}

function closeSystemIDModal() {
    const overlay = document.getElementById('sysid-modal-overlay');
    overlay.style.display = 'none';
    overlay.classList.remove('sysid-min', 'sysid-running');
    if (sysidPreflightInterval) { clearInterval(sysidPreflightInterval); sysidPreflightInterval = null; }
    if (sysidPollInterval)      { clearInterval(sysidPollInterval);      sysidPollInterval = null; }
}

// Minimize (mobile) — collapse the sheet to a progress pill and reveal the live
// current plot behind it (same Plots-tab switch the test-start already does).
function sysidMinimize() {
    const ov = document.getElementById('sysid-modal-overlay');
    if (!ov) return;
    ov.classList.add('sysid-min');
    if (!ov.classList.contains('sysid-running')) {
        const resultsScreen = document.getElementById('sysid-screen-results');
        const onResults = resultsScreen && resultsScreen.style.display !== 'none';
        sysidUpdatePill(onResults ? 'Results ready · tap to expand' : 'tap to expand',
                        onResults ? 100 : null);
    }
    if (vesselInfoComplete && typeof showMainTab === 'function') showMainTab('plots');
}

function sysidRestore() {
    const ov = document.getElementById('sysid-modal-overlay');
    if (ov) ov.classList.remove('sysid-min');
}

// Update the minimized pill's phase label + progress bar/percent.
// pct null -> blank bar/percent (idle/preflight); otherwise 0-100.
function sysidUpdatePill(phaseText, pct) {
    const ph   = document.getElementById('sysid-pill-phase');
    const fill = document.getElementById('sysid-pill-bar-fill');
    const pctEl = document.getElementById('sysid-pill-pct');
    if (ph)   ph.textContent = phaseText;
    if (fill) fill.style.width = (pct == null ? 0 : pct) + '%';
    if (pctEl) pctEl.textContent = (pct == null ? '' : Math.round(pct) + '%');
}

function sysidRunAgain() {
    if (sysidPollInterval) { clearInterval(sysidPollInterval); sysidPollInterval = null; }
    const applyBtn = document.getElementById('sysid-apply-btn');
    if (applyBtn) applyBtn.style.display = '';
    sysidShowScreen('preflight');
    sysidUpdatePreflight();
    if (!sysidPreflightInterval) {
        sysidPreflightInterval = setInterval(sysidUpdatePreflight, 1000);
    }
}

function sysidShowAborted(msg) {
    document.getElementById('sysid-modal-overlay').classList.remove('sysid-running');
    sysidRestore();   // auto-expand so the abort reason is visible, not buried in the pill
    const tbody = document.getElementById('sysid-results-body');
    if (tbody) tbody.innerHTML = '';
    document.getElementById('sysid-results-summary').textContent = '';
    const warnEl = document.getElementById('sysid-results-warning');
    if (warnEl) { warnEl.textContent = msg; warnEl.style.display = ''; }
    const applyBtn = document.getElementById('sysid-apply-btn');
    if (applyBtn) applyBtn.style.display = 'none';
    sysidShowScreen('results');
}

function sysidShowScreen(name) {
    document.getElementById('sysid-screen-preflight').style.display = (name === 'preflight') ? '' : 'none';
    document.getElementById('sysid-screen-progress').style.display  = (name === 'progress')  ? '' : 'none';
    document.getElementById('sysid-screen-results').style.display   = (name === 'results')   ? '' : 'none';
    // Results is the tallest screen; re-clamp so a panel dragged low (while a
    // short screen was showing) can't grow off the bottom of the viewport.
    sysidClampPanel();
}

// Keep the floating panel fully on screen. max-height caps its height to the
// viewport; this nudges its top (and left, once dragged) back inside the edges
// so the bottom — and the action buttons there — never fall below the fold.
function sysidClampPanel() {
    if (window.innerWidth <= 600) return;   // mobile = CSS bottom sheet, no JS positioning
    const panel = document.getElementById('sysid-modal-panel');
    if (!panel || panel.offsetParent === null) return;   // not visible
    const maxTop = Math.max(0, window.innerHeight - panel.offsetHeight);
    let top = parseFloat(panel.style.top);
    if (isNaN(top)) top = panel.getBoundingClientRect().top;
    panel.style.top = Math.min(Math.max(0, top), maxTop) + 'px';
    // Only manage left once the panel has been dragged (drag sets right:auto);
    // otherwise leave it anchored to the right edge.
    if (panel.style.right === 'auto') {
        const maxLeft = Math.max(0, window.innerWidth - panel.offsetWidth);
        let left = parseFloat(panel.style.left);
        if (isNaN(left)) left = panel.getBoundingClientRect().left;
        panel.style.left = Math.min(Math.max(0, left), maxLeft) + 'px';
    }
}

function sysidUpdatePreflight() {
    const rpm     = parseFloat(getField("RPMID") ?? 0);
    const minRpm  = parseFloat(getField("MinRPMForField_echo") ?? 500);
    const amps    = parseFloat(getField("MeasAmpsID") ?? 0);
    const battV   = parseFloat(getField("IBVID") ?? getField("BatteryVID") ?? 0);
    const bulkV   = parseFloat(getField("BulkVoltage_echo") ?? 14.8);

    const rpmOK   = rpm >= minRpm;
    const ampsOK  = amps > 2.0;
    const voltOK  = battV > 11.0 && battV < (bulkV - 0.3);

    const stage   = gLastChargeStage;
    const modeOK  = (stage === CS_BULK || stage === CS_ABSORPTION || stage === CS_FLOAT || stage === CS_TARGET_V);
    const stageLabel = {
        [CS_BULK]:       'Bulk',
        [CS_ABSORPTION]: 'Absorption',
        [CS_FLOAT]:      'Float',
        [CS_TARGET_V]:   'Target Voltage',
        [CS_MAINTAIN]:   'Maintain',
        [CS_IDLE]:       'Idle',
        [CS_MANUAL]:     'Manual',
        [CS_COMMISSION]: 'Commissioning',
    }[stage] ?? null;
    const modeMsg = modeOK
        ? '✅ Mode: ' + stageLabel + ' — OK to run (no limits enforced during test)'
        : (stage === CS_MANUAL
            ? '❌ Mode: Manual — not available in manual mode (duty is fixed; test cannot drive the field)'
            : (stageLabel
                ? '❌ Mode: ' + stageLabel + ' — charging must be active (not idle or maintain)'
                : '❌ Mode: Charging not active'));

    // Mutex check: refuse start if any square-wave tuning test is on. Firmware enforces this too;
    // this preflight row just makes the reason visible before the user clicks Start. Read the raw
    // hidden <input> value (not the _echo span, which contains "On"/"Off" text).
    const tuningOn = parseInt(getField("TuningMode") ?? 0) === 1;
    const cvTuningOn = parseInt(getField("CVTuningMode") ?? 0) === 1;
    const testsOK = !tuningOn && !cvTuningOn;
    const activeTestName = tuningOn ? 'Current tuning'
                                    : (cvTuningOn ? 'Voltage tuning' : null);
    const testsMsg = testsOK
        ? '✅ No other tuning tests active'
        : '❌ ' + activeTestName + ' is on — turn it off first';

    const allOK   = rpmOK && ampsOK && voltOK && modeOK && testsOK;

    document.getElementById('sysid-check-rpm').textContent   = (rpmOK  ? '✅' : '❌') + ' Engine running (RPM: ' + rpm.toFixed(0) + ' / min ' + minRpm.toFixed(0) + ')';
    document.getElementById('sysid-check-amps').textContent  = (ampsOK ? '✅' : '❌') + ' Alternator producing current (' + amps.toFixed(1) + 'A)';
    document.getElementById('sysid-check-volt').textContent  = (voltOK ? '✅' : '❌') + ' Battery voltage OK (' + battV.toFixed(2) + 'V)';
    document.getElementById('sysid-check-mode').textContent  = modeMsg;
    document.getElementById('sysid-check-tests').textContent = testsMsg;

    // Swap the preflight copy + duration estimate to match the selected test type.
    // (Progress and Results screens switch themselves elsewhere; this is the only
    // screen whose text was step-only.)
    const isSine = parseInt(getField("systemIDTestType_sel") ?? 0) === 1;
    const setDisp = (id, show) => { const el = document.getElementById(id); if (el) el.style.display = show ? '' : 'none'; };
    setDisp('sysid-intro-step',    !isSine);
    setDisp('sysid-intro-sine',     isSine);
    setDisp('sysid-warn-amp-step', !isSine);
    setDisp('sysid-warn-amp-sine',  isSine);
    const titleEl = document.getElementById('sysid-preflight-title');
    if (titleEl) titleEl.textContent = isSine ? 'Plant Frequency Response' : 'Plant Delay Measurement';

    // Estimated duration. Step: 20s stabilize overhead + 7 hold phases.
    // Sine: 20s stabilize + sum over the log-spaced sweep of (1 settle + N analysed)
    // cycles per point, floored at 1.5s each — mirrors the firmware and the progress poll.
    let estSec;
    if (isSine) {
        const f0  = Math.max(0.1, parseFloat(getField("systemIDSineFreqStart_echo") ?? 0.5));
        const f1  = Math.max(f0 + 0.1, parseFloat(getField("systemIDSineFreqEnd_echo") ?? 20));
        const cyc = Math.max(2, parseInt(getField("systemIDSineCycles_echo") ?? 6));
        const N   = 10;  // SYSID_SINE_NPOINTS
        let ms = 20000;
        for (let i = 0; i < N; i++) {
            const f = f0 * Math.pow(f1 / f0, i / (N - 1));
            ms += Math.max(1500, (1 + cyc) * 1000 / f);
        }
        estSec = Math.round(ms / 1000);
    } else {
        const tcMs   = parseFloat(getField("InputFilterTC_echo") ?? 1000);
        const holdMs = Math.max(15 * tcMs, 5000);
        estSec = Math.round(20 + 7 * holdMs / 1000);
    }
    const estStr = estSec >= 90 ? (estSec / 60).toFixed(1) + ' min' : estSec + ' sec';
    document.getElementById('sysid-est-time').textContent = 'Estimated test duration: ~' + estStr;

    document.getElementById('sysid-start-btn').disabled = !allOK;
}

function confirmSystemIDStart() {
    if (sysidPreflightInterval) { clearInterval(sysidPreflightInterval); sysidPreflightInterval = null; }

    const formData = new URLSearchParams();
    formData.append("password", currentAdminPassword);
    formData.append("startSystemID", "1");

    fetchWithTimeout(buildURL("/get?" + formData.toString()), {}, 8000)
        .then(() => {
            console.log("SystemID test requested");
            sysidShowScreen('progress');
            sysidLastPhase = -1;
            sysidPhaseStartWall = Date.now();
            sysidStartProgressPoll();
            // Switch to Plots tab so user can watch the current waveform during the test.
            if (vesselInfoComplete) {
                showMainTab('plots');
                // On a phone, auto-minimize to the progress pill so the waveform is
                // visible by default; it auto-expands again when results land.
                if (window.innerWidth <= 600) sysidMinimize();
            }
        })
        .catch(err => {
            xAlert("Failed to send start command: " + err);
        });
}

function abortSystemIDTest() {
    if (sysidPollInterval) { clearInterval(sysidPollInterval); sysidPollInterval = null; }
    const formData = new URLSearchParams();
    formData.append("password", currentAdminPassword || '');   // abort is password-free (safety): firmware exempts cancelSystemID
    formData.append("cancelSystemID", "1");
    fetchWithTimeout(buildURL("/get?" + formData.toString()), {}, 5000)
        .then(() => console.log("SystemID: abort sent"))
        .catch(err => console.warn("SystemID abort send failed:", err));
    closeSystemIDModal();
}

function sysidStartProgressPoll() {
    const tcMs   = parseFloat(getField("InputFilterTC_echo") ?? 1000);
    const holdMs = Math.max(15 * tcMs, 5000);
    // Step model; overridden below for sine, whose sweep can run minutes (low start
    // frequency × many cycles per point) and would otherwise trip this step-sized timeout.
    let maxWaitMs = (SYSID_STABILIZE_TIMEOUT_HINT + 7 * holdMs + 10000);
    let elapsed = 0;
    let sysidEverActive = false;
    const pollMs = 400;

    // Zero out the results-ready DOM field so a stale 1 from the previous run
    // can't short-circuit the poll before the firmware's first CSV3 update arrives.
    const rrEl = document.getElementById('systemIDResultsReady_ID');
    if (rrEl) rrEl.textContent = '0';

    // Reset all phase rows
    for (let i = 1; i <= 9; i++) {
        const el = document.getElementById('sysid-p' + i);
        if (el) { el.textContent = '⬜ ' + SYSID_PHASE_NAMES[i]; el.style.color = ''; }
    }
    document.getElementById('sysid-phase-bar').style.width = '0%';
    document.getElementById('sysid-modal-overlay').classList.add('sysid-running');   // pulses the pill dot

    // Sine sweep uses its own simple progress (no 9-phase wall model). Toggle the display
    // and precompute an estimated total duration so the bar can advance smoothly.
    const sysidIsSine = parseInt(getField("systemIDTestType_sel") ?? 0) === 1;
    const sysidPhaseListEl  = document.getElementById('sysid-phase-list');
    const sysidSineStatusEl = document.getElementById('sysid-sine-status');
    if (sysidPhaseListEl)  sysidPhaseListEl.style.display  = sysidIsSine ? 'none' : '';
    if (sysidSineStatusEl) sysidSineStatusEl.style.display = sysidIsSine ? '' : 'none';
    let sysidSineEstMs = 0;
    if (sysidIsSine) {
        const f0 = Math.max(0.1, parseFloat(getField("systemIDSineFreqStart_echo") ?? 0.5));
        const f1 = Math.max(f0 + 0.1, parseFloat(getField("systemIDSineFreqEnd_echo") ?? 20));
        const cyc = Math.max(2, parseInt(getField("systemIDSineCycles_echo") ?? 6));
        const N = 10;  // SYSID_SINE_NPOINTS
        for (let i = 0; i < N; i++) {
            const f = f0 * Math.pow(f1 / f0, i / (N - 1));
            sysidSineEstMs += Math.max(1500, (1 + cyc) * 1000 / f);
        }
        sysidSineEstMs += 20000;  // stabilize overhead
        // Generous timeout: twice the estimated sweep + 60s, and never shorter than the
        // step default. Scales automatically with the sweep range/cycles the user picked.
        maxWaitMs = Math.max(maxWaitMs, sysidSineEstMs * 2 + 60000);
    }

    // Wall-clock phase advancement: once we know a phase started, we advance the bar
    // and labels by timer without waiting for the next CSV2 packet.
    // CSV2 is the authoritative sync signal — if it shows a higher phase we jump ahead.
    let wallPhase = 0;       // phase we're currently displaying (may be ahead of last CSV2)
    let wallPhaseStart = 0;  // Date.now() when wallPhase was last set

    function sysidSetWallPhase(p) {
        if (p > wallPhase) {
            wallPhase = p;
            wallPhaseStart = Date.now();
            for (const [pStr, name] of Object.entries(SYSID_PHASE_NAMES)) {
                const pNum = parseInt(pStr);
                const el = document.getElementById('sysid-p' + pNum);
                if (!el) continue;
                if (wallPhase > pNum) {
                    el.textContent = '✅ ' + name; el.style.color = '#4caf50';
                } else if (wallPhase === pNum) {
                    el.textContent = '▶ ' + name + '…'; el.style.color = '#4a9eff';
                } else {
                    el.textContent = '⬜ ' + name; el.style.color = '';
                }
            }
        }
    }

    sysidPollInterval = setInterval(() => {
        elapsed += pollMs;

        const phase = parseInt(getField("systemIDActive_ID") ?? 0);
        const ready = parseInt(getField("systemIDResultsReady_ID") ?? 0);

        if (phase > 0) sysidEverActive = true;

        if (sysidIsSine) {
            // Sine sweep: smooth estimated bar (no per-frequency telemetry needed).
            const pct = sysidSineEstMs > 0 ? Math.min(99, elapsed / sysidSineEstMs * 100) : 0;
            document.getElementById('sysid-phase-bar').style.width = pct.toFixed(0) + '%';
            document.getElementById('sysid-elapsed').textContent = 'Elapsed: ' + (elapsed / 1000).toFixed(0) + 's';
            sysidUpdatePill('Sine sweep…', pct);
        } else {
            // Sync to firmware phase if it's ahead of our wall-clock estimate
            if (phase > wallPhase) sysidSetWallPhase(phase);

            // Once a non-stabilise phase is active, advance by holdMs wall time.
            // This means the UI advances immediately even if the next CSV2 is delayed.
            if (wallPhase >= 2 && wallPhase <= 8) {
                const elapsed_in_phase = Date.now() - wallPhaseStart;
                if (elapsed_in_phase >= holdMs && wallPhase < 9) {
                    sysidSetWallPhase(wallPhase + 1);
                }
            }

            // Phase bar: for stabilize use 30s estimate, for measured phases use holdMs
            const phaseMs = (wallPhase === 1) ? 30000 : holdMs;
            const phasePct = Math.min(100, ((Date.now() - wallPhaseStart) / phaseMs) * 100);
            document.getElementById('sysid-phase-bar').style.width = phasePct.toFixed(0) + '%';

            document.getElementById('sysid-elapsed').textContent = 'Elapsed: ' + (elapsed / 1000).toFixed(0) + 's';

            // Mirror progress into the minimized pill (8-phase measured sequence; 9 = processing)
            const overallPct = Math.min(100, Math.max(0, (wallPhase - 1 + phasePct / 100) / 8 * 100));
            sysidUpdatePill((SYSID_PHASE_NAMES[wallPhase] || 'Running') + '…', overallPct);
        }

        if (ready === 1) {
            clearInterval(sysidPollInterval); sysidPollInterval = null;
            document.getElementById('sysid-modal-overlay').classList.remove('sysid-running');
            // Mark all phases complete
            for (let i = 1; i <= 9; i++) {
                const el = document.getElementById('sysid-p' + i);
                if (el) { el.textContent = '✅ ' + SYSID_PHASE_NAMES[i]; el.style.color = '#4caf50'; }
            }
            document.getElementById('sysid-phase-bar').style.width = '100%';
            sysidUpdatePill('Results ready · tap to expand', 100);
            sysidRestore();   // auto-expand the sheet so the results are front-and-centre
            setTimeout(showSystemIDResults, 400);
            return;
        }

        // Protection layer fired mid-test — firmware aborted it, results are invalid
        if (phase === 0 && ready !== 1 && sysidEverActive) {
            clearInterval(sysidPollInterval); sysidPollInterval = null;
            document.getElementById('sysid-modal-overlay').classList.remove('sysid-running');
            const reasonCode = parseInt(getField("systemIDAbortReason_ID") ?? 0);
            const abortPhase = parseInt(getField("systemIDAbortPhase_ID") ?? 0);
            const reasonText = SYSID_ABORT_REASONS[reasonCode] ?? ('reason code ' + reasonCode);
            const phaseText  = SYSID_PHASE_NAMES[abortPhase] ?? ('phase ' + abortPhase);
            const msg = (reasonCode === 0)
                ? '⚠ Test aborted — a protection layer fired mid-test. Check the Console tab for details.'
                : '⚠ Aborted at phase ' + abortPhase + ' (' + phaseText + '): ' + reasonText + '.';
            sysidShowAborted(msg);
            return;
        }

        if (elapsed > maxWaitMs) {
            clearInterval(sysidPollInterval); sysidPollInterval = null;
            xAlert("Plant Delay test timed out after " + (elapsed / 1000).toFixed(0) + "s. Check the Console tab for details.");
            closeSystemIDModal();
        }
    }, pollMs);
}

// Hint used by progress poll for stabilize phase timeout window (must match firmware #define)
const SYSID_STABILIZE_TIMEOUT_HINT = 30000;

function showSystemIDResults() {
    // Sine sweep has its own results view (open-loop Bode); the step tables don't apply.
    const sysidIsSine = parseInt(getField("systemIDTestType_sel") ?? 0) === 1;
    if (sysidIsSine) { showSysidBodeResults(); return; }
    // Step path: restore the step sections / hide the sine Bode section (a sine run may have preceded).
    const bodeSec0 = document.getElementById('sysid-bode-section'); if (bodeSec0) bodeSec0.style.display = 'none';
    const qhint0   = document.getElementById('sysid-quality-hint');  if (qhint0)   qhint0.style.display = '';
    const tlabel0  = document.getElementById('sysid-timing-label');  if (tlabel0)  tlabel0.style.display = '';
    const rtbl0    = document.getElementById('sysid-results-table'); if (rtbl0)    rtbl0.style.display = '';
    const applyBtn0 = document.getElementById('sysid-apply-btn');    if (applyBtn0) applyBtn0.style.display = '';

    const r = [
        parseFloat(getField("systemIDRiseDelay_0_ID") ?? -1),
        parseFloat(getField("systemIDRiseDelay_1_ID") ?? -1),
        parseFloat(getField("systemIDRiseDelay_2_ID") ?? -1)
    ];
    const f = [
        parseFloat(getField("systemIDFallDelay_0_ID") ?? -1),
        parseFloat(getField("systemIDFallDelay_1_ID") ?? -1),
        parseFloat(getField("systemIDFallDelay_2_ID") ?? -1)
    ];
    // Step amplitude and noise: firmware sends ×10 integers, divide to get amps with 0.1A res
    const stepAmp = [
        parseFloat(getField("systemIDStepAmp_0_ID") ?? 0) / 10,
        parseFloat(getField("systemIDStepAmp_1_ID") ?? 0) / 10,
        parseFloat(getField("systemIDStepAmp_2_ID") ?? 0) / 10,
    ];
    const quietPP = [
        parseFloat(getField("systemIDQuietPP_0_ID") ?? 0) / 10,
        parseFloat(getField("systemIDQuietPP_1_ID") ?? 0) / 10,
        parseFloat(getField("systemIDQuietPP_2_ID") ?? 0) / 10,
    ];
    const ra = parseFloat(getField("systemIDRiseAvg_ID") ?? -1);
    const fa = parseFloat(getField("systemIDFallAvg_ID") ?? -1);

    // Recommended TC = highest single trial across all rise and fall measurements.
    // Using the worst-case individual reading (not the average) ensures the filter
    // is always long enough to cover the slowest response the plant actually showed.
    const allValid = [...r, ...f].filter(v => v >= 0);
    sysidSuggestedTC = allValid.length > 0 ? Math.max(...allValid) : 0;

    // ── Quality table ────────────────────────────────────────────────────────────
    // Step amplitude: pass > 10A. Noise peak-to-peak: green < 1A, yellow 1–2A, red ≥ 2A.
    const hasQuality = stepAmp.some(v => v > 0);
    const qTbody = document.getElementById('sysid-quality-body');
    if (qTbody) {
        qTbody.innerHTML = '';
        for (let i = 0; i < 3; i++) {
            const ampOk    = stepAmp[i] > 10;
            const noiseOk  = quietPP[i] < 1.0;
            const noiseMed = quietPP[i] < 2.0;
            const ampColor   = ampOk  ? '#4caf50' : '#ef4444';
            const noiseColor = noiseOk ? '#4caf50' : (noiseMed ? '#f0a500' : '#ef4444');
            const ampLabel   = hasQuality ? stepAmp[i].toFixed(1) + ' A' : '—';
            const noiseLabel = hasQuality ? quietPP[i].toFixed(1) + ' A' : '—';
            const tr = document.createElement('tr');
            tr.style.borderBottom = '1px solid #2a2a2a';
            tr.innerHTML =
                '<td style="padding:5px 4px; color:#aaa;">Trial ' + (i + 1) + '</td>' +
                '<td style="padding:5px 4px; color:' + ampColor   + '; font-weight:600;">' + ampLabel   + '</td>' +
                '<td style="padding:5px 4px; color:' + noiseColor + '; font-weight:600;">' + noiseLabel + '</td>';
            qTbody.appendChild(tr);
        }

        // Quality advisory
        const qNote = document.getElementById('sysid-quality-note');
        if (qNote && hasQuality) {
            const noiseHigh  = quietPP.some(v => v >= 2.0);
            const noiseMedAny = quietPP.some(v => v >= 1.0 && v < 2.0);
            const ampLow     = stepAmp.some(v => v > 0 && v <= 10);
            const msgs = [];
            if (noiseHigh)   msgs.push('⚠ High noise on one or more trials — belt or alternator resonance at this RPM is inflating the measured time constant. Re-run the test at a slightly different engine speed for a cleaner result.');
            else if (noiseMedAny) msgs.push('⚠ Moderate noise detected. Results are usable but try a different RPM if you want a tighter reading.');
            if (ampLow)      msgs.push('⚠ Step amplitude is small (≤10 A) — consider increasing SystemIDStepAmplitude for a stronger signal.');
            qNote.innerHTML = msgs.length ? msgs.join('<br>') : '✅ Signal quality is good.';
            qNote.style.display = '';
        } else if (qNote) {
            qNote.style.display = 'none';
        }
        document.getElementById('sysid-quality-section').style.display = hasQuality ? '' : 'none';
    }

    // ── Timing results table ─────────────────────────────────────────────────────
    const tbody = document.getElementById('sysid-results-body');
    tbody.innerHTML = '';
    for (let i = 0; i < 3; i++) {
        const tr = document.createElement('tr');
        tr.style.borderBottom = '1px solid #333';
        tr.innerHTML = '<td style="padding:6px 4px;">Trial ' + (i + 1) + '</td>' +
            '<td style="padding:6px 4px;">' + (r[i] >= 0 ? r[i].toFixed(0) : '—') + '</td>' +
            '<td style="padding:6px 4px;">' + (f[i] >= 0 ? f[i].toFixed(0) : '—') + '</td>';
        tbody.appendChild(tr);
    }
    const avgRow = document.createElement('tr');
    avgRow.style.fontWeight = 'bold';
    avgRow.innerHTML = '<td style="padding:8px 4px; color:#aaa;">Average</td>' +
        '<td style="padding:8px 4px;">' + (ra >= 0 ? ra.toFixed(0) : '—') + '</td>' +
        '<td style="padding:8px 4px;">' + (fa >= 0 ? fa.toFixed(0) : '—') + '</td>';
    tbody.appendChild(avgRow);

    const tcFast = Math.max(1, Math.round(sysidSuggestedTC / 3));
    const tcSlow = Math.max(1, Math.round(sysidSuggestedTC));
    document.getElementById('sysid-results-summary').innerHTML =
        'Measured plant delay: <strong style="color:#4a9eff;">' + sysidSuggestedTC.toFixed(0) + ' ms</strong>' +
        ' (highest single trial)<br>' +
        '<span style="font-size:0.85em; color:#aaa;">Suggested filter TCs: ' +
        '<strong>' + tcFast + ' ms</strong> for PID feedback &amp; the filtered-amps display (plant/3), ' +
        '<strong>' + tcSlow + ' ms</strong> for voltage smoothing (full plant delay)</span>';

    const applyBtn = document.getElementById('sysid-apply-btn');
    if (applyBtn) { applyBtn.style.display = ''; applyBtn.textContent = 'Set All Filters (' + tcFast + ' / ' + tcFast + ' / ' + tcSlow + ' ms)'; }

    // Variance check: if spread within rise or fall trials > 25%, recommend re-run
    const warnEl = document.getElementById('sysid-results-warning');
    const validR = r.filter(v => v >= 0);
    const validF = f.filter(v => v >= 0);
    function spreadPct(arr) {
        if (arr.length < 2) return 0;
        const mn = Math.min(...arr), mx = Math.max(...arr), avg = arr.reduce((a,b)=>a+b,0)/arr.length;
        return avg > 0 ? (mx - mn) / avg * 100 : 0;
    }
    const rSpread = spreadPct(validR);
    const fSpread = spreadPct(validF);
    if (rSpread > 25 || fSpread > 25) {
        warnEl.textContent = '⚠ High variance between trials (rise: ' + rSpread.toFixed(0) + '%, fall: ' + fSpread.toFixed(0) + '%). ' +
            'Results are unreliable — run the test again.';
        warnEl.style.display = '';
    } else {
        warnEl.style.display = 'none';
    }

    sysidShowScreen('results');
}

// Render the open-loop plant Bode (sine sweep) results from /sysidbode.
function showSysidBodeResults() {
    // Hide the step-test sections; show the Bode section.
    const qsec   = document.getElementById('sysid-quality-section'); if (qsec)   qsec.style.display = 'none';
    const qhint  = document.getElementById('sysid-quality-hint');    if (qhint)  qhint.style.display = 'none';
    const tlabel = document.getElementById('sysid-timing-label');    if (tlabel) tlabel.style.display = 'none';
    const rtbl   = document.getElementById('sysid-results-table');   if (rtbl)   rtbl.style.display = 'none';
    const summ   = document.getElementById('sysid-results-summary'); if (summ)   summ.textContent = '';
    const warn   = document.getElementById('sysid-results-warning'); if (warn)   warn.style.display = 'none';
    const applyBtn = document.getElementById('sysid-apply-btn');     if (applyBtn) applyBtn.style.display = 'none';
    const bodeSec  = document.getElementById('sysid-bode-section');  if (bodeSec)  bodeSec.style.display = '';
    sysidShowScreen('results');

    const body = document.getElementById('sysid-bode-body');
    const sum  = document.getElementById('sysid-bode-summary');
    if (body) body.innerHTML = '<tr><td colspan="3" style="padding:6px 4px; color:#aaa;">Loading…</td></tr>';

    fetch(buildURL('/sysidbode'))
        .then(r => r.ok ? r.json() : null)
        .then(data => {
            if (!data || !data.pts || !data.pts.length) {
                if (body) body.innerHTML = '<tr><td colspan="3" style="padding:6px 4px; color:#f0a500;">No Bode data returned.</td></tr>';
                return;
            }
            const pts = data.pts;
            const g0 = Math.max(1e-9, pts[0].g);  // low-frequency reference gain
            if (body) body.innerHTML = pts.map(p => {
                const rel   = p.g / g0;
                const relDb = 20 * Math.log10(Math.max(1e-6, rel));
                const col   = rel < 0.708 ? '#f0a500' : '#4caf50';
                return '<tr style="border-bottom:1px solid #333;">' +
                    '<td style="padding:6px 4px;">' + p.f.toFixed(2) + '</td>' +
                    '<td style="padding:6px 4px; color:' + col + ';">' + rel.toFixed(2) + ' (' + relDb.toFixed(1) + ' dB)</td>' +
                    '<td style="padding:6px 4px;">' + p.ph.toFixed(0) + '</td></tr>';
            }).join('');
            // ── Fit a first-order-plus-dead-time (FOPDT) plant model from the sweep ──
            // K = DC gain (low-freq), τ from the −3 dB corner, θ (dead time) from the
            // phase lag the pole alone can't explain. All cheap closed-form math on ~10
            // points — the heavy lock-in DFT already ran on the ESP32.
            const fit = sysidFitFOPDT(pts, g0);

            // −3 dB bandwidth: interpolated frequency where gain falls to 0.708× low-freq.
            const f3 = fit.f3Hz;
            let html = f3
                ? 'Plant −3 dB bandwidth: <strong>~' + f3.toFixed(1) + ' Hz</strong> — the fastest the field can move the output open-loop. Phase lag growing well past 90° beyond here is dead-time, not just L/R lag.'
                : 'Gain had not dropped to −3 dB within the sweep — start the sweep lower (to capture the flat DC region) or raise Sweep End, then re-run for a plant model.';

            if (fit.ok) {
                sysidFitTauMs = fit.tauMs;
                sysidFitKp = fit.Kp;
                sysidFitKi = fit.Ki;
                // Persist the fitted tau on the device + refresh the actionable-disturbance readout.
                if (currentAdminPassword) cxGet('systemIDPlantTauMs=' + Math.round(fit.tauMs));
                updatePlantTauReadout(fit.tauMs);
                const tcFast = Math.max(1, Math.round(fit.tauMs / 3));
                const tcSlow = Math.max(1, Math.round(fit.tauMs));
                html +=
                    '<div style="margin-top:10px; padding-top:8px; border-top:1px solid #333; color:#ddd;">' +
                    '<div style="color:#aaa; margin-bottom:4px;">Plant model (first-order + dead time)</div>' +
                    'DC gain (K): <strong>' + fit.K.toFixed(3) + '</strong> A per % duty<br>' +
                    'Time constant (τ): <strong style="color:#4a9eff;">' + fit.tauMs.toFixed(0) + ' ms</strong> — the field L/R lag<br>' +
                    'Dead time (θ): <strong style="color:#4a9eff;">' + fit.thetaMs.toFixed(0) + ' ms</strong> — irreducible transport delay' +
                    (fit.thetaMs > fit.tauMs * 0.5
                        ? ' <span style="color:#f0a500;">(large vs τ — limits how hard the loop can be pushed)</span>' : '') +
                    '</div>' +
                    // Filter suggestion + apply (mirrors the step test: current filters get τ/3, voltage gets full τ)
                    '<div style="margin-top:8px;">' +
                    'Suggested filter TCs: <strong>' + tcFast + ' ms</strong> for PID feedback &amp; filtered-amps display (τ/3), ' +
                    '<strong>' + tcSlow + ' ms</strong> for voltage smoothing (full τ).' +
                    '<br><button onclick="applySysidBodeFilters()" class="btn-secondary btn-sm" style="margin-top:6px;">' +
                    'Set filters from τ (' + tcFast + ' / ' + tcFast + ' / ' + tcSlow + ' ms)</button>' +
                    '</div>' +
                    // IMC PI seed for the current loop. λ (desired closed-loop speed) chosen conservatively
                    // because overvoltage is costly here; tune from this with the square-wave tuner.
                    '<div style="margin-top:8px;">' +
                    'Current-loop start (IMC, λ=' + fit.lambdaMs.toFixed(0) + ' ms): ' +
                    '<strong>Kp=' + fit.Kp.toFixed(3) + '</strong>, <strong>Ki=' + fit.Ki.toFixed(3) + '</strong> ' +
                    '<span style="color:#aaa;">(starting point — verify with the square-wave tuner)</span>' +
                    '<br><button onclick="applySysidPidSeed()" class="btn-secondary btn-sm" style="margin-top:6px;">' +
                    'Apply PID seed (Kp/Ki)</button>' +
                    '</div>';
            } else if (f3) {
                // Corner found but the model fit was rejected (e.g. too few points below the knee).
                html += '<div style="margin-top:8px; color:#f0a500;">Not enough of the flat low-frequency region was captured to fit a clean plant model — start the sweep lower and re-run.</div>';
            }
            if (sum) sum.innerHTML = html;
        })
        .catch(() => {
            if (body) body.innerHTML = '<tr><td colspan="3" style="padding:6px 4px; color:#ef4444;">Failed to fetch /sysidbode.</td></tr>';
        });
}

// Fit a first-order-plus-dead-time model G(s) = K·e^(−θs)/(τs+1) to the swept-sine
// Bode points. pts: [{f (Hz), g (A per %duty), ph (output lag, deg)}], g0 = low-freq gain.
// Returns {ok, K, tauMs, thetaMs, f3Hz, lambdaMs, Kp, Ki}. All closed-form (sums + atan).
function sysidFitFOPDT(pts, g0) {
    const out = { ok: false, K: g0, tauMs: 0, thetaMs: 0, f3Hz: null, lambdaMs: 0, Kp: 0, Ki: 0 };
    if (!pts || pts.length < 3 || g0 <= 1e-6) return out;

    // τ from the interpolated −3 dB corner: find the first segment where relative gain
    // crosses 0.708×, interpolate the crossing frequency in log-f space, τ = 1/(2π f_c).
    let f3 = null;
    for (let i = 1; i < pts.length; i++) {
        const relPrev = pts[i - 1].g / g0, relCur = pts[i].g / g0;
        if (relPrev >= 0.708 && relCur < 0.708) {
            const lf0 = Math.log(pts[i - 1].f), lf1 = Math.log(pts[i].f);
            const t = (0.708 - relPrev) / (relCur - relPrev);   // 0..1 within the segment
            f3 = Math.exp(lf0 + t * (lf1 - lf0));
            break;
        }
    }
    out.f3Hz = f3;
    if (!f3 || f3 <= 0) return out;                 // no corner in range → can't size τ
    const tauSec = 1 / (2 * Math.PI * f3);
    out.tauMs = tauSec * 1000;

    // θ (dead time) from the phase lag the pole can't explain. A pole contributes
    // atan(ωτ); dead time adds ωθ on top. Least-squares of (excess lag) = θ·ω through
    // the origin — naturally weights the high-frequency points where dead time dominates.
    let Sva = 0, Sww = 0;
    for (const p of pts) {
        const w = 2 * Math.PI * p.f;
        const excess = (p.ph * Math.PI / 180) - Math.atan(w * tauSec);   // rad
        Sva += excess * w;
        Sww += w * w;
    }
    let thetaSec = Sww > 0 ? Sva / Sww : 0;
    if (thetaSec < 0) thetaSec = 0;                 // negative = noise/phase lead; clamp
    out.thetaMs = thetaSec * 1000;

    // IMC PI seed for the current loop (error in A → duty %). Kp = τ/(K(λ+θ)), Ki = Kp/τ
    // (per-second, matching the Arduino PID SetTunings convention). λ chosen conservatively
    // — overvoltage is costly here — so this is a safe starting point, not a final tune.
    const lambdaSec = Math.max(tauSec, 2 * thetaSec);
    out.lambdaMs = lambdaSec * 1000;
    const Kp = tauSec / (g0 * (lambdaSec + thetaSec));
    if (isFinite(Kp) && Kp > 0) {
        out.Kp = Kp;
        out.Ki = Kp / tauSec;
        out.ok = true;
    }
    return out;
}

// "Biggest actionable disturbance" — worst tone the FIELD can react to, read from the resonance
// /ripple matrix (/famatrix.csv). Actionable band is [4 Hz, actuator BW], where actuator BW =
// Readout beside the (usually hidden) Compute button: shows the fitted plant time constant and the
// actuator bandwidth it implies (1/2πτ), or a muted "run the sweep" prompt when nothing is fitted yet.
// Fed by the persisted CSV3 echo (survives reboots) and refreshed instantly on a fresh fit.
// Also renders the static "biggest actionable disturbance" conclusion into #faActionableResult: on a
// normal slow-field install the actuator band sits below the 4 Hz ripple floor, so no measured tone is
// ever chaseable — a fixed fact, not worth a button. The interactive Compute scan (#faComputeBtn) is
// revealed only if a fit ever puts the band above 4 Hz (τ < ~40 ms); otherwise the button stays hidden.
function updatePlantTauReadout(tauMs) {
    const el = document.getElementById('faPlantTau_readout');
    const FLOOR_HZ = 4.0;   // matrix FFT peak-search floor (FA_MIN_TONE_HZ)
    if (el) {
        if (tauMs > 0) {
            const bwHz = 1000 / (2 * Math.PI * tauMs);
            el.innerHTML = 'Plant &tau;: <strong>' + Math.round(tauMs) + ' ms</strong> &middot; actuator band &le; ' +
                bwHz.toFixed(1) + ' Hz';
            el.style.color = '';
        } else {
            el.innerHTML = 'Plant &tau;: not fitted yet — run a Plant Delay sine sweep in Commissioning';
            el.style.color = 'var(--text-muted)';
        }
    }
    const res = document.getElementById('faActionableResult');
    const btn = document.getElementById('faComputeBtn');
    if (!res) return;
    if (!(tauMs > 0)) {
        res.innerHTML = 'Run a Plant Delay sine sweep in Commissioning to evaluate this.';
        if (btn) btn.style.display = 'none';
        return;
    }
    const actBwHz = 1000 / (2 * Math.PI * tauMs);
    if (actBwHz <= FLOOR_HZ) {
        res.innerHTML = 'None — the field bandwidth (<strong>' + actBwHz.toFixed(1) + ' Hz</strong>, from plant ' +
            'τ=' + Math.round(tauMs) + ' ms) is below the 4 Hz ripple floor, so the field is too slow to chase any ' +
            'measured ripple tone. Ripple is bounded by ripple-rejection, not reaction speed — nothing to tune here.';
        if (btn) btn.style.display = 'none';
    } else {
        res.innerHTML = 'Plant is fast enough that some tones (band 4–' + actBwHz.toFixed(1) + ' Hz) could be ' +
            'chaseable — press Compute to find the strongest one in the learned map.';
        if (btn) btn.style.display = '';
    }
}

// 1/(2π·τ_plant) from the Plant Delay sine fit (sysidFitTauMs). Tones above it are real but
// un-actionable (field too slow → the iExcess EMA averages them out), so they're excluded.
// Ranked by residual (amp/freq): a low slow tone survives the EMA far better than a high one.
// On a slow-field install the band can fall below 4 Hz → nothing is actionable (the common case).
// See iExcess_Redesign_Spec.md §11.
function computeActionableDisturbance() {
    const el = document.getElementById('faActionableResult');
    if (!el) return;
    const tauMs = sysidFitTauMs;   // fitted plant τ (ms); 0 until a Plant Delay sweep is fit
    if (!(tauMs > 0)) {
        el.textContent = 'Run a Plant Delay sine sweep first — the actionable band edge comes from the fitted plant time constant.';
        return;
    }
    const actBwHz  = 1000 / (2 * Math.PI * tauMs);   // actuator bandwidth, Hz
    const FLOOR_HZ = 4.0;                            // matrix FFT peak-search floor (FA_MIN_TONE_HZ)
    if (actBwHz <= FLOOR_HZ) {
        el.innerHTML = 'No actionable disturbance — actuator bandwidth (<strong>' + actBwHz.toFixed(1) +
            ' Hz</strong>, from plant τ=' + Math.round(tauMs) + ' ms) is below the 4 Hz measurement floor. ' +
            'Every measurable tone is faster than the field can chase, so all are averaged out. ' +
            'iExcess τ is bounded by ripple-rejection, not reaction speed.';
        return;
    }
    el.textContent = 'Computing…';
    const tauIeMs = parseFloat(getField('IExcessTau_echo'));   // detector EMA τ, for the residual figure
    const FA_RPM_BIN_W = 50;   // mirror of the firmware matrix RPM bin width
    fetch(buildURL('/famatrix.csv')).then(r => r.text()).then(txt => {
        const lines = txt.trim().split('\n');
        let best = null;
        for (let i = 1; i < lines.length; i++) {   // skip header row
            const c = lines[i].split(',');
            if (c.length < 22) continue;
            const rpmCtr = parseFloat(c[0]) + FA_RPM_BIN_W / 2;
            for (let s = 0; s < 6; s++) {           // columns: f1,a1,n1 at 4,5,6; stride 3
                const f = parseFloat(c[4 + s * 3]);
                const a = parseFloat(c[5 + s * 3]);
                const n = parseFloat(c[6 + s * 3]);
                if (!(n > 0) || !(a > 0) || !(f >= FLOOR_HZ) || f > actBwHz) continue;
                const residIdx = a / f;             // ∝ post-EMA residual (τ constant across the comparison)
                if (!best || residIdx > best.residIdx) best = { f, a, rpm: rpmCtr, residIdx };
            }
        }
        if (!best) {
            el.innerHTML = 'No actionable tone in 4–' + actBwHz.toFixed(1) +
                ' Hz across the learned map (plant τ=' + Math.round(tauMs) + ' ms). All measurable disturbances ' +
                'are above the actuator bandwidth, so the field can’t chase them and the EMA averages them out.';
            return;
        }
        let resStr = '';
        if (tauIeMs > 0) {
            const resid = best.a / (2 * Math.PI * best.f * (tauIeMs / 1000));   // post-EMA residual, A (spec §11)
            resStr = ' — post-EMA residual ≈ <strong>' + resid.toFixed(2) + ' A</strong> at the current iExcess τ (' +
                Math.round(tauIeMs) + ' ms); set the detector floor above this.';
        }
        el.innerHTML = 'Biggest actionable disturbance: <strong>' + best.a.toFixed(1) + ' A pk-pk @ ' +
            best.f.toFixed(1) + ' Hz</strong>, ' + Math.round(best.rpm) + ' RPM (band 4–' + actBwHz.toFixed(1) +
            ' Hz, plant τ=' + Math.round(tauMs) + ' ms)' + resStr;
    }).catch(e => { el.textContent = 'Matrix fetch failed: ' + e; });
}

// "Set filters from τ" — same three filters the step test writes, sized from the fitted
// time constant: current filters get τ/3 (phase margin), voltage smoothing gets full τ.
// ============================================================================
// Auto-commissioning orchestrator (spec §12). One-button guided setup of the
// current-control + over-current chain. Drives existing /get handlers and the
// existing SystemID / tuning-sweep / matrix endpoints; the operator only holds or
// slowly changes engine speed when prompted — the regulator drives the field.
// ============================================================================
const CX_PHASES = ['Prep', 'Field curve', 'Plant fit', 'Verify', 'Disturbances', 'Thresholds', 'CV plant fit', 'Min% floor'];
let cx = null;             // orchestrator state object; persists across panel close (in-session resume)
let cxPollTimer = null;
let cxHeartbeatTimer = null;   // pings commissionHeartbeat while the modal is open (firmware idle-rest hold)

// ── Per-stage run plan (partial re-commissioning) ─────────────────────────────
// cxPlan[i] = run stage i in the next/active wizard pass (0=Prep … 7=Min% floor). Prep (0) is
// ALWAYS run (it snapshots the tune for safe revert + checks preconditions), so it stays true and
// its checkbox is disabled. The wizard navigation skips any stage left false.
let cxPlan = [true, true, true, true, true, true, true, true];
// Coupling: (re)running a stage invalidates the downstream stages it feeds, so selecting one
// force-selects them. Field curve(1) → Plant fit(2)+Verify(3)+CV plant fit(6); Plant fit(2) →
// Verify(3)+CV plant fit(6); Verify(3) → CV plant fit(6); Disturbances(4) → Thresholds(5).
// CV plant fit(6) measures the current→voltage plant, downstream of the whole inner current loop.
// Min% floor(7) is independent (no dependents) and runs last so the engine is warm at max RPM.
// (Mirrors commissionDependentsMask() in the firmware.)
const CX_DEPENDENTS = { 1: [2, 3, 6], 2: [3, 6], 3: [6], 4: [5] };
let cxPlanUserSet = false;   // true once the user ticks a box, so CSV3 re-renders stop re-defaulting the plan
let cxLastPhase = 0;         // remembered from the last CSV3 frame (for re-render after a checkbox toggle)
let cxLastMask = 0;          // per-stage done bitmask from the last CSV3 frame

// Force-select every downstream dependent of any selected stage (transitive); Prep always on.
function cxApplyDeps() {
    cxPlan[0] = true;
    let changed = true;
    while (changed) {
        changed = false;
        for (const k in CX_DEPENDENTS) {
            if (cxPlan[+k]) for (const d of CX_DEPENDENTS[k]) if (!cxPlan[d]) { cxPlan[d] = true; changed = true; }
        }
    }
}
// Default plan from the persisted done-mask: pre-select the stages NOT yet done (so a fresh device
// pre-selects everything = "select all", and a single stale step — e.g. Min% after an RPM-breakpoint
// change — pre-selects just that). A fully-done device (re-commission) defaults to all selected.
function cxDefaultPlanFromMask(mask) {
    const ALL = (1 << CX_PHASES.length) - 1;   // 0xFF for 8 stages
    const allDone = (mask & ALL) === ALL;
    for (let i = 0; i < CX_PHASES.length; i++) cxPlan[i] = (i === 0) ? true : (allDone ? true : !(mask & (1 << i)));
    cxApplyDeps();
}
// Checkbox handlers (Commissioning tab). Prep can't be unchecked; selecting a step pulls in deps.
function cxToggleStage(i, on) {
    cxPlanUserSet = true;
    cxPlan[i] = on || i === 0;
    if (cxPlan[i]) cxApplyDeps();
    renderCommissionStatus(cxLastState, cxLastPhase, cxLastMask);
}
function cxToggleSelectAll(on) {
    cxPlanUserSet = true;
    for (let i = 0; i < CX_PHASES.length; i++) cxPlan[i] = on || i === 0;
    renderCommissionStatus(cxLastState, cxLastPhase, cxLastMask);
}
// Primary-button intent — derived purely from the ticked plan (cxPlan, post-dependency-cascade) vs
// the persisted done-mask (cxLastMask), NOT from the firmware state flag. Optional stages are 1..N
// (Prep always runs and is ignored here). Returns label + help + style + whether to revert.
//   nothing ticked            → disabled.
//   nothing done yet          → "Start" (clean first pass over the ticked subset).
//   every optional step ticked AND something already done → "Clear and restart": a wholesale redo,
//     so revert to the pre-commissioning snapshot and run the whole walkthrough again.
//   otherwise (a partial pass over not-yet-done, and/or a TARGETED redo of a few done steps that
//     force-pulls only their downstream) → "Continue": keep prior work + the snapshot, run the
//     ticked subset. This is the case that must NOT revert, or the "redo forces downstream" coupling
//     would be steamrolled by a full restart.
function cxStartIntent() {
    let doneCount = 0, planCount = 0, allSelected = true;
    const optional = CX_PHASES.length - 1;   // every step except Prep (always run, ignored here)
    for (let i = 1; i < CX_PHASES.length; i++) {
        if (cxLastMask & (1 << i)) doneCount++;
        if (cxPlan[i]) planCount++; else allSelected = false;
    }
    if (planCount === 0)
        return { label: 'Start commissioning…', help: 'Tick at least one step to run.', className: 'btn-primary', disabled: true, action: 'open' };
    if (doneCount === 0)
        return { label: 'Start commissioning…', help: 'Only the ticked steps will run.', className: 'btn-primary', disabled: false, action: 'open' };
    // Every step done but the device isn't COMMISSIONED (state≠2) = a completed run that was never
    // committed (Finish dropped / wizard closed at the end). Offer to commit it — NOT "clear and
    // restart", which would revert the finished work to the pre-commissioning snapshot.
    if (doneCount === optional && cxLastState !== 2)
        return { label: 'Finish commissioning…', help: 'Every step is done but the run was never saved. This commits it and marks the device commissioned — nothing is re-run or reverted.', className: 'btn-primary', disabled: false, action: 'finish' };
    if (allSelected)
        return { label: 'Clear and restart commissioning…', help: 'Every step is ticked, so this reverts to your pre-commissioning settings and runs the whole walkthrough again from the top.', className: 'btn-secondary', disabled: false, action: 'restart' };
    return { label: 'Continue commissioning…', help: 'Runs just the ticked steps and keeps everything already done. Re-running a step also re-runs the steps it feeds.', className: 'btn-primary', disabled: false, action: 'open' };
}
// Dispatch the primary button per cxStartIntent(): a wholesale redo reverts then restarts, anything
// else opens the wizard to run the ticked plan.
function commissionPrimaryAction() {
    const intent = cxStartIntent();
    if (intent.disabled) return;
    if (intent.action === 'restart') commissionClearAndRestart();
    else if (intent.action === 'finish') commissionCommitUncommitted();
    else openCommissionModal();
}
// Commit a completed-but-uncommitted run: every step is done but Finish never fired (wizard closed
// at the end, or the network dropped between the last step and Finish). Sends commissionDone=1 to
// persist the new tune and flip the badge to COMMISSIONED — without reopening the wizard or reverting.
function commissionCommitUncommitted() {
    if (!currentAdminPassword) { xAlert('Unlock settings first (enter the admin password).'); return; }
    cxGet('commissionDone=1').then(() => {
        cxLastState = 2;
        renderCommissionStatus(2, CX_PHASES.length, cxLastMask);   // phase=length clears the ▶ marker
    }).catch(e => xAlert('Finish failed: ' + e));
}
// Wizard navigation honouring the plan: next selected stage in 1..last, or -1 if none remain.
function cxNextSelected(from) { for (let i = from + 1; i < CX_PHASES.length; i++) if (cxPlan[i]) return i; return -1; }
// Mark the stage we're leaving complete (firmware sets its done bit + clears its dependents), then
// move to the next selected stage — or finish if this was the last one. markDone=false advances
// WITHOUT setting the done bit, so a step that couldn't actually complete (e.g. a failed CV plant
// fit on a weak alternator) doesn't get a ✓ or push the device to a false COMMISSIONED badge.
function cxAdvance(markDone = true) {
    const cur = cx.phase, nx = cxNextSelected(cur);
    const done = markDone ? cxGet('commissionStageDone=' + cur) : Promise.resolve();
    done.finally(() => { if (nx === -1) cxFinish(); else cxGoto(nx); });
}
// Shared "Next →"/"Finish" button for the per-phase render functions — only emitted once the step's
// action is done, so it's always clickable (no disabled-greyed Next cluttering earlier states).
// label shows the next selected stage, or "Finish" when this is the last one in the plan.
// markDone=false skips marking this stage complete (passed to cxAdvance); primary=false renders it
// as the secondary action (e.g. an explicit "skip" after a failed step).
function cxNextBtn(markDone = true, primary = true) {
    const nx = cxNextSelected(cx.phase);
    const label = (nx === -1) ? 'Finish' : ('Next: ' + CX_PHASES[nx] + ' →');
    const cls = primary ? 'btn-primary btn-sm' : 'btn-secondary btn-sm';
    return '<button onclick="cxAdvance(' + markDone + ')" class="' + cls + '">' + label + '</button>';
}
// ── Clean-pass chaining across the cruise-hold stretch (Field curve → Plant fit → Verify) ──
// These stages share one held engine speed, so when a result is CLEAN the primary button applies
// it AND starts the next stage's test in one press (instead of Apply → Next → Run). Only the
// stages in CX_AUTORUN are ever auto-started — Disturbances needs a drop to idle and CV plant fit
// has its own load-steady precondition, so a human press stays required there. Any warning or
// marginal result falls back to the plain Apply primary and today's manual flow.
const CX_AUTORUN = { 2: () => cxPlantStart(false), 3: () => cxVerifyStart() };
// applyFn = global apply-function name; it must accept (run) and call cxAdvanceRun() when true.
function cxApplyRunBtn(applyFn, clean) {
    const nx = cxNextSelected(cx.phase);
    if (clean && CX_AUTORUN[nx])
        return '<button onclick="' + applyFn + '(true)" class="btn-primary btn-sm">Apply &amp; run ' + CX_PHASES[nx] + ' →</button> ' +
               '<button onclick="' + applyFn + '()" class="btn-secondary btn-sm">Apply only</button>';
    return '<button onclick="' + applyFn + '()" class="btn-primary btn-sm">Apply</button>';
}
// cxAdvance(true) plus an immediate start of the next stage's test.
function cxAdvanceRun() {
    const nx = cxNextSelected(cx.phase);
    cxGet('commissionStageDone=' + cx.phase).finally(() => {
        if (nx === -1) { cxFinish(); return; }
        cxGoto(nx);
        if (CX_AUTORUN[nx]) CX_AUTORUN[nx]();
    });
}

function cxStopPoll() { if (cxPollTimer) { clearInterval(cxPollTimer); cxPollTimer = null; } }

// ── Live telemetry the panel reads straight from the SSE caches ───────────────
// g_lastCsv1 holds the latest CSV1 frame (raw, name-keyed); echoes carry CSV3 settings.
function cxLive() {
  const c = (typeof g_lastCsv1 === 'object' && g_lastCsv1) ? g_lastCsv1 : {};
  const num = (k, s) => (k in c && c[k] !== '' && c[k] != null) ? parseFloat(c[k]) / s : NaN;
  return {
    rpm: num('RPM', 1),
    busV: num('IBV', 100),          // INA bus voltage (volts)
    amps: num('MeasuredAmps', 100), // alternator current (amps)
    duty: num('dutyCycle', 100),    // field duty (%)
    prot: ('protEventMask' in c) ? (parseInt(c.protEventMask) || 0) : 0,  // bit1=OV bit2=iExcess bit4=LoadDump
  };
}
function cxBulkV() { const v = getEchoNumber('BulkVoltage_echo'); return (v > 0) ? v : NaN; }
function cxHardV() { const v = getEchoNumber('AlternatorHardShutdownV_echo'); return (v > 0) ? v : NaN; }

// The one true protection statement, per phase. Open-loop phases (Field curve 1, Min% floor 2,
// Plant fit 3) and the closed-loop verify (4) are guarded only by the fast OV cut + INA228 backstop;
// the disturbance map (5) and validation (7) run under full normal protection.
// Per-phase protection statement (plain text — the footer wrapper lives in commissionRender).
function cxSafetyText(phase) {
  const hv = cxHardV();
  const bv = cxBulkV();
  // Show the ACTUAL trip (AlternatorHardShutdownV), expressed as live Bulk + the real offset so it
  // always adds up — the trip is an absolute setting, not a live bulk+0.3, so don't compute the sum.
  let ov;
  if (isNaN(hv)) ov = 'the Alternator Hard Shutdown Voltage';
  else if (!isNaN(bv) && bv > 0) ov = 'Bulk ' + bv.toFixed(2) + ' V + ' + (hv - bv).toFixed(2) + ' = ' + hv.toFixed(2) + ' V (Alternator Hard Shutdown Voltage)';
  else ov = hv.toFixed(2) + ' V (Alternator Hard Shutdown Voltage)';
  // Open-loop / test-current steps (Field curve, Plant fit, Verify, CV plant fit, and Min% floor)
  // run with only the fast over-voltage hard-shutdown live; the rest run under full normal protection.
  const openLoop = (phase >= 1 && phase <= 3) || phase >= 6;
  return openLoop
    ? 'Protections active this step: <strong>over-voltage only</strong>.'
    : 'Protections active this step: <strong>all of them</strong>.';
}

// Per-phase technical fine print — the "details" the simple instructions deliberately omit.
// Shown muted at the bottom of the panel, above the protection statement.
function cxFinePrint(phase) {
  switch (phase) {
    case 0: return 'Commissioning runs some semi-automated tests on your alternator and uses the results to optimize configuration settings. Time required is ~ 5 minutes and requires some charging headroom in the battery SOC to avoid tripping overvoltage protections.';
    case 1: return 'Open-loop field-duty ramp across the full range maps duty→amps, finds the saturation knee, and proposes the plant test\'s wave floor (baseline current) and step size. No feedback control — raw duty only.';
    case 7: return 'Briefly ramps field at each held RPM until output current just begins (the onset knee). The onset follows a 1/RPM law, so those three points fit the whole Min% column, parked a margin below and maintained automatically over alternator life. Above your highest captured RPM the floor is forced to zero, so the field can always shut fully off at speed. Only over-voltage is active during the ramp.';
    case 2: return 'Open-loop sine sweep on field duty identifies the plant (time constant τ, gain, dead time) and proposes the PI gains and filter time constants. This characterizes the alternator\'s own field→current behavior, so it runs on <strong>alternator current</strong> — the same signal the inner loop regulates in every mode. Wave floor and step size carry over from the Field curve step\'s proposal (the Plant Delay tab). The sweep frequency range is fixed at <strong>0.5–20 Hz</strong> (0.3–30 Hz on an auto-widen retry).';
    case 3: return 'Closed-loop sine sweep — passes when the peak closed-loop gain stays ≤ 1.15 (no resonant peak). The parameters are computed from the plant fit and field curve. This verifies the inner current loop on alternator current — the signal it regulates in every mode.';
    case 4: return 'Records the low-frequency disturbance at each engine speed into a map; ~80% coverage of the idle-to-2000 RPM band is enough. During the sweep the wizard holds the alternator at a <strong>fixed test current</strong> (25% of your RPM/Amps table max) and captures the <strong>measured filtered ripple</strong> (the same IExcessTau-averaged signal each over-current detector trips on) per RPM bin, for both the alternator and battery detectors — a value only commits when two readings at that speed agree, so a throttle transient can\'t poison the table. The optional current-check then commands 3 current levels at the worst-ripple RPM and fits ripple = a0 + a1·I per detector. This produces the <strong>measured-ripple projection</strong> only — it never sets a threshold. Review it against your settings in the next step and on the Protections ripple plots.';
    case 5: return 'A read-only review — nothing is written here. It draws each over-current detector\'s trip threshold <code>max(Min, %·current, Max)</code> (from the Min/%/Max you set in <strong>Protections</strong>) against the ripple just measured in Step 5, for both the <strong>alternator (bulk)</strong> and <strong>battery (CV)</strong> detectors. Any current where the measured ripple crosses above your threshold is shaded red — the detector would false-trip there; raise that detector\'s floor (or accept it). The floor/ceiling/% are yours to set; commissioning only measures the ripple. The identical plots live permanently on Settings ▸ Alternator ▸ Protections and redraw live as you edit.';
    case 6: return 'Commands one bounded current step (~6–40 A, auto-sized for ~300 mV) through the already-tuned current loop and records how battery voltage responds to the current measured at the battery shunt, measuring the <strong>finite-horizon gain K20</strong> (the rise at a fixed 20 s horizon with the slow charge ramp removed — a charging battery never plateaus, so there is nothing to settle to). The voltage-loop gains follow from K20 via the exact PI magnitude condition, Ki = ρ·Kp, and the CV gain source switches to Auto on Apply. All confidence checks are advisory — they warn but never block; only "no measurement" prevents Apply. The fit runs locally in this app — no internet. Only over-voltage hard-shutdown is active; keep all other battery loads constant during the test.';
    default: return '';
  }
}

// Safe closed-loop verify-sweep parameters, computed from the plant fit (τ) and the field
// curve (saturation knee / proposed stabilize current) — NOT read off the Tuning ▸ Current
// tab, whose values are unknown/stale at commissioning time. Floor = baseline operating
// current; amplitude = small linear perturbation; sweep range brackets the plant corner.
function cxVerifyParams() {
  const tau = (cx.fit && cx.fit.tauMs > 0) ? cx.fit.tauMs : 60;   // plant time constant, ms
  const fc  = 1000 / (2 * Math.PI * tau);                          // plant corner, Hz
  const fStart = Math.min(1.0, Math.max(0.3, fc / 8));
  // End ~10× the corner and deliberately a bit past the expected crossover so a resonant peak
  // above the closed-loop bandwidth still lands inside the sweep. Capped at 25 Hz (anti-alias).
  const fEnd   = Math.min(25,  Math.max(15,  fc * 10));
  const knee = (cx.fieldResult && cx.fieldResult.kneeAmps  > 0) ? cx.fieldResult.kneeAmps  : 0;
  const stab = (cx.fieldResult && cx.fieldResult.propStabA > 0) ? cx.fieldResult.propStabA
             : (knee > 0 ? knee * 0.4 : 10);   // propStabA = 50% of the cap-at-RPM
  // The wave only swings UP from the floor, so floor and amplitude share the headroom to the
  // peak. Aim the peak at ~80% of the cap (1.6× the 50% baseline) for a meaty swing, but hold it
  // ≥15% below the measured saturation knee so the closed-loop response can't clip. Then split:
  // operating point at 70% of the peak, the rest is swing.
  let peak = stab * 1.6;
  if (knee > 0) peak = Math.min(peak, knee * 0.85);
  const floor = Math.max(3, Math.round(peak * 0.7));
  const amp   = Math.max(2, Math.round(peak - floor));
  return { floor, amp, fStart: fStart.toFixed(2), fEnd: fEnd.toFixed(1), cycles: 2 };
}

// Bring the dashboard tab the user should be watching into view. Called from the field-action
// buttons (NOT on phase entry — advancing with "Next →" leaves the tab put), so the test is
// on-screen the moment the field moves:
//   open-loop ramp / open-loop sine / disturbance creep / validation hold → Plots ▸ Short Term
//   closed-loop sine-sweep verify                                          → Tuning ▸ Current
function cxShowTab(main, sub) {
  try { showMainTab(main); showSubTab(main, sub); } catch (e) { /* tab not present — non-fatal */ }
}

// Every commissioning write goes through here so the admin password is always attached.
function cxGet(params) {
    const pw = encodeURIComponent(currentAdminPassword || '');
    return fetch(buildURL('/get?' + params + '&password=' + pw));
}

function openCommissionModal() {
    if (!currentAdminPassword) { xAlert('Unlock settings first (enter the admin password).'); return; }
    // In-session resume: if a flow is already underway, reopen exactly where it was.
    if (!cx) cx = { phase: 0, fieldApplied: false, plantApplied: false, threshApplied: false };
    document.getElementById('commission-modal-overlay').style.display = 'block';
    // Make the panel draggable (idempotent) — drag by the header, clamped on-screen.
    makePanelDraggable(document.getElementById('commission-modal-panel'),
                       document.getElementById('commission-drag-handle'));
    cxGoto(cx.phase);   // re-render the current phase + restart its live-poll timer
    // Idle-rest heartbeat: while the dialog is open, tell the firmware to "rest" the field at a low
    // duty between steps. ~2 s ping vs the 5 s firmware timeout tolerates one dropped ping. The
    // firmware only acts on this while a session is IN_PROGRESS, so pinging during Prep is harmless.
    if (cxHeartbeatTimer) clearInterval(cxHeartbeatTimer);
    cxGet('commissionHeartbeat=1').catch(() => { });
    cxHeartbeatTimer = setInterval(() => { cxGet('commissionHeartbeat=1').catch(() => { }); }, 2000);
}

function closeCommissionModal() {
    // Pause ≠ abort: closing leaves the firmware state IN_PROGRESS and KEEPS cx so the flow
    // resumes on reopen. But never leave a test running, the device in closed-loop tuning, or the
    // relaxed matrix gate live — clean up whatever this session left active.
    cxStopPoll();
    // Stop the idle-rest heartbeat and explicitly drop the hold, so a clean close resumes normal
    // charging immediately instead of waiting out the firmware's 5 s staleness timeout.
    if (cxHeartbeatTimer) { clearInterval(cxHeartbeatTimer); cxHeartbeatTimer = null; }
    cxGet('commissionHeartbeat=0').catch(() => { });
    if (cx) {
        if (cx.fieldRunning) cxGet('cancelFieldCurve=1').catch(() => { });
        if (cx.plantRunning) cxGet('cancelSystemID=1').catch(() => { });
        if (cx.verifyRunning) cxGet('TuningMode=0').catch(() => { });
        if (cx.cvFitRunning) { cx.cvFitDone = true; if (cx.cvFitCdTimer) { clearInterval(cx.cvFitCdTimer); cx.cvFitCdTimer = null; } if (cxPollTimer) { clearTimeout(cxPollTimer); cxPollTimer = null; } if (cvFitCapture) cvFitCapture.active = false; cxGet('TuningMode=0').catch(() => { }); }
        // Modal close is a sweep teardown path: freeze + persist the RPM ripple table (committed cells
        // from a cut-short sweep are honest data). The rtFieldArmed block below releases the field —
        // the game runs with rtFieldArmed set for exactly that reason.
        if (cx.matrixOn) { cxGet('ripGameFill=0').catch(() => { }); cxGet('faCommissionGate=0').catch(() => { }); }
        // The current-check and the sweep game both COMMAND the field — ramp the current to 0 first,
        // then release field-control + gate, so closing the wizard mid-test exits gently (the deadman is the
        // backstop for involuntary closes; this is the clean path for a deliberate X).
        if (cx.rtFieldArmed) {
            cxGet('resTestTargetA=0').then(() => cxGet('resTest=0')).catch(() => { });
            cxGet('bcurRtest=0').catch(() => { });
            cxGet('faCommissionGate=0').catch(() => { });
        }
        cx.fieldRunning = cx.plantRunning = cx.verifyRunning = cx.cvFitRunning = cx.matrixOn = cx.rtFieldArmed = false;
    }
    document.getElementById('commission-modal-overlay').style.display = 'none';
}

function cxGoto(phase) {
    cxStopPoll();                 // drop any timer from the phase we're leaving
    cx.phase = phase;
    // Persist the furthest phase reached so the Commissioning tab checklist survives a
    // page reload or shows on a different client (firmware clamps + ignores lower values? no —
    // it stores exactly; the wizard is forward-only in practice).
    if (currentAdminPassword) cxGet('commissionPhase=' + phase).catch(() => { });
    // No tab switch on phase entry — only the field-action buttons move the tab (cxShowTab).
    commissionRender();
    if (phase === 0) { cxPollTimer = setInterval(cxPrepRefresh, 1000); cxPrepRefresh(); }      // live Prep precheck
}

function commissionRender() {
    if (!cx) return;
    const steps = document.getElementById('commission-steps');
    steps.innerHTML = CX_PHASES.map((nm, i) => {
        const skipped = !cxPlan[i];   // not in this run's plan — shown dimmed/struck, not ✓
        if (i === cx.phase) return '<span style="color:#2ec4b6;font-weight:600;">' + (i + 1) + '. ' + nm + '</span>';
        if (skipped) return '<span style="color:#666;text-decoration:line-through;">' + nm + '</span>';
        if (i < cx.phase) return '<span style="color:#5a5;">✓ ' + nm + '</span>';
        return '<span>' + (i + 1) + '. ' + nm + '</span>';
    }).join('<span style="color:#444;"> › </span>');
    document.getElementById('commission-abort-row').style.display = (cx.phase > 0) ? 'block' : 'none';
    const b = document.getElementById('commission-body');
    const R = [cxRenderPrep, cxRenderField, cxRenderPlant, cxRenderVerify, cxRenderMatrix, cxRenderThresh, cxRenderCVPlant, cxRenderKnee];
    // Wrap render so a transient error can never blank/close the panel mid-flow.
    try { R[cx.phase](b); } catch (e) { console.warn('commissionRender', e); return; }
    // One muted footer under a single rule: technical "details" for this phase, then the
    // protection statement. Keeps the body above it to simple, large-type instructions.
    let details = cxFinePrint(cx.phase);
    // The Disturbances fine print describes the sweep/map — only relevant on this step's first
    // (sweep) screen, not once the alternator-current-check sub-flow is running. Drop it there.
    if (cx.phase === 4 && (cx.matrixOn || cx.matrixCov)) details = '';
    b.insertAdjacentHTML('beforeend',
        '<div style="margin-top:14px; padding-top:10px; border-top:1px solid #2c2c2c; font-size:11px; color:#888; line-height:1.5;">' +
        (details ? '<div style="margin-bottom:8px;">' + details + '</div>' : '') +
        '<div>' + cxSafetyText(cx.phase) + '</div>' +
        '</div>');
}

// ── Step 1 · Prep — preconditions & snapshot ────────────────────────────────
function cxRenderPrep(b) {
    b.innerHTML =
        '<p style="font-size:15px;line-height:1.5;"><strong>Start the engine and check the charging headroom</strong>.</p>' +
        '<div style="margin:10px 0; padding:8px 10px; background:#222; border-radius:6px; font-size:13px; line-height:1.7;">' +
        '<div>Engine: <span id="cx-prep-rpm">…</span></div>' +
        '<div>Charging headroom: <span id="cx-prep-headroom">…</span></div>' +
        '<div>Battery shunt: <span id="cx-prep-shunt">…</span></div>' +
        '</div>' +
        '<button id="cx-start-btn" onclick="cxStart()" class="btn-primary" style="width:100%;padding:9px;margin-top:6px;" disabled>Start commissioning</button>';
    cxPrepRefresh();
}
// Live Prep precheck — refreshed on a 1 s timer while on the Prep phase.
function cxPrepRefresh() {
    if (!cx || cx.phase !== 0) return;
    const L = cxLive(), bulk = cxBulkV();
    const rpmEl = document.getElementById('cx-prep-rpm');
    const hrEl = document.getElementById('cx-prep-headroom');
    const btn = document.getElementById('cx-start-btn');
    if (!rpmEl || !hrEl || !btn) return;
    const engineOk = !isNaN(L.rpm) && L.rpm > 300;
    rpmEl.innerHTML = isNaN(L.rpm) ? '<span style="color:#f0a500;">no RPM</span>'
        : '<strong style="color:' + (engineOk ? '#5a5' : '#f0a500') + ';">' + Math.round(L.rpm) + ' RPM</strong>' + (engineOk ? '' : ' (start the engine)');
    // Headroom is advisory only — color warns, but it never blocks commissioning.
    // Green = comfortable room, orange = tight, red = almost no room (OV trip likely).
    if (isNaN(L.busV) || isNaN(bulk)) { hrEl.innerHTML = '<span style="color:#f0a500;">unknown (no live voltage)</span>'; }
    else {
        const head = bulk - L.busV;
        const color = head > 1.0 ? '#5a5' : (head > 0.5 ? '#f0a500' : '#f0584f');
        const note = head > 1.0 ? '' : (head > 0.5 ? ' — getting tight' : ' — very little room (OV trip likely)');
        hrEl.innerHTML = '<strong style="color:' + color + ';">' + head.toFixed(2) + ' V below Bulk</strong>'
            + ' (' + L.busV.toFixed(2) + ' / ' + bulk.toFixed(2) + ' V)' + note;
    }
    // Battery-shunt availability (ADVISORY, never blocks — commissioning spec §2). The Battery Charge
    // Current Limit (G4) needs a healthy INA228 battery shunt; warn if a limit is set but the shunt
    // isn't available. Read straight from the CSV3 echo cache.
    const shEl = document.getElementById('cx-prep-shunt');
    if (shEl) {
        const c3 = (typeof g_lastCsv3 === 'object' && g_lastCsv3) ? g_lastCsv3 : {};
        const battLim = ('BattCurrentLimitA' in c3) ? parseFloat(c3.BattCurrentLimitA) / 10 : 0;
        const battSrc = ('BatteryCurrentSource' in c3) ? parseInt(c3.BatteryCurrentSource, 10) : 0;  // 0 = INA228
        const shuntR = ('ShuntResistanceMicroOhm' in c3) ? parseFloat(c3.ShuntResistanceMicroOhm) : 0;
        if (battSrc === 0 && shuntR > 0)
            shEl.innerHTML = '<strong style="color:#5a5;">INA228 shunt OK</strong>' + (battLim > 0 ? ' — Battery Charge Current Limit active at ' + battLim.toFixed(0) + ' A.' : '.');
        else if (battLim > 0)
            shEl.innerHTML = '<span style="color:#f0a500;">no valid INA228 shunt (' + (battSrc !== 0 ? 'battery-current source is not the INA228' : 'shunt resistance unset') + ') — the Battery Charge Current Limit is set but INACTIVE.</span>';
        else
            shEl.innerHTML = '<span style="color:#888;">no INA228 battery shunt configured — battery-side features (charge limit, tail detection) unavailable.</span>';
    }
    btn.disabled = !engineOk;
}
function cxStart() {
    // commissionStart snapshots the tune + marks Prep done; jump to the first selected stage
    // (or finish immediately if the plan is Prep-only).
    cxGet('commissionStart=1').then(() => { const nx = cxNextSelected(0); if (nx === -1) cxFinish(); else cxGoto(nx); }).catch(e => xAlert('Start failed: ' + e));
}

// ── Step 2 · Field curve — duty→amps map + saturation knee ───────────────────
function cxRenderField(b) {
    const r = cx.fieldResult;
    let body = '';
    if (cx.fieldRunning) {
        body += '<p style="color:#4a9eff;">Running field-% ramp… keep RPM roughly steady — best effort, it doesn\'t have to be perfect.</p>';
    } else if (cx.fieldAbort) {
        body += '<div style="margin:10px 0;padding:8px 10px;background:#3a2222;border:1px solid #a55;border-radius:6px;color:#f0a500;">' +
            'Ramp stopped: <strong>' + cx.fieldAbort + '</strong><br>' +
            '<span style="font-size:13px;color:#caa;">Open the <strong>Console</strong> tab for the firmware reason. If there is no <em>Field curve</em> line there, the regulator never ran the ramp — fix the cause above, then run again.</span></div>';
    } else if (r) {
        body += '<div style="margin:10px 0; padding:8px 10px; background:#222; border-radius:6px;">' +
            'Captured <strong>' + r.pts.length + '</strong> points. ' +
            (r.kneeAmps > 0 ? 'Saturation knee ~<strong>' + r.kneeAmps.toFixed(0) + ' A</strong> (' + r.kneeDuty.toFixed(0) + '% duty). Data is valid.'
                : 'No saturation knee within range.') +
            '<br>Proposed <strong>Stabilize current</strong> ' + r.propStabA.toFixed(0) + ' A &nbsp;·&nbsp; <strong>Step amplitude</strong> ' + r.propStepPct.toFixed(1) + '% duty.' +
            (r.ceilLimited ? '<br><span style="color:#f0a500;">The ramp hit the Max Field % limit before reaching the amp target, so the curve is cut short. If the proposals look low, raise “Max Field (%)” (Settings ▸ Battery) and re-run.</span>' : '') +
            (r.ok ? '' : '<br><span style="color:#f0a500;">Curve looks marginal — review before applying.</span>') +
            (cx.fieldApplied ? '<br><span style="color:#5a5;">Applied.</span>' : '') + '</div>';
    }
    if (!cx.fieldRunning && !r) body += '<p style="font-size:15px;line-height:1.5;"><strong>Raise engine speed to something within normal cruising range, press Run, and keep it roughly steady until the test finishes — best effort is fine, it doesn\'t have to be perfect.</strong></p><button onclick="cxFieldStart()" class="btn-primary" style="width:100%;padding:9px;">Run field-% ramp</button>';
    else if (!cx.fieldRunning && r) {
        // One primary action: clean result → Apply & run next (cxApplyRunBtn); applied → advance.
        const action = cx.fieldApplied ? cxNextBtn(true) : cxApplyRunBtn('cxFieldApply', r.ok && !r.ceilLimited);
        body += '<div style="margin-top:12px;">' + action + ' <button onclick="cxFieldStart()" class="btn-secondary btn-sm">Re-run</button></div>';
    }
    b.innerHTML = body;
}
function cxFieldStart() {
    cxShowTab('plots', 'displays');   // open-loop ramp → watch on Plots ▸ Short Term
    cx.fieldResult = null; cx.fieldApplied = false; cx.fieldAbort = null; cx.fieldRunning = true; commissionRender();
    cxGet('startFieldCurve=1').then(() => {
        cxStopPoll();
        let waited = 0, sawActive = false;
        cxPollTimer = setInterval(() => {
            waited += 1.5;
            fetch(buildURL('/fieldcurve.json')).then(r => r.json()).then(j => {
                if (j.active) sawActive = true;
                if (j.aborted) {                         // protection latched an abort — may still read active=1 during the 30s lockout, so don't wait for !active
                    cxStopPoll(); cx.fieldRunning = false; cx.fieldAbort = j.abort || 'Protection fired — see console.'; commissionRender();
                } else if (j.abort && !j.active) {        // a protection cut this run — reason latched in firmware
                    cxStopPoll(); cx.fieldRunning = false; cx.fieldAbort = j.abort; commissionRender();
                } else if (j.ready && !j.active) {        // completed normally
                    cxStopPoll(); cx.fieldRunning = false; cx.fieldResult = j; commissionRender();
                } else if (sawActive && !j.active) {      // ran then stopped, no result/reason (e.g. cancel)
                    cxStopPoll(); cx.fieldRunning = false; commissionRender();
                } else if (!sawActive && waited > 12) {   // never started
                    cxStopPoll(); cx.fieldRunning = false; cx.fieldAbort = "No start reported within 12 s (this is a browser timeout, not a firmware error). Confirm you are in AUTO mode with the engine turning, then run again."; commissionRender();
                }
            }).catch(() => { });
        }, 1500);
    }).catch(e => { cx.fieldRunning = false; xAlert('Field ramp start failed: ' + e); commissionRender(); });
}
function cxFieldApply(run = false) {
    const r = cx.fieldResult; if (!r) return;
    cxGet('SystemIDStabilizeAmps=' + r.propStabA.toFixed(1))
        .then(() => cxGet('SystemIDStepAmplitude=' + r.propStepPct.toFixed(2)))
        .then(() => { cx.fieldApplied = true; if (run) cxAdvanceRun(); else commissionRender(); })
        .catch(e => xAlert('Apply failed: ' + e));
}

// ── Step 8 · Min% floor — GUIDED onset-knee sweeps at 3 DESCENDING RPMs → Min% column ──
// Runs LAST so the engine is fully warmed up before the first hold at maximum working RPM.
// Reuses the field ramp in onset-stop mode (firmware: fieldCurveOnsetMode). The wizard walks the user
// DOWN the throttle through three held speeds (max working RPM → mid → idle) — one "Start" per step.
// Each clean sweep auto-commits as an anchor; the firmware warm-starts each sweep from the previous
// point (onset only rises as RPM falls), so only the first reaches high RPM and only briefly.
// applyKneeCurve least-squares fits onset = a + C/RPM across the 3 points (2-param model: 3 points
// give the fit PLUS an outlier residual). SAFETY: the HIGHEST captured RPM (step 1) is the zero-ceiling
// — above it the floor is forced to 0, so the field can always shut fully off at high speed.
const CX_KNEE_STEPS = [
    { tag: 'your maximum working RPM', hint: 'Rev to ~ the highest RPM you typically run and hold — test takes a few seconds.' },
    { tag: 'a mid/typical cruising RPM', hint: 'Ease the throttle down to a middle speed and hold.' },
    { tag: 'idle', hint: 'Let the engine settle to idle and hold.' }
];
function cxRenderKnee(b) {
    if (cx.kneeAnchors === undefined) { cx.kneeAnchors = []; cxKneeRefresh(); }
    const anchors = cx.kneeAnchors || [];
    const NSTEP = CX_KNEE_STEPS.length;
    const step = anchors.length;          // 0..2 = next guided capture; >=3 = review & approve
    let body = '<p style="font-size:15px;line-height:1.5;">In this final step you\'ll hold three speeds, starting at your highest ' +
        'working speed now that the engine is warm, while the regulator searches for the onset knee ' +
        '(where the field begins to produce an output current).</p>';

    // Progress dots — done (✓), current (highlighted), pending.
    let dots = '';
    for (let i = 0; i < NSTEP; i++) {
        const done = i < anchors.length, cur = i === step && step < NSTEP;
        dots += '<span style="display:inline-block;width:22px;height:22px;line-height:22px;text-align:center;border-radius:50%;margin-right:6px;font-size:12px;' +
            (done ? 'background:#2a5a2a;color:#9f9;' : cur ? 'background:#234;color:#4a9eff;border:1px solid #4a9eff;' : 'background:#222;color:#778;') + '">' +
            (done ? '✓' : (i + 1)) + '</span>';
    }
    body += '<div style="margin:4px 0 12px;">' + dots + '</div>';

    if (cx.kneeRunning) {
        body += '<p style="color:#4a9eff;">Automatic current sweep running… keep speed roughly steady — best effort, it doesn\'t have to be perfect. <span id="cx-knee-prog"></span></p>';
        body += '<button disabled class="btn-primary" style="width:100%;padding:9px;opacity:0.55;cursor:default;">Recording…</button>';
    } else if (step < NSTEP) {
        const s = CX_KNEE_STEPS[step];
        if (cx.kneeAbort) {
            body += '<div style="margin:10px 0;padding:8px 10px;background:#3a2222;border:1px solid #a55;border-radius:6px;color:#f0a500;">' +
                'Automatic current sweep stopped: <strong>' + cx.kneeAbort + '</strong><br>' +
                '<span style="font-size:13px;color:#caa;">Open the <strong>Console</strong> tab for the firmware reason. If there is no <em>Min% knee</em> line there, the regulator never ran the automatic current sweep — fix the cause above, then Start again.</span></div>';
        } else if (cx.kneeNoOnset) {
            body += '<div style="margin:10px 0;padding:8px 10px;background:#3a3322;border:1px solid #a85;border-radius:6px;color:#f0a500;">' +
                (cx.kneeCeilLimited
                    ? 'The automatic current sweep reached the Max Field % limit before any onset — the real onset may be above it. Raise “Max Field (%)” (Settings ▸ Battery) and Start again, or hold a slightly different steady RPM.'
                    : 'No clean onset at that speed — nothing recorded. Hold a slightly different steady RPM in the same range, then Start again.') + '</div>';
        }
        body += '<div style="margin:10px 0;padding:10px 12px;background:#1c2530;border-radius:6px;">' +
            '<div style="font-size:15px;"><strong>Step ' + (step + 1) + ' of ' + NSTEP + '</strong> — hold the engine at <strong style="color:#4a9eff;">' + s.tag + '</strong>, then press <strong>Record</strong>.</div>' +
            '<div style="margin-top:4px;color:#9aa;font-size:13px;">' + s.hint + '</div></div>';
        body += '<button onclick="cxKneeStart()" class="btn-primary" style="width:100%;padding:9px;">Record</button>';
    } else {
        body += '<div style="margin:10px 0;padding:8px 10px;background:#1e2a1e;border:1px solid #3a5a3a;border-radius:6px;color:#bdb;">' +
            'All three speeds captured. Review below, then approve.</div>';
        // Outlier flag — the 3 points should fall on one onset = a + C/RPM curve. A large residual means
        // one hold drifted or caught a load step during that sweep.
        if (typeof cx.kneeFitResid === 'number' && cx.kneeFitResid > 2.0) {
            const wi = cx.kneeFitWorstIdx, wlabel = (wi >= 0 && CX_KNEE_STEPS[wi]) ? CX_KNEE_STEPS[wi].tag : 'one point';
            body += '<div style="margin:10px 0;padding:8px 10px;background:#3a3322;border:1px solid #a85;border-radius:6px;color:#f0a500;">' +
                'These three don\'t sit on one curve (off by ' + cx.kneeFitResid.toFixed(1) + '% at <strong>' + wlabel + '</strong>). ' +
                'Likely a drifting hold or a load change during that automatic current sweep. You can still approve, but Start over is cheap now that automatic current sweeps are warm-started.</div>';
        }
    }

    // Captured-so-far table, labelled by which guided target produced each point.
    if (anchors.length) {
        const rows = anchors.map((a, i) => '<tr><td>' + (CX_KNEE_STEPS[i] ? CX_KNEE_STEPS[i].tag : '—') + '</td><td>' + a.rpm.toFixed(0) + '</td><td>' + a.duty.toFixed(1) + '%</td><td>' + a.tempF.toFixed(0) + '°F</td></tr>').join('');
        body += '<table style="width:100%;margin-top:12px;font-size:13px;border-collapse:collapse;"><tr style="text-align:left;color:#9aa;"><th>Target</th><th>RPM</th><th>Onset</th><th>Temp</th></tr>' + rows + '</table>';
    }

    if (step >= NSTEP) {
        if (cx.kneeApplied) {
            // Applied: drop the Apply button entirely; advance is the one primary action.
            body += '<div style="margin-top:6px;"><span style="color:#5a5;">Applied — Min% column filled.</span></div>' +
                '<div style="margin-top:12px;">' + cxNextBtn(true) + ' <button onclick="cxKneeRestart()" class="btn-secondary btn-sm">Start over</button></div>';
        } else {
            body += '<div style="margin-top:12px;">' +
                '<button onclick="cxKneeApply()" class="btn-primary btn-sm">Apply</button> ' +
                '<button onclick="cxKneeRestart()" class="btn-secondary btn-sm">Start over</button></div>';
        }
    } else if (anchors.length) {
        body += '<div style="margin-top:8px;"><button onclick="cxKneeRestart()" class="btn-secondary btn-sm">Start over</button></div>';
    }
    b.innerHTML = body;
}
function cxKneeStart() {
    cxShowTab('plots', 'displays');   // onset ramp → watch on Plots ▸ Short Term
    cx.kneeAbort = null; cx.kneeNoOnset = false; cx.kneeRunning = true; commissionRender();
    cxGet('startKneeSweep=1').then(() => {
        cxStopPoll();
        let waited = 0, sawActive = false;
        cxPollTimer = setInterval(() => {
            waited += 1.5;
            fetch(buildURL('/kneesweep.json')).then(r => r.json()).then(j => {
                cx.kneeAnchors = j.anchors || [];
                if (j.active) sawActive = true;
                if (j.aborted) {                         // protection latched an abort — may still read active=1 during the 30s lockout, so don't wait for !active
                    cxStopPoll(); cx.kneeRunning = false; cx.kneeAbort = j.abort || 'Protection fired — see console.'; commissionRender();
                } else if (j.abort && !j.active) {        // a protection cut this run — reason latched in firmware
                    cxStopPoll(); cx.kneeRunning = false; cx.kneeAbort = j.abort; commissionRender();
                } else if (j.ready && !j.active) {        // completed — auto-commit only a CLEAN onset
                    cxStopPoll();
                    if (j.ok && j.kneeDuty > 0) {         // good point → commit and advance to next step
                        cxGet('addKneeAnchor=1').then(() => { cx.kneeRunning = false; cxKneeRefresh(); })
                            .catch(e => { cx.kneeRunning = false; xAlert('Add failed: ' + e); commissionRender(); });
                    } else {                              // no clean onset → record nothing, let them retry
                        cx.kneeRunning = false; cx.kneeNoOnset = true; cx.kneeCeilLimited = !!j.ceilLimited; commissionRender();
                    }
                } else if (sawActive && !j.active) {      // ran then stopped, no result/reason (e.g. cancel)
                    cxStopPoll(); cx.kneeRunning = false; commissionRender();
                } else if (!sawActive && waited > 12) {   // never started
                    cxStopPoll(); cx.kneeRunning = false; cx.kneeAbort = "No start reported within 12 s (this is a browser timeout, not a firmware error). Confirm you are in AUTO mode with the engine turning, then Start again."; commissionRender();
                }
            }).catch(() => { });
        }, 1500);
    }).catch(e => { cx.kneeRunning = false; xAlert('Automatic current sweep start failed: ' + e); commissionRender(); });
}
function cxKneeApply() { cxGet('applyKneeCurve=1').then(() => { cx.kneeApplied = true; commissionRender(); }).catch(e => xAlert('Apply failed: ' + e)); }
function cxKneeRestart() { cxGet('clearKneeAnchors=1').then(() => { cx.kneeApplied = false; cx.kneeNoOnset = false; cx.kneeCeilLimited = false; cx.kneeAbort = null; cx.kneeFitResid = undefined; cx.kneeFitWorstIdx = -1; cxKneeRefresh(); }).catch(e => xAlert('Clear failed: ' + e)); }
function cxKneeRefresh() {
    fetch(buildURL('/kneesweep.json')).then(r => r.json()).then(j => {
        cx.kneeAnchors = j.anchors || [];
        cx.kneeFitResid = (typeof j.fitResid === 'number' && j.fitResid >= 0) ? j.fitResid : undefined;
        cx.kneeFitWorstIdx = (typeof j.fitWorstIdx === 'number') ? j.fitWorstIdx : -1;
        if (cx.phase === 7) commissionRender();
    }).catch(() => { });
}

// ── Step 3 · Plant fit — open-loop sweep → PI gains + filters ─────────────────
function cxRenderPlant(b) {
    const fit = cx.fit;
    let body = '';
    if (cx.plantRunning) body += '<p style="color:#4a9eff;">Sine sweep running… hold RPM steady.</p>';
    else if (fit) {
        if (!fit.ok) body += '<div style="margin:10px 0;color:#f0a500;">No −3 dB corner found in the swept range. Widening the sweep and retrying…</div>';
        else body += '<div style="margin:10px 0; padding:8px 10px; background:#222; border-radius:6px;">' +
            'Plant τ <strong>' + fit.tauMs.toFixed(0) + ' ms</strong>, K ' + fit.K.toFixed(3) + ' A/%, dead time ' + fit.thetaMs.toFixed(0) + ' ms.<br>' +
            'Proposed <strong>Kp ' + fit.Kp.toFixed(3) + '</strong>, <strong>Ki ' + fit.Ki.toFixed(3) + '</strong>; filters τ/3=' + Math.round(fit.tauMs / 3) + ' ms, voltage τ=' + Math.round(fit.tauMs) + ' ms.' +
            (cx.plantApplied ? '<br><span style="color:#5a5;">Applied.</span>' : '') + '</div>';
    }
    // Speed instruction tracks the plan: after the Field curve the engine is already at cruise.
    if (!cx.plantRunning && !fit) body += '<p style="font-size:15px;line-height:1.5;"><strong>' + (cxPlan[1] ? 'Keep the engine steady at the same cruising speed and press Run.' : 'Bring the engine to a typical cruising speed, hold, and press Run.') + '</strong></p><button onclick="cxPlantStart(false)" class="btn-primary" style="width:100%;padding:9px;">Run plant sine sweep</button>';
    else if (!cx.plantRunning && fit && fit.ok) {
        // One primary action: clean fit → Apply & run next (cxApplyRunBtn); applied → advance.
        const action = cx.plantApplied ? cxNextBtn(true) : cxApplyRunBtn('cxPlantApply', true);
        body += '<div style="margin-top:12px;">' + action + ' <button onclick="cxPlantStart(false)" class="btn-secondary btn-sm">Re-run</button></div>';
    }
    b.innerHTML = body;
}
function cxPlantStart(wide) {
    cxShowTab('plots', 'displays');   // open-loop sine sweep → watch on Plots ▸ Short Term
    cx.fit = null; cx.plantApplied = false; cx.plantRunning = true; commissionRender();
    const fStart = wide ? 0.3 : 0.5, fEnd = wide ? 30 : 20;
    cxGet('systemIDTestType=1&systemIDSineFreqStart=' + fStart + '&systemIDSineFreqEnd=' + fEnd)
        .then(() => cxGet('startSystemID=1'))
        .then(() => {
            cxStopPoll();
            let waited = 0;
            cxPollTimer = setInterval(() => {
                waited += 1.5;
                fetch(buildURL('/sysidbode')).then(r => r.json()).then(j => {
                    if (j.aborted) { cxStopPoll(); cx.plantRunning = false; xAlert('Plant sweep aborted — a protection fired during the test (see console). Re-run once charging resumes.'); commissionRender(); return; }
                    if (waited > 240 && !j.active && !j.ready) { cxStopPoll(); cx.plantRunning = false; xAlert('Plant sweep never reported starting (browser timeout, not a firmware error). Confirm you are in AUTO mode with the engine turning; open the Console tab to see if the regulator rejected the request, then run again.'); commissionRender(); return; }
                    if (j.ready && !j.active) {
                        cxStopPoll();
                        const pts = j.pts;
                        if (pts.length >= 3) {
                            const fit = sysidFitFOPDT(pts, Math.max(1e-9, pts[0].g));
                            cx.fit = fit;
                            if (fit.ok) {
                                sysidFitTauMs = fit.tauMs; sysidFitKp = fit.Kp; sysidFitKi = fit.Ki;
                                // Persist the fitted tau on the device + refresh the actionable-disturbance readout.
                                if (currentAdminPassword) cxGet('systemIDPlantTauMs=' + Math.round(fit.tauMs));
                                updatePlantTauReadout(fit.tauMs);
                            }
                            cx.plantRunning = false; commissionRender();
                            if (!fit.ok && !cx._widened) { cx._widened = true; setTimeout(() => cxPlantStart(true), 1500); }
                        } else { cx.fit = { ok: false }; cx.plantRunning = false; commissionRender(); }
                    }
                }).catch(() => { });
            }, 1500);
        }).catch(e => { cx.plantRunning = false; xAlert('Sweep start failed: ' + e); commissionRender(); });
}
function cxPlantApply(run = false) {
    const f = cx.fit; if (!f || !f.ok) return;
    const tcFast = Math.max(1, Math.round(f.tauMs / 3)), tcSlow = Math.max(1, Math.round(f.tauMs));
    cxGet('PidKp=' + f.Kp.toFixed(4))
        .then(() => cxGet('PidKi=' + f.Ki.toFixed(4)))
        .then(() => cxGet('InputFilterTC=' + tcFast))
        .then(() => cxGet('OutputPIDFilterTC=' + tcFast))
        .then(() => cxGet('VoltageFilterTC=' + tcSlow))
        .then(() => { cx.plantApplied = true; if (run) cxAdvanceRun(); else commissionRender(); })
        .catch(e => xAlert('Apply failed: ' + e));
}

// ── Step 4 · Verify — closed-loop stability check ────────────────────────────
function cxRenderVerify(b) {
    let body = '';
    if (cx.verifyRunning) body += '<p style="color:#4a9eff;">Closed-loop sweep running…</p>';
    else if (cx.verify) {
        const v = cx.verify;
        body += '<div style="margin:10px 0; padding:8px 10px; background:#222; border-radius:6px;">' +
            'Peak closed-loop gain <strong style="color:' + (v.pass ? '#5a5' : '#f0a500') + ';">' + v.peakGain.toFixed(2) + '</strong>' +
            (v.bwHz > 0 ? ', bandwidth ~' + v.bwHz.toFixed(1) + ' Hz' : '') + '.<br>' +
            (v.pass ? '<span style="color:#5a5;">Passed — loop is stable.</span>' : '<span style="color:#f0a500;">Peak gain above 1.15 — loop is too aggressive.</span>') + '</div>' +
            (v.pass ? '' : '<button onclick="cxDetune()" class="btn-primary btn-sm">Detune 20% &amp; re-verify</button>');
    }
    if (!cx.verifyRunning && !cx.verify) body += '<p style="font-size:15px;line-height:1.5;"><strong>' + ((cxPlan[1] || cxPlan[2]) ? 'Keep the engine steady at the same cruising speed and press Run.' : 'Bring the engine to a typical cruising speed, hold, and press Run.') + '</strong></p><button onclick="cxVerifyStart()" class="btn-primary" style="width:100%;padding:9px;">Run closed-loop verify</button>';
    else if (!cx.verifyRunning && cx.verify) {
        // cxVerifyDone leaves closed-loop tuning (TuningMode=0) before advancing, so it builds the
        // advance button inline instead of cxNextBtn. Pass → advance is the one primary action;
        // fail → no advance (Detune is primary, Re-run secondary).
        const nx = cxNextSelected(cx.phase);
        const vlabel = (nx === -1) ? 'Finish' : ('Next: ' + CX_PHASES[nx] + ' →');
        const action = cx.verify.pass ? '<button onclick="cxVerifyDone()" class="btn-primary btn-sm">' + vlabel + '</button> ' : '';
        body += '<div style="margin-top:12px;">' + action + '<button onclick="cxVerifyStart()" class="btn-secondary btn-sm">Re-run</button></div>';
    }
    b.innerHTML = body;
}
function cxVerifyStart() {
    cxShowTab('tuning', 'current');   // closed-loop sine sweep → watch on Tuning ▸ Current
    cx.verify = null; cx.verifyRunning = true; commissionRender();
    // Drive the closed-loop sweep from values computed off the plant fit + field curve, not
    // whatever happens to be on the Tuning ▸ Current tab (unknown/stale at commissioning time).
    const p = cxVerifyParams();
    cxGet('tuningWaveFloor=' + p.floor + '&waveAmplitude=' + p.amp +
          '&tuningSweepStart=' + p.fStart + '&tuningSweepEnd=' + p.fEnd +
          '&tuningSweepCycles=' + p.cycles + '&tuningWaveform=2&TuningMode=1')
        .then(() => cxGet('startTuningSweep=1'))
        .then(() => {
            cxStopPoll();
            let waited = 0;
            cxPollTimer = setInterval(() => {
                waited += 1.5;
                fetch(buildURL('/tuningbode')).then(r => r.json()).then(j => {
                    if ((j.done && !j.active) || waited > 200) {
                        cxStopPoll();
                        const pts = j.pts || [];
                        let peak = 0; pts.forEach(p2 => { if (p2.g > peak) peak = p2.g; });
                        let bw = -1; const g0 = pts.length ? pts[0].g : 0;
                        for (let i = 1; i < pts.length; i++) { if (pts[i].g < 0.707 * g0) { bw = pts[i].f; break; } }
                        cx.verify = { peakGain: peak, bwHz: bw, pass: (peak > 0 && peak <= 1.15) };
                        cx.verifyRunning = false;
                        cxGet('TuningMode=0').finally(() => commissionRender());  // leave closed-loop tuning
                    }
                }).catch(() => { });
            }, 1500);
        }).catch(e => { cx.verifyRunning = false; xAlert('Verify start failed: ' + e); commissionRender(); });
}
function cxDetune() {
    const kp = sysidFitKp * 0.8, ki = sysidFitKi * 0.8;
    sysidFitKp = kp; sysidFitKi = ki;
    cxGet('PidKp=' + kp.toFixed(4)).then(() => cxGet('PidKi=' + ki.toFixed(4))).then(() => cxVerifyStart());
}
function cxVerifyDone() { cxGet('TuningMode=0').finally(() => cxAdvance()); }

// ── Step 7 · CV plant fit — current square wave → battery-voltage FOPDT → λ-tuned Kp/Ki ──
// Reuses the proven current-tuning square wave (TuningMode, tuningWaveform=0) to COMMAND current; the
// browser records the live CSV1 (IBV, MeasuredAmps) stream and fits K/τ/L locally (no internet),
// then writes them via the cvPlantK/τ/L handlers and switches CV gains to Auto. No new firmware control
// code — TuningMode already gates G1/G2 (fast-OV stays live) and restores bumplessly on exit.
let cvFitCapture = null;   // {active, samples:[{t,v,iB,iA}], t0} while a fit run is recording

function cvFitOnCsv1(data) {
    if (!cvFitCapture || !cvFitCapture.active) return;
    // Capture IBV (the controlled voltage — INA228 bus voltage, the SAME signal the CV PI loop reads,
    // NOT BatteryV/ADS1115), Bcur (BATTERY current — the §F/§G regression denominator: battery voltage
    // responds to battery current), and MeasuredAmps (ALTERNATOR current — kept ONLY for the
    // external-network check ΔI_ext = ΔI_alt − ΔI_batt). All three are CSV1 fields scaled ×100.
    const v  = ('IBV' in data)          ? parseFloat(data.IBV) / 100          : NaN;
    const iB = ('Bcur' in data)         ? parseFloat(data.Bcur) / 100         : NaN;
    const iA = ('MeasuredAmps' in data) ? parseFloat(data.MeasuredAmps) / 100 : NaN;
    if (!isFinite(v) || !isFinite(iB)) return;
    cvFitCapture.samples.push({ t: (performance.now() - cvFitCapture.t0) / 1000, v: v, iB: iB, iA: isFinite(iA) ? iA : 0 });
}

// CV plant identification — measure ONLY the DC gain K_dc (the fast step edge, slow ramp removed) and preview the gains from a
// conservative target crossover. The old rise-to-63% τ/L FOPDT fit is RETIRED: on a battery the step is
// dominated by an instantaneous ohmic jump, so τ/L floored out and the integral gain ran away. A real
// step test proved the loop is stability-robust (86–95° phase margin even at the "disaster" gains), so
// only K_dc binds. See Working Markdown Docs/CV_AUTOTUNE_PLAN.md §E. These two constants MUST match
// CV_CROSSOVER_TARGET / CV_PI_ZERO in 6_functions.ino recomputeCvGains() (the authoritative compute).
// These mirror the device settings cvCrossover / cvPiZero (Tuning ▸ Voltage). They're `let` and refreshed
// from the CSV3 echo in updateCvGainModeUI() so the fit preview matches whatever the device will apply.
let CV_CROSSOVER_TARGET = 0.20;  // ω_c, rad/s — TRUE CV closed-loop crossover (≈20 s response default; live value from device)
let CV_PI_ZERO     = 0.70;   // ρ, rad/s — PI integral zero; Ki = ρ·Kp (default; live value from device)
// Exact PI magnitude condition at ω_c (CV_AUTOTUNE_PLAN.md §F.3) — the SAME math as firmware
// recomputeCvGains(). Knorm = K20·(12/sysV) in V per 12V-equiv per A. Returns clamped 12V-equiv {Kp,Ki}.
function cvGainsFromKnorm(Knorm, omega_c, rho) {
    omega_c = (omega_c > 1e-3) ? omega_c : 0.20; rho = rho || 0.70;
    const Kp = 1 / (Knorm * Math.sqrt(1 + (rho / omega_c) * (rho / omega_c)));
    return { Kp: Math.min(120, Math.max(2, Kp)), Ki: Math.min(80, Math.max(1, rho * Kp)) };
}
// floorA/ampA = commanded low level + step size; sysV = nominal system voltage (12/24/48).
// Returns {ok, K (V/A = K_dc), Kp, Ki (12V-equiv preview), nUp, relK, deadMs} or {ok:false, reason}.
function cvLinFit(pts) {
    // Least-squares line v = a + b*t over a window; resid = RMS of the fit (the voltage-noise estimate,
    // already detrended so it is noise only, not the slow ramp).
    const n = pts.length; if (n < 3) return null;
    let st = 0, sv = 0, stt = 0, stv = 0;
    for (const p of pts) { st += p.t; sv += p.v; stt += p.t * p.t; stv += p.t * p.v; }
    const den = n * stt - st * st; if (Math.abs(den) < 1e-12) return null;
    const b = (n * stv - st * sv) / den, a = (sv - b * st) / n;
    let ss = 0; for (const p of pts) { const e = p.v - (a + b * p.t); ss += e * e; }
    return { a: a, b: b, resid: Math.sqrt(ss / n), n: n };
}

// Mean of a sample field over a [t0,t1) time window. key ∈ {v, iB, iA}.
function cvWinMean(samples, t0, t1, key) {
    let s = 0, n = 0;
    for (const p of samples) { if (p.t >= t0 && p.t < t1) { s += p[key]; n++; } }
    return n ? s / n : NaN;
}

// Single-pulse, finite-horizon battery-current fit (CV_AUTOTUNE_PLAN.md §F rev 2). ONE bounded up-step is
// commanded through the inner current loop; we read how BATTERY voltage (IBV) responds to BATTERY current
// (Bcur) at a fixed 20 s horizon, baseline-detrended so the slow SOC/diffusion ramp cancels. There is no
// settle to wait for (a charging battery never plateaus) and no train (a train accumulates polarization).
//   K20  = [V_fit(t_edge+20s) − V_baseline_extrapolated(t_edge+20s)] / ΔI_battery     (V/A)
//   ε20  = 20·|slope of V_fit| / |ΔV20|   — what fraction of the rise is still moving at 20 s (non-stationarity)
// The up-edge gives the primary K20; the return-edge is a REPEATABILITY DIAGNOSTIC only (different
// electrochemical state — never averaged in). marks = {di (commanded ΔI), tUp, tReturn} from the orchestrator.
// ALL checks are ADVISORY (collected in .warns) — the ONLY ok:false case is "no measurement exists".
function cvFitSinglePulse(samples, marks, sysV) {
    const SKIP_S = 4.5, HORIZON_S = 20.0;   // §F.7 GUESSES from one 12 V LFP bench bank — field-verify, not validated
    if (!samples || samples.length < 20 || marks.tUp == null)
        return { ok: false, reason: 'no telemetry captured (the test produced no usable samples) — re-run' };
    const tUp = marks.tUp, tRet = (marks.tReturn != null) ? marks.tReturn : (tUp + SKIP_S + HORIZON_S + 1);
    const baseW = [tUp - 5.0, tUp - 0.3];
    const upW = [tUp + SKIP_S, Math.min(tUp + HORIZON_S, tRet - 0.3)];
    const upPts = samples.filter(p => p.t >= upW[0] && p.t < upW[1]);
    const basePts = samples.filter(p => p.t >= baseW[0] && p.t < baseW[1]);
    if (upPts.length < 6 || basePts.length < 4)
        return { ok: false, reason: 'the current step did not hold long enough to read the 20 s horizon — re-run' };
    const vFit = cvLinFit(upPts.map(p => ({ t: p.t, v: p.v })));
    const vBase = cvLinFit(basePts.map(p => ({ t: p.t, v: p.v })));
    if (!vFit || !vBase)
        return { ok: false, reason: 'could not fit the voltage response — re-run' };
    const tH = tUp + HORIZON_S;
    const dV20 = (vFit.a + vFit.b * tH) - (vBase.a + vBase.b * tH);   // baseline-detrended rise at the horizon
    const iBup = cvWinMean(samples, upW[0], upW[1], 'iB');
    const iBbase = cvWinMean(samples, baseW[0], baseW[1], 'iB');
    const dIbat = iBup - iBbase;                                       // measured BATTERY-current step = the denominator
    if (!(Math.abs(dIbat) > 0.5))
        return { ok: false, reason: 'no measurable battery-current step (current never reached the battery / divide-by-zero) — confirm the inner current loop is tuned, then re-run' };
    const K20 = dV20 / dIbat;
    if (!(K20 > 1e-4))
        return { ok: false, reason: 'battery voltage moved the wrong way for the current step — check the battery-current sensor sign / wiring, then re-run' };
    const eps20 = HORIZON_S * Math.abs(vFit.b) / Math.max(1e-4, Math.abs(dV20));
    // Alternator-current step + external-network check (advisory): in a clean test all the alternator-current
    // increment lands at the battery, so ΔI_alt ≈ ΔI_batt. A gap = a load switched / another source moved.
    const iAup = cvWinMean(samples, upW[0], upW[1], 'iA');
    const iAbase = cvWinMean(samples, baseW[0], baseW[1], 'iA');
    const dIalt = iAup - iAbase;
    const dIext = dIalt - dIbat;
    const extScore = Math.abs(dIext) / Math.max(1, Math.abs(dIalt));
    const sigV = vFit.resid;                                          // detrended voltage ripple
    const snr = Math.abs(dV20) / Math.max(1e-4, sigV);
    // Return-edge K20 — REPEATABILITY DIAGNOSTIC ONLY (do NOT average with the up-edge).
    let K20ret = NaN;
    {
        const rUpW = [tRet + SKIP_S, tRet + HORIZON_S], rBaseW = [tRet - 5.0, tRet - 0.3];
        const rUp = samples.filter(p => p.t >= rUpW[0] && p.t < rUpW[1]);
        const rB = samples.filter(p => p.t >= rBaseW[0] && p.t < rBaseW[1]);
        if (rUp.length >= 6 && rB.length >= 4) {
            const f = cvLinFit(rUp.map(p => ({ t: p.t, v: p.v }))), fb = cvLinFit(rB.map(p => ({ t: p.t, v: p.v })));
            if (f && fb) {
                const th = tRet + HORIZON_S, dvr = (f.a + f.b * th) - (fb.a + fb.b * th);
                const dir = cvWinMean(samples, rUpW[0], rUpW[1], 'iB') - cvWinMean(samples, rBaseW[0], rBaseW[1], 'iB');
                if (Math.abs(dir) > 0.5) K20ret = dvr / dir;
            }
        }
    }
    const cmdDI = marks.di || dIbat;
    const deliveryFrac = Math.abs(dIbat) / Math.max(1e-4, Math.abs(cmdDI));
    // User-facing advisories — short, actionable. The full numbers (ε20, ΔI_ext, SNR, both edges) are in the
    // downloadable cvfit.csv, not on the wizard face.
    const warns = [];
    if (deliveryFrac < 0.6) warns.push('The current step came up short — alternator may be weak at this RPM. Re-run at a higher RPM.');
    if (extScore > 0.25) warns.push('Something else moved during the test (a load switched, or another charger). Re-run with all other loads steady.');
    if (snr < 12) warns.push('Weak signal vs. noise — result is usable but rough. A higher or quieter RPM would help.');
    if (eps20 > 0.5) warns.push('The battery was still settling at the end, so the gain may read slightly aggressive. Consider re-running.');
    const vNorm = 12 / (sysV || 12), Knorm = K20 * vNorm;
    const g = cvGainsFromKnorm(Knorm, CV_CROSSOVER_TARGET, CV_PI_ZERO);
    return {
        ok: true, K20: K20, eps20: eps20, K20ret: K20ret, dIbat: dIbat, dIalt: dIalt, dIext: dIext, extScore: extScore,
        achievedDV: dV20, sigV: sigV, snr: snr, deliveryFrac: deliveryFrac, Kp: g.Kp, Ki: g.Ki,
        skipS: SKIP_S, horizonS: HORIZON_S, nUp: upPts.length, nBase: basePts.length, nSamp: samples.length, warns: warns
    };
}

function cxRenderCVPlant(b) {
    const f = cx.cvFit;
    let body = '';
    if (cx.cvFitRunning) {
        body += '<p style="color:#4a9eff;">Running CV plant fit — hold RPM steady, leave other loads alone.</p>' +
            '<p id="cvFitPhase" style="font-size:13px;color:#ddd;margin-top:-2px;">' + (cx.cvFitPhase || 'Starting…') + '</p>';
    }
    else if (f) {
        if (!f.ok) {
            body += '<div style="margin:10px 0;padding:8px 10px;background:#3a2222;border:1px solid #a55;border-radius:6px;color:#f0a500;">No usable result: ' + f.reason + '</div>';
        } else {
            const concerns = (f.warns && f.warns.length)
                ? '<br><span style="color:#f0a500;">Heads up (you can still Apply):<br>• ' + f.warns.join('<br>• ') + '</span>'
                : '<br>Data is valid.';
            body += '<div style="margin:10px 0; padding:8px 10px; background:#222; border-radius:6px;">' +
                'Measured battery gain <strong>K20 = ' + (f.K20 * 1000).toFixed(1) + ' mV/A</strong>. ' +
                'Proposed <strong>Kp ' + f.Kp.toFixed(1) + '</strong>, <strong>Ki ' + f.Ki.toFixed(1) + '</strong> (12 V-equiv).' +
                concerns +
                (cx.cvApplied ? '<br><span style="color:#5a5;">Applied.</span>' : '') + '</div>' +
                '<button onclick="cxCVFitDownload()" class="btn-secondary btn-sm">Download raw data</button>';
        }
    }
    // After the Disturbances sweep the engine could be anywhere in the band — bring it back to cruise.
    if (!cx.cvFitRunning && !f) body += '<p style="font-size:15px;line-height:1.5;"><strong>' + (cxPlan[4] ? 'Bring the engine back up to a steady cruising speed, hold, and press Run.' : 'Hold a steady cruising speed and press Run.') + '</strong> The test briefly steps the charge current and measures how the battery responds, then proposes the voltage-loop gains.</p>' +
        '<p style="font-size:13px;color:#f0a500;line-height:1.45;">⚠️ Don\'t switch other loads on or off during the test (inverter, thrusters, fridge, windlass…) — it spoils the reading.</p>' +
        '<button onclick="cxCVPlantStart()" class="btn-primary" style="width:100%;padding:9px;">Run CV plant fit</button>';
    else if (!cx.cvFitRunning && f) {
        // One primary action: Apply until applied, then the advance button. Re-run stays secondary.
        let action;
        if (!f.ok) action = '<button onclick="cxCVPlantStart()" class="btn-primary btn-sm">Re-run</button> ' + cxNextBtn(false, false);
        else if (!cx.cvApplied) action = '<button onclick="cxCVPlantApply()" class="btn-primary btn-sm">Apply</button> <button onclick="cxCVPlantStart()" class="btn-secondary btn-sm">Re-run</button>';
        else action = cxNextBtn(true) + ' <button onclick="cxCVPlantStart()" class="btn-secondary btn-sm">Re-run</button>';
        body += '<div style="margin-top:12px;">' + action + '</div>';
    }
    b.innerHTML = body;
}

// Single-pulse orchestration (CV_AUTOTUNE_PLAN.md §F.2): baseline → pilot (sizing probe) → rest → one sized
// up-step held through the 20 s horizon → return. The browser commands a HELD current by setting the tuning
// square-wave floor with amplitude 0 (so the toggle is inert) and tuningSquareAbrupt=1 (true step, no slew);
// stepping the floor IS the pulse — no new firmware control code. TuningMode gates G1/G2; fast-OV stays live.
// §F.7 GUESSES (one 12 V LFP bench bank), field-verify: BASE/PILOT currents, ΔV_target 300 mV, hold times.
function cxCVPlantStart() {
    cxShowTab('plots', 'displays');   // watch current + voltage on Plots ▸ Short Term
    cx.cvFit = null; cx.cvApplied = false; cx.cvFitRunning = true; cx.cvFitDone = false; cx.cvFitPhase = 'Starting…';
    cxStopPoll();
    const sysV = window._nominalStored || 12;
    const BASE_A = 10, PILOT_A = 6, DV_TARGET = 0.30, DI_MAX = 40, V_RESERVE = 0.15;     // §F.7 guesses
    const T_SETTLE = 6, T_PILOT = 3, T_REST = 5, T_UPHOLD = 4.5 + 20 + 3, T_RETHOLD = 4.5 + 20 + 1;  // seconds
    const bulkEcho = getEchoNumber('BulkVoltage_echo');
    const ceilingV = (bulkEcho > 5) ? (bulkEcho + 0.3) : null;   // ≈ AlternatorHardShutdownV (fast-OV trip)
    const marks = { baseLevel: BASE_A, di: null, tUp: null, tReturn: null, pilotK: null, ceilingV: ceilingV };
    const t0now = performance.now();
    cvFitCapture = { active: true, samples: [], t0: t0now };
    const tNow = () => (performance.now() - t0now) / 1000;
    const hold = ms => new Promise(r => setTimeout(r, ms));
    const cmd = floor => cxGet('tuningSquareAbrupt=1&wavePeriod=600&tuningWaveFloor=' + Math.round(floor) + '&waveAmplitude=0&tuningWaveform=0&TuningMode=1');
    const setPhase = p => { cx.cvFitPhase = p; const el = document.getElementById('cvFitPhase'); if (el) el.textContent = p; else commissionRender(); };
    const wm = (a, bb, k) => cvWinMean(cvFitCapture.samples, a, bb, k);
    const fail = e => {
        cx.cvFitDone = true; if (cvFitCapture) cvFitCapture.active = false; cx.cvFitRunning = false;
        cxGet('tuningSquareAbrupt=0&TuningMode=0').catch(() => { });
        xAlert('CV plant fit failed: ' + e); commissionRender();
    };
    commissionRender();
    cmd(BASE_A).then(async () => {
        setPhase('Settling at baseline…'); await hold(T_SETTLE * 1000);
        const vB0 = wm(tNow() - 2.5, tNow(), 'v'), iB0 = wm(tNow() - 2.5, tNow(), 'iB');
        // Pilot sizing probe
        setPhase('Sizing the step…'); await cmd(BASE_A + PILOT_A); await hold(T_PILOT * 1000);
        const vP = wm(tNow() - 1.5, tNow(), 'v'), iP = wm(tNow() - 1.5, tNow(), 'iB');
        const dIp = iP - iB0, dVp = vP - vB0;
        const Kprior = (dIp > 0.5 && dVp > 0) ? (dVp / dIp) : (DV_TARGET / Math.max(1, PILOT_A));   // V/A (fallback)
        marks.pilotK = Kprior;
        // Size the main step: target ΔV, alternator/OV-headroom capped, never below the pilot (need signal).
        const Kupper = Kprior * 1.5;                                  // pessimistic (bigger K → smaller ΔI)
        const headroom = (ceilingV != null && isFinite(vB0)) ? Math.max(0.05, ceilingV - vB0 - V_RESERVE) : DV_TARGET;
        let di = Math.min(DI_MAX, headroom / Math.max(1e-3, Kupper), DV_TARGET / Math.max(1e-3, Kprior));
        di = Math.max(PILOT_A, Math.round(di));
        marks.di = di;
        await cmd(BASE_A); setPhase('Resting…'); await hold(T_REST * 1000);
        // The sized up-step — the measured edge
        await cmd(BASE_A + di); marks.tUp = tNow();
        setPhase('Holding the step — measuring…'); await hold(T_UPHOLD * 1000);
        // Return to baseline (repeatability diagnostic)
        await cmd(BASE_A); marks.tReturn = tNow();
        setPhase('Returning to baseline…'); await hold(T_RETHOLD * 1000);
        if (cvFitCapture) cvFitCapture.active = false;
        await cxGet('tuningSquareAbrupt=0&TuningMode=0').catch(() => { });   // bumpless restore
        const samples = cvFitCapture ? cvFitCapture.samples : [];
        cx.cvFitLastSamples = samples; cx.cvFitMarks = marks;
        cx.cvFit = cvFitSinglePulse(samples, marks, sysV);
        cxCVFitLog(cx.cvFit, marks);   // full diagnostics → Console tab + browser console (NOT the wizard face)
        cx.cvFitDone = true; cx.cvFitRunning = false;
        commissionRender();
    }).catch(fail);
}

function cxCVPlantApply() {
    const f = cx.cvFit; if (!f || !f.ok) return;
    // Store the measured finite-horizon gain K20 (raw V/A at the pack) into cvPlantK; recomputeCvGains()
    // applies the 12V-block normalization + the exact PI magnitude condition and switches CV gains to Auto.
    // The fit confidence record lives in the cvfit.csv download.
    cxGet('cvPlantK=' + f.K20.toFixed(5))
        .then(() => cxGet('cvGainMode=1'))
        .then(() => { cx.cvApplied = true; commissionRender(); })
        .catch(e => xAlert('Apply failed: ' + e));
}

// Full fit diagnostics → dashboard Console tab (appendConsoleLine, so they ride along in Download Logs / the
// remote log relay) AND the browser DevTools console. Deliberately NOT on the wizard face — see the brief
// result panel in cxRenderCVPlant. Same numbers that used to clutter the face, plus the marks.
function cxCVFitLog(f, m) {
    m = m || {};
    const L = [];
    if (!f || !f.ok) {
        L.push('CVfit: no usable result — ' + (f ? f.reason : 'no fit'));
    } else {
        L.push('CVfit: K20 ' + (f.K20 * 1000).toFixed(1) + ' mV/A  Kp ' + f.Kp.toFixed(1) + '  Ki ' + f.Ki.toFixed(1) + ' (12V-equiv)');
        L.push('CVfit: ΔI_batt ' + f.dIbat.toFixed(1) + ' A  ΔV ' + (f.achievedDV * 1000).toFixed(0) + ' mV  SNR ' + f.snr.toFixed(0) + '×  ε20 ' + (f.eps20 * 100).toFixed(0) + '%');
        L.push('CVfit: ΔI_alt ' + f.dIalt.toFixed(1) + ' A  ΔI_ext ' + f.dIext.toFixed(1) + ' A (' + Math.round(f.extScore * 100) + '%)  delivery ' + Math.round(f.deliveryFrac * 100) + '%');
        L.push('CVfit: return-edge ' + (isFinite(f.K20ret) ? (f.K20ret * 1000).toFixed(1) + ' mV/A (' + Math.round(Math.abs(f.K20ret - f.K20) / Math.max(1e-4, Math.abs(f.K20)) * 100) + '% vs up, diagnostic only)' : 'not read'));
        L.push('CVfit: commanded ΔI ' + (m.di != null ? m.di + ' A' : '?') + '  pilotK ' + (m.pilotK != null ? (m.pilotK * 1000).toFixed(1) + ' mV/A' : '?') + '  skip ' + f.skipS + ' s  horizon ' + f.horizonS + ' s  samples ' + f.nSamp);
        if (f.warns && f.warns.length) L.push('CVfit: advisories — ' + f.warns.join(' | '));
    }
    for (const line of L) { try { appendConsoleLine(line, true); } catch (e) { } }
    try { console.log(L.join('\n')); } catch (e) { }
}

// Raw fit dump (CV_AUTOTUNE_PLAN.md §F.7 / commissioning spec §3): the confidence record as header comments
// + raw (t, IBV, Bcur, MeasuredAmps) so the field can tell us whether the τ_p/SKIP_S/horizon guesses transfer.
// Captured browser-side (the fit runs in the browser), offered as a download named cvfit.csv.
function cxCVFitDownload() {
    const s = cx.cvFitLastSamples, f = cx.cvFit, m = cx.cvFitMarks || {};
    if (!s || !s.length) { xAlert('No fit data captured yet.'); return; }
    let txt = '';
    if (f && f.ok) {
        txt += '# cvfit confidence record\n';
        txt += '# K20_mV_per_A,' + (f.K20 * 1000).toFixed(2) + '\n';
        txt += '# eps20,' + f.eps20.toFixed(3) + '\n';
        txt += '# SKIP_S,' + f.skipS + '\n';
        txt += '# horizon_S,' + f.horizonS + '\n';
        txt += '# achieved_dV_mV,' + (f.achievedDV * 1000).toFixed(1) + '\n';
        txt += '# dI_battery_A,' + f.dIbat.toFixed(2) + ',dI_alt_A,' + f.dIalt.toFixed(2) + ',dI_ext_A,' + f.dIext.toFixed(2) + '\n';
        txt += '# snr,' + f.snr.toFixed(1) + ',Kp,' + f.Kp.toFixed(2) + ',Ki,' + f.Ki.toFixed(2) + '\n';
        txt += '# commanded_dI_A,' + (m.di != null ? m.di : '') + ',pilotK_mV_per_A,' + (m.pilotK != null ? (m.pilotK * 1000).toFixed(1) : '') + ',t_up_s,' + (m.tUp != null ? m.tUp.toFixed(2) : '') + ',t_return_s,' + (m.tReturn != null ? m.tReturn.toFixed(2) : '') + '\n';
    }
    txt += 't_s,IBV_V,Bcur_A,MeasuredAmps_A\n';
    for (const p of s) txt += p.t.toFixed(3) + ',' + p.v.toFixed(4) + ',' + p.iB.toFixed(3) + ',' + p.iA.toFixed(3) + '\n';
    const blob = new Blob([txt], { type: 'text/csv' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob); a.download = 'cvfit.csv';
    document.body.appendChild(a); a.click(); document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(a.href), 2000);
}

// ── Step 5 · Disturbances — guided slow sweep populates the matrix ────────────
function cxRenderMatrix(b) {
    let body = '';
    // Pause length matters (§11): a ripple value needs TWO agreeing ~2 s stationary windows at a speed
    // before it commits (agree-twice), so ~6 s per pause. The wizard holds a fixed test current
    // (25% of the cap-table max ≤2000 RPM) through resTest for the whole sweep — ripple scales with
    // current, so the table is only comparable across RPM at one amperage.
    const lvl = cxMatrixLevelA();
    const sweepInstr = '<p style="font-size:15px;line-height:1.5;"><strong>Map ripple across your RPM range with this Space-Invaders-style game.</strong> After pressing Start, bring the engine down to idle and sit there ~10 s while the wizard detects your idle speed. It then holds the alternator at a fixed test current' + (lvl > 0 ? ' (~' + Math.round(lvl) + ' A)' : '') + ' for the whole sweep — keep big electrical loads steady, and pause ~6 s at each speed. You can stop as soon as the wizard confirms the worst-ripple speed is pinned down — no need to clear every target.</p>';
    if (cx.matrixOn) {
        // Sweep-in-progress view is the "RPM Invaders" game (cxGame* below): y-axis = RPM, one
        // invader per required 50-RPM bin, killed when its bin lands in /famatrix.csv. The ripple
        // strip under it plots /filtripple.csv as it populates — a live sanity check on the values
        // the map is admitting.
        body += sweepInstr +
            '<div style="position:relative;">' +
            '<canvas id="cxGame" style="display:block; width:100%; height:400px; background:#161618; border-radius:6px;"></canvas>' +
            '<div id="cxGameToast" style="position:absolute; left:50%; transform:translateX(-50%); top:12px; background:rgba(240,80,60,.92); color:#fff; font-size:12px; font-weight:600; padding:4px 12px; border-radius:12px; opacity:0; transition:opacity .25s; pointer-events:none; white-space:nowrap;"></div>' +
            '</div>' +
            '<div style="font-size:11px; color:#888; margin:8px 0 2px;">Measured filtered ripple vs engine speed, idle at left — <span style="color:#2ec4b6;">alternator</span> / <span style="color:#f0a500;">battery</span> · solid = confirmed, hollow = unconfirmed single reading</div>' +
            '<canvas id="cxGameRip" style="display:block; width:100%; height:90px; background:#161618; border-radius:6px;"></canvas>' +
            '<div id="cx-cov" style="margin:10px 0;">Coverage: checking…</div>' +
            // Disabled until the poll's confidence gate (cxSweepConfidence) is satisfied — clicking early only
            // stops the sweep and drops back to Start (no advance button below the gate), so it looks like
            // "skip" but silently traps you.
            '<button id="cx-sweep-done" onclick="cxMatrixStop()" class="btn-primary btn-sm"' + (cx.matrixCov ? '' : ' disabled') + '>I\'m done sweeping</button>';
    } else if (cx.matrixCov) {
        // Enough coverage already captured → advance is the one primary action; re-sweep is secondary.
        body += cxRtestPanel();  // optional resonance-vs-current characterization (§3.2), non-blocking
        // The panel owns its own navigation in every state that draws buttons (idle/leveling/done/failed) —
        // one green primary = the action we want clicked, plus its own Skip/Re-run/Re-sweep. Only when there
        // is nothing to characterize ('none', or the brief pre-check) does the step need a generic advance;
        // otherwise we'd double up on "to Thresholds" buttons and green a competing action.
        const rtPanelNav = (cx.rtestState === 'idle' || cx.rtestState === 'leveling' || cx.rtestState === 'done' || cx.rtestState === 'failed');
        if (!rtPanelNav) body += '<div style="margin-top:12px;">' + cxNextBtn(true, true) + ' <button onclick="cxMatrixStart()" class="btn-secondary btn-sm">Re-sweep</button></div>';
    } else {
        body += sweepInstr + '<button onclick="cxMatrixStart()" class="btn-primary" style="width:100%;padding:9px;">Start guided sweep</button>';
    }
    b.innerHTML = body;
    // Game lifecycle follows the sweep state; Stop also restores the RPM sparkline strip.
    if (cx.matrixOn) cxGameStart(); else cxGameStop();
}
// Fixed sweep current (RPM_RIPPLE_TABLE_SPEC §2.4): 0.25 × max cap-table amps over rows whose RPM
// breakpoint ≤ 2000; if no breakpoint lands exactly at 2000, the first row above 2000 also competes
// (its band covers part of ≤2000). Reads the same DOM inputs cxRtReady uses (amps valid in kW mode too).
function cxMatrixLevelA() {
    let best = 0, minAbove = Infinity, minAboveAmps = 0, sawAt2000 = false;
    for (let i = 0; i < 10; i++) {
        const cEl = document.getElementById('rpmCapCurrentTable' + i + '_input');
        const rEl = document.getElementById('rpmTableRPMPoints' + i + '_input');
        const amps = cEl ? parseFloat(cEl.value) : NaN;
        const rpm = rEl ? parseFloat(rEl.value) : NaN;
        if (!isFinite(amps) || !isFinite(rpm) || amps <= 0) continue;
        if (rpm <= 2000) { if (amps > best) best = amps; if (rpm === 2000) sawAt2000 = true; }
        else if (rpm < minAbove) { minAbove = rpm; minAboveAmps = amps; }
    }
    if (!sawAt2000 && isFinite(minAbove) && minAboveAmps > best) best = minAboveAmps;
    return 0.25 * best;
}
function cxMatrixStart() {
    const levelA = cxMatrixLevelA();
    if (!(levelA > 1)) { xAlert('RPM/Amps table looks empty — the sweep needs it to size the held test current.'); return; }
    cxShowTab('plots', 'displays');   // watch current on Plots ▸ Short Term
    cx.matrixOn = true; cx.matrixLevelA = levelA; cx.matrixIdle = 0;
    cx.rtestState = undefined; cx.rtest = null; cx.rtestOn = false; cx.rtestRpm = 0;  // re-sweep → re-check resonance
    cxGame.binLo = 0; cxGame.bins = null; cxGame.seeded = false;  // band rebuilt after idle detection
    commissionRender();
    cxGameToast('Sit at idle — detecting your idle RPM…');
    // Idle-adaptive coverage band (§2.5): median of ~4 s of live RPM sets the floor to idle−50
    // (a hardcoded 500 floor bricks the done button on engines idling above ~900). Snap to the
    // 50-RPM grid, clamp to [400, 1200], fall back to 500 if the reading is absent/nonsensical.
    const samples = [];
    const sampler = setInterval(() => { if (isFinite(cx.liveRpm) && cx.liveRpm > 0) samples.push(cx.liveRpm); }, 300);
    setTimeout(() => {
        clearInterval(sampler);
        if (!cx || !cx.matrixOn) return;   // torn down during detection
        const s = samples.slice().sort((a, b) => a - b);
        const med = s.length >= 5 ? s[Math.floor(s.length / 2)] : NaN;
        cx.matrixIdle = isFinite(med) ? Math.round(med) : 0;
        cxGame.binLo = isFinite(med) ? Math.min(1200, Math.max(400, Math.floor((med - 50) / CX_GAME_BIN_W) * CX_GAME_BIN_W)) : CX_GAME_BIN_LO;
        cxGame.bins = null;   // next cxGameStart rebuilds on the detected band
        cx.rtFieldArmed = true;   // field under wizard command → closeCommissionModal tears it down
        cx.rtLastCmd = Date.now();
        // Arm order matters: idle stamp + resTest level land BEFORE ripGameFill=1 — the firmware wipe
        // stamps resTestTargetA and the staged idle into the session at arm.
        cxGet('ripGameIdleRpm=' + cx.matrixIdle)
            .then(() => cxGet('resTest=1'))
            .then(() => cxGet('resTestTargetA=' + levelA.toFixed(1)))
            .then(() => cxGet('faCommissionGate=1'))
            .then(() => cxGet('ripGameFill=1'))
            .then(() => { cxStopPoll(); cxPollTimer = setInterval(cxMatrixPoll, 2000); cxMatrixPoll(); })
            .catch(() => cxGameToast('Device not responding — close and retry'));
        commissionRender();
    }, 4000);
}
// Confidence gate (RPM_RIPPLE_TABLE_SPEC §2.5) — replaces the flat 80% coverage bar. Unlocks the done
// button as soon as the worst-ripple RPM is located AND no unswept gap could plausibly hide a bigger peak,
// so a mostly-flat range stops after a coarse sweep instead of grinding every bin. Safe because: a gap is
// never wider than CX_SWEEP_MAX_GAP bins (=150 RPM = CX_RT_BAND), so even a peak at a gap's far edge is
// inside the resonance-check green band; and no unswept hole is left touching an already-hot bin. The user
// can always keep clearing targets to fill more. Coverage/gaps walk committed ALT bins; the worst-spot
// pick and the pending-above-committed block span both detectors (mirrors the cxRtestInit pick).
const CX_SWEEP_MIN_BINS = 6;    // committed bins needed before "flat" is trustworthy
const CX_SWEEP_MAX_GAP  = 3;    // max consecutive uncommitted bins between anchors (×50 = 150 RPM = CX_RT_BAND)
const CX_SWEEP_HOT_FRAC = 0.7;  // a gap bordered by ≥ this × peak is a suspected-peak neighborhood → must fill
function cxSweepConfidence(rows) {
    const lo = cxGame.binLo || CX_GAME_BIN_LO, hi = CX_GAME_BIN_HI, w = CX_GAME_BIN_W;
    const total = Math.round((hi - lo) / w);
    const val = {};                         // committed alt value per band bin (absent = not committed)
    // Coverage/gap walking runs on committed ALT bins; the worst-spot pick spans BOTH detectors'
    // committed values so the verdict names the same RPM cxRtestInit will run the current-check at.
    let covered = 0, maxV = 0, maxRpm = -1;
    for (const p of rows) if (p.rpm >= lo && p.rpm < hi) {
        if (p.altSt === 2) {
            val[p.rpm] = p.alt; covered++;
            if (p.alt > maxV) { maxV = p.alt; maxRpm = p.rpm; }
        }
        if (p.battSt === 2 && p.batt > maxV) { maxV = p.batt; maxRpm = p.rpm; }
    }
    if (covered < CX_SWEEP_MIN_BINS)
        return { ok: false, covered, total, maxRpm, want: new Set(), reason: 'clear a few more targets across the range to build a baseline' };
    // Walk the band; each run of uncommitted bins (a gap) must be narrow AND not border a hot bin.
    // `want` collects every bin the gate is waiting on — the game renders those as priority targets.
    let ok = true, gapStart = -1, prevVal = -1, reason = '';
    const want = new Set();
    const flush = (endRpm, rightVal) => {
        if (gapStart < 0) return;
        const gapBins = Math.round((endRpm - gapStart) / w);
        const midRpm = gapStart + Math.floor(gapBins / 2) * w;
        if (gapBins > CX_SWEEP_MAX_GAP) {
            if (ok) reason = 'a wide unswept gap near ~' + midRpm + ' RPM needs filling'; ok = false;
            want.add(midRpm);   // filling the middle splits the gap; the set recomputes every poll
        } else {
            const border = Math.max(prevVal < 0 ? 0 : prevVal, rightVal < 0 ? 0 : rightVal);
            if (maxV > 0 && border >= CX_SWEEP_HOT_FRAC * maxV) {
                if (ok) reason = 'an unswept spot next to the hot zone at ~' + midRpm + ' RPM needs filling'; ok = false;
                for (let r = gapStart; r < endRpm; r += w) want.add(r);
            }
        }
    };
    for (let r = lo; r < hi; r += w) {
        if (val[r] != null) { flush(r, val[r]); gapStart = -1; prevVal = val[r]; }
        else if (gapStart < 0) gapStart = r;
    }
    flush(hi, -1);                           // trailing gap to the band ceiling (outer border unknown)
    // The worst bin must be bracketed by committed neighbors (a real local peak), unless it sits at the
    // reachable floor — idle is a legitimate low-RPM extreme you cannot rev below.
    if (ok && maxRpm > lo) {
        const leftOk = val[maxRpm - w] != null || maxRpm - w <= lo;   // floor bin (idle−50) may be unreachable → counts as an edge
        const rightOk = val[maxRpm + w] != null || maxRpm + w >= hi;
        if (!leftOk || !rightOk) {
            ok = false; reason = 'hold ~' + maxRpm + ' RPM again to bracket the worst spot';
            if (!leftOk) want.add(maxRpm - w);
            if (!rightOk) want.add(maxRpm + w);
        }
    }
    // A pending single-window reading ABOVE every committed value is exactly "something significant
    // likely missed": one more pause there either commits it (the true worst — the current-check must
    // run there) or replaces it (a transient, refuted). Never green while one is outstanding.
    let pMax = 0, pRpm = -1;
    for (const p of rows) if (p.rpm >= lo && p.rpm < hi) {
        const pv = Math.max(p.altSt === 1 ? p.alt : 0, p.battSt === 1 ? p.batt : 0);
        if (pv > pMax) { pMax = pv; pRpm = p.rpm; }
    }
    if (pMax > maxV && pRpm >= 0) {
        if (ok) reason = 'an unconfirmed reading at ~' + (pRpm + w / 2) + ' RPM is higher than anything confirmed — pause there again to confirm or refute it';
        ok = false; want.add(pRpm);
    }
    return { ok, covered, total, maxRpm, want, reason };
}
function cxMatrixPoll() {
    // Keepalive: the game holds the fixed test current through resTest — refresh the 8 s deadman on
    // this 2 s poll so a closed/crashed tab auto-releases the field (and freezes+saves the table).
    if (cx.matrixOn && cx.rtFieldArmed && cx.matrixLevelA) { cxGet('resTestTargetA=' + cx.matrixLevelA.toFixed(1)).catch(() => { }); cx.rtLastCmd = Date.now(); }
    // One fetch serves kills, coverage AND the ripple strip — the table state IS the kill ground truth.
    fetch(buildURL('/filtripple.csv')).then(r => r.text()).then(txt => {
        const rows = txt.trim().split('\n').slice(1).map(l => l.split(','))
            .filter(c => c.length >= 5)
            .map(c => ({ rpm: +c[0], alt: +c[1], batt: +c[2], altSt: +c[3], battSt: +c[4] }));
        cxGame.rip = rows;
        cxGameRipDraw();
        cxGamePollBins(rows);
        // Confidence gate (§2.5, replaces the flat 80% bar): unlock once the worst-ripple RPM is located and
        // no unswept gap could hide a bigger peak. Batt commits ride along and are not gated on.
        const conf = cxSweepConfidence(rows);
        cx.matrixCov = conf.ok;
        cxGame.want = conf.want;   // priority-target bins → rendered as pulsing gold invaders
        const el = document.getElementById('cx-cov');
        if (el) el.innerHTML = conf.ok
            ? 'Coverage: <strong style="color:#5a5;">worst spot located' + (conf.maxRpm >= 0 ? ' at ~' + (conf.maxRpm + CX_GAME_BIN_W / 2) + ' RPM' : '') + ' — nothing significant likely missed.</strong> ' + conf.covered + '/' + conf.total + ' bins swept. Stop here, or keep clearing targets to fill in more.'
            : 'Coverage: <strong style="color:#f0a500;">' + conf.covered + '/' + conf.total + ' bins</strong> — ' + conf.reason + '.' + (conf.want.size ? ' Go for the gold targets.' : '') + ' Pause ~6 s on each.';
        const doneBtn = document.getElementById('cx-sweep-done'); if (doneBtn) doneBtn.disabled = !cx.matrixCov;
    }).catch(() => { });
}
function cxMatrixStop() {
    cx.matrixOn = false; cxStopPoll(); cx.rtLastCmd = 0; cx.rtFieldArmed = false;
    // Freeze + persist the table FIRST, then the gentle resTest exit (mirrors cxRtFinish: command 0,
    // let the slew actually get there, then release — firmware deferred-release covers the rest).
    cxGet('ripGameFill=0')
        .then(() => cxGet('resTestTargetA=0')).then(() => new Promise(r => setTimeout(r, 2500)))
        .then(() => cxGet('resTest=0')).then(() => cxGet('faCommissionGate=0'))
        .catch(() => { });
    commissionRender();
}

// ── "RPM Invaders" — the guided sweep as a game ───────────────────────────────
// Y-axis = RPM (auto-ranged so a low idle slides the floor down, never clipped), trace + ship
// ride the same CSV1 ring as the sparkline strip (which is hidden while the game owns the screen).
// TWO invaders per required 50-RPM bin (idle-adaptive floor → 2000): the right one dies when the
// bin gets a qualifying pending value, the left one when the agree-twice pair commits. Kills are
// GROUND TRUTH from the new RPM ripple table's state (rides the /filtripple.csv poll); the charge
// ring is a local dwell estimate only. A disagree (pending replaced) regrows the right invader +
// toasts. A FULL ring left unconfirmed for ~3 polls means the §11 admission gates rejected the
// pause → "not admitted" toast + ring reset — that reject feedback is the whole point.
const CX_GAME_BIN_LO = 500, CX_GAME_BIN_HI = 2000;   // default band; cxGame.binLo overrides the floor after idle detection
const CX_GAME_BIN_W = 50;
const CX_GAME_CHARGE_S = 4;      // nominal dwell-to-full-ring; real pending usually beats it
const CX_GAME_MISS_MS = 6500;    // full ring unconfirmed this long (~3 polls) = admission reject
const cxGame = { active: false, raf: 0, lastT: 0, bins: null, seeded: false, binLo: 0,
                 coveredExtra: null, parts: [], rip: null, toastT: 0, view: null };
// classic 11×8 invader bitmap
const _cxInvBmp = ['00100000100', '00010001000', '00111111100', '01101110110',
                   '11111111111', '10111111101', '10100000101', '00011011000'].map(s => s.split('').map(Number));

function cxGameStart() {
    const strip = document.getElementById('cx-rpm-strip');
    if (strip) strip.style.display = 'none';
    if (!cxGame.bins) {
        cxGame.bins = {};
        const lo = cxGame.binLo || CX_GAME_BIN_LO;
        for (let r = lo; r < CX_GAME_BIN_HI; r += CX_GAME_BIN_W)
            cxGame.bins[r] = { covered: false, pend: false, pendVal: 0, regrowT: 0, charge: 0, pendT: 0, wob: Math.random() * 6.28 };
        cxGame.coveredExtra = new Set();
    }
    if (!cxGame.active) {
        cxGame.active = true; cxGame.lastT = performance.now();
        cxGame.raf = requestAnimationFrame(cxGameFrame);
    }
    cxGameRipDraw();
}
function cxGameStop() {
    cxGame.active = false;
    if (cxGame.raf) { cancelAnimationFrame(cxGame.raf); cxGame.raf = 0; }
    const strip = document.getElementById('cx-rpm-strip');
    if (strip) strip.style.display = '';
}
// Called from cxMatrixPoll with the parsed /filtripple.csv rows. Kill ground truth is the RPM ripple
// table's per-bin ALT state: pending (altSt 1) kills the first invader, commit (altSt 2) kills both
// (batt commits opportunistically alongside — never gated on). A pending VALUE that changed while
// still pending means the agree-twice pair disagreed → the first invader regrows + toast.
function cxGamePollBins(rows) {
    if (!cxGame.bins) return;
    const byRpm = {};
    for (const p of rows) byRpm[p.rpm] = p;
    for (const k in cxGame.bins) {
        const bin = cxGame.bins[k], p = byRpm[k];
        if (p && p.altSt === 2) {
            if (!bin.covered) {
                bin.covered = true; bin.pend = true; bin.regrowT = 0; bin.charge = 0; bin.pendT = 0;
                if (cxGame.seeded) cxGameBoom(+k);   // seed poll = resumed prior coverage, no fireworks
            }
        } else if (p && p.altSt === 1) {
            if (!bin.pend) {
                bin.pend = true; bin.pendVal = p.alt; bin.charge = 0; bin.pendT = 0;
                if (cxGame.seeded) cxGameBoom(+k);
            } else if (Math.abs(p.alt - bin.pendVal) > 0.005) {
                bin.pendVal = p.alt; bin.regrowT = 1.4;
                if (cxGame.seeded) cxGameToast('Readings at ~' + (+k + CX_GAME_BIN_W / 2) + ' RPM disagree — hold it again');
            }
        } else if (!p && (bin.covered || bin.pend)) {
            bin.covered = bin.pend = false;   // table wiped mid-sweep (re-sweep)
        }
    }
    // Committed bins OUTSIDE the required band (e.g. below the detected idle floor) still earn a
    // green tick — real data, they just don't count toward the 80% gate.
    const lo = cxGame.binLo || CX_GAME_BIN_LO;
    cxGame.coveredExtra = new Set(rows.filter(p => p.altSt === 2 && (p.rpm < lo || p.rpm >= CX_GAME_BIN_HI)).map(p => p.rpm));
    cxGame.seeded = true;
}
function cxGameToast(msg) {
    const t = document.getElementById('cxGameToast');
    if (t) { t.textContent = msg; t.style.opacity = 1; }
    cxGame.toastT = 2.4;
}
function cxGameBoom(rpmLo) {
    const v = cxGame.view; if (!v) return;
    const y = v.yOf(rpmLo + CX_GAME_BIN_W / 2);
    for (let i = 0; i < 26; i++) {
        const a = Math.random() * 6.28, sp = 30 + Math.random() * 120;
        cxGame.parts.push({ x: v.tgtX, y, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
                            life: 0.55 + Math.random() * 0.35, c: Math.random() < 0.5 ? '#2ec4b6' : '#f0a500' });
    }
}
function cxGameFrame(now) {
    if (!cxGame.active) return;
    const c = document.getElementById('cxGame');
    if (!c) { cxGameStop(); return; }            // step advanced / body re-rendered without the game
    if (!c.clientWidth) {                        // modal hidden — idle cheaply until it's back
        cxGame.lastT = now; cxGame.raf = requestAnimationFrame(cxGameFrame); return;
    }
    const dt = Math.min(0.05, (now - cxGame.lastT) / 1000); cxGame.lastT = now;
    const rpm = (cx && isFinite(cx.liveRpm)) ? cx.liveRpm : NaN;
    const curKey = (isFinite(rpm) && rpm >= (cxGame.binLo || CX_GAME_BIN_LO) && rpm < CX_GAME_BIN_HI)
        ? Math.floor(rpm / CX_GAME_BIN_W) * CX_GAME_BIN_W : -1;
    for (const k in cxGame.bins) {
        const bin = cxGame.bins[k];
        if (bin.regrowT > 0) bin.regrowT -= dt;
        if (bin.covered) continue;
        if (+k === curKey) {
            if (!bin.pendT) {
                bin.charge = Math.min(1, bin.charge + dt / CX_GAME_CHARGE_S);
                if (bin.charge >= 1) bin.pendT = now;
            } else if (now - bin.pendT > CX_GAME_MISS_MS) {
                bin.pendT = 0; bin.charge = 0;
                cxGameToast('Not admitted — too unsteady, hold this speed again');
            }
        } else {
            // brief grace then drain; walking away also cancels a pending miss (commit may still
            // arrive via the poll and kill the invader from afar)
            bin.charge = Math.max(0, bin.charge - dt * 2.5);
            if (bin.charge <= 0) bin.pendT = 0;
        }
    }
    if (cxGame.toastT > 0) {
        cxGame.toastT -= dt;
        if (cxGame.toastT <= 0) { const t = document.getElementById('cxGameToast'); if (t) t.style.opacity = 0; }
    }
    cxGameDraw(c, now / 1000, rpm, curKey, dt);
    cxGame.raf = requestAnimationFrame(cxGameFrame);
}
function cxGameDraw(c, t, rpm, curKey, dt) {
    const dpr = window.devicePixelRatio || 1, w = c.clientWidth, h = c.clientHeight;
    if (c.width !== w * dpr || c.height !== h * dpr) { c.width = w * dpr; c.height = h * dpr; }
    const g = c.getContext('2d'); g.setTransform(dpr, 0, 0, dpr, 0, 0); g.clearRect(0, 0, w, h);
    const padT = 14, padB = 14, axisX = 40;
    const shipX = axisX + (w - axisX) * 0.52;    // ship well left of the targets → long shot travel
    const tgtX = w - 46;
    // Auto range: default 450–2050, extended to keep the whole trace on screen (low idle, high revs).
    let dmin = Infinity, dmax = -Infinity;
    for (const v of _cxRpmSpark.rpm) if (isFinite(v)) { if (v < dmin) dmin = v; if (v > dmax) dmax = v; }
    const lo = Math.min(450, isFinite(dmin) ? dmin - 40 : 450);
    const hi = Math.max(2050, isFinite(dmax) ? dmax + 40 : 2050);
    const yOf = r => (h - padB) - (r - lo) / (hi - lo) * (h - padT - padB);
    cxGame.view = { tgtX, yOf };                 // for explosion placement between frames
    const binPx = (h - padT - padB) * CX_GAME_BIN_W / (hi - lo);

    // gridlines + labels (coarser when revving stretches the range)
    const step = (hi - lo) > 2400 ? 500 : 250;
    g.font = '10px -apple-system, sans-serif'; g.textAlign = 'right'; g.textBaseline = 'middle';
    for (let gv = Math.ceil(lo / step) * step; gv <= hi; gv += step) {
        const y = yOf(gv);
        g.strokeStyle = '#242428'; g.beginPath(); g.moveTo(axisX, y); g.lineTo(w - 6, y); g.stroke();
        g.fillStyle = '#666'; g.fillText(gv, axisX - 5, y);
    }
    g.textAlign = 'left'; g.textBaseline = 'top'; g.fillText('RPM', 6, 6);
    // current-bin band highlight
    if (curKey >= 0 && !cxGame.bins[curKey].covered) {
        g.fillStyle = 'rgba(46,196,182,0.07)';
        g.fillRect(axisX, yOf(curKey + CX_GAME_BIN_W), w - 6 - axisX, binPx);
    }
    // covered bins → green strips on the target column (required band + any extras like a low idle)
    const drawTick = rLo => { g.fillRect(tgtX - 16, yOf(rLo + CX_GAME_BIN_W) + 1, 58, binPx - 2); };
    g.fillStyle = 'rgba(85,170,85,0.16)';
    for (const k in cxGame.bins) if (cxGame.bins[k].covered) drawTick(+k);
    if (cxGame.coveredExtra) for (const r of cxGame.coveredExtra) drawTick(r);
    // RPM trace (same 150-sample ~15 s ring as the sparkline), ending at the ship column
    const S = _cxRpmSpark, N = S.N;
    g.strokeStyle = '#2ec4b6'; g.lineWidth = 1.7; g.beginPath();
    let started = false;
    for (let i = 0; i < N; i++) {
        const v = S.rpm[i]; if (!isFinite(v)) { started = false; continue; }
        const x = axisX + 4 + i * (shipX - axisX - 4) / (N - 1), y = yOf(v);
        started ? g.lineTo(x, y) : g.moveTo(x, y); started = true;
    }
    g.stroke(); g.lineWidth = 1;
    if (isFinite(rpm)) {
        const sy = yOf(rpm);
        // ship chevron
        g.fillStyle = '#2ec4b6'; g.beginPath();
        g.moveTo(shipX + 12, sy); g.lineTo(shipX - 2, sy - 7); g.lineTo(shipX + 2, sy);
        g.lineTo(shipX - 2, sy + 7); g.closePath(); g.fill();
        // charging shot: long fast dashes from ship to the live target
        if (curKey >= 0 && !cxGame.bins[curKey].covered && cxGame.bins[curKey].charge > 0.02) {
            const ty = yOf(curKey + CX_GAME_BIN_W / 2);
            const gr = g.createLinearGradient(shipX + 12, 0, tgtX - 10, 0);
            gr.addColorStop(0, 'rgba(46,196,182,0.9)'); gr.addColorStop(1, 'rgba(46,196,182,0.15)');
            g.strokeStyle = gr; g.lineWidth = 1 + cxGame.bins[curKey].charge * 2.5;
            g.setLineDash([14, 10]); g.lineDashOffset = -t * 160;
            g.beginPath(); g.moveTo(shipX + 12, sy); g.lineTo(tgtX - 10, ty); g.stroke();
            g.setLineDash([]); g.lineWidth = 1;
        }
    }
    // invaders + charge rings — TWO monsters per bin: right dies on pending, left on commit.
    // A disagree regrows the right one briefly (regrowT flicker) — the pending value was replaced.
    for (const k in cxGame.bins) {
        const bin = cxGame.bins[k];
        if (bin.covered) continue;
        const cy = yOf(+k + CX_GAME_BIN_W / 2), hot = +k === curKey;
        // Priority target: the confidence gate is waiting on exactly this bin (cxSweepConfidence.want)
        // → gold, pulsing, haloed. Everything else stays grey so the valuable kills stand out.
        const want = !hot && cxGame.want && cxGame.want.has(+k);
        const wob = Math.sin(t * 2 + bin.wob) * 1.5;
        const col = bin.pendT ? '#fff' : hot ? '#f0a500' : want ? '#ffd24a' : '#8a8a92';
        const px = Math.max(1.1, (binPx - 3) / 9), iw = 11 * px, ih = 8 * px;
        const drawInv = (xOff, alpha) => {
            g.globalAlpha = alpha; g.fillStyle = col;
            for (let r = 0; r < 8; r++) for (let cc = 0; cc < 11; cc++)
                if (_cxInvBmp[r][cc]) g.fillRect(tgtX + xOff + wob - iw / 2 + cc * px, cy - ih / 2 + r * px, px + 0.5, px + 0.5);
            g.globalAlpha = 1;
        };
        const baseA = cx.matrixCov ? 0.4 : 0.85;                          // gate satisfied → remaining bins optional, dimmed
        const a = hot ? 1 : want ? 0.75 + 0.25 * Math.sin(t * 5 + bin.wob) : baseA;
        drawInv(-iw * 0.75, a);                                           // left monster (dies on commit)
        if (!bin.pend) drawInv(iw * 0.75, a);                             // right monster (dies on pending)
        else if (bin.regrowT > 0) drawInv(iw * 0.75, 0.2 + 0.4 * Math.abs(Math.sin(t * 10)));  // disagree regrow flicker
        if (want) {
            g.strokeStyle = 'rgba(255,210,74,' + (0.35 + 0.25 * Math.sin(t * 5 + bin.wob)).toFixed(2) + ')';
            g.beginPath(); g.arc(tgtX + wob, cy, binPx * 0.95, 0, 6.283); g.stroke();
        }
        if (bin.charge > 0.02) {
            g.strokeStyle = '#f0a500'; g.lineWidth = 2;
            g.beginPath(); g.arc(tgtX + wob, cy, binPx * 0.75, -Math.PI / 2, -Math.PI / 2 + bin.charge * 6.283);
            g.stroke(); g.lineWidth = 1;
        }
    }
    // explosion particles
    for (let i = cxGame.parts.length - 1; i >= 0; i--) {
        const p = cxGame.parts[i];
        p.life -= dt; p.x += p.vx * dt; p.y += p.vy * dt; p.vy += 60 * dt;
        if (p.life <= 0) { cxGame.parts.splice(i, 1); continue; }
        g.globalAlpha = Math.min(1, p.life * 2); g.fillStyle = p.c;
        g.fillRect(p.x, p.y, 2.5, 2.5); g.globalAlpha = 1;
    }
    // live RPM readout (replaces the hidden strip's number)
    g.font = '700 16px -apple-system, sans-serif'; g.textAlign = 'right'; g.textBaseline = 'top';
    g.fillStyle = '#2ec4b6';
    g.fillText(isFinite(rpm) ? Math.round(rpm) + ' RPM' : '—', w - 8, 6);
}
// Ripple sanity strip: the RPM ripple table per bin, both detectors, redrawn per poll.
// Committed values draw solid; pending (unconfirmed agree-twice candidates) draw dimmed.
function cxGameRipDraw() {
    const c = document.getElementById('cxGameRip');
    if (!c || !c.clientWidth) return;
    const dpr = window.devicePixelRatio || 1, w = c.clientWidth, h = c.clientHeight;
    if (c.width !== w * dpr || c.height !== h * dpr) { c.width = w * dpr; c.height = h * dpr; }
    const g = c.getContext('2d'); g.setTransform(dpr, 0, 0, dpr, 0, 0); g.clearRect(0, 0, w, h);
    const rip = (cxGame.rip || []).filter(p => p.alt > 0 || p.batt > 0);
    g.font = '10px -apple-system, sans-serif';
    if (!rip.length) {
        g.fillStyle = '#555'; g.textAlign = 'center'; g.textBaseline = 'middle';
        g.fillText('No ripple committed yet — values appear here as pauses are admitted', w / 2, h / 2);
        return;
    }
    const padL = 30, padR = 8, padT = 8, padB = 15;
    const xLo = 400, xHi = 2100;   // matches the game's default RPM span
    const yMax = Math.max(0.5, ...rip.map(p => Math.max(p.alt, p.batt))) * 1.15;
    const Xr = r => padL + (r - xLo) / (xHi - xLo) * (w - padL - padR);   // raw RPM → x
    const X = r => Xr(r + CX_GAME_BIN_W / 2);                            // bin lo → bin-center x
    const Y = v => (h - padB) - v / yMax * (h - padT - padB);
    // x-axis = RPM (same span as the game's y-axis, idle at the left)
    g.fillStyle = '#666'; g.textAlign = 'center'; g.textBaseline = 'bottom';
    for (let r = 500; r <= 2000; r += 500) {
        const x = Xr(r);
        g.strokeStyle = '#242428'; g.beginPath(); g.moveTo(x, padT); g.lineTo(x, h - padB); g.stroke();
        g.fillText(r === 2000 ? '2000 RPM' : r, x, h - 1);
    }
    g.strokeStyle = '#242428'; g.beginPath(); g.moveTo(padL, Y(yMax / 1.15)); g.lineTo(w - padR, Y(yMax / 1.15)); g.stroke();
    g.fillStyle = '#666'; g.textAlign = 'right'; g.textBaseline = 'middle';
    g.fillText((yMax / 1.15).toFixed(1) + 'A', padL - 3, Y(yMax / 1.15));
    for (const ser of [['alt', '#2ec4b6', 'altSt'], ['batt', '#f0a500', 'battSt']]) {
        const pts = rip.filter(p => p[ser[0]] > 0).sort((a, b) => a.rpm - b.rpm);
        if (!pts.length) continue;
        // Line + solid dots = confirmed (agree-twice) values ONLY. A pending single-window value
        // draws as a hollow ring off the line so it can't masquerade as measured data — the wizard's
        // worst-spot pick ignores it.
        const conf = pts.filter(p => p[ser[2]] === 2);
        g.strokeStyle = ser[1]; g.globalAlpha = 0.5; g.beginPath();
        conf.forEach((p, i) => { const x = X(p.rpm), y = Y(p[ser[0]]); i ? g.lineTo(x, y) : g.moveTo(x, y); });
        g.stroke(); g.globalAlpha = 1;
        for (const p of pts) {
            const x = X(p.rpm), y = Y(p[ser[0]]);
            g.beginPath();
            if (p[ser[2]] === 2) { g.fillStyle = ser[1]; g.arc(x, y, 2.2, 0, 7); g.fill(); }
            else { g.strokeStyle = ser[1]; g.arc(x, y, 2.8, 0, 7); g.stroke(); }
        }
    }
    // Mark the worst committed bin across BOTH detectors — the same pick cxRtestInit runs the
    // current-check at, and the RPM the coverage verdict names.
    let worst = null, wv = 0;
    for (const p of rip) {
        if (p.altSt === 2 && p.alt > wv) { wv = p.alt; worst = p; }
        if (p.battSt === 2 && p.batt > wv) { wv = p.batt; worst = p; }
    }
    if (worst) {
        const x = X(worst.rpm);
        g.strokeStyle = '#f0584f'; g.setLineDash([3, 3]);
        g.beginPath(); g.moveTo(x, padT); g.lineTo(x, h - padB); g.stroke(); g.setLineDash([]);
        g.fillStyle = '#f0584f'; g.textBaseline = 'top';
        const flip = x > w * 0.72;
        g.textAlign = flip ? 'right' : 'left';
        g.fillText('worst ~' + (worst.rpm + CX_GAME_BIN_W / 2) + ' RPM', x + (flip ? -4 : 4), padT - 4);
    }
}

// ── Guided resonance current-check (RIPPLE_DETECTION_REARCH_SPEC §3.2/§3.3) ──────────────────
// After the coverage sweep, if measured filtered ripple was captured, the wizard commands the alternator to
// 3 current levels at the worst-ripple RPM (you hold the speed in the green band and Record each) and fits
// ripple = a0 + a1·I per detector on the IExcessTau-filtered pk-pk. It writes ONLY the ripFit reference
// projection (POSTed in cxRtFinish) — the over-current floor is operator-owned and never touched here. The
// fit surfaces on the Protections ripple-vs-threshold plot. Non-blocking: no ripple, or you skip → the plot
// stays in its no-data state. State machine on cx.rtestState:
//   undefined→'checking'→ 'none' (no ripple, silent) | 'idle' (Ready) → 'leveling' (3 commanded steps)
//   → 'done' (fit) | 'failed'. REQUIRES the matching firmware (resTest/bcurRtest) flashed.
const CX_RT_BAND = 150;    // ± RPM considered "in range" (green)
const CX_RT_MIN_WINS = 5;  // captured ring windows (~2 s each) required before Record unlocks — counts real admissions off /bcurrtest.csv, not a blind timer
function cxRtestPanel() {
    if (cx.rtestState === undefined) { cx.rtestState = 'checking'; cxRtestInit(); return '<div style="margin:10px 0;color:#4a9eff;">Checking for resonance…</div>'; }
    if (cx.rtestState === 'checking') return '<div style="margin:10px 0;color:#4a9eff;">Checking for resonance…</div>';
    if (cx.rtestState === 'none') return '';  // no significant resonance → silent skip
    let h = '<div style="margin:12px 0;padding:8px 10px;background:#222;border-radius:6px;">';
    // Origin line only outside the run — during leveling the per-point header is all that's needed.
    if (cx.rtestState !== 'leveling') h += 'From the disturbance sweep: worst ripple was <strong>' + cx.rtestPkpk.toFixed(2) + ' A pk-pk at ' + cx.rtestRpm + ' RPM</strong>.<br>';
    if (cx.rtestState === 'done' && cx.rtest) {
        const R = cx.rtest, P = cx.rtPts || [];
        h += '<div style="font-size:13px;margin-bottom:6px;">Results: how this scales with current:</div>';
        h += '<table style="border-collapse:collapse;font-size:12px;width:100%;">' +
             '<tr style="color:#9aa0a8;text-align:right;"><th style="text-align:left;padding:2px 8px 4px 0;">Nominal</th><th style="padding:2px 8px 4px;">Alt&nbsp;I</th><th style="padding:2px 0 4px 8px;">Alt&nbsp;ripple</th></tr>';
        for (let k = 0; k < P.length; k++) {
            const q = P[k], cmd = (cx.rtLevels && cx.rtLevels[k] != null) ? Math.round(cx.rtLevels[k]) : null;
            h += '<tr style="text-align:right;">' +
                 '<td style="text-align:left;padding:2px 8px 2px 0;">' + (cmd != null ? cmd + ' A' : '&mdash;') + '</td>' +
                 '<td style="padding:2px 8px;">' + (q.ia ? q.ia.toFixed(0) + ' A' : '&mdash;') + '</td>' +
                 '<td style="padding:2px 0 2px 8px;">' + (q.pa ? q.pa.toFixed(2) : '&mdash;') + '</td></tr>';
        }
        h += '</table>';
        // Measured projection (reference data for the Protections plot; nothing is applied).
        h += '<div style="margin-top:8px;font-size:13px;line-height:1.6;">' +
             'Alternator ripple &asymp; <strong>' + R.a0.toFixed(2) + ' + ' + R.a1.toFixed(3) + '&middot;I</strong> A pk-pk' +
             '</div>';
        h += '<div style="margin-top:8px;font-size:13px;">Saved as the measured-ripple overlay. Check it against your thresholds on the <strong>Protections</strong> ripple plot (or the review in the next step) &mdash; nothing was changed automatically.</div>';
        h += '<div style="margin-top:8px;">' + cxNextBtn(true, true) + ' ' +
             '<button onclick="cxRtReady()" class="btn-secondary btn-sm">Re-run</button> ' +
             '<button onclick="cxMatrixStart()" class="btn-secondary btn-sm">Re-sweep</button></div>';
    } else if (cx.rtestState === 'leveling') {
        const L = cx.rtLevels, n = cx.rtLevel + 1;
        h += '<span style="font-size:15px;"><strong>' + Math.round(L[cx.rtLevel]) + ' amp point (' + n + ' of 3) — hold ' + cx.rtestRpm + ' RPM</strong></span>';
        h += '<div id="cx-rt-rpm" style="margin-top:8px;font-weight:600;">RPM —</div>';
        h += '<div id="cx-rt-msg" style="margin-top:4px;color:#4a9eff;font-size:13px;">Bring RPM to ' + cx.rtestRpm + '.</div>';
        h += '<div style="margin-top:8px;"><button id="cx-rt-confirm" onclick="cxRtConfirm()" class="btn-primary btn-sm" disabled>Record</button> ' +
             '<button onclick="cxRtAbort()" class="btn-danger-ghost btn-sm">Abort</button></div>';
    } else if (cx.rtestState === 'failed') {
        h += '<span style="color:#f0a500;font-size:13px;">' + (cx.rtFailMsg || 'Test did not produce a usable slope.') + '</span>';
        h += '<div style="margin-top:8px;"><button onclick="cxRtReady()" class="btn-primary btn-sm">Retry</button> ' +
             '<button onclick="cxAdvance(true)" class="btn-secondary btn-sm">Skip to Thresholds &rarr;</button></div>';
    } else {  // 'idle'
        h += '<span style="font-size:13px;color:#bbb;">Bring engine to ' + cx.rtestRpm + ' RPM and the wizard will study how this scales with current.</span>';
        // "(Recommended)" whenever the captured resonance clears the 1 A pk-pk floor that made this panel appear.
        const rec = (cx.rtestPkpk > 1) ? ' <span style="color:#5a5;">(Recommended)</span>' : '';
        h += '<div style="margin-top:8px;"><button onclick="cxRtReady()" class="btn-primary btn-sm">Start current check' + rec + '</button> ' +
             '<button onclick="cxAdvance(true)" class="btn-secondary btn-sm">Skip to Thresholds &rarr;</button> ' +
             '<button onclick="cxMatrixStart()" class="btn-secondary btn-sm">Re-sweep</button></div>';
    }
    h += '</div>';
    return h;
}
function cxRtestInit() {  // find the RPM with the worst measured filtered ripple → the resonance to characterize (§3.2)
    // Columns: rpmLo, altFiltPkA, battFiltPkA, altSt, battSt (IExcessTau-filtered pk-pk == detector
    // mExcessEma pk-pk, captured at the sweep's fixed current). COMMITTED values only (st 2) — a lone
    // pending candidate never passed the agree-twice test and must not steer the pick. The belt
    // resonance is mechanical and common to both detectors, so the strongest committed ripple across
    // either signal locates the RPM to run the 3-level check at (it records both fits in one pass).
    fetch(buildURL('/filtripple.csv')).then(r => r.text()).then(txt => {
        let bestP = 0, bestRpm = 0; const bl = txt.trim().split('\n');
        for (let i = 1; i < bl.length; i++) {
            const c = bl[i].split(','); if (c.length < 3) continue;
            const aOk = c.length < 5 || +c[3] === 2, bOk = c.length < 5 || +c[4] === 2;
            const p = Math.max(aOk ? parseFloat(c[1]) || 0 : 0, bOk ? parseFloat(c[2]) || 0 : 0);
            if (p > bestP) { bestP = p; bestRpm = parseInt(c[0], 10) + 25; }
        }
        if (bestP >= 0.3) { cx.rtestPkpk = bestP; cx.rtestRpm = Math.round(bestRpm); cx.rtestState = 'idle'; }
        else cx.rtestState = 'none';  // no meaningful filtered ripple → nothing to characterize
        commissionRender();
    }).catch(() => { cx.rtestState = 'none'; commissionRender(); });
}
function cxRtReady() {  // user is holding the resonant RPM → arm field-commanding and start level 1
    // Size the 3 levels from the cap-table ceiling AT THE TEST RPM, not the global table max. With the
    // §11 stationarity gates the worst-ripple pick can legitimately land at idle, where a global-max
    // level is unreachable — the command would saturate at the idle ceiling, cluster the 3 points, and
    // fail the fit's span check. Table rows are "below this RPM" bands in ascending order, so the
    // binding row is the first breakpoint above the test RPM (amps column is populated in kW mode too).
    let iMax = 0, capAt = 0;
    for (let i = 0; i < 10; i++) {
        const c = document.getElementById('rpmCapCurrentTable' + i + '_input');
        const r = document.getElementById('rpmTableRPMPoints' + i + '_input');
        const v = c ? parseFloat(c.value) : NaN;
        if (isFinite(v) && v > iMax) iMax = v;
        if (!capAt && r && isFinite(v) && cx.rtestRpm < (parseFloat(r.value) || 0)) capAt = v;
    }
    if (!capAt) capAt = iMax;   // test RPM above every breakpoint (or RPM column unreadable) → top-band cap
    if (!(capAt > 5)) { cx.rtestState = 'failed'; cx.rtFailMsg = 'Output ceiling at ' + cx.rtestRpm + ' RPM unknown (RPM-cap table empty) — can\'t size the levels.'; commissionRender(); return; }
    cx.rtLevels = [0.30 * capAt, 0.60 * capAt, 0.90 * capAt];  // 3 spread levels across what this speed can actually deliver
    cx.rtLevel = 0; cx.rtPts = []; cx.rtest = null; cx.rtWinN = 0; cx.rtRingAt = 0;
    cx.rtFieldArmed = true;   // field is now under wizard command → closeCommissionModal must tear it down
    cx.rtestState = 'leveling';
    cxShowTab('plots', 'displays');
    commissionRender();
    // Arm ripple capture + field-commanding, then command level 1.
    cxGet('faCommissionGate=1').then(() => cxGet('bcurRtest=1')).then(() => cxGet('resTest=1'))
        .then(() => cxRtSetLevel(0));
}
function cxRtSetLevel(idx) {
    cx.rtLevel = idx; cx.rtWinN = 0; cx.rtRingAt = 0; cx.rtLastCmd = Date.now();  // reset window count + keepalive stamp (ring itself is cleared below)
    // Clear the ring at each level: the 64-slot ring would otherwise fill across 3 levels and freeze with
    // stale data (level 3 would capture nothing). bcurRtest=1 zeroes the count → each level starts fresh.
    cxGet('bcurRtest=1').then(() => cxGet('resTestTargetA=' + cx.rtLevels[idx].toFixed(1)));
    commissionRender();
}
// Driven off the live CSV1 RPM stream (cxRpmSparkOnCsv1) while leveling: green/red + settle gating.
function cxRtTick() {
    const now = Date.now();
    // Keepalive: refresh the firmware deadman every ~3 s so a closed/crashed wizard auto-releases field control.
    if (cx.rtLastCmd && now - cx.rtLastCmd > 3000) { cxGet('resTestTargetA=' + cx.rtLevels[cx.rtLevel].toFixed(1)); cx.rtLastCmd = now; }
    const rpmEl = document.getElementById('cx-rt-rpm'), msgEl = document.getElementById('cx-rt-msg'), btn = document.getElementById('cx-rt-confirm');
    if (!rpmEl) return;
    const rpm = cx.liveRpm, inRange = isFinite(rpm) && Math.abs(rpm - cx.rtestRpm) <= CX_RT_BAND;
    rpmEl.innerHTML = (isFinite(rpm) ? Math.round(rpm) : '—') + ' RPM ' +
        '<span style="padding:1px 8px;border-radius:8px;background:' + (inRange ? '#2a6' : '#a33') + ';color:#fff;font-size:12px;">' + (inRange ? 'IN RANGE' : 'OUT — adjust throttle') + '</span>';
    if (!inRange) { if (msgEl) { msgEl.style.color = '#4a9eff'; msgEl.textContent = 'Bring RPM to ' + cx.rtestRpm + ' (±' + CX_RT_BAND + ').'; } if (btn) btn.disabled = true; return; }
    // Ring is cleared at each level start, so its in-range row count IS this level's progress.
    if (!cx.rtRingAt || now - cx.rtRingAt > 2500) {
        cx.rtRingAt = now;
        fetch(buildURL('/bcurrtest.csv')).then(r => r.text()).then(txt => {
            const lines = txt.trim().split('\n'); let n = 0;
            for (let i = 1; i < lines.length; i++) {
                const c = lines[i].split(','); if (c.length < 3) continue;
                if (Math.abs(parseFloat(c[0]) - cx.rtestRpm) <= CX_RT_BAND) n++;
            }
            cx.rtWinN = n;
        }).catch(() => {});
    }
    const got = cx.rtWinN || 0;
    if (got < CX_RT_MIN_WINS) { if (msgEl) { msgEl.style.color = '#4a9eff'; msgEl.textContent = 'Capturing steady windows… ' + got + ' of ' + CX_RT_MIN_WINS + ' — hold steady.'; } if (btn) btn.disabled = true; }
    else { if (msgEl) { msgEl.style.color = '#5a5'; msgEl.textContent = 'Captured ' + got + ' steady windows — press Record.'; } if (btn) btn.disabled = false; }
}
function cxRtConfirm() {  // capture this level from the most-recent in-range windows (the stable hold)
    fetch(buildURL('/bcurrtest.csv')).then(r => r.text()).then(txt => {
        const lines = txt.trim().split('\n'); const inrange = [];
        for (let i = 1; i < lines.length; i++) {
            const c = lines[i].split(','); if (c.length < 5) continue;
            const rpm = parseFloat(c[0]);
            const iAlt = parseFloat(c[3]), pkAlt = parseFloat(c[4]);  // ring rows: rpm, battI, battPk, altI, altPk
            if (Math.abs(rpm - cx.rtestRpm) <= CX_RT_BAND) inrange.push({ ia: iAlt, pa: pkAlt });
        }
        // Record unlocked on ≥CX_RT_MIN_WINS captured in-range ring windows at this level → the last
        // few windows ARE this level. Use the operating current the ring logged (MeasuredAmps),
        // NOT the commanded level.
        // MEDIAN of the recent windows: with the firmware §10/§11 admission gates the ring rows
        // are already ramp-free, and the median makes the fit point immune to any single outlier window.
        const recent = inrange.slice(-8);
        const med = a => { const s = a.slice().sort((x, y) => x - y); return s.length ? (s.length % 2 ? s[(s.length - 1) / 2] : (s[s.length / 2 - 1] + s[s.length / 2]) / 2) : 0; };
        let iaSum = 0;
        for (const q of recent) { iaSum += q.ia; }
        const pa = med(recent.map(q => q.pa));
        if (recent.length === 0 || !(pa > 0)) { const m = document.getElementById('cx-rt-msg'); if (m) { m.style.color = '#f0a500'; m.textContent = 'No windows captured at this level — hold RPM steady longer, then Record.'; } return; }
        cx.rtPts.push({ ia: iaSum / recent.length, pa });
        if (cx.rtLevel < 2) { cxRtSetLevel(cx.rtLevel + 1); }
        else cxRtFinish();
    }).catch(() => { const m = document.getElementById('cx-rt-msg'); if (m) m.textContent = 'Read failed — press Record again.'; });
}
function cxRtFinish() {
    cxStopPoll(); cx.rtLastCmd = 0; cx.rtFieldArmed = false;  // stop the keepalive; field released below
    // Gentle exit: ramp the commanded current to 0 and wait long enough for the slew to actually reach it
    // (~2.5 s covers a high last level at SetpointFallRate), THEN release (slew carries it back to AUTO).
    cxGet('resTestTargetA=0').then(() => new Promise(r => setTimeout(r, 2500)))
        .then(() => cxGet('resTest=0')).then(() => cxGet('bcurRtest=0')).then(() => cxGet('faCommissionGate=0'));
    const pts = cx.rtPts;
    // Least-squares ripple = a0 + a1·I, clamping a1 ≥ 0 (ripple can't credibly fall with current; a noisy
    // negative slope must never LOWER a safety floor) → on clamp, fall back to a flat mean.
    const lineFit = (getX, getY) => {
        let n = pts.length, Sx = 0, Sy = 0, Sxx = 0, Sxy = 0, lo = 1e9, hi = 0;
        for (const q of pts) { const x = getX(q), y = getY(q); Sx += x; Sy += y; Sxx += x * x; Sxy += x * y; if (x < lo) lo = x; if (x > hi) hi = x; }
        const d = n * Sxx - Sx * Sx;
        let a1 = (d !== 0) ? (n * Sxy - Sx * Sy) / d : 0;
        let a0 = (Sy - a1 * Sx) / n;
        if (a1 < 0) { a1 = 0; a0 = Sy / n; }
        return { a0, a1, lo, hi };
    };
    const fa = lineFit(q => q.ia || 0, q => q.pa || 0);   // alternator (ADS path)
    if (pts.length >= 3 && (fa.hi - fa.lo) >= 5) {
        cx.rtest = { a0: fa.a0, a1: fa.a1, n: pts.length, iLo: fa.lo, iHi: fa.hi, rpm: cx.rtestRpm };
        cx.rtestState = 'done';
        // Persist the measured ripple projection (§3.3). This is the ONLY thing the current-check
        // writes — reference data for the Protections plot, never the over-current floor. String encoding
        // matches the firmware ripFitDecode: "a0,a1,rpm,i0,i1,i2,pk0,pk1,pk2,n".
        const enc = (a0, a1, getI, getP, n) => {
            const i = [0, 0, 0], p = [0, 0, 0];
            for (let k = 0; k < 3 && k < pts.length; k++) { i[k] = getI(pts[k]); p[k] = getP(pts[k]); }
            return [a0.toFixed(4), a1.toFixed(5), Math.round(cx.rtestRpm),
                    i[0].toFixed(2), i[1].toFixed(2), i[2].toFixed(2),
                    p[0].toFixed(3), p[1].toFixed(3), p[2].toFixed(3), n].join(',');
        };
        cxGet('ripFitAlt=' + encodeURIComponent(enc(fa.a0, fa.a1, q => q.ia || 0, q => q.pa || 0, pts.length)))
            .then(() => { cxRipFit = null; loadRipFit(() => renderRipplePlots()); });  // refresh the Protections plot
    } else {
        const iLo = fa.lo, iHi = fa.hi;
        cx.rtestState = 'failed';
        cx.rtFailMsg = 'Levels spanned only ' + (iHi - iLo > 0 ? (iHi - iLo).toFixed(0) : '0') + ' A (need ≥5 A). Retry — make sure the alternator actually reaches the higher levels at this RPM.';
    }
    commissionRender();
}
function cxRtAbort() {
    cxStopPoll(); cx.rtLastCmd = 0; cx.rtFieldArmed = false;  // stop the keepalive; field released below
    cxGet('resTestTargetA=0').then(() => new Promise(r => setTimeout(r, 2500)))
        .then(() => cxGet('resTest=0')).then(() => cxGet('bcurRtest=0')).then(() => cxGet('faCommissionGate=0'));
    cx.rtestState = 'idle';
    commissionRender();
}

// ── Ripple vs. trip-threshold reference plot (RIPPLE_DETECTION_REARCH_SPEC §4) ──
// Shared by the permanent Protections plots and the read-only Step-6 review. Draws each detector's trip
// threshold E(I)=max(floor,min(frac·I,ceil)) — recomputed live from the setting fields — against the stored
// measured ripple fit (a0+a1·I). Shades any current band where ripple ≥ the binding (lowest) threshold and
// writes a one-line verdict. NEVER writes anything to the device — the operator owns the floor/ceiling/%.
let cxRipFit = null;   // {alt:{a0,a1,rpm,n,i:[],pk:[]}} from /ripfit; null until first fetch
function loadRipFit(cb) {
    fetch(buildURL('/ripfit')).then(r => r.json()).then(j => { cxRipFit = j; if (cb) cb(); }).catch(() => { if (cb) cb(); });
}
// Typed value wins (live preview while editing); else the current echo value. Protections inputs are blank
// "set new value" boxes, so the live setting normally comes from the echo span.
function pField(name, echoId) {
    const el = document.querySelector('input[name="' + name + '"]');
    if (el && el.value !== '' && isFinite(parseFloat(el.value))) return parseFloat(el.value);
    return getEchoNumber(echoId);
}
function rippleVerdict(rf, bindE, xMax) {
    if (!rf || !(rf.n > 0)) return 'Run the current check in <strong>Commissioning ▸ Step 5 (Disturbances)</strong> to overlay measured ripple.';
    const rip = I => rf.a0 + rf.a1 * I;
    let worstMargin = 1e9, worstAt = 0, bandHiI = -1, needFloor = 0;
    for (let I = 0; I <= xMax; I += Math.max(0.5, xMax / 300)) {
        const m = bindE(I) - rip(I);
        if (m < worstMargin) { worstMargin = m; worstAt = I; }
        if (rip(I) >= bindE(I)) { if (I > bandHiI) bandHiI = I; if (rip(I) > needFloor) needFloor = rip(I); }
    }
    if (bandHiI < 0) return '<span style="color:#5a5;">Settings clear the measured ripple across the whole range (worst margin ' + worstMargin.toFixed(1) + ' A at ' + Math.round(worstAt) + ' A).</span>';
    return '<span style="color:#f0a500;">Measured ripple exceeds the trip threshold below ~' + Math.round(bandHiI) + ' A (floor-limited) — false-trip likely there. Raise the floor to ≥' + Math.ceil(needFloor) + ' A or accept it.</span>';
}
function drawRippleThreshPlot(canvasId, cfg) {
    const cv = document.getElementById(canvasId);
    if (!cv) return;
    const cssW = cv.clientWidth || 600, cssH = cv.clientHeight || 220;
    const dpr = window.devicePixelRatio || 1;
    cv.width = Math.round(cssW * dpr); cv.height = Math.round(cssH * dpr);
    const g = cv.getContext('2d'); g.setTransform(dpr, 0, 0, dpr, 0, 0);
    g.clearRect(0, 0, cssW, cssH);
    g.font = '11px system-ui,sans-serif';
    const xMax = cfg.xMax > 0 ? cfg.xMax : 150;
    // Settings may not have arrived yet (echo shows '?') → sane fallbacks so the plot is never NaN-broken.
    const floor = isFinite(cfg.floor) ? cfg.floor : 0;
    const ceil = isFinite(cfg.ceil) && cfg.ceil > 0 ? cfg.ceil : 1e6;
    const fracLines = cfg.fracLines.filter(fl => isFinite(fl.frac) && fl.frac > 0);
    const Efrac = (frac, I) => Math.max(floor, Math.min(frac * I, ceil));
    const bindE = I => fracLines.length ? Math.min.apply(null, fracLines.map(fl => Efrac(fl.frac, I))) : floor;  // lowest line = first to false-trip
    const rf = cfg.ripFit, hasFit = rf && rf.n > 0;
    const rip = I => rf.a0 + rf.a1 * I;
    let yMax = floor;
    for (let I = 0; I <= xMax; I += xMax / 60) yMax = Math.max(yMax, bindE(I), hasFit ? rip(I) : 0);
    if (hasFit) for (let k = 0; k < rf.n; k++) yMax = Math.max(yMax, rf.pk[k]);
    yMax = Math.max(yMax * 1.15, 2);
    const padL = 44, padR = 12, padT = 22, padB = 34;
    const plotW = cssW - padL - padR, plotH = cssH - padT - padB;
    const sx = x => padL + (Math.min(x, xMax) / xMax) * plotW;
    const sy = y => padT + (1 - Math.min(y, yMax) / yMax) * plotH;
    g.fillStyle = cfg.color; g.textAlign = 'left'; g.fillText(cfg.title, padL, 13);
    // Red-shade the current bands where ripple ≥ the binding threshold (drawn first, under the lines).
    if (hasFit) {
        g.fillStyle = 'rgba(220,60,60,0.22)';
        for (let px = 0; px < plotW; px++) { const I = px / plotW * xMax; if (rip(I) >= bindE(I)) g.fillRect(padL + px, padT, 1.5, plotH); }
    }
    g.strokeStyle = '#333'; g.lineWidth = 1;
    g.beginPath(); g.moveTo(padL, padT); g.lineTo(padL, padT + plotH); g.lineTo(padL + plotW, padT + plotH); g.stroke();
    const xStep = xMax <= 60 ? 10 : (xMax <= 160 ? 30 : 50);
    for (let xv = 0; xv <= xMax + 0.1; xv += xStep) {
        g.strokeStyle = '#262626'; g.beginPath(); g.moveTo(sx(xv), padT); g.lineTo(sx(xv), padT + plotH); g.stroke();
        g.fillStyle = '#888'; g.textAlign = 'center'; g.fillText(Math.round(xv) + '', sx(xv), padT + plotH + 15);
    }
    const yStep = yMax <= 6 ? 1 : (yMax <= 12 ? 2 : (yMax <= 30 ? 5 : 10));
    for (let yv = 0; yv <= yMax; yv += yStep) {
        g.strokeStyle = '#262626'; g.beginPath(); g.moveTo(padL, sy(yv)); g.lineTo(padL + plotW, sy(yv)); g.stroke();
        g.fillStyle = '#888'; g.textAlign = 'right'; g.fillText(yv + '', padL - 5, sy(yv) + 4);
    }
    g.fillStyle = '#aaa'; g.textAlign = 'center'; g.fillText('operating current (A)', padL + plotW / 2, cssH - 4);
    g.save(); g.translate(11, padT + plotH / 2); g.rotate(-Math.PI / 2); g.fillText('amps', 0, 0); g.restore();
    // Threshold line(s): floor → %/A ramp → ceiling. Labels clamp to the right edge (they're long
    // enough to overflow a phone-width canvas) and sit above the line's value at the label's END,
    // so the monotonic ramp can never rise through the text.
    let lastLabelY = 1e9;
    fracLines.forEach(fl => {
        g.strokeStyle = fl.color; g.lineWidth = 2; g.setLineDash([]);
        g.beginPath();
        for (let px = 0; px <= plotW; px++) { const I = px / plotW * xMax, y = Efrac(fl.frac, I); if (px === 0) g.moveTo(sx(I), sy(y)); else g.lineTo(sx(I), sy(y)); }
        g.stroke();
        const Il = Math.min(xMax * 0.55, fl.frac > 0 ? ceil / fl.frac : xMax);
        g.fillStyle = fl.color; g.textAlign = 'left';
        const lw = g.measureText(fl.label).width;
        const lx = Math.max(padL + 2, Math.min(sx(Il) + 3, padL + plotW - lw - 2));
        const Iend = ((lx + lw - padL) / plotW) * xMax;
        let ly = Math.max(padT + 10, sy(Efrac(fl.frac, Iend)) - 4);
        if (lastLabelY - ly < 12) ly = lastLabelY - 12;
        lastLabelY = ly;
        g.fillText(fl.label, lx, ly);
    });
    // Measured ripple fit: solid within the tested span, dashed on extrapolation, dots at the 3 levels.
    if (hasFit) {
        const iLo = Math.min.apply(null, rf.i.slice(0, rf.n)), iHi = Math.max.apply(null, rf.i.slice(0, rf.n));
        g.strokeStyle = '#dc5050'; g.lineWidth = 2; g.setLineDash([]);
        g.beginPath(); g.moveTo(sx(iLo), sy(rip(iLo))); g.lineTo(sx(Math.min(iHi, xMax)), sy(rip(Math.min(iHi, xMax)))); g.stroke();
        g.setLineDash([5, 5]);
        if (iLo > 0) { g.beginPath(); g.moveTo(sx(0), sy(rip(0))); g.lineTo(sx(iLo), sy(rip(iLo))); g.stroke(); }
        if (iHi < xMax) { g.beginPath(); g.moveTo(sx(iHi), sy(rip(iHi))); g.lineTo(sx(xMax), sy(rip(xMax))); g.stroke(); }
        g.setLineDash([]); g.fillStyle = '#dc5050';
        for (let k = 0; k < rf.n; k++) { g.beginPath(); g.arc(sx(rf.i[k]), sy(rf.pk[k]), 4, 0, 2 * Math.PI); g.fill(); }
        g.textAlign = 'left';
        const rl = 'measured and extrapolated ripple';
        const rlx = Math.max(padL + 2, Math.min(sx(iLo), padL + plotW - g.measureText(rl).width - 2));
        g.fillText(rl, rlx, Math.max(padT + 10, sy(rip(iHi)) - 6));
    }
    if (cfg.verdictId) { const vd = document.getElementById(cfg.verdictId); if (vd) vd.innerHTML = rippleVerdict(rf, bindE, xMax); }
}
// Per-plot X-axis-length control (operator-adjustable, persisted). Default 0–150 A.
function rippleXmax(id) {
    const el = document.getElementById(id);
    let v = el ? parseFloat(el.value) : NaN;
    if (!isFinite(v) || v <= 0) { v = parseFloat(localStorage.getItem(id)) || 150; if (el && el.value === '') el.value = v; }
    else localStorage.setItem(id, v);
    return v;
}
// The two permanent Protections plots. Threshold lines recompute client-side on every keystroke (pField
// reads the typed value before saving); the ripple line is fixed measured data (cxRipFit).
function renderRipplePlots() {
    const cv = document.getElementById('rippleThreshPlotAlt');
    if (!cv || cv.offsetParent === null) return;   // not mounted / tab hidden → skip (redraws on show)
    const rf = cxRipFit || {};
    const fracCV = pField('IExcessFrac', 'IExcessFrac_echo') / 100, fracBulk = pField('IExcessFracBulk', 'IExcessFracBulk_echo') / 100;
    drawRippleThreshPlot('rippleThreshPlotAlt', {
        title: 'Alternator (G3)', color: '#4a9eff',
        floor: pField('IExcessFloorA', 'IExcessFloorA_echo'), ceil: pField('IExcessCeilA', 'IExcessCeilA_echo'),
        fracLines: [{ frac: fracCV, label: 'protection threshold near voltage target', color: '#4a9eff' },
                    { frac: fracBulk, label: 'protection threshold in bulk', color: '#f0a500' }],
        ripFit: rf.alt, xMax: rippleXmax('rippleXmaxAlt'), verdictId: 'rippleVerdictAlt'
    });
}

// ── Step 6 · Thresholds — READ-ONLY review (§6) ──────────────────────────────
// No compute, no apply, no ÷2πfτ. Shows the same Protections crossing-plot inline with a verdict so
// the operator can confirm their over-current settings clear the ripple this alternator actually produces.
function cxRenderThresh(b) {
    let body = '<p style="font-size:15px;line-height:1.5;">Normal ripple plotted with your protection thresholds — make sure the normal ripple stays below the thresholds at all currents. A red band marks where the detector would false-trip.</p>';
    body += '<canvas id="cxThreshPlotAlt" style="width:100%;height:220px;margin-top:8px;background:#161616;border-radius:6px;display:block;"></canvas>' +
            '<div id="cxThreshVerdictAlt" style="font-size:12px;color:#bbb;margin-top:6px;line-height:1.5;"></div>';
    body += '<p style="font-size:12px;color:#999;margin-top:10px;">Nothing is written on this step. If a threshold needs changing, you can do that later in <strong>Settings ▸ Alternator ▸ Protections</strong> — the same plot lives there and redraws live as you type.</p>';
    body += '<details style="margin-top:8px;"><summary style="cursor:pointer;font-size:12px;color:#aaa;">Applied settings</summary>' +
        '<div style="font-size:12px;color:#bbb;line-height:1.6;margin-top:6px;">' + cxAppliedSummary() + '</div></details>';
    if (cxNextSelected(cx.phase) === -1)
        body += '<p style="font-size:12px;color:#999;margin-top:12px;">Finishing discards the pre-commissioning snapshot and clears the warning badge.</p>';
    body += '<div style="margin-top:12px;">' + cxNextBtn(true) + '</div>';
    b.innerHTML = body;
    loadRipFit(() => {
        const rf = cxRipFit || {};
        const fracCV = getEchoNumber('IExcessFrac_echo') / 100, fracBulk = getEchoNumber('IExcessFracBulk_echo') / 100;
        drawRippleThreshPlot('cxThreshPlotAlt', {
            title: 'Alternator (G3)', color: '#4a9eff',
            floor: getEchoNumber('IExcessFloorA_echo'), ceil: getEchoNumber('IExcessCeilA_echo'),
            fracLines: [{ frac: fracCV, label: 'protection threshold near voltage target', color: '#4a9eff' },
                        { frac: fracBulk, label: 'protection threshold in bulk', color: '#f0a500' }],
            ripFit: rf.alt, xMax: 150, verdictId: 'cxThreshVerdictAlt'
        });
    });
}

function cxAppliedSummary() {
    const r = cx.fieldResult, f = cx.fit;
    const rows = [];
    if (r) rows.push('Field: stabilize ' + r.propStabA.toFixed(0) + ' A, step ' + r.propStepPct.toFixed(1) + '%');
    if (f && f.ok) rows.push('Gains: Kp ' + f.Kp.toFixed(3) + ', Ki ' + f.Ki.toFixed(3) + '; filters ' + Math.round(f.tauMs / 3) + '/' + Math.round(f.tauMs) + ' ms');
    // Over-current floor/ceiling are operator-owned (Protections), so they're echoed here, not "applied" by
    // commissioning. The current-check only produced the measured ripple projection (the plot above).
    const flr = getEchoNumber('IExcessFloorA_echo');
    if (flr > 0) rows.push('Over-current floor (set in Protections): ' + flr.toFixed(1) + ' A');
    return rows.length ? rows.join('<br>') : 'No settings applied yet — earlier phases were skipped.';
}
function cxFinish() {
    cxGet('commissionDone=1').then(() => {
        const _ALL = (1 << COMMISSION_STEPS.length) - 1;
        const allDone = (cxLastMask & _ALL) === _ALL;
        if (!allDone) xAlert('Selected steps saved. Some steps are still pending — the badge shows what remains.');
        closeCommissionModal(); cx = null; cxPlanUserSet = false;   // re-default the plan next time
        showMainTab('tuning'); showSubTab('tuning', 'commissioning');   // land on the Commissioning checklist when the wizard finishes
    }).catch(e => xAlert('Finish failed: ' + e));
}
async function commissionAbort() {
    if (!await xConfirm('Abort commissioning and revert all settings to the pre-commissioning snapshot?')) return;
    cxStopPoll();
    cxGet('commissionAbort=1').then(() => { xAlert('Reverted to pre-commissioning settings.'); closeCommissionModal(); cx = null; cxPlanUserSet = false; }).catch(e => xAlert('Abort failed: ' + e));
}

// The eight wizard steps, mirrored from CX_PHASES, with a one-line plain-English purpose.
// Single source for the Commissioning tab checklist; indices match the persisted commissionPhase.
const COMMISSION_STEPS = [
    { name: 'Prep', desc: 'Preconditions checked, current tune snapshotted for safe revert.' },
    { name: 'Field curve', desc: 'Map field duty → current and find the saturation knee.' },
    { name: 'Plant fit', desc: 'Measure the field coil\'s electrical lag (plant delay) and set the filters.' },
    { name: 'Verify', desc: 'Seed the current-loop gains and confirm the loop responds.' },
    { name: 'Disturbances', desc: 'Map the worst over-current the field can actually react to.' },
    { name: 'Thresholds', desc: 'Set the over-current trip points above that disturbance floor.' },
    { name: 'CV plant fit', desc: 'Step the charge current and measure the battery-voltage step gain K_dc (fast edge, slow charge ramp removed); set the voltage-loop Kp = ω/K_dc, Ki = ρ·Kp at the recommended ~14 s response and switch the CV gain source to Auto.' },
    { name: 'Min% floor', desc: 'Runs last, with the engine warm: guided onset-knee automatic current sweeps down the throttle at three RPMs (max working → mid → idle) fit the per-RPM Min% floor; above the max it is forced to zero.' },
];
let cxLastState = 0;   // remembered from the last CSV3 frame, for the clear/restart confirm text

// Render the whole Commissioning tab status block: badge + overall line + step checklist (with
// per-step run checkboxes) + clear/restart button. Driven by persisted state (0/1/2), furthest
// phase reached (0..7), and the per-stage done bitmask (bit i = stage i complete).
function renderCommissionStatus(state, phase, mask) {
    cxLastState = state;
    cxLastPhase = phase;
    cxLastMask = mask || 0;
    // Until the user touches a checkbox, keep the run plan defaulted to the pending stages (so a
    // fresh device pre-selects all and a single stale step pre-selects just that one).
    if (!cxPlanUserSet) cxDefaultPlanFromMask(cxLastMask);

    // A partial is wiped on reboot (firmware aborts in-progress at boot). If the device now
    // reports NOT_COMMISSIONED while we still hold stale in-session state past Prep — and the
    // panel is closed — drop it so "Resume" can't reopen a phase the device no longer backs.
    // Gated on the panel being closed so a freshly-started flow (Prep→phase 1) can't be nuked
    // by a late CSV3 frame still carrying the pre-start state.
    const _ov = document.getElementById('commission-modal-overlay');
    const _panelOpen = _ov && _ov.style.display === 'block';
    if (state === 0 && !_panelOpen && cx && cx.phase > 0) { cx = null; }

    const ov = document.getElementById('commission-overall');
    if (ov) {
        let doneCount = 0; for (let i = 0; i < COMMISSION_STEPS.length; i++) if (cxLastMask & (1 << i)) doneCount++;
        if (state === 2) { ov.textContent = 'Commissioned'; ov.style.color = '#2e7d32'; }
        else if (state === 1) {
            // Every step done but state still 1 = the run completed but Finish never committed it
            // (closed early / dropped network). Say so instead of "in progress" — the button offers Finish.
            if (doneCount === COMMISSION_STEPS.length) { ov.textContent = 'All steps done — press “Finish commissioning” to save'; ov.style.color = '#b8860b'; }
            else { ov.textContent = 'In progress — ' + doneCount + ' of ' + COMMISSION_STEPS.length + ' steps done'; ov.style.color = '#b8860b'; }
        }
        else { ov.textContent = 'Not commissioned'; ov.style.color = '#c62828'; }
    }

    const cl = document.getElementById('commission-checklist');
    if (cl) {
        cl.innerHTML = COMMISSION_STEPS.map((s, i) => {
            const done = !!(cxLastMask & (1 << i));   // ✓ now comes from the per-stage done mask
            // "Current" = the step the wizard is on. Done always wins, so a finished current step shows ✓.
            const current = (state === 1) && (i === phase) && (phase < COMMISSION_STEPS.length) && !done;
            const prep = (i === 0);
            const cbAttrs = (cxPlan[i] ? 'checked ' : '') + (prep ? 'disabled ' : '');
            const cbTitle = prep ? 'Prep always runs (snapshot + preconditions)' : 'Run this step in the next commissioning pass';
            // Status badge sits at the RIGHT of the row (not between the checkbox and the name) so a
            // completed step is unmistakable next to the run checkboxes. Big bold ✓ DONE when complete;
            // ▶ RUNNING while the wizard is open on this step, ▶ RESUME when paused (modal closed); ○ otherwise.
            let badge;
            if (done) {
                badge = '<span style="font-size:22px;font-weight:800;color:#2e7d32;line-height:1;">✓</span>' +
                        '<span style="font-size:9px;font-weight:700;letter-spacing:.06em;color:#2e7d32;">DONE</span>';
            } else if (current) {
                const lbl = _panelOpen ? 'RUNNING' : 'RESUME';
                badge = '<span style="font-size:16px;color:#1565c0;line-height:1;">▶</span>' +
                        '<span style="font-size:9px;font-weight:700;letter-spacing:.06em;color:#1565c0;">' + lbl + '</span>';
            } else {
                badge = '<span style="font-size:16px;color:var(--text-muted);line-height:1;">○</span>';
            }
            return '<div style="display:flex;gap:10px;align-items:center;padding:10px 0;border-top:1px solid var(--border);">' +
                '<input type="checkbox" ' + cbAttrs + 'onchange="cxToggleStage(' + i + ', this.checked)" title="' + cbTitle + '" style="flex:0 0 auto;cursor:' + (prep ? 'default' : 'pointer') + ';">' +
                '<span style="flex:1;min-width:0;line-height:1.45;">' +
                '<span style="font-weight:' + (current ? '700' : '500') + ';">' + (i + 1) + '. ' + s.name + '</span>' +
                '<br><span style="font-size:12px;color:var(--text-muted);">' + s.desc + '</span>' +
                '</span>' +
                '<span style="flex:0 0 auto;display:flex;flex-direction:column;align-items:center;gap:1px;min-width:46px;">' + badge + '</span>' +
                '</div>';
        }).join('');
    }
    // Master "Select all steps" reflects whether every optional stage (1..last) is selected.
    const sa = document.getElementById('commission-select-all');
    if (sa) sa.checked = cxPlan.slice(1).every(Boolean);

    // Primary button label/class/help adapt to the ticked plan vs. the done-mask (see cxStartIntent):
    // Start (nothing done) / Continue (partial pass or targeted redo) / Clear-and-restart (all ticked
    // with work already done). The old separate clear-row is folded into this one button.
    const sb = document.getElementById('commission-start-btn');
    const sh = document.getElementById('commission-start-help');
    const intent = cxStartIntent();
    if (sb) {
        sb.textContent = intent.label;
        sb.className = intent.className;
        sb.disabled = intent.disabled;
    }
    if (sh) sh.textContent = intent.help;
}

// Clear progress & start over: revert to the pre-commissioning snapshot (firmware also resets
// state→0, phase→0) and reopen the wizard fresh at Prep. From a COMMISSIONED device there is no
// snapshot to revert (it was discarded on Finish), so the current good tune simply stays as the
// new starting point and is snapshotted again when the fresh run begins.
async function commissionClearAndRestart() {
    if (!currentAdminPassword) { xAlert('Unlock settings first (enter the admin password).'); return; }
    const msg = (cxLastState === 2)
        ? 'Clear the commissioned mark and start the setup wizard over?\n\nThe wizard restarts from the beginning, using your current settings as the starting point. Nothing is permanently changed until you finish — use "Abort and revert all" to restore your starting settings at any point. Closing the wizard with the X just pauses it and keeps your progress so you can resume later.'
        : 'Clear commissioning progress and revert all settings to the pre-commissioning snapshot, then start over?';
    if (!await xConfirm(msg)) return;
    cxStopPoll();
    cxGet('commissionAbort=1').then(() => {
        cx = null;                 // drop any stale in-session state
        cxPlanUserSet = false;     // re-default the run plan (everything will read as not-done now)
        // Clear the local mirror and repaint so the checklist ✓ marks flip to ○ the instant the
        // user clicks — otherwise they linger until the next CSV3 frame round-trips the now-zeroed
        // done-mask back (CSV3 is event-driven, so that lag is user-visible).
        cxLastState = 0; cxLastPhase = 0; cxLastMask = 0;
        renderCommissionStatus(0, 0, 0);
        openCommissionModal();     // reopen fresh at Prep (user re-confirms Start there)
    }).catch(e => xAlert('Clear failed: ' + e));
}

function applySysidBodeFilters() {
    if (!currentAdminPassword) { xAlert("Please unlock settings first."); return; }
    if (sysidFitTauMs <= 0) { xAlert("No plant fit available — re-run the sweep."); return; }
    const tcFast = encodeURIComponent(Math.max(1, Math.round(sysidFitTauMs / 3)));
    const tcSlow = encodeURIComponent(Math.max(1, Math.round(sysidFitTauMs)));
    const pw = encodeURIComponent(currentAdminPassword);
    fetch(buildURL("/get?InputFilterTC=" + tcFast + "&password=" + pw))
        .then(() => fetch(buildURL("/get?OutputPIDFilterTC=" + tcFast + "&password=" + pw)))
        .then(() => fetch(buildURL("/get?VoltageFilterTC=" + tcSlow + "&password=" + pw)))
        .then(() => { console.log("Filters set from τ: PID/display=" + tcFast + "ms, voltage=" + tcSlow + "ms"); closeSystemIDModal(); })
        .catch(err => console.error("Filter set from τ failed:", err));
}

// "Apply PID seed" — write the IMC starting Kp/Ki to the current loop. A starting point;
// the user refines with the square-wave tuner. Kd left untouched (PI seed).
function applySysidPidSeed() {
    if (!currentAdminPassword) { xAlert("Please unlock settings first."); return; }
    if (!(sysidFitKp > 0)) { xAlert("No PID seed available — re-run the sweep."); return; }
    const pw = encodeURIComponent(currentAdminPassword);
    const kp = encodeURIComponent(sysidFitKp.toFixed(4));
    const ki = encodeURIComponent(sysidFitKi.toFixed(4));
    fetch(buildURL("/get?PidKp=" + kp + "&password=" + pw))
        .then(() => fetch(buildURL("/get?PidKi=" + ki + "&password=" + pw)))
        .then(() => { console.log("PID seed applied: Kp=" + kp + ", Ki=" + ki); closeSystemIDModal(); })
        .catch(err => console.error("PID seed apply failed:", err));
}

function applySystemIDResults() {
    if (!currentAdminPassword) { xAlert("Please unlock settings first."); return; }
    // PID feedback and the filtered-amps display get plant/3 to preserve phase margin
    // inside the control loop. (iExcess no longer uses InputFilterTC — it has its own EMA on
    // IExcessTau, sized by belt resonance, not plant delay — so this only sets the display
    // filter now.) Voltage smoothing gets the full plant delay because its consumer
    // (slope bleed dV/dt) runs on the same timescale as the voltage loop tick.
    const tcFast = Math.max(1, Math.round(sysidSuggestedTC / 3));
    const tcSlow = Math.max(1, Math.round(sysidSuggestedTC));
    const tcFastEnc = encodeURIComponent(tcFast);
    const tcSlowEnc = encodeURIComponent(tcSlow);
    const pw = encodeURIComponent(currentAdminPassword);
    fetch(buildURL("/get?InputFilterTC=" + tcFastEnc + "&password=" + pw))
        .then(() => fetch(buildURL("/get?OutputPIDFilterTC=" + tcFastEnc + "&password=" + pw)))
        .then(() => fetch(buildURL("/get?VoltageFilterTC=" + tcSlowEnc + "&password=" + pw)))
        .then(() => {
            console.log("Filter TCs updated: iExcess=" + tcFast + "ms, PID=" + tcFast + "ms, Voltage=" + tcSlow + "ms");
            closeSystemIDModal();
        })
        .catch(err => console.error("Filter TC update failed:", err));
}


// Auto-login via URL parameter for local automation (e.g. SwiftBar shortcut)
window.addEventListener('load', function () {
  const autopass = new URLSearchParams(window.location.search).get('autopass');
  if (autopass) {
    const el = document.getElementById('admin_password');
    if (el) { el.value = autopass; setAdminPassword(); }
  }
});

// Live Data → Diag checkpoint pills (C1–C4) — same pattern as the Protections filter below,
// but filtering whole <details class="checkpoint-section"> blocks (data-checkpoints is
// space-separated; an empty list means All-view only, e.g. Wear Rate / Accuracy Scores).
(function initDiagCheckpoints() {
    // Pills live only in Setup → Diag (the knobs). Live Data → Diag is results-only, never filtered.
    const panel = document.getElementById('settings-diag');
    if (!panel) return;
    const pills = panel.querySelectorAll('.checkpoint-filters button[data-filter]');
    if (!pills.length) return;
    let active = 'all';

    function apply() {
        panel.querySelectorAll('.checkpoint-param').forEach(card => {
            const cks = (card.dataset.checkpoints || '').split(/\s+/).filter(Boolean);
            const show = (active === 'all') || cks.includes(active);
            card.style.display = show ? '' : 'none';
        });
        panel.querySelectorAll('.checkpoint-intro p').forEach(p => {
            p.classList.toggle('active', p.dataset.intro === active);
        });
    }

    pills.forEach(btn => {
        btn.addEventListener('click', () => {
            pills.forEach(b => b.classList.remove('active'));
            btn.classList.add('active');
            active = btn.dataset.filter;
            apply();
        });
    });

    apply();
})();

// Protections alt-tab — filter pills + intro toggling + empty-phase hiding.
// Scoped to #alt-panel-protections so it can't affect the rest of the site.
(function initProtectionsFilters() {
  const panel = document.getElementById('alt-panel-protections');
  if (!panel) return;

  const pills = panel.querySelectorAll('.protections-filters button[data-filter]');
  let activeFilter = 'all';

  function applyFilter() {
    panel.querySelectorAll('.protections-param').forEach(card => {
      const groups = (card.dataset.groups || '').split(/\s+/).filter(Boolean);
      const show = (activeFilter === 'all') || groups.includes(activeFilter);
      card.style.display = show ? '' : 'none';
    });
    // data-intro accepts a space-separated group list (same convention as data-groups),
    // so one paragraph can serve several pills — e.g. the shared Recovery intro.
    panel.querySelectorAll('.protections-intro p').forEach(p => {
      p.classList.toggle('active', (p.dataset.intro || '').split(/\s+/).includes(activeFilter));
    });
    panel.querySelectorAll('.protections-phase').forEach(sec => {
      const anyCard = Array.from(sec.querySelectorAll('.protections-param'))
        .some(a => a.style.display !== 'none');
      const anyIntro = sec.querySelector('.protections-intro p.active') !== null;
      sec.classList.toggle('empty', !anyCard && !anyIntro);
      const grid = sec.querySelector('.protections-cards');
      if (grid) grid.classList.toggle('empty', !anyCard);
    });
  }

  pills.forEach(btn => {
    btn.addEventListener('click', () => {
      pills.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      activeFilter = btn.dataset.filter;
      applyFilter();
      renderRipplePlots();   // filter change re-lays-out the cards → redraw the now-visible plot(s)
    });
  });

  applyFilter();

  // Ripple-vs-threshold plots (§4): live threshold redraw on every keystroke, fixed measured-ripple overlay.
  ['IExcessFloorA', 'IExcessCeilA', 'IExcessFrac', 'IExcessFracBulk'].forEach(n => {
    const el = panel.querySelector('input[name="' + n + '"]');
    if (el) el.addEventListener('input', renderRipplePlots);
  });
  loadRipFit(renderRipplePlots);
  // Draw when the panel first becomes visible (canvas has no size while its tab is hidden).
  const cv = document.getElementById('rippleThreshPlotAlt');
  if (cv && typeof IntersectionObserver !== 'undefined') {
    new IntersectionObserver((ents) => { if (ents.some(e => e.isIntersecting)) renderRipplePlots(); })
      .observe(cv);
  }
  // Redraw when the setting echoes refresh (CSV3 arrives after the tab is already open), debounced.
  if (typeof MutationObserver !== 'undefined') {
    let deb = null;
    const mo = new MutationObserver(() => { clearTimeout(deb); deb = setTimeout(renderRipplePlots, 120); });
    ['IExcessFloorA_echo', 'IExcessCeilA_echo', 'IExcessFrac_echo', 'IExcessFracBulk_echo'].forEach(id => {
      const e = document.getElementById(id); if (e) mo.observe(e, { childList: true, characterData: true, subtree: true });
    });
  }
  window.addEventListener('resize', renderRipplePlots);
})();

// ========================================================================
// BAROMETER PANEL (Other tab) — Zambretti forecast + 14-day history plot
// Lives in its own IIFE so locals don't leak into the global namespace.
// Public hooks (window.*) are how the rest of the app pokes us:
//   window.initBaroPanel()              — call on Other-tab activation (idempotent)
//   window.updateBaroDisplay(data, sa)  — call from CSV2 dispatcher each cycle
// ========================================================================
(function () {
  'use strict';

  const BARO_HISTORY_SIZE = 1008;              // must match firmware (7 days × 6 samples/h)
  const SAMPLE_INTERVAL_MIN = 10;              // ditto — firmware samples every 10 min
  const FETCH_INTERVAL_MS = 10 * 60 * 1000;    // refresh history every 10 min while tab visible
  const STALE_MS_NMEA = 10000;                 // mirrors STALE_THRESHOLD_TEMP_MS-style logic for NMEA fields

  // 26-slot Zambretti forecast table (slot 1 = best, slot 26 = worst).
  // Wording follows the conventional 1985 Beteljuice reproduction commonly cited online.
  const Z_FORECASTS = [
    'Settled fine',
    'Fine weather',
    'Becoming fine',
    'Fine, becoming less settled',
    'Fine, possible showers',
    'Fairly fine, improving',
    'Fairly fine, possible showers early',
    'Fairly fine, showery later',
    'Showery early, improving',
    'Changeable, mending',
    'Fairly fine, showers likely',
    'Rather unsettled, clearing later',
    'Unsettled, probably improving',
    'Showery, bright intervals',
    'Showery, becoming less settled',
    'Changeable, some rain',
    'Unsettled, short fine intervals',
    'Unsettled, rain later',
    'Unsettled, rain at times',
    'Very unsettled, rain',
    'Stormy, may improve',
    'Stormy, much rain',
    'Rain at times, worse later',
    'Rain at times, very unsettled',
    'Rain, becoming heavy and squally',
    'Stormy, possibly worse'
  ];

  // Pressure zones (mbar). Colors mirror the prototype palette and degrade gracefully in dark mode.
  const ZONES = [
    { min: -Infinity, max: 980,      name: 'STORMY',   color: '#c62828', dark: '#e57373', range: 'below 980 mbar' },
    { min: 980,       max: 1000,     name: 'RAIN',     color: '#ef6c00', dark: '#ffb74d', range: '980–1000 mbar' },
    { min: 1000,      max: 1010,     name: 'CHANGE',   color: '#c0a000', dark: '#ddcc66', range: '1000–1010 mbar' },
    { min: 1010,      max: 1025,     name: 'FAIR',     color: '#2e7d32', dark: '#81c784', range: '1010–1025 mbar' },
    { min: 1025,      max: Infinity, name: 'VERY DRY', color: '#1565c0', dark: '#64b5f6', range: 'above 1025 mbar' }
  ];

  // State — buffer is held chronologically (oldest at index 0, newest at end).
  // NaN slots = empty (no sample yet, or wiped because too old to display).
  let baroPlot = null;
  let baroBuffer = new Float32Array(BARO_HISTORY_SIZE);
  let baroBufferEpochAtEnd = 0;          // unix seconds of the newest non-NaN sample (0 = unknown)
  let currentRangeHours = 24;
  let autoscaleY = false;
  let baroYManual = null;          // [min,max] typed on the plot; beats autoscale + fixed default
  try { baroYManual = JSON.parse(localStorage.getItem('baroYManual')) || null; } catch (e) { }
  let fetchTimer = null;
  let initialized = false;
  let panelVisible = false;

  for (let i = 0; i < BARO_HISTORY_SIZE; i++) baroBuffer[i] = NaN;

  // ---------- PUBLIC API ---------------------------------------------------
  window.initBaroPanel = function () {
    panelVisible = true;
    if (!initialized) {
      wireControls();
      initialized = true;
    }
    fetchBaroHistory();
    if (fetchTimer) clearInterval(fetchTimer);
    fetchTimer = setInterval(() => { if (panelVisible) fetchBaroHistory(); }, FETCH_INTERVAL_MS);
  };

  // Note: we don't have a "tab hidden" hook so panelVisible stays true. Fetches are cheap (~8 KB)
  // so re-fetching every 5 min in the background is fine.

  window.updateBaroDisplay = function (data, sa) {
    if (!data) return;
    const p = parseFloat(data.baroPressure) / 10;   // CSV2 sends mbar ×10
    if (!isFinite(p) || p < 800 || p > 1100) {
      setText('baroZoneLabel', '—');
      setText('baroZoneSub', 'sensor offline');
      return;
    }

    // Zone
    const dark = document.body.classList.contains('dark-mode');
    const zone = pressureZone(p);
    const zoneColor = dark ? zone.dark : zone.color;
    const zEl = document.getElementById('baroZoneLabel');
    if (zEl) { zEl.textContent = zone.name; zEl.style.color = zoneColor; }
    setText('baroZoneSub', zone.range);

    // 3-hour tendency from buffer
    const samplesPer3h = Math.round((3 * 60) / SAMPLE_INTERVAL_MIN);  // 36
    let delta = null;
    if (baroBufferEpochAtEnd > 0) {
      // Newest non-NaN sample is at the last filled slot; walk back samplesPer3h slots.
      const lastIdx = lastFilledIdx();
      if (lastIdx >= samplesPer3h) {
        const oldP = baroBuffer[lastIdx - samplesPer3h];
        if (isFinite(oldP)) delta = p - oldP;
      }
    }

    if (delta === null) {
      setText('baroTendencyLabel', 'Building…');
      setText('baroTendencyDelta', 'need 3 h of samples');
      setHTML('baroTendencyArrow', makeTendencyArrow(0));
    } else {
      setText('baroTendencyLabel', tendencyLabel(delta));
      setText('baroTendencyDelta', `${delta >= 0 ? '+' : ''}${delta.toFixed(1)} mbar / 3h`);
      setHTML('baroTendencyArrow', makeTendencyArrow(delta));
    }

    // Forecast — Zambretti when wind & GPS fresh, fallback otherwise
    const headingFresh    = sa && sa.heading != null && sa.heading < STALE_MS_NMEA;
    const trueWindFresh   = sa && sa.trueWindAngle != null && sa.trueWindAngle < STALE_MS_NMEA;
    const latFresh        = isFinite(parseFloat(data.LatitudeNMEA)) && data.LatitudeNMEA !== 0;

    let forecastStr, methodLabel, methodSub;
    if (delta !== null && headingFresh && trueWindFresh && latFresh) {
      // heading + true wind angle now ride CSV4/NavStream; read them from the nav cache (LatitudeNMEA stays on CSV2)
      const twdEarth = (parseFloat(window._navLast.HeadingNMEA) + parseFloat(window._navLast.TrueWindAngleNMEA) + 360) % 360;
      const z = zambretti(p, delta, twdEarth, parseFloat(data.LatitudeNMEA), new Date());
      forecastStr = z.text;
      methodLabel = 'Zambretti';
      methodSub = `wind ${twdToCompass(twdEarth)} · slot ${z.Z}`;
    } else if (delta !== null) {
      forecastStr = fallbackForecast(p, delta);
      methodLabel = 'Tendency only';
      const missing = [];
      if (!headingFresh)  missing.push('heading');
      if (!trueWindFresh) missing.push('true wind');
      if (!latFresh)      missing.push('GPS');
      methodSub = missing.length ? `no ${missing.join(', ')}` : '';
    } else {
      forecastStr = 'Collecting history — full forecast available after 3 h of samples.';
      methodLabel = 'Warming up';
      methodSub = '';
    }
    setText('baroForecastText', forecastStr);
    setText('baroMethodLabel', methodLabel);
    setText('baroMethodSub', methodSub);
  };

  // ---------- HISTORY FETCH ------------------------------------------------
  function fetchBaroHistory() {
    fetch('/baroHistory.bin', { cache: 'no-cache' })
      .then(r => { if (!r.ok) throw new Error('http ' + r.status); return r.arrayBuffer(); })
      .then(buf => parseHistory(buf))
      .then(() => { if (baroPlot) refreshPlot(); else buildBaroPlot(); })
      .catch(e => { /* offline / not yet implemented in older firmware — quietly skip */ });
  }

  function parseHistory(arrayBuf) {
    // Header (8 B): u16 head, u32 epoch, u16 count.  Samples: u16 mbar×10 (0 = empty).
    const view = new DataView(arrayBuf);
    if (arrayBuf.byteLength < 8) return;
    const head  = view.getUint16(0, true);
    const epoch = view.getUint32(2, true);
    const count = view.getUint16(6, true);
    if (count !== BARO_HISTORY_SIZE) return;
    if (arrayBuf.byteLength < 8 + count * 2) return;

    // Firmware stores samples circularly with `head` = next write slot. The newest sample
    // is at (head - 1) mod count; oldest unwritten slots are zero. Walk back chronologically.
    for (let i = 0; i < count; i++) {
      const ringIdx = (head - count + i + count) % count;
      const raw = view.getUint16(8 + ringIdx * 2, true);
      baroBuffer[i] = raw === 0 ? NaN : raw / 10.0;
    }
    baroBufferEpochAtEnd = epoch;
  }

  function lastFilledIdx() {
    for (let i = BARO_HISTORY_SIZE - 1; i >= 0; i--) if (isFinite(baroBuffer[i])) return i;
    return -1;
  }

  // ---------- PLOT ---------------------------------------------------------
  function buildBaroPlot() {
    const el = document.getElementById('baroPlot');
    if (!el || typeof uPlot === 'undefined') return;
    el.innerHTML = '';

    const accent = getCss('--accent') || '#00a19a';
    const ink    = getCss('--text-dark') || '#333';
    const slice  = computePlotSlice();

    const opts = {
      width: Math.max(el.clientWidth, 320),
      height: el.clientHeight || 280,
      series: [
        { label: 'Seconds ago' },
        { label: 'Pressure (mbar)', stroke: accent, width: 2, fill: hexAlpha(accent, 0.12) }
      ],
      scales: {
        x: { time: false, auto: false, range: [slice.xAxis[0], slice.xAxis[slice.xAxis.length - 1] || 0] },
        y: { auto: false, range: () => computeYRange() }
      },
      axes: [
        { label: 'Time', grid: { show: true }, values: (u, ticks) => ticks.map(formatAgoLabel) },
        { scale: 'y', label: 'mbar', grid: { show: true }, side: 3,
          splits: edgeLabeledSplits(() => baroYManual !== null) }
      ],
      legend: { show: false },
      cursor: { drag: { x: false, y: false } }
    };

    baroPlot = new uPlot(opts, [slice.xAxis, slice.values], el);
    new ResizeObserver(() => {
      if (baroPlot) baroPlot.setSize({ width: el.clientWidth, height: el.clientHeight || 280 });
    }).observe(el);

    // Click-to-edit Y limits. Typing pins the axis; the Autoscale checkbox below
    // the plot is the only way back to auto — no hidden clear-the-box gesture.
    attachYAxisEdit(baroPlot, [{
      scale: 'y', decimals: 0,
      apply: (mn, mx) => {
        baroYManual = [mn, mx];
        autoscaleY = false;                       // typing pins the axis and unchecks auto
        const cb = document.getElementById('baroAutoscaleY'); if (cb) cb.checked = false;
        localStorage.setItem('baroYManual', JSON.stringify(baroYManual));
        refreshPlot();
      }
    }]);
  }

  function refreshPlot() {
    const slice = computePlotSlice();
    baroPlot.setData([slice.xAxis, slice.values]);
    baroPlot.setScale('x', { min: slice.xAxis[0], max: slice.xAxis[slice.xAxis.length - 1] || 0 });
  }

  function computePlotSlice() {
    // X axis = seconds ago (negative). Newest sample is at x=0.
    const samples = currentRangeHours * 60 / SAMPLE_INTERVAL_MIN;
    const startIdx = Math.max(0, BARO_HISTORY_SIZE - samples);
    const xAxis = new Array(BARO_HISTORY_SIZE - startIdx);
    const values = new Array(BARO_HISTORY_SIZE - startIdx);
    for (let i = startIdx; i < BARO_HISTORY_SIZE; i++) {
      const ago = (BARO_HISTORY_SIZE - 1 - i) * SAMPLE_INTERVAL_MIN * 60;  // seconds
      const k = i - startIdx;
      xAxis[k]  = -ago;
      values[k] = isFinite(baroBuffer[i]) ? baroBuffer[i] : null;
    }
    return { xAxis, values };
  }

  function computeYRange() {
    if (baroYManual) return baroYManual;
    if (!autoscaleY) return [940, 1050];
    // Middle 2/3 of plot height: pad = 25% of data range above and below.
    const slice = computePlotSlice().values;
    let lo = Infinity, hi = -Infinity;
    for (const v of slice) { if (v != null) { if (v < lo) lo = v; if (v > hi) hi = v; } }
    if (!isFinite(lo) || !isFinite(hi) || lo >= hi) return [940, 1050];
    const range = Math.max(hi - lo, 2);
    const pad = range * 0.25;
    return [lo - pad, hi + pad];
  }

  function formatAgoLabel(secNeg) {
    const s = Math.abs(secNeg);
    if (s < 60) return 'now';
    if (s < 3600) return '−' + Math.round(s / 60) + 'm';
    const h = s / 3600;
    if (h < 24) return '−' + (h % 1 ? h.toFixed(1) : h.toFixed(0)) + 'h';
    const d = h / 24;
    return '−' + (d % 1 ? d.toFixed(1) : d.toFixed(0)) + 'd';
  }

  // ---------- ZAMBRETTI ----------------------------------------------------
  function zambretti(pressureMb, delta3h, windDirDeg, latDeg, dateObj) {
    let tendency;
    if (delta3h > 1.6)       tendency = 'rising';
    else if (delta3h < -1.6) tendency = 'falling';
    else                     tendency = 'steady';

    // Base index: 1050 mbar → slot 1 (best), 950 mbar → slot 26 (worst). Clamp.
    const p = Math.max(950, Math.min(1050, pressureMb));
    let Z = Math.round(((1050 - p) / 100) * 25) + 1;

    if (tendency === 'rising')  Z -= 5;
    if (tendency === 'falling') Z += 5;

    // Wind direction adjustment (NH; mirror N↔S for SH). Easterly winds in temperate latitudes
    // are associated with pre-frontal weather (worse Z); westerlies with post-frontal clearing.
    // Sector index from windDirDeg (FROM direction): 0=N, 1=NE, 2=E, 3=SE, 4=S, 5=SW, 6=W, 7=NW.
    const adj = [0, 1, 2, 1, -1, 0, -1, -2];
    const mirrorSH = [4, 3, 2, 1, 0, 7, 6, 5];
    const sector = Math.round((((windDirDeg % 360) + 360) % 360) / 45) % 8;
    Z += latDeg >= 0 ? adj[sector] : adj[mirrorSH[sector]];

    // Season adjustment — Zambretti was developed for temperate latitudes
    const month = dateObj.getMonth() + 1;
    const summerN = month >= 4 && month <= 9;
    const summer = latDeg >= 0 ? summerN : !summerN;
    if (summer && tendency === 'rising')  Z -= 2;
    if (summer && tendency === 'falling') Z += 1;

    Z = Math.max(1, Math.min(26, Z));
    return { Z, text: Z_FORECASTS[Z - 1], tendency };
  }

  // Fallback: UK Met Office Shipping Forecast wording, tendency-only.
  function fallbackForecast(p, d) {
    const a = Math.abs(d);
    const falling = d < -0.3, rising = d > 0.3, steady = !falling && !rising;
    const high = p > 1018, low = p < 1005;
    if (falling && a > 6 && low)    return 'Storm approaching — secure gear and reduce sail.';
    if (falling && a > 3.5)         return low
      ? 'Front passing — wind and rain likely within hours.'
      : 'Wind backing — rain likely within 12 h, reef early.';
    if (falling && a > 1.5)         return high
      ? 'Pressure easing — weather may turn, watch the sky.'
      : 'Unsettled spell developing — stow loose gear.';
    if (falling)                    return 'Slow decline — fair for now, watch the trend.';
    if (steady && high)             return 'Settled high — light winds, fair skies.';
    if (steady && low)              return 'Stalled low — unsettled, showers may persist.';
    if (steady)                     return 'No notable change — conditions should hold.';
    if (rising && a > 6)            return 'Sharp rise — gusty winds as the front clears.';
    if (rising && a > 3.5)          return low
      ? 'Clearing — winds easing, skies opening within hours.'
      : 'Building — fair weather strengthening, light to moderate breeze.';
    if (rising && a > 1.5)          return 'Improving — fair weather building over next 12 h.';
    return 'Slow recovery — trending toward fair.';
  }

  function tendencyLabel(delta) {
    const a = Math.abs(delta);
    const dir = delta > 0 ? 'Rising' : (delta < 0 ? 'Falling' : '');
    if (a < 0.1)  return 'Steady';
    if (a < 1.5)  return dir + ' slowly';
    if (a < 3.5)  return dir;
    if (a < 6)    return dir + ' quickly';
    return dir + ' very rapidly';
  }

  function pressureZone(p) {
    for (const z of ZONES) if (p < z.max) return z;
    return ZONES[ZONES.length - 1];
  }

  function makeTendencyArrow(delta) {
    const abs = Math.abs(delta);
    let rotation;
    if (abs < 0.1) rotation = 90;
    else {
      const steep = abs < 1.5 ? 60 : (abs < 3.5 ? 35 : (abs < 6 ? 18 : 6));
      rotation = delta > 0 ? steep : (180 - steep);
    }
    return `<svg viewBox="0 0 28 28" width="28" height="28">
      <g transform="rotate(${rotation} 14 14)">
        <line x1="14" y1="23" x2="14" y2="6" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"/>
        <path d="M 8 11 L 14 5 L 20 11" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/>
      </g>
    </svg>`;
  }

  function twdToCompass(deg) {
    const dirs = ['N','NE','E','SE','S','SW','W','NW'];
    return dirs[Math.round((((deg % 360) + 360) % 360) / 45) % 8];
  }

  // ---------- CONTROLS -----------------------------------------------------
  function wireControls() {
    const pills = document.querySelectorAll('#baroRangePills .sub-tab');
    pills.forEach(btn => btn.addEventListener('click', () => {
      pills.forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      currentRangeHours = parseInt(btn.dataset.range, 10);
      if (baroPlot) refreshPlot();
    }));
    const cb = document.getElementById('baroAutoscaleY');
    if (cb) cb.addEventListener('change', e => {
      autoscaleY = e.target.checked;
      baroYManual = null;                       // the checkbox always wins over a typed range
      localStorage.removeItem('baroYManual');
      if (baroPlot) refreshPlot();
    });
  }

  // ---------- HELPERS ------------------------------------------------------
  function setText(id, t) { const e = document.getElementById(id); if (e) e.textContent = t; }
  function setHTML(id, h) { const e = document.getElementById(id); if (e) e.innerHTML = h; }
  function getCss(name) { return getComputedStyle(document.documentElement).getPropertyValue(name).trim(); }
  function hexAlpha(hex, a) {
    if (!hex || !hex.startsWith('#')) return hex;
    const r = parseInt(hex.slice(1,3), 16), g = parseInt(hex.slice(3,5), 16), b = parseInt(hex.slice(5,7), 16);
    return `rgba(${r},${g},${b},${a})`;
  }
})();

// ========================================================================
// LONG TERM PLOTS — native render of the on-device month-long ring.
// Mirrors the barometer pattern: lazy fetch of a binary ring on tab open,
// parse header + records, derive each record's time from a single lastEpoch +
// ring position (no per-record timestamp), render with uPlot. Supabase data
// tier (older than the local ring) stitches in later. Public: initLongTermPlots().
// Record layout MUST match firmware LongTermRecord (116 B).
// ========================================================================
(function () {
  'use strict';

  let ltLoaded = false;   // session cache: fetch the ring once per session
  let ltData = null;      // { t:[], n, lastEpoch, interval, fields:{ key:{min,max,avg}|{avg} } }

  function getCss(name) { return getComputedStyle(document.documentElement).getPropertyValue(name).trim(); }
  function hexAlpha(hex, a) {
    if (!hex || !hex.startsWith('#')) return hex || '#888';
    const r = parseInt(hex.slice(1,3),16), g = parseInt(hex.slice(3,5),16), b = parseInt(hex.slice(5,7),16);
    return `rgba(${r},${g},${b},${a})`;
  }

  // Envelope fields in struct order with the scale divisor to reach real units.
  const ENV = [
    ['battVolt',100], ['battCurr',10], ['altCurr',10], ['victronCurr',10],
    ['rpm',1], ['duty',100], ['altTemp',10], ['tempTherm',10],
    ['sog',100], ['tws',100], ['vmg',100], ['aws',100],
    ['awa',10], ['twa',10], ['heel',100], ['pitch',100], ['soc',10]
  ];
  const AVG = [
    ['baro',10], ['ambTemp',10], ['cog',10], ['heading',10],
    ['leeway',10], ['altZero',100]
  ];

  // Only a genuine power-off should break the trace. Cadence jitter or a few missed
  // samples must NOT insert a gap-marker — ltBin nulls a whole bin that contains one,
  // so over-eager gaps blank the chart at low zoom. Break only on big gaps (≥ ~20 min).
  function ltGapThreshold(interval) { return Math.max((interval || 600) * 4, 1200); }

  // Header (16 B LE): u16 head, u16 count, u16 capacity, u16 recordSize,
  // u32 lastEpoch, u32 intervalSec. Then capacity × recordSize raw records.
  function parseLT(buf) {
    const dv = new DataView(buf);
    if (buf.byteLength < 16) return null;
    const head      = dv.getUint16(0, true);
    const count     = dv.getUint16(2, true);
    const capacity  = dv.getUint16(4, true);
    const recSize   = dv.getUint16(6, true);
    const lastEpoch = dv.getUint32(8, true);
    const interval  = dv.getUint32(12, true) || 600;   // seconds between records
    // Body is `count` records in chronological order (the endpoint no longer sends the
    // whole ring), so the buffer is 16 + count*recSize.
    if (!recSize || buf.byteLength < 16 + count * recSize) return null;

    const fields = {};
    ENV.forEach(([k]) => fields[k] = { min:[], max:[], avg:[] });
    AVG.forEach(([k]) => fields[k] = { avg:[] });
    const t = [], isGap = [], stage = [];
    // Synthetic null entry to break the line across a real time gap (power-off period).
    const pushGap = (gt) => {
      t.push(gt); isGap.push(true); stage.push(null);
      ENV.forEach(([k]) => { fields[k].min.push(null); fields[k].max.push(null); fields[k].avg.push(null); });
      AVG.forEach(([k]) => fields[k].avg.push(null));
    };

    // Record layout (132 B): u32 timestamp @0, i32 lat @4, i32 lon @8, u32 validMask @12,
    // envelope [min,max,avg]×17 from @16, avg-only ×6 after, u8 chargeStage + pad.
    // Records arrive in chronological order (oldest first), so read them linearly.
    let prevTs = null;
    for (let i = 0; i < count; i++) {
      const base = 16 + i * recSize;
      const tsRaw = dv.getUint32(base, true);
      const valid = dv.getUint32(base + 12, true);
      // Use the record's real timestamp (legit axis); fall back to position-derived if unsynced.
      const ts = tsRaw > 0 ? tsRaw : (lastEpoch ? lastEpoch - (count - 1 - i) * interval : i * interval);
      if (prevTs != null && (ts - prevTs) > ltGapThreshold(interval)) pushGap((prevTs + ts) / 2);  // gap → break
      prevTs = ts;

      t.push(ts); isGap.push(false);
      let off = base + 16;   // envelope block: [min,max,avg] int16 each
      ENV.forEach(([k, scale], fi) => {
        const f = fields[k];
        if (valid & (1 << fi)) {
          f.min.push(dv.getInt16(off, true) / scale);
          f.max.push(dv.getInt16(off + 2, true) / scale);
          f.avg.push(dv.getInt16(off + 4, true) / scale);
        } else { f.min.push(null); f.max.push(null); f.avg.push(null); }
        off += 6;
      });
      let ao = base + 16 + ENV.length * 6;   // avg-only block: one int16 each
      AVG.forEach(([k, scale], ai) => {
        fields[k].avg.push((valid & (1 << (ENV.length + ai))) ? dv.getInt16(ao, true) / scale : null);
        ao += 2;
      });
      // chargeStage u8 sits right after the avg-only block (display code 0-7).
      stage.push(dv.getUint8(base + 16 + ENV.length * 6 + AVG.length * 2));
    }
    return { t, n: t.length, lastEpoch, interval, fields, isGap, stage };
  }

  // Charge-stage palette — matches the live `.charge-stage-*` badge colors in styles.css.
  // Codes per firmware LongTermRecord.chargeStage: 1 bulk,2 absorption,3 float,4 manual,
  // 5 maintain,6 targetV,7 idle,8 commissioning (0 = off/none → bare track).
  const LT_STAGE_COLORS = { 1:'#00c853', 2:'#7e57c2', 3:'#ffb300', 4:'#ef5350', 5:'#66bb6a', 6:'#42a5f5', 7:'#78909c', 8:'#8d6e63' };
  const LT_STAGE_NAMES  = { 1:'Bulk', 2:'Absorption', 3:'Float', 4:'Manual', 5:'Maintain', 6:'Target V', 7:'Idle', 8:'Commissioning' };

  // ---- Decimation (ported from the cloud viewer's applyBinning) ----------------
  const LT_MAX_BINS = 120;   // matches the viewer's cap: ≤120 points drawn per chart
  const ltCharts = [];       // [{ id, plot, spec }] — built once, fed binned data
  let ltFullRange = null;    // [minSec, maxSec] of the whole ring
  let ltCurRange = null;     // [minSec, maxSec] currently rendered (for re-render after Y-axis edits)
  let ltRendering = false;   // re-entrancy guard so our setScale doesn't re-fire the zoom hook

  // Per-chart manual Y-axis overrides, persisted: { chartId: { scaleName: [min,max] } }.
  // Enforced every render in ltRenderAll; absent → that axis auto-fits to visible data.
  let ltYOverride = {};
  try { ltYOverride = JSON.parse(localStorage.getItem('lt_yaxis') || '{}') || {}; } catch (e) { ltYOverride = {}; }
  function ltSaveYOverride() { try { localStorage.setItem('lt_yaxis', JSON.stringify(ltYOverride)); } catch (e) {} }

  // Persist the long-term time-window CHOICE (re-anchored to newest data on reload, not an absolute range).
  let ltWindowPref = null;   // { hours: <n> } | { all: true } | null
  try { ltWindowPref = JSON.parse(localStorage.getItem('lt_window') || 'null'); } catch (e) { ltWindowPref = null; }
  function ltSaveWindowPref(p) { ltWindowPref = p; try { localStorage.setItem('lt_window', JSON.stringify(p)); } catch (e) {} }

  // Persist per-chart legend series visibility: { chartId: { seriesKey: true } } where true = hidden.
  let ltSeriesHidden = {};
  try { ltSeriesHidden = JSON.parse(localStorage.getItem('lt_series_hidden') || '{}') || {}; } catch (e) { ltSeriesHidden = {}; }
  function ltSaveSeriesHidden() { try { localStorage.setItem('lt_series_hidden', JSON.stringify(ltSeriesHidden)); } catch (e) {} }

  // Equal-width bins over [fromSec,toSec], capped at maxBins, ENVELOPE-PRESERVING:
  // bin min = min of mins, bin max = max of maxes, bin avg = avg of avgs (nulls skipped).
  // Re-run per visible range so zoomed views show finer detail with bounded point count.
  function ltBin(fromSec, toSec, maxBins) {
    const t = ltData.t, N = ltData.n;
    let lo = 0, hi = N;
    while (lo < N && t[lo] < fromSec) lo++;
    while (hi > lo && t[hi - 1] > toSec) hi--;
    const out = { t: [], fields: {} };
    ENV.forEach(([k]) => out.fields[k] = { min: [], max: [], avg: [] });
    AVG.forEach(([k]) => out.fields[k] = { avg: [] });
    const vis = hi - lo;
    if (vis <= 0) return out;
    const binSize = Math.max(1, Math.ceil(vis / maxBins));
    const ig = ltData.isGap || [];
    for (let i = lo; i < hi; i += binSize) {
      const end = Math.min(i + binSize, hi);
      out.t.push(t[i + ((end - i) >> 1)]);   // mid-bin timestamp
      // A bin spanning a gap marker is nulled wholesale → the line breaks there.
      let hasGap = false;
      for (let j = i; j < end; j++) if (ig[j]) { hasGap = true; break; }
      if (hasGap) {
        ENV.forEach(([k]) => { const o = out.fields[k]; o.min.push(null); o.max.push(null); o.avg.push(null); });
        AVG.forEach(([k]) => out.fields[k].avg.push(null));
        continue;
      }
      ENV.forEach(([k]) => {
        const f = ltData.fields[k], o = out.fields[k];
        let mn = Infinity, mx = -Infinity, sum = 0, cnt = 0;
        for (let j = i; j < end; j++) if (f.avg[j] != null) {
          const lo = f.min[j], hi = f.max[j];
          if (lo != null && lo < mn) mn = lo;   // skip null min/max (sentinel-cleaned cloud rows)
          if (hi != null && hi > mx) mx = hi;    // so Infinity never leaks into the band → uPlot scale
          sum += f.avg[j]; cnt++;
        }
        o.avg.push(cnt ? sum / cnt : null);
        o.min.push(isFinite(mn) ? mn : null);    // finite-or-null only
        o.max.push(isFinite(mx) ? mx : null);
      });
      AVG.forEach(([k]) => {
        const f = ltData.fields[k], o = out.fields[k];
        let sum = 0, cnt = 0;
        for (let j = i; j < end; j++) if (f.avg[j] != null) { sum += f.avg[j]; cnt++; }
        o.avg.push(cnt ? sum / cnt : null);
      });
    }
    return out;
  }

  // Keep compass/wind angles continuous so a 360→0 wrap doesn't draw a vertical crash.
  function unwrapAngles(arr) {
    const out = []; let prev = null;
    for (const v of arr) {
      if (v == null) { out.push(null); prev = null; continue; }
      let x = v;
      if (prev != null) { while (x - prev > 180) x -= 360; while (x - prev < -180) x += 360; }
      out.push(x); prev = x;
    }
    return out;
  }

  // Re-bin the ring to [fromSec,toSec] and push to every chart (synced X; Y auto-fits to
  // the visible binned data). The guard stops our setScale from re-triggering the hook.
  function ltRenderAll(fromSec, toSec) {
    if (!ltData || !ltCharts.length) return;
    // A zero/negative-width x-range makes uPlot null out its scales and draw nothing.
    if (!(toSec > fromSec)) { const c = fromSec; fromSec = c - 1800; toSec = c + 1800; }
    ltRendering = true;
    ltCurRange = [fromSec, toSec];
    const b = ltBin(fromSec, toSec, LT_MAX_BINS);
    ltCharts.forEach(c => {
      const data = [ b.t ];
      const scaleVals = {};   // scaleName → arrays feeding that scale (for explicit range calc)
      c.spec.series.forEach(s => {
        const f = b.fields[s.key];
        const avg = s.unwrap ? unwrapAngles(f.avg) : f.avg;
        data.push(avg);
        (scaleVals[s.scale] = scaleVals[s.scale] || []).push(avg);
        if (s.band) { data.push(f.max); data.push(f.min); scaleVals[s.scale].push(f.max, f.min); }
      });
      c.plot.setData(data);          // rebuilds series paths (auto-scale may null out; we override below)
      c.plot.setScale('x', { min: fromSec, max: toSec });
      // Set every Y-scale EXPLICITLY from the visible data. uPlot's own auto-range was
      // intermittently leaving scales null (→ nothing drawn), so we compute min/max here.
      const ov = ltYOverride[c.id] || {};
      c.spec.scales.forEach(sc => {
        if (ov[sc.name]) { c.plot.setScale(sc.name, { min: ov[sc.name][0], max: ov[sc.name][1] }); return; }
        if (sc.range) { c.plot.setScale(sc.name, { min: sc.range[0], max: sc.range[1] }); return; }  // fixed (e.g. SOC 0-100)
        let mn = Infinity, mx = -Infinity;
        (scaleVals[sc.name] || []).forEach(arr => { for (const v of arr) { if (v != null && isFinite(v)) { if (v < mn) mn = v; if (v > mx) mx = v; } } });
        if (isFinite(mn) && isFinite(mx)) {
          if (mn === mx) { mn -= 1; mx += 1; }
          const pad = (mx - mn) * 0.05;
          c.plot.setScale(sc.name, { min: mn - pad, max: mx + pad });
        }
      });
    });
    ltRendering = false;
    ltDrawStageBar();   // repaint the charge-stage strip over the same range
    // Reflect the rendered range back onto the brush selection (keeps the brush in sync
    // whether the range came from the brush itself or from a chart drag-zoom).
    if (_brushState && _brushState.nativeSink) {
      _brushState.from = fromSec * 1000; _brushState.to = toSec * 1000;
      if (typeof _brushUpdateSelectionUI === 'function') _brushUpdateSelectionUI();
    }
    ltCloudMaybePull(fromSec);   // brushed past the loaded edge → stitch in older cloud data
  }
  const ltZoomDebounced = debounce((min, max) => { if (min != null && max != null) ltRenderAll(min, max); }, 120);

  // Hand the relocated dashboard-brush its data bounds + a sink into ltRenderAll, wire
  // it once, and show it. Brush works in ms; ltRenderAll in seconds.
  function ltInitBrush(minSec, maxSec, latestSec) {
    if (typeof _brushState === 'undefined' || !_brushState) return;
    _brushState.nativeSink = (fromMs, toMs) => ltRenderAll(fromMs / 1000, toMs / 1000);
    _brushState.ltSaveWindowPref = ltSaveWindowPref;   // bridge: snap handler is top-level, can't see the IIFE-private fn
    _brushState.dataMin = minSec * 1000;
    _brushState.dataMax = maxSec * 1000;
    _brushState.latestSample = (latestSec || maxSec) * 1000;
    _brushState.from = _brushState.dataMin;
    _brushState.to = _brushState.dataMax;
    if (!_brushState.wired) { _brushWireDrag(); _brushWireSnap(); _brushState.wired = true; }
    const bEl = document.getElementById('dashboard-brush'); if (bEl) bEl.style.display = 'block';
    const mn = document.getElementById('dashboard-brush-data-min'); if (mn) mn.textContent = _brushFormatTime(_brushState.dataMin);
    const mx = document.getElementById('dashboard-brush-data-max'); if (mx) mx.textContent = _brushFormatTime(_brushState.dataMax);
    // Cadence note in the sticky brush bar — true rate from the .bin header, not a hardcode
    const sn = document.getElementById('dashboard-sample-note');
    if (sn && ltData && ltData.interval) sn.textContent = 'Sampled every ' + Math.round(ltData.interval / 60) + ' min';
    _brushUpdateSelectionUI();
    // Re-anchored restore: apply the saved window choice relative to the NEWEST data, not an absolute old range.
    if (ltWindowPref) {
      let from = _brushState.dataMin, to = _brushState.dataMax;
      if (ltWindowPref.hours) {
        const t = Math.min(_brushState.dataMax, Date.now());
        from = Math.max(_brushState.dataMin, t - ltWindowPref.hours * 3600 * 1000);
        to = t;
      }
      // Reflect the active snap button visually if one matches the saved choice.
      try {
        document.querySelectorAll('.dashboard-brush-snap-btn').forEach(b => {
          const isAll = b.getAttribute('data-all') === 'true';
          const h = parseInt(b.getAttribute('data-hours'), 10);
          const match = ltWindowPref.all ? isAll : (isFinite(h) && h === ltWindowPref.hours);
          if (match) b.classList.add('active');
        });
      } catch (e) {}
      _brushApplyRange(from, to);   // same path the snap buttons use → drives ltRenderAll
    }
    _brushUpdateStaleness();
    if (_brushState.stalenessTimerId == null) {
      _brushState.stalenessTimerId = (typeof setTrackedInterval === 'function' ? setTrackedInterval : setInterval)(_brushUpdateStaleness, 10000);
    }
    // Freshness banner shares a tracked timer (5 s so the countdown isn't too jumpy).
    ltUpdateFreshness();
    if (_ltFreshTimerId == null) {
      _ltFreshTimerId = (typeof setTrackedInterval === 'function' ? setTrackedInterval : setInterval)(ltUpdateFreshness, 5000);
    }
    const clr = document.getElementById('dashboard-crosshair-clear');
    if (clr && !clr._ltWired) { clr._ltWired = true; clr.addEventListener('click', () => { ltPinnedTime = null; ltRedrawMarkers(); ltUpdateCrosshairIndicator(); }); }
  }

  // ---- Markers: live-edge "now" line + a tap-to-pin crosshair synced across charts ----
  let ltPinnedTime = null;   // pinned crosshair time (sec); null = none
  function ltDrawMarkers(u) {
    const ctx = u.ctx, xmin = u.scales.x.min, xmax = u.scales.x.max;
    const vline = (tSec, color, dash) => {
      if (tSec == null || !isFinite(tSec) || tSec < xmin || tSec > xmax) return;
      const x = Math.round(u.valToPos(tSec, 'x', true)) + 0.5;
      ctx.save();
      ctx.strokeStyle = color; ctx.lineWidth = 1; ctx.setLineDash(dash);
      ctx.beginPath(); ctx.moveTo(x, u.bbox.top); ctx.lineTo(x, u.bbox.top + u.bbox.height); ctx.stroke();
      ctx.restore();
    };
    vline(Math.floor(Date.now() / 1000), 'rgba(244,67,54,0.55)', [4, 3]);   // live edge "now"
    vline(ltPinnedTime, 'rgba(60,60,60,0.85)', []);                          // pinned crosshair
  }
  function ltRedrawMarkers() { ltCharts.forEach(c => { try { c.plot.redraw(false); } catch (e) {} }); }
  function ltUpdateCrosshairIndicator() {
    const ind = document.getElementById('dashboard-crosshair-indicator');
    const txt = document.getElementById('dashboard-crosshair-time');
    if (!ind || !txt) return;
    if (ltPinnedTime == null) { ind.style.display = 'none'; txt.textContent = '—'; }
    else { ind.style.display = 'inline-block'; txt.textContent = (typeof _brushFormatTime === 'function') ? _brushFormatTime(ltPinnedTime * 1000) : new Date(ltPinnedTime * 1000).toLocaleString(); }
  }

  // Build one chart ONCE (empty); ltRenderAll feeds it binned data. drag-x zoom →
  // re-bins ALL charts (synced); dbl-click resets the range; click pins a crosshair.
  // Bottom legend shows live values at the cursor (setCursor hook).
  function buildLtChart(id, spec) {
    const el = document.getElementById(id);
    if (!el || typeof uPlot === 'undefined') return;
    el.innerHTML = '';
    const series = [ { label: 'Time' } ], bands = [], initData = [ [] ], avgIdx = [];
    const seriesGroups = [];   // per spec-series: uPlot series indices (avg + band edges) to toggle together
    let di = 1;
    spec.series.forEach(s => {
      const group = [di];
      avgIdx.push(di);
      series.push({ label: s.label, scale: s.scale, stroke: s.color, width: 2, points: { show: false }, spanGaps: false });
      initData.push([]); di++;
      if (s.band) {
        const maxIdx = series.length; series.push({ scale: s.scale, stroke: 'transparent', width: 0, points: { show: false } });
        const minIdx = series.length; series.push({ scale: s.scale, stroke: 'transparent', width: 0, points: { show: false } });
        bands.push({ series: [maxIdx, minIdx], fill: hexAlpha(s.color, 0.14) });
        initData.push([]); initData.push([]); di += 2;
        group.push(maxIdx, minIdx);
      }
      seriesGroups.push(group);
    });
    const scales = { x: { time: true } };
    const axes = [ { grid: { show: true } } ];
    spec.scales.forEach(sc => {
      scales[sc.name] = sc.range ? { auto: false, range: sc.range } : { auto: true };
      axes.push({ scale: sc.name, label: sc.label, side: sc.side, grid: { show: sc.side === 3 },
                  splits: edgeLabeledSplits(() => !!(ltYOverride[id] && ltYOverride[id][sc.name])),
                  values: sc.fmt ? (u, ticks) => ticks.map(sc.fmt) : undefined });
    });
    // Keep the X-axis time ticks lined up across every stacked chart. uPlot reserves a
    // right-hand gutter (~size 50 + labelSize 30 = 80px) for any secondary (side:1) axis.
    // Charts with only a left axis (Currents, Speeds, Angles, Motion) would otherwise
    // extend their plot area that 80px further right and their shared X scale would not
    // match the charts that DO have a secondary axis (Voltage&SOC, Temp&Baro, RPM&Duty).
    // Reserve an identical but invisible right gutter on single-axis charts to match.
    if (!spec.scales.some(sc => sc.side === 1)) {
      axes.push({ scale: spec.scales[0].name, side: 1, label: '',
                  grid: { show: false }, ticks: { show: false },
                  values: (u, ticks) => ticks.map(() => '') });
    }

    // Bottom legend with live value readouts (filled by the setCursor hook on hover).
    const legendEl = document.createElement('div');
    legendEl.style.cssText = 'display:flex;justify-content:center;gap:14px;flex-wrap:wrap;margin-top:8px;font-size:12px;';
    const valSpans = [];
    spec.series.forEach((s, i) => {
      const item = document.createElement('span');
      item.style.cssText = 'display:inline-flex;align-items:center;gap:5px;cursor:pointer;user-select:none;';
      item.title = 'Click to show/hide';
      const sw = document.createElement('span');
      sw.style.cssText = 'width:11px;height:11px;border-radius:2px;display:inline-block;background:' + s.color + ';';
      const val = document.createElement('b');
      item.appendChild(sw); item.appendChild(document.createTextNode(s.label + ': ')); item.appendChild(val);
      // Click the legend item to toggle that series (and its envelope band) on/off.
      item.addEventListener('click', () => {
        const show = !plot.series[seriesGroups[i][0]].show;
        seriesGroups[i].forEach(idx => plot.setSeries(idx, { show }));
        item.style.opacity = show ? '1' : '0.4';
        // Persist visibility by stable series key (true = hidden).
        ltSeriesHidden[id] = ltSeriesHidden[id] || {};
        if (show) delete ltSeriesHidden[id][s.key]; else ltSeriesHidden[id][s.key] = true;
        ltSaveSeriesHidden();
      });
      // Restore persisted visibility (keyed by series key). Dim the legend item now;
      // the matching plot.setSeries() runs after the plot is created (see below).
      if (ltSeriesHidden[id] && ltSeriesHidden[id][s.key]) {
        item.style.opacity = '0.4';
      }
      legendEl.appendChild(item);
      valSpans.push(val);
    });

    const opts = {
      title: spec.title, width: Math.max(el.clientWidth, 320), height: 300,
      series, scales, axes, bands, legend: { show: false },
      cursor: { sync: { key: 'ltsync' }, y: false, drag: { x: true, y: false } },   // x crosshair synced across charts; no horizontal y line
      hooks: {
        setScale: [ (u, key) => { if (key === 'x' && !ltRendering) { const sx = u.scales.x; ltZoomDebounced(sx.min, sx.max); } } ],
        setCursor: [ (u) => {
          const idx = u.cursor.idx;
          for (let i = 0; i < valSpans.length; i++) {
            const arr = u.data[avgIdx[i]];
            const v = (idx != null && arr) ? arr[idx] : null;
            valSpans[i].textContent = (v == null) ? '—' : v.toFixed(Math.abs(v) >= 100 ? 0 : 1);
          }
        } ],
        draw: [ (u) => ltDrawMarkers(u) ]
      }
    };
    const plot = new uPlot(opts, initData, el);
    el.appendChild(legendEl);
    ltCharts.push({ id, plot, spec });

    // Apply persisted legend hides now that the plot exists (opacity was set in the loop above).
    if (ltSeriesHidden[id]) {
      spec.series.forEach((s, i) => {
        if (ltSeriesHidden[id][s.key]) seriesGroups[i].forEach(idx => plot.setSeries(idx, { show: false }));
      });
    }

    // Y-axis controls: per-scale manual Min/Max + Apply + Auto (reset). Persisted; absent
    // → that axis auto-fits to the visible binned data (enforced in ltRenderAll).
    const ctrl = document.createElement('div');
    ctrl.style.cssText = 'display:flex;justify-content:center;align-items:center;gap:8px;flex-wrap:wrap;margin-top:4px;font-size:11px;color:#888;';
    ctrl.appendChild(document.createTextNode('Y-axis:'));
    const saved = ltYOverride[id] || {};
    const inputs = {};
    spec.scales.forEach(sc => {
      const wrap = document.createElement('span');
      wrap.style.cssText = 'display:inline-flex;align-items:center;gap:3px;';
      const lbl = document.createElement('span'); lbl.textContent = sc.label;
      const mn = document.createElement('input'); mn.type = 'number'; mn.placeholder = 'min'; mn.style.width = '70px';
      const mx = document.createElement('input'); mx.type = 'number'; mx.placeholder = 'max'; mx.style.width = '70px';
      if (saved[sc.name]) { mn.value = saved[sc.name][0]; mx.value = saved[sc.name][1]; }
      wrap.appendChild(lbl); wrap.appendChild(mn); wrap.appendChild(mx);
      ctrl.appendChild(wrap);
      inputs[sc.name] = { mn, mx };
    });
    const applyBtn = document.createElement('button'); applyBtn.textContent = 'Apply'; applyBtn.className = 'dashboard-brush-snap-btn';
    const resetBtn = document.createElement('button'); resetBtn.textContent = '⤢ Auto'; resetBtn.className = 'dashboard-brush-snap-btn';
    applyBtn.addEventListener('click', () => {
      const ov = {};
      spec.scales.forEach(sc => {
        const a = parseFloat(inputs[sc.name].mn.value), b2 = parseFloat(inputs[sc.name].mx.value);
        if (isFinite(a) && isFinite(b2) && b2 > a) ov[sc.name] = [a, b2];
      });
      if (Object.keys(ov).length) ltYOverride[id] = ov; else delete ltYOverride[id];
      ltSaveYOverride();
      if (ltCurRange) ltRenderAll(ltCurRange[0], ltCurRange[1]);
    });
    resetBtn.addEventListener('click', () => {
      delete ltYOverride[id];
      spec.scales.forEach(sc => { inputs[sc.name].mn.value = ''; inputs[sc.name].mx.value = ''; });
      ltSaveYOverride();
      if (ltCurRange) ltRenderAll(ltCurRange[0], ltCurRange[1]);
    });
    ctrl.appendChild(applyBtn); ctrl.appendChild(resetBtn);
    el.appendChild(ctrl);

    // On-plot Y boxes mirror the Min/Max fields above — same persistence path
    // (clear both boxes + Enter returns that axis to auto-fit).
    attachYAxisEdit(plot, spec.scales.map(sc => ({
      scale: sc.name,
      apply: (mn, mx) => { inputs[sc.name].mn.value = mn; inputs[sc.name].mx.value = mx; applyBtn.click(); },
      auto: () => { inputs[sc.name].mn.value = ''; inputs[sc.name].mx.value = ''; applyBtn.click(); }
    })));

    if (document.body.classList.contains('dark-mode') && typeof updateUplotTheme === 'function') updateUplotTheme(plot);
    plot.over.addEventListener('click', () => {   // tap to pin a crosshair time across all charts
      const idx = plot.cursor.idx;
      if (idx != null && plot.data[0]) { ltPinnedTime = plot.data[0][idx]; ltRedrawMarkers(); ltUpdateCrosshairIndicator(); }
    });
    el.addEventListener('dblclick', () => { if (ltFullRange) ltRenderAll(ltFullRange[0], ltFullRange[1]); });
    if (!el._ltRO) {
      el._ltRO = new ResizeObserver(debounce(() => plot.setSize({ width: el.clientWidth, height: 300 }), 500));
      el._ltRO.observe(el);
    }
  }

  function buildAllLtPlots() {
    if (!ltCharts.length) {
    // Groupings mirror the cloud "My History" viewer minus the eliminated fields
    // (u_target_amps, temp_margin, ign_duty, eng_duty). Every envelope-recorded field
    // gets band:true; line-only series (Board temp, Baro, COG, Heading, Leeway)
    // are avg-only in the 132 B record itself, so a band would need a record-layout
    // change. heel/pitch (Motion) is a local-only bonus.
    buildLtChart('lt-current-plot', {
      title: 'Currents (A)',
      scales: [ { name:'A', label:'Amps', side:3 } ],
      series: [ { key:'battCurr',    scale:'A', color:'#FF9800', label:'Battery (A)',       band:true },
                { key:'altCurr',     scale:'A', color:'#4CAF50', label:'Alternator (A)',    band:true },
                { key:'victronCurr', scale:'A', color:'#2196F3', label:'Victron/Solar (A)', band:true } ]
    });
    buildLtChart('lt-voltage-plot', {
      title: 'Battery Voltage & SOC',
      scales: [ { name:'V', label:'Volts', side:3 },
                { name:'pct', label:'SOC %', side:1, range:[0,100], fmt:v=>Math.round(v)+'%' } ],
      series: [ { key:'battVolt', scale:'V', color:'#4CAF50', label:'Battery (V)', band:true },
                { key:'soc', scale:'pct', color:'#2196F3', label:'SOC (%)', band:true } ]
    });
    buildLtChart('lt-temp-plot', {
      title: 'Temperatures & Barometric Pressure',
      scales: [ { name:'F', label:'°F', side:3 },
                { name:'mb', label:'mbar', side:1 } ],
      series: [ { key:'altTemp',   scale:'F',  color:'#F44336', label:'Alternator (°F)', band:true },
                { key:'tempTherm', scale:'F',  color:'#FF9800', label:'Thermistor (°F)', band:true },
                { key:'ambTemp',   scale:'F',  color:'#2196F3', label:'Board (°F)' },
                { key:'baro',      scale:'mb', color:'#9C27B0', label:'Baro (mbar)' } ]
    });
    buildLtChart('lt-rpm-plot', {
      title: 'Engine RPM & Alternator Duty',
      scales: [ { name:'rpm', label:'RPM', side:3 },
                { name:'pct', label:'Duty %', side:1, range:[0,100], fmt:v=>Math.round(v)+'%' } ],
      series: [ { key:'rpm',  scale:'rpm', color:'#9C27B0', label:'RPM', band:true },
                { key:'duty', scale:'pct', color:'#9E9E9E', label:'Duty (%)', band:true } ]
    });
    buildLtChart('lt-wind-plot', {
      title: 'Speeds (kt)',
      scales: [ { name:'kt', label:'Knots', side:3 } ],
      series: [ { key:'sog', scale:'kt', color:'#4CAF50', label:'SOG (kt)',        band:true },
                { key:'tws', scale:'kt', color:'#2196F3', label:'True Wind (kt)',  band:true },
                { key:'vmg', scale:'kt', color:'#9C27B0', label:'VMG (kt)',        band:true },
                { key:'aws', scale:'kt', color:'#00BCD4', label:'App. Wind (kt)',  band:true } ]
    });
    buildLtChart('lt-angles-plot', {
      title: 'Angles (°)',
      scales: [ { name:'deg', label:'Degrees', side:3 } ],
      series: [ { key:'cog',     scale:'deg', color:'#2196F3', label:'COG (°)',     unwrap:true },
                { key:'heading', scale:'deg', color:'#FF9800', label:'Heading (°)', unwrap:true },
                { key:'awa',     scale:'deg', color:'#4CAF50', label:'AWA (°)',  band:true },
                { key:'twa',     scale:'deg', color:'#E91E63', label:'TWA (°)',  band:true },
                { key:'leeway',  scale:'deg', color:'#00BCD4', label:'Leeway (°)' } ]
    });
    buildLtChart('lt-motion-plot', {
      title: 'Motion — Heel & Pitch (°)',
      scales: [ { name:'deg', label:'Degrees', side:3 } ],
      series: [ { key:'heel',  scale:'deg', color:'#3F51B5', label:'Heel (°)',  band:true },
                { key:'pitch', scale:'deg', color:'#FF5722', label:'Pitch (°)', band:true } ]
    });
    ltBuildStageLegend();

    }
    // When the local ring holds little (< ~1h span — always true right after an OTA
    // reboot until the field-off dump persists it), lean on cloud: anchor the view to the
    // last 24h and auto-pull cloud history. Otherwise show the full local span.
    const nowSec = Math.floor(Date.now() / 1000);
    const localSpan = (ltData.n >= 2) ? (ltData.t[ltData.n - 1] - ltData.t[0]) : 0;
    const sparse = localSpan < 3600;
    const oldestBoundary = (ltData.n > 0) ? ltData.t[0] : nowSec;   // cloud fills below this
    const loSec = sparse ? (nowSec - 86400) : ltData.t[0];
    const hiSec = sparse ? nowSec : ltData.t[ltData.n - 1];
    ltFullRange = [loSec, hiSec];
    // Order matters: brush (sets nativeSink) → cloud state (reach) → render. The render's
    // ltCloudMaybePull then fires exactly ONE pull (loSec < oldest in the sparse case).
    ltInitBrush(loSec, hiSec, sparse ? nowSec : (ltData.lastEpoch || hiSec));
    ltCloudInit(oldestBoundary);
    ltRenderAll(loSec, hiSec);
    // Force each chart to its real container width + repaint. Charts can get stuck at
    // the 320px fallback if first built before the sub-tab had laid out; the per-chart
    // ResizeObserver never corrects it because `el` itself doesn't change size. Run on
    // every open (idempotent) so a reopen also fixes any stale narrow sizing.
    requestAnimationFrame(() => requestAnimationFrame(ltResizeAll));
    setTimeout(ltResizeAll, 250);   // fallback for late layout (card width applied after activate)
  }

  function ltResizeAll() {
    ltCharts.forEach(c => {
      const el = document.getElementById(c.id);
      if (!el) return;
      // Size to the parent CARD's content width, not the .plot-container's — uPlot's root
      // is `width: min-content`, so the container collapses to ~the canvas width (e.g. 324px)
      // and reading it just re-pins the narrow size. The card is a full-width block.
      const card = el.closest('.settings-card');
      const w = Math.floor((card ? card.clientWidth : el.clientWidth)) - 22;  // minus card padding
      if (w > 50) c.plot.setSize({ width: w, height: 300 });
    });
    ltDrawStageBar();   // chart widths/x-gutter just changed → realign the stage strip
  }

  // Fill the charge-stage legend once (swatch + label per code) from the shared palette.
  function ltBuildStageLegend() {
    const el = document.getElementById('lt-stage-legend');
    if (!el || el.childElementCount) return;
    Object.keys(LT_STAGE_NAMES).forEach(code => {
      const item = document.createElement('span');
      item.style.cssText = 'display:inline-flex;align-items:center;gap:4px;';
      const sw = document.createElement('span');
      sw.style.cssText = 'width:11px;height:11px;border-radius:2px;display:inline-block;background:' + LT_STAGE_COLORS[code] + ';';
      item.appendChild(sw); item.appendChild(document.createTextNode(LT_STAGE_NAMES[code]));
      el.appendChild(item);
    });
    // Bare-track entry: the strip leaves stage 0 (field not active) and no-data gaps unpainted,
    // so its swatch uses the same rgba(128,128,128,0.15) fill as the track (+ faint border so the
    // near-transparent swatch is still findable). No causal claim — not "engine off".
    const off = document.createElement('span');
    off.style.cssText = 'display:inline-flex;align-items:center;gap:4px;';
    const osw = document.createElement('span');
    osw.style.cssText = 'width:11px;height:11px;border-radius:2px;display:inline-block;background:rgba(128,128,128,0.15);border:1px solid rgba(128,128,128,0.35);';
    off.appendChild(osw); off.appendChild(document.createTextNode('Not Charging'));
    el.appendChild(off);
  }

  // Paint the charge-stage strip over the currently-rendered range. One bar (not per-chart
  // shading); its painted region is x-aligned to a reference chart's plot area so it sits
  // under the curves, past the y-axis gutter. Stage 0/off and gaps are left as bare track.
  function ltDrawStageBar() {
    const cv = document.getElementById('lt-stage-bar');
    if (!cv || !ltData || !ltData.stage || !ltCurRange) return;
    const fromSec = ltCurRange[0], toSec = ltCurRange[1];
    const card = cv.closest('.settings-card');
    const cssW = Math.max((card ? card.clientWidth : cv.clientWidth) - 22, 50);
    const cssH = 18, dpr = window.devicePixelRatio || 1;
    cv.style.width = cssW + 'px'; cv.style.height = cssH + 'px';
    cv.width = Math.round(cssW * dpr); cv.height = Math.round(cssH * dpr);
    const ctx = cv.getContext('2d');
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, cssW, cssH);
    // Align the painted span to a reference chart's plotting area (uPlot adds a y-axis gutter).
    let x0 = 0, x1 = cssW;
    const ref = ltCharts.length ? ltCharts[0].plot : null;
    if (ref && ref.over) {
      const oRect = ref.over.getBoundingClientRect(), cRect = cv.getBoundingClientRect();
      const a = oRect.left - cRect.left, b = oRect.right - cRect.left;
      if (b > a && a >= -2 && b <= cssW + 2) { x0 = Math.max(a, 0); x1 = Math.min(b, cssW); }
    }
    const span = (toSec - fromSec) || 1;
    ctx.fillStyle = 'rgba(128,128,128,0.15)';   // bare track behind everything
    ctx.fillRect(x0, 0, x1 - x0, cssH);
    // Per-pixel DOMINANT stage (no binning, never microscopic): accumulate each stage run's
    // time-overlap into the pixel column(s) it covers, then paint each column the stage that
    // held it longest. Stage 0/off (and no-data) winning a column → bare track. Zooming in
    // shrinks each column's time slice, so short stages emerge instead of aliasing at zoom-out.
    const t = ltData.t, st = ltData.stage, ig = ltData.isGap || [], N = ltData.n;
    const interval = ltData.interval || 600;
    const W = x1 - x0, pxN = Math.max(1, Math.round(W));
    const acc = new Float32Array(pxN * 8);   // [pixel*8 + stageCode] → accumulated width (∝ time)
    let i = 0;
    while (i < N) {
      if (ig[i] || st[i] == null) { i++; continue; }
      const s = st[i];
      let j = i;   // merge consecutive same-stage records to cover many columns in one pass
      while (j + 1 < N && !ig[j + 1] && st[j + 1] === s) j++;
      let segStart = t[i], segEnd = (j + 1 < N) ? t[j + 1] : t[j] + interval;
      i = j + 1;
      if (s < 0 || s > 7 || segEnd <= fromSec || segStart >= toSec) continue;
      if (segStart < fromSec) segStart = fromSec;
      if (segEnd > toSec) segEnd = toSec;
      const pa = (segStart - fromSec) / span * W, pb = (segEnd - fromSec) / span * W;
      const p0 = Math.max(0, Math.floor(pa)), p1 = Math.min(pxN - 1, Math.ceil(pb) - 1);
      for (let p = p0; p <= p1; p++) {
        const lo = Math.max(pa, p), hi = Math.min(pb, p + 1);
        if (hi > lo) acc[p * 8 + s] += (hi - lo);
      }
    }
    const dom = new Uint8Array(pxN);   // dominant stage per column (0 = off/no-data → track)
    for (let p = 0; p < pxN; p++) {
      let best = 0, bestV = 0;
      for (let sc = 0; sc <= 7; sc++) { const v = acc[p * 8 + sc]; if (v > bestV) { bestV = v; best = sc; } }
      dom[p] = bestV > 0 ? best : 0;
    }
    let p = 0;   // merge adjacent same-stage columns into one rect (no internal seams)
    while (p < pxN) {
      const d = dom[p];
      if (d < 1 || !LT_STAGE_COLORS[d]) { p++; continue; }
      let q = p; while (q + 1 < pxN && dom[q + 1] === d) q++;
      ctx.fillStyle = LT_STAGE_COLORS[d];
      ctx.fillRect(x0 + p, 0, q - p + 1, cssH);
      p = q + 1;
    }
  }

  function ltStatus(msg) {
    const status = document.getElementById('longterm-status');
    if (!status) return;
    const card = status.closest('.settings-card') || status;
    if (msg) { status.textContent = msg; card.style.display = ''; }
    else { card.style.display = 'none'; }   // hide the whole card, not just the text
  }

  // Freshness banner. Long-term points are min/max/avg ENVELOPES the firmware commits once
  // per closing window (ltData.interval — ~10 min in production), NOT instant writes — so the
  // newest point lags live by up to one interval. This is the averaging window, not slow
  // PSRAM. Banner shows the countdown to the next averaged point, and once that point is due
  // (the device should have committed it) flips to a one-tap Refresh that re-pulls the ring.
  let _ltFreshTimerId = null;
  function ltUpdateFreshness() {
    const banner = document.getElementById('lt-freshness-banner');
    if (!banner) return;
    // Need loaded data with a real epoch (unsynced clock → lastEpoch 0 → nothing to count from).
    if (!ltLoaded || !ltData || !ltData.n || !ltData.lastEpoch) { banner.style.display = 'none'; return; }
    const interval = ltData.interval || 600;             // seconds between committed points
    const nowSec   = Math.floor(Date.now() / 1000);
    const dueIn    = ltData.lastEpoch + interval - nowSec; // seconds until the next point commits
    const mins     = Math.max(1, Math.round(interval / 60));
    if (dueIn > 0) {                                       // up to date — show the countdown
      const m = Math.floor(dueIn / 60), s = dueIn % 60;
      const cd = m > 0 ? (m + 'm ' + s + 's') : (s + 's');
      banner.className = 'settings-card lt-fresh-ok';
      banner.innerHTML = 'Up to date — points are ' + mins +
        '-min averaged envelopes. Next point in <strong>' + cd + '</strong>.';
      banner.style.display = '';
    } else if (dueIn > -interval) {                        // overdue by < one interval → new point ready
      banner.className = 'settings-card lt-fresh-pending';
      banner.innerHTML = '<strong>New data pending</strong> — a fresh ' + mins +
        '-min averaged point is ready on the device. ' +
        '<button class="btn btn-sm btn-primary" id="lt-fresh-refresh" style="margin-left:8px;">Refresh</button>';
      const btn = document.getElementById('lt-fresh-refresh');
      if (btn) btn.onclick = () => { if (typeof window.initLongTermPlots === 'function') window.initLongTermPlots(); };
      banner.style.display = '';
    } else {
      // Overdue by more than a full interval = the device hasn't been logging (engine/board off).
      // That's staleness, not a pending write — the brush-bar "Last data: X ago" already shows it.
      banner.style.display = 'none';
    }
  }

  // ======================================================================
  // CLOUD STITCH — history older than the local ring (LOCAL_DATA_SYSTEMS_PLAN 1b).
  // Lazy + cloud-gated: when Cloud Features is on and the device is registered,
  // brushing past the oldest local record pulls a matching 10-min min/max/avg
  // aggregate from Supabase (get-history, date-range) and PREPENDS it into ltData,
  // so it renders as one continuous band+line across the SAME 7 charts. Pulled in
  // 30-day chunks, each older than the last; reaching the loaded edge opens + fetches
  // the next chunk. When cloud is off/unregistered the pre-ring region simply stays
  // empty (one-line hint), never an error, and the in-ring month is never greyed.
  // ======================================================================
  const LT_CLOUD_CHUNK_S        = 30 * 86400;    // pull 30 days of older history per request
  const LT_CLOUD_MAX_LOOKBACK_S = 365 * 86400;   // stop pulling beyond ~1 year back
  // JS field key → sensor_history column prefix (envelope: _min/_max/_avg; avg-only: _avg).
  const LT_CLOUD_COL = {
    battVolt:'batt_volt', battCurr:'batt_curr', altCurr:'alt_curr', victronCurr:'victron_curr',
    rpm:'rpm', duty:'duty_cycle', altTemp:'alt_temp', tempTherm:'temp_therm',
    sog:'sog', tws:'tws', vmg:'vmg', aws:'aws', awa:'awa', twa:'twa',
    heel:'imu_heel', pitch:'imu_pitch',
    soc:'soc', baro:'baro', ambTemp:'amb_temp', cog:'cog', heading:'heading',
    leeway:'leeway', altZero:'alt_zero'
  };
  let ltCloud = { avail: undefined, fetching: false, oldest: null, exhausted: false };

  function ltCloudEnabled() {
    // Source of truth is the checkbox — the settings echo (updateCheckbox) keeps
    // CloudFeatures_checkbox.checked current but does NOT write the hidden
    // #CloudFeatures input's .value (it stays "0"), so reading that gave false negatives.
    const cb = document.getElementById('CloudFeatures_checkbox');
    if (cb) return !!cb.checked;
    const cf = document.getElementById('CloudFeatures');
    return !!cf && cf.value === '1';
  }
  function ltIso(sec) { return new Date(sec * 1000).toISOString().replace(/\.\d+Z$/, 'Z'); }

  // One-line note below the brush, shown when cloud history isn't available. mode:
  //   'off' — Cloud Features off but available (Client mode) → tell them they can enable it
  //   'ap'  — Access Point mode → Cloud Features can't be enabled, so don't suggest it
  //   null  — cloud on → hide the note
  function ltCloudHint(mode) {
    let el = document.getElementById('lt-cloud-hint');
    if (!el) {
      const host = document.getElementById('dashboard-brush');
      if (!host || !host.parentNode) return;
      el = document.createElement('div');
      el.id = 'lt-cloud-hint';
      el.style.cssText = 'font-size:12px;opacity:0.7;margin:6px 2px;';
      host.parentNode.insertBefore(el, host.nextSibling);
    }
    if (mode === 'off') el.textContent = 'Showing on-device history (~1 month). Enable Cloud Features in Setup to view older data.';
    else if (mode === 'ap') el.textContent = 'Showing on-device history (~1 month). Older data needs Cloud Features, which is unavailable in Access Point mode.';
    el.style.display = mode ? '' : 'none';
  }

  // Map get-history rows (must be ascending) into parallel arrays in ltData's field
  // shape, dropping any overlap with already-loaded data and breaking the line where
  // the 10-min cadence is interrupted (power-off period).
  function ltCloudRowsToSlice(rows, interval, boundarySec) {
    const t = [], isGap = [], stage = [], fields = {};
    ENV.forEach(([k]) => fields[k] = { min:[], max:[], avg:[] });
    AVG.forEach(([k]) => fields[k] = { avg:[] });
    const num = (v) => (v == null ? null : Number(v));
    const pushGap = (gt) => {
      t.push(gt); isGap.push(true); stage.push(null);
      ENV.forEach(([k]) => { fields[k].min.push(null); fields[k].max.push(null); fields[k].avg.push(null); });
      AVG.forEach(([k]) => fields[k].avg.push(null));
    };
    let prevTs = null;
    for (const r of rows) {
      const ts = Math.floor(Date.parse(r.timestamp) / 1000);
      if (!isFinite(ts) || ts >= boundarySec) continue;   // drop overlap with loaded data
      // Skip invalid/boot windows: a battery can't read 0 V, so batt_volt_avg<=0 means
      // the device sampled before sensors were ready (each reboot leaves one). Bridge over
      // it rather than letting every trace dive to 0. Legit zeros (SOG, VMG) are kept.
      const bv = num(r.batt_volt_avg);
      if (bv == null || bv <= 0) continue;
      if (prevTs != null && (ts - prevTs) > ltGapThreshold(interval)) pushGap((prevTs + ts) / 2);
      prevTs = ts;
      t.push(ts); isGap.push(false);
      // Fields where 0 means "no reading" (a battery/baro can't be 0): null the garbage so
      // boot-window transients don't pull lines/bands to 0. Legit zeros (speeds, angles) kept.
      const nz = (k, v) => ((k === 'battVolt' || k === 'baro') && v != null && v <= 0) ? null : v;
      ENV.forEach(([k]) => {
        const c = LT_CLOUD_COL[k], f = fields[k];
        f.min.push(nz(k, num(r[c + '_min']))); f.max.push(nz(k, num(r[c + '_max']))); f.avg.push(nz(k, num(r[c + '_avg'])));
      });
      AVG.forEach(([k]) => fields[k].avg.push(nz(k, num(r[LT_CLOUD_COL[k] + '_avg']))));
      stage.push(r.charge_stage == null ? null : Number(r.charge_stage));
    }
    return { t, fields, isGap, stage, n: t.length };
  }

  // Reorder ltData strictly by ascending timestamp. A single out-of-order point makes
  // uPlot draw a line segment that jumps backward across the chart (looks like an extra
  // crossing line). Reorders all parallel arrays (t, isGap, every field) by one index map.
  function ltSortData() {
    if (!ltData || ltData.n < 2) return;
    const ot = ltData.t;
    // Sort by timestamp AND drop exact-duplicate timestamps (keep first). Dedup guards
    // against any double-prepend; a backward-jumping point or duplicate both draw wrong.
    const sortIdx = ot.map((_, i) => i).sort((a, b) => ot[a] - ot[b]);
    const idx = []; let last = null;
    for (const i of sortIdx) { if (ot[i] === last) continue; idx.push(i); last = ot[i]; }
    if (idx.length === ot.length) {   // already sorted, no dups → nothing to do
      let clean = true;
      for (let j = 0; j < idx.length; j++) if (idx[j] !== j) { clean = false; break; }
      if (clean) return;
    }
    const og = ltData.isGap || [], ost = ltData.stage || [];
    ltData.t = idx.map(i => ot[i]);
    ltData.isGap = idx.map(i => og[i]);
    ltData.stage = idx.map(i => ost[i]);
    ENV.forEach(([k]) => { const f = ltData.fields[k], mn = f.min, mx = f.max, av = f.avg;
      f.min = idx.map(i => mn[i]); f.max = idx.map(i => mx[i]); f.avg = idx.map(i => av[i]); });
    AVG.forEach(([k]) => { const av = ltData.fields[k].avg; ltData.fields[k].avg = idx.map(i => av[i]); });
    ltData.n = ltData.t.length;
  }

  // Prepend an older slice into ltData chronologically, breaking the line at the
  // cloud↔local seam if the cadence gaps there.
  function ltCloudPrepend(slice, interval) {
    if (!slice.n) return;
    const t = slice.t.slice(), isGap = slice.isGap.slice(), stage = (slice.stage || []).slice(), fields = {};
    ENV.forEach(([k]) => fields[k] = { min: slice.fields[k].min.slice(), max: slice.fields[k].max.slice(), avg: slice.fields[k].avg.slice() });
    AVG.forEach(([k]) => fields[k] = { avg: slice.fields[k].avg.slice() });
    if (ltData.t.length && (ltData.t[0] - slice.t[slice.n - 1]) > ltGapThreshold(interval)) {
      const gt = (slice.t[slice.n - 1] + ltData.t[0]) / 2;   // seam gap
      t.push(gt); isGap.push(true); stage.push(null);
      ENV.forEach(([k]) => { fields[k].min.push(null); fields[k].max.push(null); fields[k].avg.push(null); });
      AVG.forEach(([k]) => fields[k].avg.push(null));
    }
    ltData.t = t.concat(ltData.t);
    ltData.isGap = isGap.concat(ltData.isGap || []);
    ltData.stage = stage.concat(ltData.stage || []);
    ENV.forEach(([k]) => {
      ltData.fields[k].min = fields[k].min.concat(ltData.fields[k].min);
      ltData.fields[k].max = fields[k].max.concat(ltData.fields[k].max);
      ltData.fields[k].avg = fields[k].avg.concat(ltData.fields[k].avg);
    });
    AVG.forEach(([k]) => { ltData.fields[k].avg = fields[k].avg.concat(ltData.fields[k].avg); });
    ltData.n = ltData.t.length;
    ltSortData();   // guarantee strict monotonic order (no backward-jumping line segments)
  }

  // Open one chunk of reachable past so the brush can be dragged into cloud territory
  // (the actual fetch stays lazy — triggered only when the view passes the loaded edge).
  function ltCloudOldestSec() {   // oldest loaded boundary, valid even with an empty local ring
    if (ltCloud.oldest != null) return ltCloud.oldest;
    if (ltData && ltData.n > 0) return ltData.t[0];
    return Math.floor(Date.now() / 1000);
  }
  function ltCloudExtendReach() {
    if (!_brushState || !_brushState.nativeSink) return;
    const reachMs = (ltCloudOldestSec() - LT_CLOUD_CHUNK_S) * 1000;
    _brushState.dataMin = reachMs;
    const mn = document.getElementById('dashboard-brush-data-min');
    if (mn && typeof _brushFormatTime === 'function') mn.textContent = _brushFormatTime(reachMs);
  }
  function ltCloudClampReach() {   // exhausted: stop the brush at real data
    if (!_brushState || !_brushState.nativeSink) return;
    _brushState.dataMin = ltCloudOldestSec() * 1000;
    const mn = document.getElementById('dashboard-brush-data-min');
    if (mn && typeof _brushFormatTime === 'function') mn.textContent = _brushFormatTime(_brushState.dataMin);
  }

  // Pull the next older 30-day chunk (cloud-gated, deduped, bounded, chains while the
  // brushed range still extends past the loaded edge).
  async function ltCloudPull() {
    if (!ltData || ltCloud.fetching || ltCloud.exhausted) return;
    if (!ltCloudEnabled()) { ltCloud.avail = false; return; }
    // local had little (≤1 pt or <1h span) → after the fill, show the whole loaded range
    const wasSparse = (ltData.n < 2) || ((ltData.t[ltData.n - 1] - ltData.t[0]) < 3600);
    const boundary = (ltCloud.oldest != null) ? ltCloud.oldest : ltData.t[0];
    if (boundary <= Math.floor(Date.now() / 1000) - LT_CLOUD_MAX_LOOKBACK_S) { ltCloud.exhausted = true; ltCloudClampReach(); return; }
    ltCloud.fetching = true;
    try {
      const token = await ensureCloudToken();
      if (!token) { ltCloud.avail = false; ltCloudClampReach(); return; }  // not registered → no cloud tier
      ltCloud.avail = true;
      const startSec = boundary - LT_CLOUD_CHUNK_S;
      const resp = await fetch(`${SUPABASE_URL}/functions/v1/get-history`, {
        method: 'POST', headers: cloudHeaders(),
        body: JSON.stringify({ token, start: ltIso(startSec), end: ltIso(boundary) })
      });
      if (!resp.ok) { if (resp.status === 401) g_cloudToken = null; return; }   // leave state → retry later
      const json = await resp.json();
      const rows = (json && json.data) ? json.data.slice() : [];
      rows.sort((a, b) => Date.parse(a.timestamp) - Date.parse(b.timestamp));   // ascending
      const interval = ltData.interval || 600;
      const slice = ltCloudRowsToSlice(rows, interval, boundary);
      if (slice.n === 0) { ltCloud.exhausted = true; ltCloudClampReach(); return; }  // no older data
      ltCloudPrepend(slice, interval);
      ltCloud.oldest = slice.t[0];
      ltFullRange = [ ltData.t[0], ltFullRange ? ltFullRange[1] : ltData.t[ltData.n - 1] ];
      ltCloudExtendReach();
    } catch (e) {
      // Network/parse failure — leave state so a later brush retries.
    } finally {
      ltCloud.fetching = false;
    }
    // Re-render so the stitched data appears. If the ring was sparse (no real local
    // span), show the whole freshly-loaded range; otherwise keep the current range (and
    // if it still passes the new loaded edge, that re-triggers a pull → next chunk).
    if (wasSparse && ltData.n >= 2 && ltData.t[ltData.n - 1] > ltData.t[0]) {
      ltRenderAll(ltData.t[0], ltData.t[ltData.n - 1]);
    } else if (ltCurRange) {
      ltRenderAll(ltCurRange[0], ltCurRange[1]);
    }
  }

  // Called from ltRenderAll: pull when the view passes the oldest loaded record.
  function ltCloudMaybePull(fromSec) {
    if (!ltData || ltCloud.exhausted || ltCloud.fetching || ltCloud.avail === false) return;
    if (isFinite(fromSec) && fromSec < ltCloudOldestSec()) ltCloudPull();
  }

  // oldestSec = the boundary below which cloud fills (oldest local record, or `now` when
  // the local ring is empty). No auto-pull here — the initial ltRenderAll's
  // ltCloudMaybePull triggers exactly one pull when the view reaches past `oldest`
  // (which it does in the sparse case, where loSec is well before oldest). Calling a pull
  // here too caused a concurrent double-fetch (fetching flag was reset) → duplicate data.
  function ltCloudInit(oldestSec) {
    ltCloud = { avail: undefined, fetching: false, oldest: oldestSec, exhausted: false };
    if (!ltCloudEnabled()) {
      ltCloud.avail = false;
      const apMode = (document.getElementById('currentModeID')?.value === '1');  // 1 = Access Point
      ltCloudHint(apMode ? 'ap' : 'off');
      return;
    }
    ltCloudHint(null);
    ltCloudExtendReach();
  }

  // Re-fetch the on-device ring on EVERY tab open (the endpoint now sends only the
  // populated records, so it's cheap) → the local portion is always current. Cloud stays
  // lazy: re-stitched on brush-past-horizon. Charts are built once; subsequent opens
  // refresh their data.
  window.initLongTermPlots = function () {
    fetch('/longTermPlots.bin', { cache: 'no-cache' })
      .then(r => { if (!r.ok) throw new Error('http ' + r.status); return r.arrayBuffer(); })
      .then(buf => {
        ltData = parseLT(buf);
        if (!ltData) throw new Error('parse failed');
        ltSortData();   // strict monotonic order before any render
        ltLoaded = true;
        // Empty local ring: if Cloud Features is on, still build the charts so the cloud
        // stitch can fill the timeline; only show the "no data" notice when cloud is off.
        if (ltData.n === 0 && !ltCloudEnabled()) {
          ltStatus('No long-term data yet — records accumulate locally every ~10 min. Without WiFi/Cloud, history is on-device only (about 30 days).');
          return;
        }
        ltStatus(null);
        buildAllLtPlots();
      })
      // On a transient re-fetch failure, keep whatever's already on screen rather than blanking.
      .catch(e => { if (!ltLoaded) ltStatus('Long-term history unavailable (' + e.message + ').'); });
  };
})();

/* ---- Session fuel-economy curve (mpg vs RPM), driven each CSV2 tick by window.updateFuelCurve ---- */
(function () {
  const NBINS = 18;                 // must match firmware FUELCURVE_BINS
  const DEFAULT_TOP = 4500;         // fallback x-scale until firmware reports the configured top RPM
  let plot = null;
  let yManual = null;               // [min,max] typed on the plot; null = auto-fit
  try { yManual = JSON.parse(localStorage.getItem('fuelCurveYRange')) || null; } catch (e) { }

  function make(el) {
    const opts = {
      width: el.clientWidth || 600,
      height: 300,
      scales: {
        x: { time: false },
        mpg: { range: (u, mn, mx) => yManual ? yManual : stableAutoRange(mn, mx, 0.1) }
      },
      series: [
        { label: "RPM" },
        { label: "mpg", scale: "mpg", stroke: "#2e7d32", width: 2, points: { show: true, size: 6 }, spanGaps: false }
      ],
      axes: [
        { scale: "x", label: "RPM", values: (u, t) => t.map(v => Math.round(v)) },
        { scale: "mpg", label: "naut mi / gal", side: 3,
          splits: edgeLabeledSplits(() => yManual !== null) }
      ],
      legend: { show: false }
    };
    plot = new uPlot(opts, [[0], [null]], el);
    if (document.body.classList.contains('dark-mode')) updateUplotTheme(plot);
    const ro = new ResizeObserver(() => { if (plot) plot.setSize({ width: el.clientWidth || 600, height: 300 }); });
    ro.observe(el);

    // Auto checkbox (top-right) — same convention as the other plots. No lock button:
    // this is an RPM-domain curve that redraws on new fuel data, not a streaming
    // time-series, so unchecking (pin to what's shown) covers the freeze case.
    // Checked = auto-fit (null manual range); unchecked = pin to what's shown.
    el.style.position = 'relative';
    const exFuelAs = el.querySelector('.autoscale-ctrl'); if (exFuelAs) exFuelAs.remove();
    const fuelAsDiv = document.createElement('div');
    fuelAsDiv.className = 'autoscale-ctrl';
    fuelAsDiv.style.cssText = 'position:absolute;top:6px;right:8px;z-index:10;display:flex;align-items:center;gap:3px;font-size:11px;opacity:0.6;';
    fuelAsDiv.innerHTML = '<input type="checkbox" id="autoscale-fuel-cb" style="cursor:pointer;width:12px;height:12px;margin:0;"><label for="autoscale-fuel-cb" style="cursor:pointer;user-select:none;">auto</label>';
    el.appendChild(fuelAsDiv);
    const fuelAsCb = document.getElementById('autoscale-fuel-cb');
    fuelAsCb.checked = (yManual == null);   // null manual range = auto-fit
    fuelAsCb.addEventListener('change', e => {
      if (e.target.checked) { yManual = null; localStorage.removeItem('fuelCurveYRange'); }
      else if (plot) { yManual = [plot.scales.mpg.min, plot.scales.mpg.max]; localStorage.setItem('fuelCurveYRange', JSON.stringify(yManual)); }
      if (plot) plot.setData(plot.data);   // re-runs the range function
    });

    // Click-to-edit Y limits. Typing pins the axis and unchecks auto; the checkbox
    // is the only way back to auto-fit — no hidden clear-the-box gesture.
    attachYAxisEdit(plot, [{
      scale: 'mpg', decimals: 2,
      apply: (mn, mx) => {
        yManual = [mn, mx];
        fuelAsCb.checked = false;
        localStorage.setItem('fuelCurveYRange', JSON.stringify(yManual));
        plot.setData(plot.data);   // re-runs the range function
      }
    }]);
  }

  window.updateFuelCurve = function (data) {
    if (data.fuelCurveNMPG_0 === undefined) return;        // not in this payload
    const el = document.getElementById('fuelCurvePlot');
    if (!el) return;
    if (!plot) { if (typeof uPlot === 'undefined') return; make(el); }
    // Bin width is universal: it scales with the engine's configured fuel-table top RPM.
    const topRPM = Number(data.fuelCurveTopRPM) > 0 ? Number(data.fuelCurveTopRPM) : DEFAULT_TOP;
    const binW = topRPM / NBINS;
    const X = Array.from({ length: NBINS }, (_, i) => i * binW + binW / 2);  // bin centers
    const y = new Array(NBINS);
    let bestV = 0, bestI = -1;
    for (let i = 0; i < NBINS; i++) {
      const v = Number(data['fuelCurveNMPG_' + i]) / 100;
      y[i] = v > 0 ? v : null;                              // 0 = empty bin -> gap
      if (v > bestV) { bestV = v; bestI = i; }
    }
    plot.setData([X, y]);
    const best = document.getElementById('fuelCurveBestID');
    if (best) {
      const txt = bestI >= 0
        ? bestV.toFixed(2) + ' naut mi/gal at ~' + Math.round(bestI * binW) + '–' + Math.round((bestI + 1) * binW) + ' rpm'
        : '—';
      if (best.textContent !== txt) best.textContent = txt;
    }
  };
})();

// ─────────────────────────────────────────────────────────────────────────────
// Fast alternator-current scope (Plots → Scope). Pulls /fastscope.bin — a 500 ms
// raw capture at 20 kSPS — and renders it as amps vs milliseconds. Zoom buttons
// show the LAST N ms of the capture (ms is ground truth); the hint reports how many engine
// and alternator revolutions that window spans, from the live RPM and PulleyRatio.
// ─────────────────────────────────────────────────────────────────────────────
let fastScopePlot = null;
let fastScopeData = null;
let fastScopeViewMs = 200;   // shared X window (ms) for BOTH the scope and the Reference Flipbook; capped at the 200 ms flipbook page length
let fastScopeAmpsMin = null, fastScopeAmpsMax = null;  // null = auto-scale; set via the click-to-edit Y widget, persisted to localStorage like the other plots
let fastScopePaused = false;
// Raw and Filtered are independent show/hide toggles (plot series 1 and 2), not an A/B switch.
// Raw = the full 20 kHz samples; Filtered = the boxcar-16 the analysis uses (≈550 Hz bandwidth).
// Any combination is allowed, including both or neither. Default: Raw on, Filtered on.
let fastScopeShowRaw = true;
let fastScopeShowFilt = true;
const FA_SCOPE_BOXCAR_N = 16;   // matches the firmware FA_DECIM — first null 20 kHz/16 = 1.25 kHz, −3 dB ≈ 550 Hz

// Trailing N-sample moving average (same shape as the firmware boxcar-16 decimation, but kept
// at full sample positions so the time axis is unchanged — a single-sample glitch shrinks ~Nx).
function fastScopeBoxcar(amps, N) {
    const n = amps.length, out = new Array(n);
    let acc = 0;
    for (let i = 0; i < n; i++) {
        acc += amps[i];
        if (i >= N) acc -= amps[i - N];
        out[i] = acc / Math.min(i + 1, N);
    }
    return out;
}
// Plot data is always [tMs, rawAmps, filteredAmps] — both series columns are present every
// frame; the toggles control series visibility (show), not which column is computed. The
// boxcar over ~5 k samples is cheap, so we compute it unconditionally.
function fastScopeViewData() {
    if (!fastScopeData) return [[], [], []];
    return [fastScopeData.tMs, fastScopeData.amps, fastScopeBoxcar(fastScopeData.amps, FA_SCOPE_BOXCAR_N)];
}
function fastScopeLoadAmpsRange() {
    try { const s = JSON.parse(localStorage.getItem('faScopeAmpsRange')); if (s && isFinite(s.min) && isFinite(s.max)) { fastScopeAmpsMin = s.min; fastScopeAmpsMax = s.max; } } catch (e) { }
}
function fastScopeSaveAmpsRange() {
    try {
        if (fastScopeAmpsMin != null && fastScopeAmpsMax != null) localStorage.setItem('faScopeAmpsRange', JSON.stringify({ min: fastScopeAmpsMin, max: fastScopeAmpsMax }));
        else localStorage.removeItem('faScopeAmpsRange');
    } catch (e) { }
}
fastScopeLoadAmpsRange();
let fastScopeResizeObserver = null;

function parseFastScope(buf) {
    const dv = new DataView(buf);
    if (buf.byteLength < 24 || dv.getUint32(0, true) !== 0x46534331) return null;  // 'FSC1', 24 B header
    const rate = dv.getUint16(4, true) * 10;
    const count = dv.getUint16(6, true);
    const zeroMv = dv.getUint16(8, true);
    const apv = dv.getUint16(10, true);
    const atten = dv.getUint8(12);
    const state = dv.getUint8(13);
    const rpm = dv.getUint16(14, true);          // tach at capture (request time = capture-end)
    const altTempF = dv.getInt16(16, true);      // whole °F at capture
    const epoch = dv.getUint32(18, true);        // unix time at capture (0 = clock not synced)
    if (buf.byteLength < 24 + count * 2) return null;
    const tMs = new Array(count), amps = new Array(count);
    for (let i = 0; i < count; i++) {
        const mv = dv.getInt16(24 + i * 2, true);
        amps[i] = (mv - zeroMv) * apv / 1000;
        tMs[i] = i * 1000 / rate;
    }
    return { rate, count, zeroMv, apv, atten, state, rpm, altTempF, epoch, tMs, amps };
}

// How many engine and alternator turns the currently-shown window spans. Engine speed is the
// live tach reading (window._debugData.RPM); the alternator turns PulleyRatio times faster
// (Alt_RPM = RPM × PulleyRatio, matching the firmware's Alt_RPM). The count scales with the View
// buttons because the window is fastScopeViewMs wide. Approximate — RPM is a live reading, not
// measured off this trace, so a sudden RPM change mid-capture won't be reflected exactly.
function fastScopeRevHint() {
    const rpm = parseFloat((window._debugData || {}).RPM);
    if (!isFinite(rpm) || rpm < 1) return 'Engine stopped — no revolutions to show.';
    const fmt = v => v < 1 ? v.toFixed(2) : v.toFixed(1);
    const engineRevs = rpm / 60 * (fastScopeViewMs / 1000);
    const pulleyEl = document.getElementById('PulleyRatio_echo');
    const pulley = pulleyEl ? parseFloat(pulleyEl.textContent) : NaN;
    let s = '≈ ' + fmt(engineRevs) + ' engine revs';
    if (isFinite(pulley) && pulley > 0) s += ' · ' + fmt(engineRevs * pulley) + ' alternator revs';
    return s + ' in this ' + fastScopeViewMs + ' ms window';
}

function initFastScopePlot() {
    const plotEl = document.getElementById('fastscope-plot');
    if (!plotEl || fastScopePlot) return;
    const opts = {
        width: Math.min(plotEl.clientWidth || 360, 800),
        height: 300,
        // No title: the view buttons re-window one capture, so any fixed "250 ms" label is wrong once zoomed. Signal is named on the Y axis instead.
        series: [
            {},
            { label: "Raw (A)", stroke: "#2196F3", width: 1, points: { show: false }, scale: "amps", show: fastScopeShowRaw },
            { label: "Filtered (A)", stroke: "#FF9800", width: 1.5, points: { show: false }, scale: "amps", show: fastScopeShowFilt }
        ],
        scales: {
            // x window pinned by a range fn (re-read each redraw) to the last fastScopeViewMs of the
            // capture — so a refresh or zoom never flashes through the full 250 ms range. auto:false
            // keeps setData from re-fitting x. dEnd = newest sample time.
            x: {
                time: false,
                auto: false,
                range: () => {
                    const d = fastScopeData;
                    const tEnd = (d && d.count > 0) ? d.tMs[d.count - 1] : fastScopeViewMs;
                    return [Math.max(0, tEnd - fastScopeViewMs), tEnd];
                }
            },
            // Default auto (NOT auto:false): uPlot only recomputes the data min/max it passes to
            // this fn when the scale is auto, so the auto-fit branch AND the "auto" checkbox need
            // fresh extents on each setData. Manual pin returns the saved range. Mirrors the CV plot.
            amps: {
                range: (u, mn, mx) => (fastScopeAmpsMin != null && fastScopeAmpsMax != null)
                    ? [fastScopeAmpsMin, fastScopeAmpsMax]
                    : (mn == null ? [-1, 1] : stableAutoRange(mn, mx, 0.1))
            }
        },
        axes: [
            { label: "Milliseconds", grid: { show: true } },
            {
                scale: "amps", label: "Alternator Current (A)", grid: { show: true }, side: 3,
                splits: edgeLabeledSplits(() => fastScopeAmpsMin != null)  // show the editable min/max at the edges when manually ranged
            }
        ],
        legend: { show: false }
    };
    fastScopePlot = new uPlot(opts, [[], [], []], plotEl);
    if (document.body.classList.contains('dark-mode')) updateUplotTheme(fastScopePlot);

    // Auto checkbox (top-right) — same convention as the other plots. No "lock" button:
    // this is a one-shot capture, not a streaming autoscale loop. Checked = auto-fit (null
    // range vars); unchecked = pin to whatever is currently shown.
    plotEl.style.position = 'relative';
    const existingAs = plotEl.querySelector('.autoscale-ctrl');
    if (existingAs) existingAs.remove();
    const asDiv = document.createElement('div');
    asDiv.className = 'autoscale-ctrl';
    asDiv.style.cssText = 'position:absolute;top:6px;right:8px;z-index:10;display:flex;flex-direction:column;align-items:flex-end;gap:2px;font-size:11px;';
    asDiv.innerHTML = '<button id="fastscope-pause-btn" title="Pause — freeze the displayed capture (stops the ~5 s auto-refresh)" style="font-size:10px;padding:0 6px;cursor:pointer;border:1px solid #999;border-radius:2px;background:transparent;line-height:16px;" onclick="fastScopePauseToggle(this)">Pause</button><div style="display:flex;align-items:center;gap:3px;opacity:0.6;"><input type="checkbox" id="autoscale-fastscope-cb" style="cursor:pointer;width:12px;height:12px;margin:0;"><label for="autoscale-fastscope-cb" style="cursor:pointer;user-select:none;">auto</label></div>';
    plotEl.appendChild(asDiv);
    if (fastScopePaused) { const pb = document.getElementById('fastscope-pause-btn'); if (pb) pb.textContent = 'Resume'; }
    const faCb = document.getElementById('autoscale-fastscope-cb');
    faCb.checked = (fastScopeAmpsMin == null);  // null range vars = auto-fit
    faCb.addEventListener('change', e => {
        if (e.target.checked) { fastScopeAmpsMin = null; fastScopeAmpsMax = null; }
        else if (fastScopePlot) { fastScopeAmpsMin = fastScopePlot.scales.amps.min; fastScopeAmpsMax = fastScopePlot.scales.amps.max; }
        fastScopeSaveAmpsRange();
        if (fastScopePlot) fastScopePlot.setData(fastScopePlot.data);
    });

    // Click-to-edit Y limits — the same shared widget every other plot uses; persisted to localStorage.
    // Editing pins the range and unchecks auto; the auto checkbox is the only way back to auto-fit.
    attachYAxisEdit(fastScopePlot, [{
        scale: 'amps', decimals: 2,
        apply: (mn, mx) => { fastScopeAmpsMin = mn; fastScopeAmpsMax = mx; faCb.checked = false; fastScopeSaveAmpsRange(); if (fastScopePlot) fastScopePlot.setData(fastScopePlot.data); }
    }]);
    const resizePlot = debounce(() => {
        const el = document.getElementById('fastscope-plot');
        if (el && fastScopePlot) fastScopePlot.setSize({ width: Math.min(el.clientWidth || 360, 800), height: 300 });
    }, 1000);
    if (fastScopeResizeObserver) fastScopeResizeObserver.disconnect();
    fastScopeResizeObserver = new ResizeObserver(resizePlot);
    fastScopeResizeObserver.observe(plotEl);
}

function fastScopeStatusText(d) {
    if (!d) return 'Bad response from regulator.';
    if (d.state === 0) return 'Channel off (sampler failed to start).';
    if (d.state === 2) return 'Channel dormant — input reads railed full-scale (sense jumper open?).';
    const range = d.atten ? 'high range' : 'standard range';
    return 'Captured ' + d.count + ' samples at ' + (d.rate / 1000) + ' kHz, ' + range + '. Auto-updates every 5 seconds while this panel is open.';
}

function fastScopeApplyZoom() {
    // Re-run the x range fn with the current fastScopeViewMs — a queued setData is all it takes.
    if (fastScopePlot && fastScopeData && fastScopeData.count > 0) fastScopePlot.setData(fastScopePlot.data);
}

function fastScopeZoom(ms, btn) {
    fastScopeViewMs = ms;
    // Only the window buttons carry data-ms; flipbook page buttons share .fastscope-zoom for
    // styling but use data-slot, so scope the deselect here or it clears the selected page.
    document.querySelectorAll('.fastscope-zoom[data-ms]').forEach(b => b.classList.remove('active'));
    if (btn) btn.classList.add('active');
    fastScopeApplyZoom();
    // Same window drives the Reference Flipbook below. A new window width changes the frame split,
    // so reset to the first frame and re-trigger its x range fn; both plots span identical ms.
    if (fastFlipPlot && fastFlipSelected >= 0) { faFlipFrame = 0; fastFlipPlot.setData(fastFlipPlot.data); faFlipUpdateNav(); }
    // Revs shown scale with the window width, so refresh the hint on every view change.
    const hint = document.getElementById('fastscope-cycle-hint');
    if (hint && fastScopeData && fastScopeData.count > 0) hint.textContent = fastScopeRevHint();
}

// silent=true (the 5 s auto-refresh) skips the "Fetching…" status flash so the panel updates in
// place. The x range fn pins the view, so setData alone re-windows without a full-range flash.
function fetchFastScope(silent) {
    const status = document.getElementById('fastscope-status');
    if (status && !silent) status.textContent = 'Fetching…';
    fetch(buildURL('/fastscope.bin'), { cache: 'no-cache' })
        .then(r => { if (!r.ok) throw new Error('http ' + r.status); return r.arrayBuffer(); })
        .then(buf => {
            const d = parseFastScope(buf);
            fastScopeData = d;
            if (status) status.textContent = fastScopeStatusText(d);
            const hint = document.getElementById('fastscope-cycle-hint');
            if (hint) hint.textContent = (d && d.count > 0) ? fastScopeRevHint() : '';
            if (!d || d.count === 0) return;
            initFastScopePlot();
            if (fastScopePlot) fastScopePlot.setData(fastScopeViewData());  // x range fn pins the window — no flash
        })
        .catch(e => { if (status) status.textContent = 'Capture unavailable (' + e.message + ').'; });
}

function fastScopeOnOpen() {
    if (!fastScopeData) fetchFastScope();
    else if (fastScopePlot) setTimeout(() => fastScopePlot.setSize({ width: Math.min(document.getElementById('fastscope-plot').clientWidth || 360, 800), height: 300 }), 50);
    fetchFastFlip();   // always re-pull on open so freshly-frozen reference pages show without a manual Refresh
}

// Pause freezes the displayed capture by halting the ~5 s auto-refresh. The on-chart Pause
// button (top-right of the scope plot) is the only control; press Resume to re-arm the refresh.
function fastScopePauseToggle(btn) {
    fastScopePaused = !fastScopePaused;
    if (btn) { btn.textContent = fastScopePaused ? 'Resume' : 'Pause'; btn.classList.toggle('active', fastScopePaused); }
    const status = document.getElementById('fastscope-status');
    if (status && fastScopePaused) status.textContent = 'Paused — showing a frozen capture.';
}

// Build a metadata-rich CSV for one scope capture: a commented header (capture time, RPM, alt
// temp, rate, range — all stamped at capture in the FSC1 blob) followed by BOTH the raw 20 kHz
// samples and the boxcar-16 filtered version (what the analysis sees). Shared by the Download CSV
// button and the remote log relay so both carry identical, self-describing content.
function buildFaScopeCsv(d) {
    const filt = fastScopeBoxcar(d.amps, FA_SCOPE_BOXCAR_N);
    const when = (d.epoch && d.epoch > 1577836800) ? new Date(d.epoch * 1000).toISOString() : 'clock not set';
    let csv = '';
    csv += '# Alt scope capture (fast alternator-current channel)\n';
    csv += '# captured,' + when + '\n';
    csv += '# rpm,' + d.rpm + '\n';
    csv += '# alt_temp_F,' + d.altTempF + '\n';
    csv += '# sample_rate_hz,' + d.rate + '\n';
    csv += '# range,' + (d.atten ? '12dB' : '6dB') + '\n';
    csv += 'ms,amps_raw,amps_filtered\n';
    for (let i = 0; i < d.count; i++) csv += d.tMs[i].toFixed(4) + ',' + d.amps[i].toFixed(3) + ',' + filt[i].toFixed(3) + '\n';
    return csv;
}

// Export the currently-shown scope capture as CSV (header + raw + boxcar-16 filtered).
function downloadFaScopeCsv() {
    if (!fastScopeData || !fastScopeData.count) { xAlert('No scope capture yet — wait a few seconds for the first capture.'); return; }
    const csv = buildFaScopeCsv(fastScopeData);
    const dt = new Date(), p = n => String(n).padStart(2, '0');
    const stamp = dt.getFullYear() + '-' + p(dt.getMonth() + 1) + '-' + p(dt.getDate()) + ' ' + p(dt.getHours()) + '-' + p(dt.getMinutes()) + '-' + p(dt.getSeconds());
    const a = document.createElement('a');
    a.href = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
    a.download = 'Alt Scope Capture ' + stamp + '.csv';
    document.body.appendChild(a); a.click();
    setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 1000);
}

// Live Data → Diag sub-tab (item 1). Opens the relocated scope/flipbook and starts the
// ~5 s scope auto-refresh (item 2). The refresh polls /fastscope.bin only while the Diag
// panel is the active sub-tab AND the page is visible; it stops itself otherwise. The fetch
// runs on the Core-0 web task — the only control-loop cost is the ~0.1–0.2 ms ring-snapshot
// spinlock wait (verified safe in the audit).
let fastDiagAutoTimer = null;
function fastDiagIsVisible() {
    if (document.visibilityState !== 'visible') return false;
    const panel = document.getElementById('livedata-diag');
    if (!panel || !panel.classList.contains('active')) return false;
    // The scope lives in the Waveforms <details> on the Diag tab; only live when that section is
    // expanded AND actually on-screen (offsetParent is null when display:none)
    const det = document.getElementById('fa-monitor-details');
    return !!(det && det.open && det.offsetParent !== null);
}
let fastDiagFlipTick = 0;
function fastDiagStartAuto() {
    if (fastDiagAutoTimer) return;
    fastDiagFlipTick = 0;
    fastDiagAutoTimer = setInterval(() => {
        if (!fastDiagIsVisible()) { fastDiagStopAuto(); return; }
        if (!fastScopePaused) fetchFastScope(true);  // silent: no "Fetching…" flash on the 5 s tick. Pause freezes auto-refresh.
        // Flipbook poll every 6th tick (~30 s): reference bands freeze themselves, so their
        // buttons light up here with no manual press. Silent + non-disruptive (see fetchFastFlip).
        if (++fastDiagFlipTick % 6 === 0) fetchFastFlip(true);
    }, 5000);
}
function fastDiagStopAuto() {
    if (fastDiagAutoTimer) { clearInterval(fastDiagAutoTimer); fastDiagAutoTimer = null; }
}
function fastDiagOnOpen() {
    if (!fastScopeData) fetchFastScope();
    else if (fastScopePlot) setTimeout(() => fastScopePlot.setSize({ width: Math.min(document.getElementById('fastscope-plot').clientWidth || 360, 800), height: 300 }), 50);
    fetchFastFlip();   // always re-pull on open so freshly-frozen reference pages show without a manual Refresh
    fastDiagStartAuto();
}
document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') { if (fastDiagIsVisible()) fastDiagStartAuto(); }
    else fastDiagStopAuto();
});

// Build a metadata-rich CSV for one flipbook page: commented header (capture time, RPM, mean amps,
// reference-band/anomaly type, range — all stored per page) + raw and boxcar-16 filtered columns.
// Shared by the download button and the relay. NOTE: per-page temperature is not available — RPM
// and capture time are stored in each FaFlipPage, but board/alt temp is not (adding it needs a
// firmware struct change that would invalidate already-saved pages).
function buildFaFlipPageCsv(pg) {
    const when = (pg.epoch && pg.epoch > 1577836800) ? new Date(pg.epoch * 1000).toISOString() : 'clock not set';
    const type = pg.isAnomaly ? ('anomaly k=' + pg.patternK + ' score=' + pg.score.toFixed(2))
                              : ('reference band ' + pg.band + ' (' + pg.band + 'k-' + (pg.band + 1) + 'k RPM)');
    let csv = '';
    csv += '# Alt reference waveform (fast alternator-current channel)\n';
    csv += '# captured,' + when + '\n';
    csv += '# rpm,' + pg.rpm + '\n';
    csv += '# amps_mean,' + pg.amps.toFixed(1) + '\n';
    csv += '# type,' + type + '\n';
    csv += '# range,' + (pg.attenIs12 ? '12dB' : '6dB') + '\n';
    csv += 'ms,amps_raw,amps_filtered\n';
    for (let s = 0; s < pg.t_ms.length; s++) csv += pg.t_ms[s].toFixed(3) + ',' + pg.amps_t[s].toFixed(3) + ',' + pg.filt_t[s].toFixed(3) + '\n';
    return csv;
}

// Per-page CSV export of the currently-shown flipbook waveform (item 8).
function downloadFaFlipPageCsv() {
    if (!fastFlipPages || fastFlipSelected < 0) { xAlert('Select a flipbook page first.'); return; }
    const pg = fastFlipPages[fastFlipSelected];
    if (!pg || !pg.used) { xAlert('That flipbook page is empty.'); return; }
    const csv = buildFaFlipPageCsv(pg);
    const d = new Date(), p = n => String(n).padStart(2, '0');
    const stamp = d.getFullYear() + '-' + p(d.getMonth() + 1) + '-' + p(d.getDate()) + ' ' + p(d.getHours()) + '-' + p(d.getMinutes()) + '-' + p(d.getSeconds());
    const tag = pg.isAnomaly ? ('anomaly k' + pg.patternK) : (pg.band + 'k-' + (pg.band + 1) + 'k RPM');
    const a = document.createElement('a');
    a.href = URL.createObjectURL(new Blob([csv], { type: 'text/csv' }));
    a.download = 'Alt Waveform ' + tag + ' ' + stamp + '.csv';
    document.body.appendChild(a); a.click();
    setTimeout(() => { URL.revokeObjectURL(a.href); a.remove(); }, 1000);
}

// ─────────────────────────────────────────────────────────────────────────────
// Reference flipbook (Plots → Scope, second card). Pulls /faflip.bin: 8-byte header
// then fixed 2020-byte pages — slots 0..refSlots-1 are the per-1000-RPM reference
// pages, the rest are anomaly captures. Layout pinned by static_assert in firmware.
// ─────────────────────────────────────────────────────────────────────────────
// ── Fast current channel (faEnabled/faAlarmEnable): segmented Off/On toggles + the chart Pause/Resume (faAnomPause) ──
// updateSegToggle mirrors updateCheckbox's pending-toggle reconciliation so an in-flight
// optimistic press isn't reverted by a stale echo before the regulator confirms.
function updateSegToggle(key, value) {
    if (value === undefined) return;
    const pending = pendingToggles.get(key);
    if (pending) {
        if (pending.deadlineMs === undefined) pending.deadlineMs = Date.now() + 2500;
        if (value !== pending.desiredValue) { if (Date.now() <= pending.deadlineMs) return; pendingToggles.delete(key); }
        else pendingToggles.delete(key);
    }
    const off = document.getElementById(key + '_off');
    const on = document.getElementById(key + '_on');
    const v = value | 0;
    if (off) off.classList.toggle('cap-mode-active', v === 0);
    if (on) on.classList.toggle('cap-mode-active', v === 1);
}
function faSegSet(key, value, form) {
    const inp = document.getElementById(key);
    if (inp) inp.value = value;
    pendingToggles.set(key, { desiredValue: value, baseRev: lastSeenRev });
    const off = document.getElementById(key + '_off');
    const on = document.getElementById(key + '_on');
    if (off) off.classList.toggle('cap-mode-active', value === 0);
    if (on) on.classList.toggle('cap-mode-active', value === 1);
    if (form) form.submit();
    submitMessage();
}
let _faAnomPause = 0;
function faUpdatePauseBtn(value) {
    if (value === undefined) return;
    const pending = pendingToggles.get('faAnomPause');
    if (pending) {
        if (pending.deadlineMs === undefined) pending.deadlineMs = Date.now() + 2500;
        if (value !== pending.desiredValue) { if (Date.now() <= pending.deadlineMs) return; pendingToggles.delete('faAnomPause'); }
        else pendingToggles.delete('faAnomPause');
    }
    _faAnomPause = value | 0;
    const b = document.getElementById('faflip-pause-btn');
    if (b) {
        b.textContent = _faAnomPause ? 'Resume' : 'Pause';
        b.title = _faAnomPause ? 'Anomaly captures paused — click to resume saving new fault snapshots'
            : 'Pause — stop new fault snapshots from overwriting the saved ones';
    }
}
function faAnomPauseToggle() {
    if (!currentAdminPassword) { xAlert('Please unlock settings first'); return; }
    const next = _faAnomPause ? 0 : 1;
    pendingToggles.set('faAnomPause', { desiredValue: next, baseRev: lastSeenRev });
    faUpdatePauseBtn(next);
    fetchWithTimeout(buildURL('/get?password=' + encodeURIComponent(currentAdminPassword) + '&faAnomPause=' + next), {}, 5000).then(() => {}).catch(() => {});
}
// Live Oscilloscope: Raw and Filtered are independent show/hide toggles (depress/return per
// click) — any combination including both traces at once or neither. Each button drives its
// own plot series' visibility; the button's cap-mode-active class mirrors the shown state.
function fastScopeViewToggle(which, btn) {
    if (which === 'raw') fastScopeShowRaw = !fastScopeShowRaw;
    else fastScopeShowFilt = !fastScopeShowFilt;
    const raw = document.getElementById('faScopeRawBtn');
    const filt = document.getElementById('faScopeFiltBtn');
    if (raw) raw.classList.toggle('cap-mode-active', fastScopeShowRaw);
    if (filt) filt.classList.toggle('cap-mode-active', fastScopeShowFilt);
    if (fastScopePlot) {
        fastScopePlot.setSeries(1, { show: fastScopeShowRaw });
        fastScopePlot.setSeries(2, { show: fastScopeShowFilt });
    }
}

let fastFlipPages = null;
let fastFlipPlot = null;
let fastFlipSelected = -1;
let faFlipAxis = {};   // per-slot Y-axis state, in-session only: { auto, locked, min, max }
// Raw/Filtered toggles mirror the live scope above (same two series, same colors). Default
// matches the scope: Raw on, Filtered on. Independent show/hide, any combination allowed.
let faFlipShowRaw = true;
let faFlipShowFilt = true;
// Frame paging: a page is 200 ms; the shared Time-window buttons split it into N equal frames
// (200 ms = 1 frame = whole page; 100 ms = 2; 50 ms = 4; …). faFlipFrame is which one is shown,
// 0 = the FIRST window. We page from the start (the scope above stays trailing/live) so the
// reference always opens at frame 1, with the on-plot ‹ › arrows stepping through.
let faFlipFrame = 0;

// How many equal time-windows the current view splits a page into, and the [lo,hi] ms span of
// the active frame. The last frame is clamped back so every frame keeps the full window width.
function faFlipFrameCount() {
    const pg = fastFlipPages && fastFlipPages[fastFlipSelected];
    const tEnd = (pg && pg.t_ms && pg.t_ms.length) ? pg.t_ms[pg.t_ms.length - 1] : 200;
    return Math.max(1, Math.ceil(tEnd / fastScopeViewMs));
}
function faFlipFrameRange() {
    const pg = fastFlipPages && fastFlipPages[fastFlipSelected];
    const tEnd = (pg && pg.t_ms && pg.t_ms.length) ? pg.t_ms[pg.t_ms.length - 1] : 200;
    const n = faFlipFrameCount();
    const f = Math.min(Math.max(0, faFlipFrame), n - 1);
    let lo = f * fastScopeViewMs, hi = lo + fastScopeViewMs;
    if (hi > tEnd) { hi = tEnd; lo = Math.max(0, tEnd - fastScopeViewMs); }
    return [lo, hi];
}
function faFlipStep(dir) {
    faFlipFrame = Math.min(faFlipFrameCount() - 1, Math.max(0, faFlipFrame + dir));
    if (fastFlipPlot) fastFlipPlot.setData(fastFlipPlot.data);   // re-runs the x range fn
    faFlipUpdateNav();
}
function faFlipUpdateNav() {
    const wrap = document.getElementById('faflip-nav');
    if (!wrap) return;
    const n = faFlipFrameCount();
    if (n <= 1) { wrap.style.display = 'none'; return; }   // longest window = one frame, no paging
    wrap.style.display = 'flex';
    const f = Math.min(Math.max(0, faFlipFrame), n - 1);
    const lbl = document.getElementById('faflip-frame-label');
    if (lbl) lbl.textContent = 'Frame ' + (f + 1) + ' / ' + n;
    const prev = document.getElementById('faflip-prev'), next = document.getElementById('faflip-next');
    if (prev) prev.disabled = (f <= 0);
    if (next) next.disabled = (f >= n - 1);
}
// Raw and Filtered are independent show/hide toggles for the flipbook plot, identical in
// behaviour to fastScopeViewToggle on the scope above.
function faFlipViewToggle(which) {
    if (which === 'raw') faFlipShowRaw = !faFlipShowRaw;
    else faFlipShowFilt = !faFlipShowFilt;
    const raw = document.getElementById('faFlipRawBtn');
    const filt = document.getElementById('faFlipFiltBtn');
    if (raw) raw.classList.toggle('cap-mode-active', faFlipShowRaw);
    if (filt) filt.classList.toggle('cap-mode-active', faFlipShowFilt);
    if (fastFlipPlot) {
        fastFlipPlot.setSeries(1, { show: faFlipShowRaw });
        fastFlipPlot.setSeries(2, { show: faFlipShowFilt });
    }
}
const FASTFLIP_PAGE_BYTES = 8020;
const FASTFLIP_NSAMP = 4000;

function parseFastFlip(buf) {
    const dv = new DataView(buf);
    if (buf.byteLength < 8 || dv.getUint32(0, true) !== 0x46464C50) return null;  // 'FFLP'
    const refSlots = dv.getUint8(4);
    const anomSlots = dv.getUint8(5);
    const rate = dv.getUint16(6, true) * 10;
    const total = refSlots + anomSlots;
    if (buf.byteLength < 8 + total * FASTFLIP_PAGE_BYTES) return null;
    const pages = [];
    for (let i = 0; i < total; i++) {
        const o = 8 + i * FASTFLIP_PAGE_BYTES;
        const used = dv.getUint8(o + 8);
        const pg = {
            slot: i,
            isRef: i < refSlots,
            band: i < refSlots ? i : null,
            used: used === 1,
            rpm: dv.getUint16(o, true),
            amps: dv.getUint16(o + 2, true) / 10,
            epoch: dv.getUint32(o + 4, true),
            isAnomaly: dv.getUint8(o + 9),
            patternK: dv.getUint8(o + 10),
            attenIs12: dv.getUint8(o + 11),   // range at capture (for the CSV header label)
            score: dv.getFloat32(o + 12, true),
            zeroMv: dv.getUint16(o + 16, true),
            apv: dv.getUint16(o + 18, true),
            rate: rate,
            amps_t: null, t_ms: null
        };
        if (pg.used) {
            pg.amps_t = new Array(FASTFLIP_NSAMP);
            pg.t_ms = new Array(FASTFLIP_NSAMP);
            for (let s = 0; s < FASTFLIP_NSAMP; s++) {
                const mv = dv.getInt16(o + 20 + s * 2, true);
                pg.amps_t[s] = (mv - pg.zeroMv) * pg.apv / 1000;
                pg.t_ms[s] = s * 1000 / rate;
            }
            // Filtered trace built client-side from the raw samples with the SAME boxcar-16 the
            // live scope uses — the saved page only stores raw mV, so the filtered overlay costs
            // no extra storage and matches what the analysis sees (≈550 Hz bandwidth).
            pg.filt_t = fastScopeBoxcar(pg.amps_t, FA_SCOPE_BOXCAR_N);
        }
        pages.push(pg);
    }
    return pages;
}

function initFastFlipPlot() {
    const plotEl = document.getElementById('fastflip-plot');
    if (!plotEl || fastFlipPlot) return;
    fastFlipPlot = new uPlot({
        width: Math.min(plotEl.clientWidth || 360, 800),
        height: 300,   // match the scope plot above it so the two stacked charts read as the same size
        // No fixed-ms title: the shared Time window buttons re-window this page, so any "200 ms"
        // label is wrong once zoomed (mirrors the scope, which titles via the Y axis instead).
        title: "Reference Waveform — 20 kHz",
        // Raw + Filtered, same two series and colors as the live scope above so the stacked plots
        // read alike. Toggled by faFlipViewToggle; data is always [t, raw, filtered] each render.
        series: [
            {},
            { label: "Raw (A)", stroke: "#2196F3", width: 1, points: { show: false }, scale: "amps", show: faFlipShowRaw },
            { label: "Filtered (A)", stroke: "#FF9800", width: 1.5, points: { show: false }, scale: "amps", show: faFlipShowFilt }
        ],
        scales: {
            // x pinned to the active frame (faFlipFrameRange) — the page is split into N windows of
            // the shared fastScopeViewMs width and the ‹ › arrows step through them, opening at the
            // first frame. Same window width as the scope above, so both stacked plots match.
            x: {
                time: false,
                auto: false,
                range: () => faFlipFrameRange()
            },
            amps: { auto: true }
        },
        axes: [
            { label: "Milliseconds", grid: { show: true } },
            { scale: "amps", label: "Amperes", grid: { show: true }, side: 3 }
        ],
        legend: { show: false }
    }, [[], []], plotEl);
    if (document.body.classList.contains('dark-mode')) updateUplotTheme(fastFlipPlot);

    // Per-page Y-axis controls — same auto / lock / click-to-edit widget as the other plots,
    // but each flipbook slot remembers its own state for the session (faFlipAxis keyed by slot).
    // The waveform is absolute current (not AC-coupled), so each page sits at its own DC level
    // and is auto-fit independently rather than sharing one scale.
    plotEl.style.position = 'relative';
    const existing = plotEl.querySelector('.autoscale-ctrl');
    if (existing) existing.remove();
    const ctrl = document.createElement('div');
    ctrl.className = 'autoscale-ctrl';
    ctrl.style.cssText = 'position:absolute;top:6px;right:8px;z-index:10;display:flex;flex-direction:column;align-items:flex-end;gap:2px;font-size:11px;';
    ctrl.innerHTML = '<button id="faflip-pause-btn" title="Pause — stop new fault snapshots from overwriting the saved ones" style="font-size:10px;padding:0 6px;cursor:pointer;border:1px solid #999;border-radius:2px;background:transparent;line-height:16px;" onclick="faAnomPauseToggle()">Pause</button><div style="display:flex;align-items:center;gap:3px;opacity:0.6;"><input type="checkbox" id="faflip-auto-cb" style="cursor:pointer;width:12px;height:12px;margin:0;"><label for="faflip-auto-cb" style="cursor:pointer;user-select:none;">auto</label></div><button id="faflip-lock-btn" style="display:none;font-size:10px;padding:0 5px;cursor:pointer;border:1px solid #999;border-radius:2px;background:transparent;opacity:0.6;line-height:16px;">lock</button>';
    plotEl.appendChild(ctrl);
    faUpdatePauseBtn(_faAnomPause);  // reflect last-known pause state on (re)build

    // On-plot frame paging — ‹ prev / next › arrows + "Frame n / N" label, top-left so they clear
    // the Pause/auto/lock cluster top-right. Hidden whenever the page is a single frame (200 ms).
    const existingNav = plotEl.querySelector('#faflip-nav');
    if (existingNav) existingNav.remove();
    const nav = document.createElement('div');
    nav.id = 'faflip-nav';
    nav.style.cssText = 'position:absolute;top:6px;left:8px;z-index:10;display:none;align-items:center;gap:5px;font-size:11px;';
    const btnCss = 'font-size:13px;line-height:16px;padding:0 7px;cursor:pointer;border:1px solid #999;border-radius:2px;background:transparent;';
    nav.innerHTML = '<button id="faflip-prev" title="Previous frame" style="' + btnCss + '" onclick="faFlipStep(-1)">‹</button><span id="faflip-frame-label" style="color:#888;user-select:none;">Frame 1 / 1</span><button id="faflip-next" title="Next frame" style="' + btnCss + '" onclick="faFlipStep(1)">›</button>';
    plotEl.appendChild(nav);

    document.getElementById('faflip-auto-cb').addEventListener('change', e => {
        const st = faFlipAxisState(fastFlipSelected);
        st.auto = e.target.checked;
        if (!st.auto) { const sc = fastFlipPlot.scales.amps; st.min = sc.min; st.max = sc.max; }  // seed manual from what's shown
        st.locked = false;
        faFlipApplyAxis(fastFlipSelected);
        faFlipSyncControls(fastFlipSelected);
    });
    document.getElementById('faflip-lock-btn').addEventListener('click', () => {
        const st = faFlipAxisState(fastFlipSelected);
        if (!st.auto) return;               // lock only applies while auto is on
        st.locked = !st.locked;
        if (st.locked) { const sc = fastFlipPlot.scales.amps; st.min = sc.min; st.max = sc.max; }  // freeze current auto range
        faFlipApplyAxis(fastFlipSelected);
        faFlipSyncControls(fastFlipSelected);
    });

    attachYAxisEdit(fastFlipPlot, [{
        scale: 'amps', decimals: 1,
        apply: (mn, mx) => {                 // typing a number → manual for this page only (the auto checkbox is the way back)
            const st = faFlipAxisState(fastFlipSelected);
            st.auto = false; st.locked = false; st.min = mn; st.max = mx;
            faFlipApplyAxis(fastFlipSelected);
            faFlipSyncControls(fastFlipSelected);
        }
    }]);
}

function faFlipAxisState(slot) {
    if (!faFlipAxis[slot]) faFlipAxis[slot] = { auto: true, locked: false, min: null, max: null };
    return faFlipAxis[slot];
}

function faFlipApplyAxis(slot) {
    if (!fastFlipPlot) return;
    const st = faFlipAxisState(slot);
    if (st.auto && !st.locked) {             // auto-fit to this page's own data
        const pg = fastFlipPages && fastFlipPages[slot];
        let lo = Infinity, hi = -Infinity;
        if (pg && pg.amps_t) for (const v of pg.amps_t) { if (v < lo) lo = v; if (v > hi) hi = v; }
        if (!isFinite(lo)) { lo = 0; hi = 1; }
        const pad = Math.max(1, (hi - lo) * 0.1);
        fastFlipPlot.setScale('amps', { min: lo - pad, max: hi + pad });
    } else if (isFinite(st.min) && isFinite(st.max) && st.max > st.min) {
        fastFlipPlot.setScale('amps', { min: st.min, max: st.max });
    }
}

function faFlipSyncControls(slot) {
    const autoCb = document.getElementById('faflip-auto-cb');
    const lockBtn = document.getElementById('faflip-lock-btn');
    if (!autoCb || !lockBtn) return;
    const st = faFlipAxisState(slot);
    autoCb.checked = st.auto;
    lockBtn.style.display = st.auto ? 'block' : 'none';
    lockBtn.textContent = st.locked ? 'unlock' : 'lock';
    lockBtn.style.opacity = st.locked ? '1' : '0.6';
}

function fastFlipRender(slot) {
    if (!fastFlipPages) return;
    const pg = fastFlipPages[slot];
    if (!pg || !pg.used) return;
    fastFlipSelected = slot;
    faFlipFrame = 0;   // new page always opens on the first frame
    document.querySelectorAll('.fastflip-band').forEach(b => b.classList.toggle('active', +b.dataset.slot === slot));
    const meta = document.getElementById('fastflip-meta');
    if (meta) {
        // > 2020 guard (not just truthy): legacy pages froze before the libc clock was set and
        // hold a small non-zero epoch that would render as 1/1/1970 — show "clock not set" instead.
        const when = pg.epoch > 1577836800 ? new Date(pg.epoch * 1000).toLocaleDateString() : 'clock not set';
        // Band 0 reads "100–1000" (engines don't idle below ~100 RPM); higher bands span full 1000-RPM ranges
        const bandLabel = pg.band === 0 ? '100–1000' : (pg.band * 1000) + '–' + (pg.band * 1000 + 999);
        meta.textContent = (pg.isAnomaly
            ? 'Anomaly capture (class k=' + pg.patternK + ', score ' + pg.score.toFixed(2) + ')'
            : 'Reference, ' + bandLabel + ' RPM band')
            + ' — captured at ' + pg.rpm + ' RPM, ' + pg.amps.toFixed(1) + ' A, ' + when + '.';
    }
    initFastFlipPlot();
    if (fastFlipPlot) {
        // Re-fit to the real container width every render. The plot is built once (often while the
        // Diag tab is still hidden, so clientWidth was 0 → it fell back to the tiny 360 px default
        // and stayed stuck narrow). The scope above it does the same setSize on tab open; matching
        // it here keeps the two stacked charts the same size. Height matches the scope (300).
        const fpEl = document.getElementById('fastflip-plot');
        const w = Math.min((fpEl && fpEl.clientWidth) || 360, 800);
        if (fastFlipPlot.width !== w || fastFlipPlot.height !== 300) fastFlipPlot.setSize({ width: w, height: 300 });
        fastFlipPlot.setData([pg.t_ms, pg.amps_t, pg.filt_t]);
        faFlipApplyAxis(slot);
        faFlipSyncControls(slot);
        faFlipUpdateNav();
    }
}

function fastFlipBuildButtons() {
    const wrap = document.getElementById('fastflip-bands');
    const anomWrap = document.getElementById('fastflip-anoms');
    if (!wrap || !fastFlipPages) return;
    wrap.innerHTML = '';
    if (anomWrap) anomWrap.innerHTML = '';
    const nRef = fastFlipPages.filter(p => p.isRef).length;   // ref-slot count straight from the payload header
    fastFlipPages.forEach(pg => {
        const b = document.createElement('button');
        b.type = 'button';
        // Both rows share the same class — only one button is ever .active (green) across both,
        // because fastFlipRender toggles it on every .fastflip-band by matching slot.
        b.className = 'btn-secondary btn-sm fastscope-zoom fastflip-band';
        b.dataset.slot = pg.slot;
        if (pg.isRef) {
            // Band 0 reads "100–1000 RPM" (engines don't idle below ~100); higher bands "N–N+1k RPM"
            b.textContent = pg.band === 0 ? '100–1000 RPM' : pg.band + '–' + (pg.band + 1) + 'k RPM';
        } else {
            b.textContent = 'Anomaly ' + (pg.slot - nRef);
        }
        if (!pg.used) {
            b.disabled = true;
            b.style.opacity = '0.4';
            b.title = pg.isRef ? 'No steady run captured in this band yet' : 'Empty anomaly slot';
        } else {
            b.onclick = () => fastFlipRender(pg.slot);
        }
        (pg.isRef ? wrap : (anomWrap || wrap)).appendChild(b);
    });
}

// auto=true is the silent background poll (from the Diag auto-loop): it refreshes the page
// buttons so freshly-frozen reference bands light up on their own, but never flashes the
// status line and never yanks the plot away from a page you're currently examining. Manual
// Refresh / open / re-baseline call it without auto, so they always re-render.
function fetchFastFlip(auto) {
    const status = document.getElementById('fastflip-status');
    if (status && !auto) status.textContent = 'Fetching…';
    fetch(buildURL('/faflip.bin'), { cache: 'no-cache' })
        .then(r => { if (!r.ok) throw new Error('http ' + r.status); return r.arrayBuffer(); })
        .then(buf => {
            fastFlipPages = parseFastFlip(buf);
            if (!fastFlipPages) { if (status && !auto) status.textContent = 'Bad response from regulator.'; return; }
            const nUsed = fastFlipPages.filter(p => p.used).length;
            if (status) status.textContent = nUsed === 0
                ? 'No pages captured yet — references freeze automatically on steady runs (20–100 A).'
                : nUsed + ' page' + (nUsed > 1 ? 's' : '') + ' captured.';
            fastFlipBuildButtons();
            const cur = (fastFlipSelected >= 0) ? fastFlipPages.find(p => p.slot === fastFlipSelected && p.used) : null;
            if (!(auto && cur)) {   // auto poll leaves an open page alone; otherwise show the selected-or-first used page
                const first = cur || fastFlipPages.find(p => p.used);
                if (first) {
                    fastFlipRender(first.slot);
                } else {
                    // Nothing left to show (e.g. just re-baselined and no anomaly captures kept): wipe the
                    // chart instead of leaving the now-deleted reference waveform painted on screen.
                    fastFlipSelected = -1;
                    document.querySelectorAll('.fastflip-band').forEach(b => b.classList.remove('active'));
                    const meta = document.getElementById('fastflip-meta');
                    if (meta) meta.textContent = '';
                    if (fastFlipPlot) fastFlipPlot.setData([[], [], []]);
                }
            } else {
                // Buttons were just rebuilt (highlight cleared) but we skipped the re-render — re-mark the open page.
                document.querySelectorAll('.fastflip-band').forEach(b => b.classList.toggle('active', +b.dataset.slot === fastFlipSelected));
            }
        })
        .catch(e => { if (status && !auto) status.textContent = 'Flipbook unavailable (' + e.message + ').'; });
}

// ════════════ Battery Health (active DCIR test + capacity-vs-cycles trend) ════════════
function bhSet(id, t) { const e = document.getElementById(id); if (e) e.textContent = t; }

// DCIR normalized to a 25°C (77°F) reference. Resistance rises as the bank cools, so a cold run
// reads high; this brings every row onto a common footing so the trend isn't just temperature.
// Board temp is a warm-biased proxy, so this is an APPROXIMATE correction (same model as the
// battery-temp CV-gain derate). ~0.6%/°F ≈ 1%/°C.
const BH_TREF_F = 77, BH_TEMPCO_PER_F = 0.006;
function bhDcir25(dcir, tF) {
  if (!(dcir > 0) || !isFinite(tF)) return null;
  return dcir * Math.exp(BH_TEMPCO_PER_F * (tF - BH_TREF_F));
}

function bhWhen(epoch) {
  if (!epoch || epoch < 1000000000) return '—';   // 0 = clock not synced when the test ran
  const d = new Date(epoch * 1000);
  return (d.getMonth() + 1) + '/' + d.getDate() + ' ' +
    String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
}

// ════════ Battery-health DCIR test wizard (mirrors the commissioning modal) ════════
// Three panes — precheck → running (live countdown) → result — driven off the /batteryHealth
// poll. The run itself, and the protection-drop during it, are firmware-side; this only walks
// the user through it. Countdown uses firmware totalMs/elapsedMs so a reopened modal recomputes
// remaining without a client-side start-time it would lose on close.
let bhw = null;   // { pane:'pre'|'run'|'done', renderedPane, startedAt, j, poll }

function bhwGet(params) {
  const pw = encodeURIComponent(currentAdminPassword || '');
  return fetch(buildURL('/get?' + params + '&password=' + pw));
}
// Live precheck snapshot — RPM/voltage/alt-current off CSV1 (via cxLive), AUTO bit off CSV2
// thermalFlags, battery shunt + Bcur off CSV3/CSV1.
function bhwLive() {
  const L = cxLive();
  const c1 = (typeof g_lastCsv1 === 'object' && g_lastCsv1) ? g_lastCsv1 : {};
  const c2 = (typeof g_lastCsv2 === 'object' && g_lastCsv2) ? g_lastCsv2 : {};
  const c3 = (typeof g_lastCsv3 === 'object' && g_lastCsv3) ? g_lastCsv3 : {};
  const auto = ((parseInt(c2.thermalFlags) || 0) & (1 << 4)) !== 0;
  const battSrc = ('BatteryCurrentSource' in c3) ? parseInt(c3.BatteryCurrentSource, 10) : 0;  // 0 = INA228
  const shuntR = ('ShuntResistanceMicroOhm' in c3) ? parseFloat(c3.ShuntResistanceMicroOhm) : 0;
  const bcur = ('Bcur' in c1 && c1.Bcur !== '' && c1.Bcur != null) ? parseFloat(c1.Bcur) / 100 : NaN;
  return { rpm: L.rpm, alt: L.amps, bcur, auto, shuntOk: (battSrc === 0 && shuntR > 0) };
}

function bhwOpen() {
  if (!bhw) bhw = { pane: 'pre', renderedPane: null, startedAt: 0, j: null, poll: null };
  bhw.renderedPane = null;   // force a full pane rebuild on (re)open
  document.getElementById('bhw-modal-overlay').style.display = 'block';
  makePanelDraggable(document.getElementById('bhw-modal-panel'),
                     document.getElementById('bhw-drag-handle'));
  // Resume: if a run is already live, jump straight to the running pane and back-date the start.
  fetch(buildURL('/batteryHealth')).then(r => r.json()).then(j => {
    bhw.j = j;
    bhw.pane = (j.state === 1) ? 'run' : 'pre';
    if (j.state === 1) bhw.startedAt = Date.now() - (j.elapsedMs || 0);
    bhwRender();
  }).catch(() => { bhw.pane = 'pre'; bhwRender(); });
  if (bhw.poll) clearInterval(bhw.poll);
  bhw.poll = setInterval(bhwPoll, 1000);
}

function bhwClose() {
  if (bhw && bhw.poll) { clearInterval(bhw.poll); bhw.poll = null; }
  document.getElementById('bhw-modal-overlay').style.display = 'none';
  // Refresh the underlying Health panel so a freshly-finished run's row/headline updates.
  if (typeof pollBatteryHealth === 'function') pollBatteryHealth();
}

function bhwPoll() {
  return fetch(buildURL('/batteryHealth')).then(r => r.json()).then(j => {
    bhw.j = j;
    if (bhw.pane === 'pre' && j.state === 1) { bhw.startedAt = Date.now() - (j.elapsedMs || 0); bhw.pane = 'run'; }
    if (bhw.pane === 'run' && (j.state === 2 || j.state === 3)) bhw.pane = 'done';
    bhwRender();
  }).catch(() => { });
}

function bhwStart() {
  const btn = document.getElementById('bhw-start-btn');
  if (btn) btn.disabled = true;   // prevent double-fire; bhwPoll flips to the run pane once state==1
  bhwGet('BatteryHealthTest=1').then(() => setTimeout(bhwPoll, 400)).catch(e => xAlert('Start failed: ' + e));
}
function bhwAbort() { bhwGet('bhAbort=1').then(() => setTimeout(bhwPoll, 300)).catch(() => { }); }
function bhwRestart() { bhw.pane = 'pre'; bhw.startedAt = 0; bhw.renderedPane = null; bhwRender(); }

function bhwRender() {
  if (!bhw) return;
  const b = document.getElementById('bhw-body');
  if (!b) return;
  if (bhw.renderedPane !== bhw.pane) {        // pane changed — rebuild the shell once
    bhw.renderedPane = bhw.pane;
    if (bhw.pane === 'pre') bhwRenderPre(b);
    else if (bhw.pane === 'run') bhwRenderRun(b);
    else bhwRenderDone(b);
  } else {                                     // same pane — light in-place refresh only (no flicker)
    if (bhw.pane === 'pre') bhwPrePrecheck();
    else if (bhw.pane === 'run') bhwRunRefresh();
    // 'done' is static
  }
}

function bhwRenderPre(b) {
  const j = bhw.j || {};
  const low = (j.low != null) ? j.low : 30, delta = (j.delta != null) ? j.delta : 30;
  const totalS = Math.round(((j.totalMs != null) ? j.totalMs : ((j.edges || 4) + 3) * (j.dwellMs || 8000)) / 1000);
  b.innerHTML =
    '<p style="font-size:15px;line-height:1.5;"><strong>Measure the battery\'s internal resistance.</strong> The regulator briefly raises and lowers the alternator output a few times and watches how far the battery voltage moves.</p>' +
    '<div style="margin:10px 0; padding:8px 10px; background:#222; border-radius:6px; font-size:13px; line-height:1.7;">' +
    '<div>Engine: <span id="bhw-pre-rpm">…</span></div>' +
    '<div>Mode: <span id="bhw-pre-mode">…</span></div>' +
    '<div>Battery shunt: <span id="bhw-pre-shunt">…</span></div>' +
    '</div>' +
    '<div style="margin:10px 0;padding:8px 10px;background:#1b2a1b;border:1px solid #356b35;border-radius:6px;font-size:12px;color:#bcd;line-height:1.5;">' +
    'Output will swing between <strong>' + low.toFixed(0) + ' A</strong> and <strong>' + (low + delta).toFixed(0) + ' A</strong> over about <strong>' + totalS + ' s</strong>. <strong>Stay clear of belts and the alternator.</strong> Over-current limits are relaxed during the test so your settings can\'t spoil it; fast over-voltage and the hardware cutoff stay active.' +
    '</div>' +
    '<div id="bhw-pre-fail"></div>' +
    '<button id="bhw-start-btn" onclick="bhwStart()" class="btn-primary" style="width:100%;padding:9px;margin-top:6px;" disabled>Start test</button>';
  bhwPrePrecheck();
}
// Live Prep precheck — mirrors bhStartTest()'s gates (engine running, AUTO, INA228 shunt). The
// firmware is the final authority: if Start fails anyway, j.reason surfaces in #bhw-pre-fail.
function bhwPrePrecheck() {
  if (!bhw || bhw.pane !== 'pre') return;
  const v = bhwLive(), j = bhw.j || {};
  const rpmEl = document.getElementById('bhw-pre-rpm');
  const modeEl = document.getElementById('bhw-pre-mode');
  const shEl = document.getElementById('bhw-pre-shunt');
  const failEl = document.getElementById('bhw-pre-fail');
  const btn = document.getElementById('bhw-start-btn');
  if (!rpmEl || !btn) return;
  const engineOk = !isNaN(v.rpm) && v.rpm > 100;
  rpmEl.innerHTML = isNaN(v.rpm) ? '<span style="color:#f0a500;">no RPM — start the engine</span>'
    : '<strong style="color:' + (engineOk ? '#5a5' : '#f0a500') + ';">' + Math.round(v.rpm) + ' RPM</strong>' + (engineOk ? '' : ' (start the engine)');
  if (modeEl) modeEl.innerHTML = v.auto ? '<strong style="color:#5a5;">AUTO</strong>'
    : '<span style="color:#f0a500;">not in AUTO — switch the system to Auto</span>';
  if (shEl) shEl.innerHTML = v.shuntOk ? '<strong style="color:#5a5;">INA228 shunt OK</strong>'
    : '<span style="color:#f0a500;">no INA228 battery shunt — the test needs the battery-current shunt</span>';
  if (failEl) failEl.innerHTML = (j.state === 0 && j.reason) ?
    '<div style="margin:8px 0;padding:8px 10px;background:#3a2222;border:1px solid #a55;border-radius:6px;color:#f0a500;font-size:13px;">Could not start: <strong>' + j.reason + '</strong></div>' : '';
  btn.disabled = !(engineOk && v.auto && v.shuntOk);
}

function bhwRenderRun(b) {
  b.innerHTML =
    '<p style="font-size:15px;"><strong>Test running</strong> — keep the engine running and steady.</p>' +
    '<div style="text-align:center;margin:14px 0;">' +
    '<div id="bhw-cd" style="font-size:34px;font-weight:700;color:#2ec4b6;line-height:1;">…</div>' +
    '<div style="font-size:12px;color:#888;margin-top:2px;">remaining</div></div>' +
    '<div style="height:8px;background:#333;border-radius:4px;overflow:hidden;margin:10px 0;"><i id="bhw-bar" style="display:block;height:100%;width:0%;background:#2ec4b6;transition:width 0.6s linear;"></i></div>' +
    '<div id="bhw-step" style="font-size:12px;color:#999;text-align:center;">—</div>' +
    '<div style="margin:12px 0 6px;padding:8px 10px;background:#222;border-radius:6px;font-size:13px;line-height:1.7;">' +
    '<div>Alternator current: <span id="bhw-alt">—</span></div>' +
    '<div>Battery current: <span id="bhw-bcur">—</span></div></div>' +
    '<button onclick="bhwAbort()" class="btn-danger-ghost btn-sm" style="width:100%;margin-top:8px;">Abort test</button>';
  bhwRunRefresh();
}
function bhwRunRefresh() {
  const j = bhw.j || {};
  const total = (j.totalMs != null && j.totalMs > 0) ? j.totalMs : (((j.edges || 4) + 3) * (j.dwellMs || 8000));
  const elapsed = bhw.startedAt ? (Date.now() - bhw.startedAt) : (j.elapsedMs || 0);
  const remain = Math.max(0, total - elapsed);
  const cd = document.getElementById('bhw-cd'); if (cd) cd.textContent = Math.ceil(remain / 1000) + 's';
  const bar = document.getElementById('bhw-bar'); if (bar) bar.style.width = Math.min(100, total > 0 ? (elapsed / total * 100) : 0).toFixed(0) + '%';
  const toggles = (j.edges || 4) + 3, stepN = Math.min(toggles, Math.floor(elapsed / (j.dwellMs || 3000)) + 1);
  const stepEl = document.getElementById('bhw-step'); if (stepEl) stepEl.textContent = 'Current level ' + stepN + ' of ' + toggles;
  const v = bhwLive();
  const altEl = document.getElementById('bhw-alt'); if (altEl) altEl.textContent = isNaN(v.alt) ? '—' : v.alt.toFixed(1) + ' A';
  const bcEl = document.getElementById('bhw-bcur'); if (bcEl) bcEl.textContent = isNaN(v.bcur) ? '—' : v.bcur.toFixed(1) + ' A';
}

function bhwRenderDone(b) {
  const j = bhw.j || {};
  const res = (j.results && j.results.length) ? j.results[j.results.length - 1] : null;
  let html;
  if (j.state === 3) {
    html = '<div style="margin:6px 0;padding:10px 12px;background:#3a2222;border:1px solid #a55;border-radius:6px;color:#f0a500;">' +
      '<strong>Test aborted</strong>' + (j.reason ? '<br><span style="font-size:13px;color:#caa;">' + j.reason + '</span>' : '') + '</div>';
  } else if (res) {
    const dcir25 = bhDcir25(res.dcir, res.tF);
    const cv = (res.dcir > 0 && isFinite(res.spread)) ? (res.spread / res.dcir) : 1;   // mirror the history-table fit test
    const fitOk = cv <= 0.10 && res.edges >= 3;
    const isBase = (j.results.length === 1);
    html = '<p style="font-size:15px;"><strong>Done.</strong></p>' +
      '<div style="margin:10px 0;padding:10px 12px;background:#1b2a1b;border:1px solid #356b35;border-radius:6px;line-height:1.8;">' +
      '<div style="font-size:24px;font-weight:700;color:#2ec4b6;">' + res.dcir.toFixed(2) + ' mΩ</div>' +
      '<div style="font-size:13px;color:#bcd;">' + dcir25.toFixed(2) + ' mΩ at 25 °C · fit ' + (fitOk ? '<span style="color:#5a5;">✓</span>' : '<span style="color:#f0a500;">⚠</span>') + ' · ' + res.edges + ' steps</div>' +
      (isBase ? '<div style="font-size:12px;color:#9b9;margin-top:4px;">Stored as the 100% baseline.</div>' : '') + '</div>' +
      '<div style="font-size:12px;color:#888;line-height:1.5;">Internal resistance depends on temperature and state of charge — compare runs taken at a similar state of charge. The full history is on the Health panel.</div>';
  } else {
    html = '<p>Test finished — see the Health panel for the result.</p>';
  }
  html += '<div style="display:flex;gap:10px;margin-top:14px;">' +
    '<button onclick="bhwRestart()" class="btn-secondary" style="flex:1;">Run again</button>' +
    '<button onclick="bhwClose()" class="btn-primary" style="flex:1;">Close</button></div>';
  b.innerHTML = html;
}

function pollBatteryHealth() {
  if (!document.getElementById('bh_status')) return;
  return fetch(buildURL('/batteryHealth')).then(r => r.json()).then(j => {
    const states = { 0: 'Idle', 1: 'Running test…', 2: 'Done', 3: 'Aborted' };
    let s = states[j.state] || '—';
    if (j.state === 3 && j.reason) s += ' — ' + j.reason;
    bhSet('bh_status', s);
    bhSet('bh_lastdcir', (j.lastDcir && j.lastDcir > 0) ? (j.lastDcir.toFixed(2) + ' mΩ') : '—');
    bhSet('bhStepLowA_echo', j.low.toFixed(1) + ' A');
    bhSet('bhStepDeltaA_echo', j.delta.toFixed(1) + ' A');
    bhSet('bhDwellSec_echo', (j.dwellMs / 1000).toFixed(1) + ' s');
    bhSet('bhNumEdges_echo', String(j.edges));

    const tb = document.getElementById('bhResultsBody');
    if (tb) {
      if (!j.results || j.results.length === 0) {
        tb.innerHTML = '<tr><td colspan="13" style="text-align:center; opacity:0.7;">No tests yet</td></tr>';
      } else {
        // Oldest row (results[0]) is the baseline; compare temp-corrected to temp-corrected.
        const base25 = bhDcir25(j.results[0].dcir, j.results[0].tF);
        let rows = '';
        for (let i = j.results.length - 1; i >= 0; i--) {   // newest first
          const r = j.results[i];
          const d25 = bhDcir25(r.dcir, r.tF);
          const dV = r.dcir * r.delta;                       // mΩ × A = mV (the raw sag the DCIR came from)
          let baseCell;
          if (i === 0) baseCell = '<span style="opacity:0.7;">base</span>';
          else if (base25 && d25) {
            const pct = (d25 - base25) / base25 * 100;
            baseCell = '<span style="color:' + (pct > 0 ? '#ff9800' : '#4caf50') + '">' +
              (pct >= 0 ? '+' : '') + pct.toFixed(1) + '%</span>';
          } else baseCell = '—';
          // Fit quality: spread of the per-edge DCIR relative to the value. Tight + enough edges = trustworthy.
          const cv = (r.dcir > 0 && isFinite(r.spread)) ? (r.spread / r.dcir) : 1;
          const fitOk = cv <= 0.10 && r.edges >= 3;
          const fitCell = '<td style="color:' + (fitOk ? '#4caf50' : '#ff9800') + '" title="edge spread ±' +
            (isFinite(r.spread) ? r.spread.toFixed(2) : '?') + ' mΩ (' + (cv * 100).toFixed(0) + '%), ' +
            r.edges + ' edges">' + (fitOk ? '✓' : '⚠') + '</td>';
          rows += '<tr>' +
            '<td>' + bhWhen(r.epoch) + '</td>' +
            '<td>' + r.dcir.toFixed(2) + '</td>' +
            '<td>' + (d25 ? d25.toFixed(2) : '—') + '</td>' +
            '<td>' + baseCell + '</td>' +
            fitCell +
            '<td>' + dV.toFixed(0) + '</td>' +
            '<td>' + r.delta.toFixed(0) + '</td>' +
            '<td>' + (r.dwell ? (r.dwell / 1000).toFixed(1) : '—') + '</td>' +
            '<td>' + r.soc.toFixed(0) + '%</td>' +
            '<td>' + r.v.toFixed(2) + '</td>' +
            '<td>' + r.tF.toFixed(0) + '</td>' +
            '<td>' + r.low.toFixed(0) + '→' + (r.low + r.delta).toFixed(0) + 'A</td>' +
            '<td>' + r.edges + '</td></tr>';
        }
        tb.innerHTML = rows;
      }
    }

    // Capacity (OCV-anchored, date-based)
    const cap = j.cap || [];
    drawBhCapDate(cap);
    const latest = cap.length ? cap[cap.length - 1] : null;
    bhSet('bh_capheadline', latest ? (latest.pct.toFixed(0) + '%  (' + latest.ah.toFixed(0) + ' Ah)') : 'awaiting first deep cycle');
    let st = '';
    if (j.capLastUpd) st += 'last updated ' + bhWhen(j.capLastUpd) + ' · ';
    st += j.capAnchored
      ? ('low anchor held at ' + (Number(j.capAnchorSoC) || 0).toFixed(0) + '% — waiting for a full charge')
      : ('no low anchor yet · resting ' + (j.capRestMin || 0) + ' min, dV/dt ' + (Number(j.capDvdt) || 0).toFixed(1) + ' mV/10min');
    bhSet('bh_capstatus', st);
    const empty = document.getElementById('bh_capempty');
    if (empty) empty.style.display = cap.length ? 'none' : 'block';

    // capacity config echoes
    const cfg = j.capCfg || {};
    bhSet('capBankAh_echo', cfg.capacityAh + ' Ah');
    bhSet('capRefMode_echo', cfg.refMode == 1 ? '1 (first reading)' : '0 (rated)');
    bhSet('capRestFrac_echo', cfg.restFrac);
    bhSet('capRestFloor_echo', cfg.restFloor + ' min');
    bhSet('capSettleRate_echo', cfg.settleRate + ' mV/10min');
    bhSet('capSocLowMax_echo', cfg.socLowMax + '%');
    bhSet('capFullSoc_echo', cfg.fullSoc + '%');
    bhSet('capMinSpan_echo', cfg.minSpan + '%');
    bhSet('capChgEff_echo', (Number(cfg.chgEff) * 100).toFixed(1) + '%');
    bhSet('capTempNorm_echo', cfg.tempNorm == 1 ? 'on' : 'off');
    bhSet('capTempCoeff_echo', cfg.tempCoeff + ' %/°C');
    bhSet('capTempRef_echo', cfg.tempRef + ' °C');
    if (j.ocv && j.ocvSoc) renderCapOcvTable(j.ocv, j.ocvSoc);
  }).catch(() => { });
}

// Capacity health plot (uPlot, house style): X = date, Y = capacity %. Filled dot = high
// confidence, hollow = low. Dashed connector only — the gaps between points are real (weeks apart).
let bhCapPlot = null;
let bhCapPts = [];
let bhCapYManual = null;
try { bhCapYManual = JSON.parse(localStorage.getItem('bhCapY') || 'null'); } catch (e) { }

function bhCapData() {
  const xs = [], all = [], hi = [], lo = [];
  for (const p of bhCapPts) {
    xs.push(p.epoch || 0);
    all.push(p.pct);
    hi.push(p.conf ? p.pct : null);
    lo.push(p.conf ? null : p.pct);
  }
  return [xs, all, hi, lo];
}

function bhCapYRange() {
  if (bhCapYManual) return bhCapYManual;
  let mn = Infinity, mx = -Infinity;
  for (const p of bhCapPts) { if (p.pct < mn) mn = p.pct; if (p.pct > mx) mx = p.pct; }
  if (!isFinite(mn)) return [80, 105];
  mn = Math.min(mn, 80); mx = Math.max(mx, 100);
  const pad = Math.max(1, (mx - mn) * 0.08);
  return [mn - pad, mx + pad];
}

function buildBhCapPlot() {
  const el = document.getElementById('bhCapPlot');
  if (!el || typeof uPlot === 'undefined') return;
  el.innerHTML = '';
  el.style.position = 'relative';
  const opts = {
    width: Math.max(el.clientWidth, 320),
    height: 220,
    padding: [30, 8, 0, 0],   // top inset clears the auto checkbox
    series: [
      { label: 'date' },
      { label: 'capacity', stroke: 'rgba(58,123,213,0.5)', width: 1, dash: [4, 4], points: { show: false } },
      { label: 'measured', stroke: '#3a7bd5', paths: () => null, points: { show: true, size: 7, stroke: '#3a7bd5', width: 1.5, fill: '#3a7bd5' } },
      { label: 'low confidence', stroke: '#3a7bd5', paths: () => null, points: { show: true, size: 7, stroke: '#3a7bd5', width: 1.5, fill: '#fff' } },
    ],
    scales: {
      y: { auto: false, range: () => bhCapYRange() },
    },
    axes: [
      { grid: { show: true } },
      { scale: 'y', grid: { show: true }, side: 3, values: (u, t) => t.map(v => v + '%') },
    ],
    legend: { show: false },
    cursor: { drag: { x: false, y: false } },
    hooks: {
      draw: [u => {
        const y = u.valToPos(100, 'y', true);   // 100% baseline reference
        if (y >= u.bbox.top && y <= u.bbox.top + u.bbox.height) {
          const ctx = u.ctx; ctx.save();
          ctx.strokeStyle = '#cde'; ctx.setLineDash([4, 4]);
          ctx.beginPath(); ctx.moveTo(u.bbox.left, y); ctx.lineTo(u.bbox.left + u.bbox.width, y); ctx.stroke();
          ctx.restore();
        }
      }]
    }
  };
  bhCapPlot = new uPlot(opts, bhCapData(), el);
  new ResizeObserver(() => {
    if (bhCapPlot) bhCapPlot.setSize({ width: Math.max(el.clientWidth, 320), height: 220 });
  }).observe(el);
  const asDiv = document.createElement('div');
  asDiv.className = 'autoscale-ctrl';
  asDiv.style.cssText = 'position:absolute;top:6px;right:8px;z-index:10;display:flex;align-items:center;gap:3px;font-size:11px;opacity:0.6;';
  asDiv.innerHTML = '<input type="checkbox" id="autoscale-bhcap-cb" style="cursor:pointer;width:12px;height:12px;margin:0;"><label for="autoscale-bhcap-cb" style="cursor:pointer;user-select:none;">auto</label>';
  el.appendChild(asDiv);
  const asCb = document.getElementById('autoscale-bhcap-cb');
  asCb.checked = (bhCapYManual == null);
  asCb.addEventListener('change', e => {
    if (e.target.checked) { bhCapYManual = null; localStorage.removeItem('bhCapY'); }
    else if (bhCapPlot) { bhCapYManual = [bhCapPlot.scales.y.min, bhCapPlot.scales.y.max]; localStorage.setItem('bhCapY', JSON.stringify(bhCapYManual)); }
    if (bhCapPlot) bhCapPlot.redraw();
  });
  attachYAxisEdit(bhCapPlot, [{
    scale: 'y', decimals: 0,
    apply: (mn, mx) => { bhCapYManual = [mn, mx]; asCb.checked = false; localStorage.setItem('bhCapY', JSON.stringify(bhCapYManual)); bhCapPlot.redraw(); }
  }]);
}

function drawBhCapDate(pts) {
  bhCapPts = pts || [];
  if (!document.getElementById('bhCapPlot')) return;
  if (!bhCapPlot) { buildBhCapPlot(); if (!bhCapPlot) return; }
  bhCapPlot.setData(bhCapData());
}

const CAP_OCV_DEFAULT = [13.6, 13.4, 13.3, 13.2, 13.1, 13.0, 12.9, 12.8, 12.5, 12.0, 10.0];
function renderCapOcvTable(volts, socs) {
  const tb = document.getElementById('capOcvBody');
  if (!tb) return;
  if (tb.children.length !== volts.length) {   // build once; don't clobber the user's typing each poll
    let html = '';
    for (let i = 0; i < volts.length; i++) {
      const knee = socs[i] <= 20;
      html += '<tr' + (knee ? ' style="font-weight:600;"' : '') + '><td>' + socs[i] + (knee ? ' ◀' : '') + '</td>' +
        '<td><input id="capOcv_' + i + '" type="number" step="0.01" style="width:80px;" value="' + Number(volts[i]).toFixed(2) + '"></td></tr>';
    }
    tb.innerHTML = html;
  }
}
function submitCapOcv() {
  const tb = document.getElementById('capOcvBody');
  if (!tb) return;
  const vals = [];
  for (let i = 0; i < tb.children.length; i++) { const el = document.getElementById('capOcv_' + i); if (el) vals.push(Number(el.value).toFixed(3)); }
  const pw = document.querySelector('.password_field');
  fetch(buildURL('/get?capOcv=' + encodeURIComponent(vals.join(',')) + '&password=' + encodeURIComponent(pw ? pw.value : '')))
    .then(() => setTimeout(pollBatteryHealth, 500)).catch(() => { });
}
function loadCapOcvDefaults() {
  for (let i = 0; i < CAP_OCV_DEFAULT.length; i++) { const el = document.getElementById('capOcv_' + i); if (el) el.value = CAP_OCV_DEFAULT[i].toFixed(2); }
}

// Poll only when the Health section is on-screen (sub-tab active AND details open).
setInterval(() => {
  const e = document.getElementById('bh_status');
  if (e && e.offsetParent !== null) pollBatteryHealth();
}, 3000);

// ── Resonance & Ripple Map heatmap (Live Data → Diag) ──
// Fixed learnable envelope (500–4000 RPM × 5–105 A) so a fresh device reads as a
// mostly-empty map that fills in over time; extends if learned cells fall outside.
let rippleMapCells = null;
let rippleMapHover = null;
let rippleMapObsHooked = false;
const RIPPLEMAP_RAMP_LIGHT = ['#e4f4f3', '#b9e2e0', '#8bcfcc', '#59b8b3', '#2b9a94', '#0b6f6a', '#054240'];
const RIPPLEMAP_RAMP_DARK = ['#123433', '#1c4b49', '#276460', '#348079', '#4b9e97', '#6fc3bc', '#a5e8e2'];

function rippleMapThemeDark() {
    const m = (getComputedStyle(document.body).backgroundColor || '').match(/\d+/g);
    if (!m) return false;
    return (0.2126 * m[0] + 0.7152 * m[1] + 0.0722 * m[2]) < 128;
}

function drawRippleMap() {
    const canvas = document.getElementById('ripplemap-canvas');
    if (!canvas || canvas.offsetParent === null) return;
    fetch(buildURL('/famatrix.csv'), { cache: 'no-cache' }).then(r => r.text()).then(txt => {
        const rows = txt.trim().split('\n');
        rows.shift();
        rippleMapCells = rows.filter(Boolean).map(l => {
            const c = l.split(',');
            return { rpmLo: +c[0], ampLo: +c[1], windows: +c[2], pkpk: +c[3], f1: +c[4], a1: +c[5] };
        });
        rippleMapRender();
        if (!rippleMapObsHooked && typeof ResizeObserver !== 'undefined') {
            rippleMapObsHooked = true;
            let t = null;
            new ResizeObserver(() => { clearTimeout(t); t = setTimeout(rippleMapRender, 150); })
                .observe(canvas.parentElement);
            canvas.addEventListener('pointermove', rippleMapPointer);
            canvas.addEventListener('pointerdown', rippleMapPointer);
            canvas.addEventListener('pointerleave', () => { rippleMapHover = null; rippleMapRender(); rippleMapInfoDefault(); });
        }
        rippleMapInfoDefault();
    }).catch(() => { });
}

function rippleMapFrame() {
    const RPW = 50, APW = 20;
    let rpmMin = 500, rpmMax = 4000, ampMin = 5, ampMax = 105;
    for (const c of (rippleMapCells || [])) {
        rpmMin = Math.min(rpmMin, c.rpmLo); rpmMax = Math.max(rpmMax, c.rpmLo + RPW);
        ampMin = Math.min(ampMin, c.ampLo); ampMax = Math.max(ampMax, c.ampLo + APW);
    }
    return { RPW, APW, rpmMin, rpmMax, ampMin, ampMax,
        cols: Math.round((rpmMax - rpmMin) / RPW), rows: Math.round((ampMax - ampMin) / APW) };
}

function rippleMapGeom() {
    const canvas = document.getElementById('ripplemap-canvas');
    const f = rippleMapFrame();
    const cssW = Math.min(canvas.parentElement.clientWidth || 560, 800);
    const padL = 34, padR = 16, padT = 30, padB = 26;
    const cw = (cssW - padL - padR) / f.cols;
    const ch = Math.max(18, Math.min(30, cw * 3));
    return { f, cssW, cssH: padT + f.rows * ch + padB, padL, padT, cw, ch };
}

function rippleMapInfoDefault() {
    const info = document.getElementById('ripplemap-info');
    if (!info || !rippleMapCells) return;
    const f = rippleMapFrame();
    info.textContent = rippleMapCells.length
        ? rippleMapCells.length + ' of ' + (f.cols * f.rows) + ' operating points learned — tap a square for its numbers'
        : 'No cells learned yet — the map fills in as the engine runs at different speeds and loads.';
}

function rippleMapRender() {
    const canvas = document.getElementById('ripplemap-canvas');
    if (!canvas || !rippleMapCells) return;
    const g = rippleMapGeom(), f = g.f;
    const dpr = window.devicePixelRatio || 1;
    canvas.width = g.cssW * dpr; canvas.height = g.cssH * dpr;
    canvas.style.height = g.cssH + 'px';
    const ctx = canvas.getContext('2d');
    ctx.scale(dpr, dpr);
    const dark = rippleMapThemeDark();
    const ramp = dark ? RIPPLEMAP_RAMP_DARK : RIPPLEMAP_RAMP_LIGHT;
    const cs = getComputedStyle(document.body);
    const muted = (cs.getPropertyValue('--text-muted') || '').trim() || '#888';
    const maxPk = Math.max(0.01, ...rippleMapCells.map(c => c.pkpk));
    const byKey = {};
    for (const c of rippleMapCells) byKey[c.rpmLo + '_' + c.ampLo] = c;

    for (let i = 0; i < f.cols; i++) {
        for (let j = 0; j < f.rows; j++) {
            const rpmLo = f.rpmMin + i * f.RPW, ampLo = f.ampMin + j * f.APW;
            const x = g.padL + i * g.cw, y = g.padT + (f.rows - 1 - j) * g.ch;
            const c = byKey[rpmLo + '_' + ampLo];
            if (c) ctx.fillStyle = ramp[Math.min(ramp.length - 1, Math.round((c.pkpk / maxPk) * (ramp.length - 1)))];
            else ctx.fillStyle = dark ? 'rgba(255,255,255,0.05)' : 'rgba(0,0,0,0.04)';
            ctx.fillRect(x + 0.5, y + 0.5, Math.max(0.5, g.cw - 1), g.ch - 1);
        }
    }
    if (rippleMapHover) {
        const i = Math.round((rippleMapHover.rpmLo - f.rpmMin) / f.RPW);
        const j = Math.round((rippleMapHover.ampLo - f.ampMin) / f.APW);
        ctx.strokeStyle = dark ? '#a5e8e2' : '#054240';
        ctx.lineWidth = 1.5;
        ctx.strokeRect(g.padL + i * g.cw + 0.75, g.padT + (f.rows - 1 - j) * g.ch + 0.75, g.cw - 1.5, g.ch - 1.5);
    }
    ctx.fillStyle = muted;
    ctx.font = '10px sans-serif';
    ctx.textAlign = 'center';
    for (let r = Math.ceil(f.rpmMin / 500) * 500; r <= f.rpmMax; r += 500)
        ctx.fillText(String(r), g.padL + ((r - f.rpmMin) / f.RPW) * g.cw, g.padT + f.rows * g.ch + 12);
    ctx.fillText('RPM', g.padL + (f.cols * g.cw) / 2, g.padT + f.rows * g.ch + 24);
    ctx.textAlign = 'right';
    for (let j = 0; j <= f.rows; j++)
        ctx.fillText(String(f.ampMin + j * f.APW), g.padL - 5, g.padT + (f.rows - j) * g.ch + 3);
    ctx.save();
    ctx.translate(9, g.padT + (f.rows * g.ch) / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.textAlign = 'center';
    ctx.fillText('Amps', 0, 0);
    ctx.restore();
    const lw = 12, lbl = maxPk.toFixed(1) + ' A pk-pk';
    const lx = g.cssW - 6 - ctx.measureText(lbl).width - 4 - ramp.length * lw;
    for (let k = 0; k < ramp.length; k++) { ctx.fillStyle = ramp[k]; ctx.fillRect(lx + k * lw, 8, lw - 1, 8); }
    ctx.fillStyle = muted;
    ctx.textAlign = 'right';
    ctx.fillText('0', lx - 4, 15);
    ctx.textAlign = 'left';
    ctx.fillText(lbl, lx + ramp.length * lw + 4, 15);
}

function rippleMapPointer(ev) {
    const canvas = document.getElementById('ripplemap-canvas');
    if (!canvas || !rippleMapCells) return;
    const g = rippleMapGeom(), f = g.f;
    const r = canvas.getBoundingClientRect();
    const i = Math.floor((ev.clientX - r.left - g.padL) / g.cw);
    const j = f.rows - 1 - Math.floor((ev.clientY - r.top - g.padT) / g.ch);
    const info = document.getElementById('ripplemap-info');
    if (i < 0 || i >= f.cols || j < 0 || j >= f.rows) { rippleMapHover = null; rippleMapRender(); rippleMapInfoDefault(); return; }
    const rpmLo = f.rpmMin + i * f.RPW, ampLo = f.ampMin + j * f.APW;
    const c = rippleMapCells.find(x => x.rpmLo === rpmLo && x.ampLo === ampLo);
    rippleMapHover = { rpmLo, ampLo };
    rippleMapRender();
    if (info) info.textContent = c
        ? rpmLo + '–' + (rpmLo + f.RPW) + ' RPM × ' + ampLo + '–' + (ampLo + f.APW) + ' A — ripple ' + c.pkpk.toFixed(2)
          + ' A pk-pk · top tone ' + c.f1.toFixed(0) + ' Hz @ ' + c.a1.toFixed(2) + ' A · ' + c.windows + ' windows'
        : rpmLo + '–' + (rpmLo + f.RPW) + ' RPM × ' + ampLo + '–' + (ampLo + f.APW) + ' A — not learned yet';
}

setTimeout(drawRippleMap, 1500);

/* XREG_END */